  var WORKS = [{"base":"T0235","name":"T0235《金剛般若波羅蜜經》","path":"01-大正藏/03般若部類/T0235《金剛般若波羅蜜經》.md","loci":[{"p":19,"q":"如是我聞","notes":[{"by":"金剛般若經贊述","era":"","t":"佛初成道，初一時中，度五人俱隣等；第二時，度耶舍等五十人；第三時，度舍利子等一百人；第四時，度目犍連等一百人；第五時，度優樓頻螺迦葉等五百人；第六時，度迦耶迦葉等二百九十五人；第七時，度那提迦葉等二百人。"},{"by":"天台智者大師","era":"隋","t":"言則當理，理亦如言，當理得時令人開悟，聖不虛說，言必會機，故言一時也。"}]},{"p":88,"q":"飯食","notes":[{"by":"天台智者大師","era":"隋","t":"佛從前代八萬四千歲皆輪王位，至釋尊身，若不出家，當二千五百歲作金輪王，而能捨位從門乞食，是為希有，此歎身密。"},{"by":"宗密","era":"","t":"字義屬上句，文連下句。"}]},{"p":291,"q":"佛告","notes":[{"by":"天台智者大師","era":"隋","t":"第二、廣答。"}]},{"p":304,"q":"應如是降伏其心","notes":[{"by":"宗密","era":"","t":"二、列，三：一、受生差別。"}]},{"p":338,"q":"若有色","notes":[{"by":"天台智者大師","era":"隋","t":"即欲、色二界，"}]},{"p":362,"q":"我皆令入無餘涅槃而滅度之。","notes":[{"by":"宗密","era":"","t":"即無住處涅槃，不共二乘，故云第一。"}]},{"p":400,"q":"何以故","notes":[{"by":"天台智者大師","era":"隋","t":"釋菩提無相可取，諸法空不可說，非法即不有，非非法即不無，故不可說，有無並無，理之極也。"},{"by":"宗密","era":"","t":"釋於中，三：初、法說，為疑無福，不可思以斷之。"}]},{"p":432,"q":"復次","notes":[{"by":"天台智者大師","era":"隋","t":"第二答住問。"}]},{"p":474,"q":"須菩提！菩薩應如是布施，不住於相","notes":[{"by":"宗密","era":"","t":"前但指三事，今則心境空有，微細盡袪。"},{"by":"天台智者大師","era":"隋","t":"結成住義，施、受皆不可得，不住相也。"}]},{"p":522,"q":"東方虛空","notes":[{"by":"天台智者大師","era":"隋","t":"善吉深識法身，故言不可以身相而見，或一身、一智，或言真、應，或言法、報、應，皆是明果。"},{"by":"宗密","era":"","t":"喻說，可知。"}]},{"p":598,"q":"須菩提！菩薩但應如所教住。","notes":[{"by":"宗密","era":"","t":"本秪因以相為佛，故對前不住相起疑；佛舉疑起之因，問答欲令除斷。"},{"by":"天台智者大師","era":"隋","t":"第三結勸也。"}]},{"p":621,"q":"可以身相見如來不","notes":[{"by":"金剛般若經贊述","era":"","t":"明斷疑，謂能斷道般若，所斷者謂二障也。"}]},{"p":706,"q":"頗有","notes":[{"by":"天台智者大師","era":"隋","t":"第二明信者行深。"}]},{"p":882,"q":"若心取","notes":[{"by":"宗密","era":"","t":"總明二相，總解取法非法，盡名相也，亦是建立取相，則我等相便生，立義宗也。"}]},{"p":901,"q":"若取法","notes":[{"by":"宗密","era":"","t":"別明二相，論云"}]},{"p":979,"q":"法尚應捨，何況非法。","notes":[{"by":"金剛般若經贊述","era":"","t":"訛也，應云蘇補底，此云善現，即世尊弟子之中解空第一也，謂應佛之世即能現生，或善能現前了達空義，或初生現時其室空寂，相師占之名為善現。"},{"by":"胡吉藏","era":"","t":"復次，欲轉眾生深重鄣，故說此經；下云：應墮惡道，以受持經故，三惡道消滅，當得三菩提。"},{"by":"宗密","era":"","t":"佛問得不，意顯不得。"}]},{"p":1243,"q":"須菩提！所謂佛法者，即非佛法。","notes":[{"by":"宗密","era":"","t":"第一義中，無有佛法從經出也。"},{"by":"金剛般若經贊述","era":"","t":"如是等皆應准釋名為不失也。"}]},{"p":1268,"q":"須陀洹","notes":[{"by":"天台智者大師","era":"隋","t":"第三、舉菩薩遍行。"}]},{"p":1555,"q":"世尊！佛說","notes":[{"by":"天台智者大師","era":"隋","t":"第二、自陳。"}]},{"p":1582,"q":"我不作是念：『我是離欲阿羅漢。』","notes":[{"by":"宗密","era":"","t":"三、却釋佛意。"}]},{"p":1667,"q":"昔在然燈","notes":[{"by":"天台智者大師","era":"隋","t":"第四、舉往古時事為證，次明菩薩其解亦同。"}]},{"p":1703,"q":"須菩提！於意云何？菩薩莊嚴佛土不","notes":[{"by":"宗密","era":"","t":"佛意欲明法性真土，故問："}]},{"p":1806,"q":"譬如","notes":[{"by":"天台智者大師","era":"隋","t":"第六、須彌山王，此即非果而果。"}]},{"p":1863,"q":"恒河","notes":[{"by":"天台智者大師","era":"隋","t":"第三、信者福重。"}]},{"p":1953,"q":"三千","notes":[{"by":"天台智者大師","era":"隋","t":"是第二受、持福多。"}]},{"p":1983,"q":"佛告","notes":[{"by":"天台智者大師","era":"隋","t":"答名、答持，名冠題首，義已備矣，境慧相從，通名般若，那要宜別，歸乎聖心，挈網舉目，詮合義從，名正理顯，宜應修習。"}]},{"p":2083,"q":"須菩提","notes":[{"by":"胡吉藏","era":"","t":"此人本迹，其事難知。"}]},{"p":2104,"q":"若是經典","notes":[{"by":"胡吉藏","era":"","t":"第四、釋處貴。"}]},{"p":2125,"q":"爾時","notes":[{"by":"胡吉藏","era":"","t":"若依開善，從上已來並是說波若體，此之一章明波若名，即是名說也。"},{"by":"宗密","era":"","t":"佛告須菩提："}]},{"p":2139,"q":"當何名","notes":[{"by":"天台智者大師","era":"隋","t":"第二、辨名空無所有。"}]},{"p":2184,"q":"所以者何","notes":[{"by":"天台智者大師","era":"隋","t":"釋無相意，我相即是非相，無片許相可得故，其能不顛倒，我、人等從本以來無一相可得故，其體本來無相即為希有，此是反釋；四、"}]},{"p":2209,"q":"須菩提！於意云何","notes":[{"by":"宗密","era":"","t":"無所說者，無別、異，增、減之說，但如證而說，既如其說則無所說，三世佛皆然，故云無異說。"},{"by":"胡吉藏","era":"","t":"此文所以來者，凡有二義：一者、證信故來。"}]},{"p":2289,"q":"諸微塵","notes":[{"by":"胡吉藏","era":"","t":"明微塵有兩種：一者、塵染之塵；二者、成世界無記之塵。"}]},{"p":2330,"q":"可以三十二相","notes":[{"by":"天台智者大師","era":"隋","t":"二、明身相不無所有。"}]},{"p":2361,"q":"何以故","notes":[{"by":"天台智者大師","era":"隋","t":"第二、明般若用，以非忍為忍有大力用，初、一世忍，次、多世忍。"},{"by":"胡吉藏","era":"","t":"此是第七、廣釋淨信之義。"}]},{"p":2411,"q":"若復有人","notes":[{"by":"胡吉藏","era":"","t":"第二、正格量。"}]},{"p":2462,"q":"而白佛言","notes":[{"by":"胡吉藏","era":"","t":"他云世諦生、真諦不生，即問：實相即是真諦，既生實相，何不生真諦耶？"}]},{"p":2503,"q":"若復有人得聞","notes":[{"by":"天台智者大師","era":"隋","t":"第二、餘人能信。"}]},{"p":2529,"q":"第一","notes":[{"by":"天台智者大師","era":"隋","t":"即般若諸度中最為第一，六從後數亦是第一。"},{"by":"胡吉藏","era":"","t":"獨佛法大乘有此實相，故云實相。"}]},{"p":2549,"q":"是故","notes":[{"by":"天台智者大師","era":"隋","t":"是後誡，令不住六塵行施，還舉前宗會以成義。"}]},{"p":2580,"q":"若當來世","notes":[{"by":"胡吉藏","era":"","t":"第四、陳他悟為難。"},{"by":"天台智者大師","era":"隋","t":"第四、餘人信難。"}]},{"p":2634,"q":"所以者何？我相即是非相","notes":[{"by":"胡吉藏","era":"","t":"所以不取我等相者，非有我相，是故不取我相，以實無我故無所取耳，故云我相即是非相也。"}]},{"p":2677,"q":"佛告","notes":[{"by":"天台智者大師","era":"隋","t":"第四、如來述成。"},{"by":"胡吉藏","era":"","t":"第二、佛述成。"}]},{"p":2717,"q":"何以故？須菩提！如來說第一波羅蜜","notes":[{"by":"胡吉藏","era":"","t":"他云般若是六度中第一，故言第一則非第一者，真諦遣第一也。"},{"by":"宗密","era":"","t":"何以故者，有二：一、躡前不驚等徵，二、都躡前勝以徵。"}]},{"p":2753,"q":"忍辱","notes":[{"by":"天台智者大師","era":"隋","t":"第三、明般若功用無所有。"}]},{"p":2781,"q":"歌利","notes":[{"by":"天台智者大師","era":"隋","t":"此云惡生王。"},{"by":"胡吉藏","era":"","t":"引事證因緣。"}]},{"p":2897,"q":"應離","notes":[{"by":"天台智者大師","era":"隋","t":"第三、勸誡。"}]},{"p":2915,"q":"不應","notes":[{"by":"天台智者大師","era":"隋","t":"即是前誡不應住色，心中離一切相，不住聲、香等也。"}]},{"p":2937,"q":"應生無所住心","notes":[{"by":"天台智者大師","era":"隋","t":"即次勸應住般若，般若無相可緣，心何所住？"}]},{"p":2970,"q":"須菩提！菩薩為利益一切眾生","notes":[{"by":"胡吉藏","era":"","t":"前既明無住發心、無住修行，人便謂既無所住，何故發心？"},{"by":"天台智者大師","era":"隋","t":"即是後勸，令為利益而行施，施不望報，利益必深也。"}]},{"p":3022,"q":"須菩提！如來是真語者","notes":[{"by":"胡吉藏","era":"","t":"有此文來者，上來至此，凡有三文引佛語勸信：初引如來說一切相則非相，說一切眾生則非眾生，此勸菩薩捨人法見，令信無所住教。"},{"by":"宗密","era":"","t":"佛所有說皆如其事，今說證果，何疑不然？"},{"by":"天台智者大師","era":"隋","t":"第二、舉能說人為證。"}]},{"p":3064,"q":"無實無虛","notes":[{"by":"天台智者大師","era":"隋","t":"第三、舉所得法為證。"}]},{"p":3127,"q":"當來之世","notes":[{"by":"天台智者大師","era":"隋","t":"第二、能如是解，即仰參佛說，當來若能受、持即為佛悉知見，皆得成就無量無邊功德，如來所見理用非謬，明將來宜加勤修也。"}]},{"p":3196,"q":"初日分","notes":[{"by":"胡吉藏","era":"","t":"第二、三時捨身格量功德也，為二：初、明格量；第二、稱歎勸修。"}]},{"p":3285,"q":"須菩提！以要言之","notes":[{"by":"天台智者大師","era":"隋","t":"答上無所有、如是有，不可思議事也。"},{"by":"胡吉藏","era":"","t":"第二、稱歎勸修。"}]},{"p":3312,"q":"如來為發大乘者說","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"故以大乘為教相也。"},{"by":"胡吉藏","era":"","t":"第二、歎人。"}]},{"p":3344,"q":"如來悉知是人","notes":[{"by":"胡吉藏","era":"","t":"問：前已二處明知見竟，今復明者，有何異耶？"}]},{"p":3390,"q":"阿耨多羅","notes":[{"by":"金剛般若經贊述","era":"","t":"稱覺；應云無上正等正覺及等正覺，謂初是總名，次簡外道邪覺，次簡二乘偏覺，次簡菩薩缺覺，舉圓滿故如是名為無上正等正覺也。"},{"by":"天台智者大師","era":"隋","t":"三乘不堪聞、不信受，樂小是二乘，著我是凡夫，著見是外道。"},{"by":"金剛般若波羅蜜經註解","era":"","t":"又自徵釋，由不可取、不可說，非法、非非法。"}]},{"p":3408,"q":"若樂小法者","notes":[{"by":"胡吉藏","era":"","t":"此明舉失顯得，歎此中舉二人。"}]},{"p":3425,"q":"壽者見","notes":[{"by":"天台智者大師","era":"隋","t":"明用並無所有。"}]},{"p":3452,"q":"在在處處","notes":[{"by":"天台智者大師","era":"隋","t":"地是無知，法處故貴，雖復廢言息義，此處常有天龍圍遶，如帝王所居之處，人皆宗重，天人供養，此處是塔，恭敬、作禮、香花而散也。"}]},{"p":3507,"q":"復次","notes":[{"by":"金剛般若經贊述","era":"","t":"等者，即謂烏波索迦等也。"}]},{"p":3580,"q":"我念過去","notes":[{"by":"天台智者大師","era":"隋","t":"明能持經者所得福德勝佛往行。"},{"by":"胡吉藏","era":"","t":"第三、舉釋迦往因格量。"}]},{"p":3765,"q":"世尊！善男子、善女人發阿耨多羅三","notes":[{"by":"金剛般若經贊述","era":"","t":"欲、願故，欲者正求也，謂即正求佛故；願者為所求故，作心思念也，謂發正願，斷一切惡等故。"},{"by":"宗密","era":"","t":"二、答，三：○初、若名菩薩必無我。"},{"by":"金剛般若波羅蜜經註解","era":"","t":"善現初聞此義，至是復問者，何耶？"}]},{"p":3800,"q":"佛告","notes":[{"by":"天台智者大師","era":"隋","t":"釋因無所有；次、"}]},{"p":3862,"q":"何以故","notes":[{"by":"天台智者大師","era":"隋","t":"第二是明果無所有，有三義，初、明如，次、證，後、譬。"},{"by":"胡吉藏","era":"","t":"第四、釋無所得故得記之義也。"}]},{"p":3923,"q":"於意云何？如來於然燈佛所","notes":[{"by":"胡吉藏","era":"","t":"第二章來者，論生起云"}]},{"p":3952,"q":"不也，世尊！","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"善現答意云：善慧彼時都無所得，離諸分別，由悟無法故得受記。"},{"by":"金剛般若經贊述","era":"","t":"述曰，此第二舉喻，於中初舉東方虛空，次舉餘九方。"}]},{"p":4024,"q":"若有法","notes":[{"by":"胡吉藏","era":"","t":"此是反釋，若有所得則不得記也。"}]},{"p":4069,"q":"以實無有法","notes":[{"by":"胡吉藏","era":"","t":"順釋，以無所得故乃得記耳。"}]},{"p":4116,"q":"何以故","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"如者，真如也，不偽曰真、不異曰如。"},{"by":"天台智者大師","era":"隋","t":"釋菩薩自無，何有眾生？"}]},{"p":4131,"q":"若有人言","notes":[{"by":"胡吉藏","era":"","t":"第二、引現在得果時以釋疑也。"}]},{"p":4192,"q":"無實無虛","notes":[{"by":"胡吉藏","era":"","t":"前各彈有無見，此雙結非有非無也。"}]},{"p":4224,"q":"即非一切法","notes":[{"by":"胡吉藏","era":"","t":"一切顛倒之法，此非如來所證，故云則非一切法也。"}]},{"p":4275,"q":"是名大身","notes":[{"by":"胡吉藏","era":"","t":"此是成就眾生菩薩、淨佛土菩薩也，亦如上發心受記菩薩不可得，故云亦如是也。"},{"by":"金剛般若經贊述","era":"","t":"是無分別身也。"}]},{"p":4313,"q":"何以故？須菩提！實無有法名為菩薩","notes":[{"by":"宗密","era":"","t":"無法名菩薩，豈有我度眾生？"}]},{"p":4359,"q":"若菩薩作是言","notes":[{"by":"天台智者大師","era":"隋","t":"第三明菩薩化他無所有。"}]},{"p":4380,"q":"何以故？如來說莊嚴佛土者，即非莊","notes":[{"by":"宗密","era":"","t":"三、釋成菩薩。"}]},{"p":4393,"q":"即非莊嚴","notes":[{"by":"金剛般若經贊述","era":"","t":"是無相無取真莊嚴也。"}]},{"p":4407,"q":"若菩薩通達無我、法者","notes":[{"by":"天台智者大師","era":"隋","t":"第二明名假無所有。"}]},{"p":4528,"q":"於意云何","notes":[{"by":"胡吉藏","era":"","t":"第八章經論生起，　從上第二章經生。"}]},{"p":4672,"q":"甚多，世尊！","notes":[{"by":"金剛般若經贊述","era":"","t":"佛告須菩提："},{"by":"金剛般若波羅蜜經註解","era":"","t":"佛告須菩提："}]},{"p":4710,"q":"如來說諸心","notes":[{"by":"胡吉藏","era":"","t":"明如來見一切眾生心唯在顛倒中行也。"}]},{"p":4726,"q":"所以者何？須菩提！過去心不可得，","notes":[{"by":"金剛般若經贊述","era":"","t":"述曰，世親云，上來破於本處生疑竟，自下第二有四疑，展轉釋疑故生也。"}]},{"p":4815,"q":"須菩提！若福德有實，如來不說得福","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"前說眾生心有住著是為顛倒，然福由心造，豈亦是顛倒？"}]},{"p":4834,"q":"以福德無故","notes":[{"by":"胡吉藏","era":"","t":"此明無得福德，故是佛因也。"}]},{"p":4861,"q":"具足色身","notes":[{"by":"胡吉藏","era":"","t":"唯佛一人盡形相之美，故言具足；餘人乃至輪王，相不明了，故不具足也。"}]},{"p":4906,"q":"是名具足","notes":[{"by":"胡吉藏","era":"","t":"此破異見，何處離相好別有法身也？"}]},{"p":4954,"q":"何以故","notes":[{"by":"胡吉藏","era":"","t":"釋止疑念所以，明實無眾生可度，汝不應念佛度眾生也。"}]},{"p":4994,"q":"我當有所說法","notes":[{"by":"天台智者大師","era":"隋","t":"第二明說法。"}]},{"p":5071,"q":"頗有眾生於未來世","notes":[{"by":"金剛般若經贊述","era":"","t":"等，此為初也。"}]},{"p":5094,"q":"須菩提！彼非眾生，非不眾生。","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"眾生有聖、有凡，而凡夫眾生於此般若不能生信，聖體眾生乃能信解。"},{"by":"金剛般若經贊述","era":"","t":"述曰，此第二佛答中，初、標，次、釋，此初也。"}]},{"p":5144,"q":"世尊！佛得阿耨多羅三藐三菩提，為","notes":[{"by":"金剛般若經贊述","era":"","t":"述曰，世親云，此大段中破第四疑也，即是第二展轉釋中第二疑也。"}]},{"p":5190,"q":"無有少法可得","notes":[{"by":"天台智者大師","era":"隋","t":"相盡虛通謂之菩提，菩提無相有何可得？"}]},{"p":5217,"q":"是法平等","notes":[{"by":"金剛般若經贊述","era":"","t":"有為法有取捨，菩薩於十地中得勝無漏而捨劣故，無為無勝劣可取捨故，言無高下也。"},{"by":"天台智者大師","era":"隋","t":"結成菩提義也。"}]},{"p":5254,"q":"修一切善法","notes":[{"by":"胡吉藏","era":"","t":"上三門就果釋無上，此第四義就因門釋無上，以有無上方便修一切眾行滿足，故是無上；餘菩薩修因行不滿，故非無上也。"},{"by":"金剛般若經贊述","era":"","t":"述曰，世親云，此第三彰方便滿足也。"}]},{"p":5289,"q":"是名善法","notes":[{"by":"胡吉藏","era":"","t":"還結取無所得善法也。"}]},{"p":5364,"q":"百分不及一","notes":[{"by":"金剛般若經贊述","era":"","t":"等者，論家有四種校量勝，謂一者、數勝，二者、力勝，三者、無相似勝，四者、因勝。"}]},{"p":5389,"q":"須菩提！於意云何？汝等勿謂如來作","notes":[{"by":"宗密","era":"","t":"二、示其正見。"}]},{"p":5409,"q":"我當度眾生","notes":[{"by":"天台智者大師","era":"隋","t":"菩提無得為果，故以忘言而說，勿謂如來見眾生可度，若見有眾生則為我見，何謂如來？"},{"by":"金剛般若波羅蜜經註解","era":"","t":"如來不以具足相而得菩提，具足相即福德相也。"},{"by":"金剛般若經贊述","era":"","t":"勸令勿生前念，以相為因而得法身。"}]},{"p":5439,"q":"若有眾生如來度者","notes":[{"by":"金剛般若經贊述","era":"","t":"述曰，此第二明凡亦非實，但假施言也，謂於貪、嗔未亡之類，假名凡夫，非如其言即實凡夫也。"},{"by":"胡吉藏","era":"","t":"此是反釋，若見有眾生可度，佛則有取我之過也。"}]},{"p":5466,"q":"如來說有我者，則非有我","notes":[{"by":"胡吉藏","era":"","t":"又釋疑，疑云：若無眾生可度，佛口中何故自稱我耶？"}]},{"p":5505,"q":"須菩提！於意云何？可以三十二相觀","notes":[{"by":"宗密","era":"","t":"二、答因苗識根。"},{"by":"胡吉藏","era":"","t":"此第十一章經。"}]},{"p":5552,"q":"須菩提！若以三十二相觀如來者，轉","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"爾時，世尊而說偈言："},{"by":"金剛般若經贊述","era":"","t":"述曰，義可知也。"}]},{"p":5580,"q":"白佛","notes":[{"by":"天台智者大師","era":"隋","t":"第二明體道證忍之人無所有，初、明因人不受，後、明果人不受。"},{"by":"宗密","era":"","t":"五、即見聞不及。"}]},{"p":5648,"q":"汝若作是念","notes":[{"by":"胡吉藏","era":"","t":"第十二章經來者，論生起云"},{"by":"金剛般若經贊述","era":"","t":"明因果不失；後、"}]},{"p":5719,"q":"發阿耨","notes":[{"by":"天台智者大師","era":"隋","t":"第二明因亦二，前、誡，後、明有。"}]},{"p":5744,"q":"何以故？發阿耨多羅三藐三菩提心者","notes":[{"by":"金剛般若經贊述","era":"","t":"述曰，此第二釋所以之中，初、佛略標釋，次、善現問，後、佛答，此初也。"}]},{"p":5790,"q":"若復有人","notes":[{"by":"天台智者大師","era":"隋","t":"明成忍之行無所有，忘我則忍成，超出故勝也。"}]},{"p":5826,"q":"不受福德","notes":[{"by":"胡吉藏","era":"","t":"不受有所得福德故此菩薩勝前菩薩，前菩薩受有得福德故不及後菩薩也。"}]},{"p":5891,"q":"若來若去","notes":[{"by":"天台智者大師","era":"隋","t":"明果人不受，若言從真如實際中來，善逝自及，化人去至涅槃，皆是不解佛所說義。"}]},{"p":5935,"q":"須菩提！若善男子、善女人以三千大","notes":[{"by":"金剛般若經贊述","era":"","t":"述曰，世親云，此第二明法身一、化身多也。"},{"by":"天台智者大師","era":"隋","t":"並是大行，同《華嚴》中說"}]},{"p":5975,"q":"甚多，世尊！","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"上明應身去來是異，法身無去來是一，佛恐善現有一、異之見，故設喻以釋之。"},{"by":"天台智者大師","era":"隋","t":"一偈明觀，觀諸法夢、幻等，而為人說句，偈有真實，及有此假有也。"}]},{"p":6008,"q":"佛說微塵眾","notes":[{"by":"金剛般若經贊述","era":"","t":"述曰，此第二釋中，初、却質，次、說非，後、明執實，此初也。"},{"by":"胡吉藏","era":"","t":"還結正假名義也。"}]},{"p":6026,"q":"世尊！如來所說三千大千世界，則非","notes":[{"by":"宗密","era":"","t":"本論破世界不實之義可知，無著云："}]},{"p":6063,"q":"一合相","notes":[{"by":"天台智者大師","era":"隋","t":"破一合相，以非合為合故是不可說，只復言是合，此復非復，是故假名說合，何為而非合？"}]},{"p":6088,"q":"須菩提！一合相者，則是不可說，但","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"此釋世界喻法身無一性，若知合微塵為世界，世界全是微塵，則世界無實性，故曰則非世界；以離性計而說世界，故曰是名世界也。"}]},{"p":6122,"q":"佛說我見","notes":[{"by":"天台智者大師","era":"隋","t":"明破諸見用。"}]},{"p":6159,"q":"世尊！是人不解如來所說義。","notes":[{"by":"宗密","era":"","t":"二、遣言執。"}]},{"p":6209,"q":"是名我見","notes":[{"by":"金剛般若經贊述","era":"","t":"等者，謂如來假說也。"}]},{"p":6244,"q":"於一切法","notes":[{"by":"胡吉藏","era":"","t":"上明我見本來不可得，今明法見亦本來不可得，故舉我列法，故云應如是知、見、信解，不生法相也。"},{"by":"金剛般若經贊述","era":"","t":"顯示於何法不分別。"}]},{"p":6258,"q":"如是信解","notes":[{"by":"天台智者大師","era":"隋","t":"理深未明，推信為解耳。"},{"by":"金剛般若經贊述","era":"","t":"非是實執之法相也。"}]},{"p":6315,"q":"若有善男子","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"明持說福勝。"}]},{"p":6357,"q":"云何為人","notes":[{"by":"金剛般若波羅蜜經註解","era":"","t":"是釋福勝，所以據經文但明持說功德，而論乃謂化佛說法有無量功德者，蓋化佛是說經教主，持說是弘經之人，所弘之經是佛所說，佛之所說離言說相，故功德無量。"},{"by":"胡吉藏","era":"","t":"釋為他說義，明上來數勸為人說法。"},{"by":"天台智者大師","era":"隋","t":"後方法，初、標，次、釋。"},{"by":"金剛般若經贊述","era":"","t":"述曰，此明離相而說也。"}]},{"p":6407,"q":"佛說是經","notes":[{"by":"天台智者大師","era":"隋","t":"第二奉行流通。"}]}]},{"base":"T0262","name":"T0262《妙法蓮華經》","path":"01-大正藏/04法華部類/T0262《妙法蓮華經》.md","loci":[{"p":1239,"q":"其名曰","notes":[{"by":"法華義疏","era":"","t":"第五、列名。"}]},{"p":1449,"q":"供養無量百千諸佛","notes":[{"by":"法華義疏","era":"","t":"約事而言，能動大千為大力；據理言之，有得煩惱能令三界紛綸、二乘迷倒，其力最大，菩薩能摧此大惡，名大力也。"}]},{"p":1732,"q":"有八龍王","notes":[{"by":"法華義疏","era":"","t":"有人言：從國立名，住在娑伽羅國，此國近仙人而住，王觸忤仙人，仙人呪此國令成海，此龍居住其中，從本國立名也。"}]},{"p":1798,"q":"有四緊那羅","notes":[{"by":"法華義疏","era":"","t":"總持上三法，即是奏陀羅尼曲也。"}]},{"p":1889,"q":"阿修羅","notes":[{"by":"法華義疏","era":"","t":"此言縛，其人是修羅中前峯，與帝釋鬪時被縛，因誓得脫，故以為名也。"}]},{"p":1911,"q":"毘摩質多羅","notes":[{"by":"法華義疏","era":"","t":"此云響高，以其於大水中出大音聲，自唱言我是毘摩質多羅，故云響高。"}]},{"p":1940,"q":"迦樓羅","notes":[{"by":"法華義疏","era":"","t":"此云金翅鳥，以其翅頭即有金色，故以為名。"}]},{"p":1985,"q":"韋提希子","notes":[{"by":"法華義疏","era":"","t":"翻為思惟，亦云四維。"}]},{"p":2018,"q":"四眾圍遶","notes":[{"by":"法華義疏","era":"","t":"有人言，天有二眾：謂魔眾、梵眾，舉欲色天之大者也。"}]},{"p":2035,"q":"為諸菩薩說大乘經","notes":[{"by":"法華義疏","era":"","t":"即說無相一法生一切法，以教根熟菩薩也。"}]},{"p":2070,"q":"入於無量義處三昧","notes":[{"by":"法華義疏","era":"","t":"雨華時也，正是四眾聞經悟一乘時。"}]},{"p":5282,"q":"天雨曼陀華，天鼓自然鳴，諸天龍鬼","notes":[{"by":"法華義疏","era":"","t":"約理而談者，天者淨也，四眾封執之心既淨，故得聞經成佛。"}]},{"p":5570,"q":"爾時四部眾","notes":[{"by":"法華義疏","era":"","t":"第二、時眾生疑也。"}]},{"p":5756,"q":"一心","notes":[{"by":"法華義疏","era":"","t":"明意無他緣。"}]},{"p":5829,"q":"是德藏菩薩","notes":[{"by":"法華義疏","era":"","t":"一行半，頌授記。"}]},{"p":5866,"q":"佛此夜滅度","notes":[{"by":"法華義疏","era":"","t":"依小乘義，以身為薪、智慧為火，故智慧依於身、身盡智便滅。"}]},{"p":5914,"q":"是妙光法師","notes":[{"by":"法華義疏","era":"","t":"六行，頌彌勒本緣，開之為三：兩行半頌彌勒之失，兩行半頌彌勒之得，一行頌結會古今。"}]},{"p":5938,"q":"是諸八王子","notes":[{"by":"法華義疏","era":"","t":"三行，頌匠成八子。"}]},{"p":6131,"q":"佛滅度後","notes":[{"by":"法華義疏","era":"","t":"第四、妙光弘經。"}]},{"p":6154,"q":"我見燈明佛","notes":[{"by":"法華義疏","era":"","t":"二行，頌第四、分明結答。"}]},{"p":6202,"q":"諸人今當知","notes":[{"by":"法華義疏","era":"","t":"昔說小乘，教猶未圓、理猶未滿，故生解不足。"}]},{"p":6226,"q":"諸求三乘人，若有疑悔者，佛當為除","notes":[{"by":"法華經義記","era":"","t":"緣是義故，時眾相與，欣心澍仰，冀聞妙說。"}]},{"p":6258,"q":"方便品","notes":[{"by":"法華義疏","era":"","t":"但此義難明，今以四句顯之：一者、昔開今覆。"}]},{"p":9546,"q":"今正是其時，決定說大乘","notes":[{"by":"胡吉藏","era":"","t":"故知菩薩利根先聞大道，聲聞淺劣後入佛慧，明既其證也。"}]},{"p":9762,"q":"佛自住大乘，如其所得法，定慧力莊","notes":[{"by":"法華義疏","era":"","t":"則所乘之法也。"}]},{"p":9882,"q":"舍利弗當知，我本立誓願，欲令一切","notes":[{"by":"曉師","era":"元","t":"案云：此文正明如來所願滿足。"}]},{"p":9954,"q":"我知此眾生","notes":[{"by":"法華義疏","era":"","t":"上明生惱謂現報也，從此以下明生後二報也。"}]},{"p":10002,"q":"受胎之微形","notes":[{"by":"法華義疏","era":"","t":"細論胎內時分不同，為世世增長。"}]},{"p":10026,"q":"入邪見稠林","notes":[{"by":"法華義疏","era":"","t":"此中有一見二見乃至六十二見。"}]},{"p":10050,"q":"深著虛妄法","notes":[{"by":"法華義疏","era":"","t":"上來從正使生正使，今從正使生於纏垢，諂即六垢之一也。"}]},{"p":10092,"q":"如是人難度","notes":[{"by":"法華義疏","era":"","t":"總此愛見眾生難可以一乘法度之。"}]},{"p":10116,"q":"示之以涅槃","notes":[{"by":"法華義疏","era":"","t":"有人言：涅槃有三種，初教以灰斷無為為寂滅，般若教以四諦平等為寂滅，此經明寶所俗外涅槃為寂滅也。"}]},{"p":10158,"q":"我有方便力","notes":[{"by":"法華義疏","era":"","t":"第三、勸信門。"}]},{"p":10194,"q":"諸佛語無異","notes":[{"by":"法華義疏","era":"","t":"以理既不二，教表於理故教亦無異。"}]},{"p":10230,"q":"如是諸世尊","notes":[{"by":"法華義疏","era":"","t":"上之法譬皆是善巧故名方便。"}]},{"p":10278,"q":"又諸大聖主","notes":[{"by":"法華義疏","era":"","t":"第二，一行半，就神通門明教意也。"}]},{"p":10302,"q":"更以異方便","notes":[{"by":"法華義疏","era":"","t":"有人言：上明三乘方便，今明人天乘異上三乘故名異方便。"}]},{"p":10338,"q":"精進","notes":[{"by":"法華義疏","era":"","t":"念念善法相續，不令餘念間之，謂無間修。"}]},{"p":10362,"q":"諸佛滅度已","notes":[{"by":"法華義疏","era":"","t":"第二、明佛滅度後修行成佛。"}]},{"p":10398,"q":"起萬億種塔","notes":[{"by":"法華義疏","era":"","t":"第三、明起塔。"}]},{"p":10495,"q":"若人為佛故","notes":[{"by":"法華義疏","era":"","t":"第四、明造像。"}]},{"p":10651,"q":"若人於塔廟","notes":[{"by":"法華義疏","era":"","t":"第五、明三業供養。"}]},{"p":10843,"q":"於諸過去佛","notes":[{"by":"法華義疏","era":"","t":"則是聞上來所說法皆得成佛也。"}]},{"p":10927,"q":"諸佛本誓願","notes":[{"by":"法華義疏","era":"","t":"第二、廣頌未來教意，亦開三門：初一行，辨本願願為明一；次一行，辨說法為明一；次兩行，就諸佛所證為明一。"}]},{"p":10951,"q":"未來世諸佛","notes":[{"by":"法華義疏","era":"","t":"第二、頌上未來世諸佛。"}]},{"p":10975,"q":"諸佛兩足尊","notes":[{"by":"法華義疏","era":"","t":"以菩提心假緣而起，故佛為說一乘令發菩提心，一乘教則是發菩提心緣也。"}]},{"p":11059,"q":"知第一寂滅，以方便力故，雖示種種","notes":[{"by":"法華義疏","era":"","t":"第二三偈廣頌上三事：初一行明三種法輪，"},{"by":"灌頂","era":"","t":"二、華敷譬開權，蓮現譬顯實。"}]},{"p":11131,"q":"今我亦如是","notes":[{"by":"法華義疏","era":"","t":"出安穩之方，令入於佛道，置安穩之處也。"}]},{"p":11179,"q":"舍利弗當知","notes":[{"by":"法華義疏","era":"","t":"如諸外道計三界苦為涅槃；檀提婆羅門指腹為涅槃，則計欲界苦為涅槃；阿羅羅外道計無想為涅槃，即計色界苦以為捨苦；欝頭監弗計非想為涅槃，則以無色苦而欲捨生死苦也。"}]},{"p":11383,"q":"我即自思惟","notes":[{"by":"法華義疏","era":"","t":"二章經始末有四思惟：不說一乘有二思惟，如前釋之：說於三乘亦二思惟，所以有二思惟者，隨順世法再思方決也。"}]},{"p":11420,"q":"我寧不說法","notes":[{"by":"法華義疏","era":"","t":"大段第三，明初成道時眾生既不堪受一乘故於一佛乘分別說三。"}]},{"p":11457,"q":"作是思惟時","notes":[{"by":"法華義疏","era":"","t":"第二、十方諸佛勸說三乘也。"}]},{"p":11506,"q":"我等亦皆得","notes":[{"by":"法華義疏","era":"","t":"第二、明諸佛自敘，則是獎勸。"}]},{"p":11567,"q":"舍利弗當知","notes":[{"by":"法華義疏","era":"","t":"第三、明無機之失也。"}]},{"p":11587,"q":"南無","notes":[{"by":"法華義疏","era":"","t":"雖有十方佛勸，若出好世亦不說三，今自省釋迦出於惡世，故宜受勸說三也。"}]},{"p":11617,"q":"思惟是事已","notes":[{"by":"法華義疏","era":"","t":"第二、釋疑密開壽量，明釋迦久解於一說三，非受諸佛勸始能說涅槃。"}]},{"p":11701,"q":"舍利弗當知","notes":[{"by":"法華義疏","era":"","t":"大機既發，有紹繼之能，為佛子義也。"}]},{"p":11725,"q":"咸以恭敬心","notes":[{"by":"法華義疏","era":"","t":"據事而論，既到佛所聽法，必尊人而重法也。"}]},{"p":11799,"q":"今我喜無畏","notes":[{"by":"法華義疏","era":"","t":"第二、正明說一乘也，指三乘人名為菩薩。"}]},{"p":11847,"q":"如三世諸佛","notes":[{"by":"法華義疏","era":"","t":"第三大段次明讚歎法。"}]},{"p":11979,"q":"汝等勿有疑","notes":[{"by":"法華義疏","era":"","t":"第四大段，明勸信也。"}]},{"p":12015,"q":"汝等舍利弗","notes":[{"by":"法華義疏","era":"","t":"大段第二示上根人弘經方法，上一周說竟。"}]},{"p":12087,"q":"有慚愧清淨","notes":[{"by":"法華義疏","era":"","t":"第二、勸是器應授。"}]},{"p":12117,"q":"諸佛法如是","notes":[{"by":"法華義疏","era":"","t":"要先權後實，此示所學之摸軌。"}]},{"p":12153,"q":"諸佛世之師","notes":[{"by":"法華義疏","era":"","t":"身子初聞略說謂佛是魔，聞後廣說方知是世大師，此半行明識人之邪正。"}]},{"p":12220,"q":"譬喻品","notes":[{"by":"法華義疏","era":"","t":"第二、發言自敘領解，候得其機乃敢發言也。"}]},{"p":12274,"q":"我昔從佛聞如是法","notes":[{"by":"法華義疏","era":"","t":"總敘昔日聞法也。"}]},{"p":12305,"q":"失於如來無量知見","notes":[{"by":"法華義疏","era":"","t":"同入法性，明所證是同，以小乘法而見濟度，明所得為異。"}]},{"p":12372,"q":"若我等待說所因","notes":[{"by":"法華義疏","era":"","t":"待謂當待之待，所因者謂學地六度等諸行，六度等諸行並是成極果之因，故謂諸行為所因也。"}]},{"p":12401,"q":"然我等不解方便隨宜所說","notes":[{"by":"法華義疏","era":"","t":"此第二、明自取於小。"}]},{"p":12433,"q":"我從昔來","notes":[{"by":"法華義疏","era":"","t":"第三、結歡喜也。"}]},{"p":12479,"q":"真是佛子","notes":[{"by":"法華義疏","era":"","t":"明佛子有二門：一者、小乘有五佛子，謂四果及緣覺；二者、大小合明五佛子，謂四果及法身菩薩。"}]},{"p":12535,"q":"疑網皆已除","notes":[{"by":"法華義疏","era":"","t":"解昔所得即是大乘，昔說大因為小果名於一說三，今悟小果即是大因故不失於大乘也。"}]},{"p":12577,"q":"我處於山谷","notes":[{"by":"法華義疏","era":"","t":"上明其現同，今傷其當果異，此半行明失化他果也。"}]},{"p":12685,"q":"我獨經行時","notes":[{"by":"法華義疏","era":"","t":"此頌長行中在會見聞故悔，接前偈來者，上明失於德果，今明失名聞果。"}]},{"p":12721,"q":"我常於日夜","notes":[{"by":"法華義疏","era":"","t":"自上已來皆頌昔悔，此二行偈，第二、頌於悔後生疑，兩偈為二：初偈、獨處生疑；次偈、在會生疑。"}]},{"p":12769,"q":"今聞佛音聲","notes":[{"by":"法華義疏","era":"","t":"自上已來都是序二疑二悔故憂，此一行偈聞今教疑悔得除故信解。"}]},{"p":12793,"q":"我本著邪見","notes":[{"by":"法華義疏","era":"","t":"刪闍夜去世，以二百五十人門徒付囑身子，為諸梵志師也。"}]},{"p":12853,"q":"若得作佛時","notes":[{"by":"法華義疏","era":"","t":"前半行領識迷，即領開方便門。"}]},{"p":12889,"q":"佛於大眾中","notes":[{"by":"法華義疏","era":"","t":"第三、一行稱歎佛，即序得悟之由也。"}]},{"p":12913,"q":"初聞佛所說","notes":[{"by":"法華義疏","era":"","t":"夫虛危假誑必心神睒爍，而今安定惔靜即知非魔，安者如山之安、如海之曠，心神既同山海，則知非魔，故疑斷也。"}]},{"p":13009,"q":"如今者世尊","notes":[{"by":"法華義疏","era":"","t":"第三、領順同門。"}]},{"p":13033,"q":"世尊說實道","notes":[{"by":"法華義疏","era":"","t":"第二、結於邪正。"}]},{"p":13057,"q":"我墮疑網故","notes":[{"by":"法華義疏","era":"","t":"第三、此半偈身子引過歸已自悔責也。"}]},{"p":13130,"q":"爾時佛告舍利弗","notes":[{"by":"法華義疏","era":"","t":"上明身子本學大時，今第二、辨中途棄大取小時。"}]},{"p":13158,"q":"我昔曾於二萬億佛所","notes":[{"by":"法華義疏","era":"","t":"上明教被緣，今明緣受教。"}]},{"p":13229,"q":"我今還欲","notes":[{"by":"法華義疏","era":"","t":"此第三、明今為說大時，初憶念本願，謂菩提心所行道故謂菩薩行，欲令聲聞續菩提心還修菩薩行，故說《法華》也。"}]},{"p":13275,"q":"汝於未來世","notes":[{"by":"法華義疏","era":"","t":"第四大段，為身子授記。"}]},{"p":13315,"q":"當得作佛","notes":[{"by":"法華義疏","era":"","t":"或可從時事以立名，如《智論》釋〈往生品〉明三百比丘脫衣上佛舉手為相，得成佛時名為大相。"}]},{"p":13362,"q":"國名離垢","notes":[{"by":"法華義疏","era":"","t":"上標土名、今出土體。"}]},{"p":13392,"q":"有八交道","notes":[{"by":"法華義疏","era":"","t":"別明道莊嚴也。"}]},{"p":13420,"q":"華光如來亦以三乘教化","notes":[{"by":"法華義疏","era":"","t":"第三、明教門果也。"}]},{"p":13458,"q":"其劫名大寶莊嚴","notes":[{"by":"法華義疏","era":"","t":"第四、明時節果。"}]},{"p":13486,"q":"彼諸菩薩","notes":[{"by":"法華義疏","era":"","t":"第五、明眷屬果。"}]},{"p":13608,"q":"舍利弗！華光佛壽","notes":[{"by":"法華義疏","era":"","t":"第六、壽命果。"}]},{"p":13640,"q":"華光如來過十二小劫","notes":[{"by":"法華義疏","era":"","t":"第七、明紹繼果。"}]},{"p":13682,"q":"號曰華足安行","notes":[{"by":"法華義疏","era":"","t":"寶華承足安祥而行也。"}]},{"p":13704,"q":"其佛國土亦復如是","notes":[{"by":"法華義疏","era":"","t":"雖有異佛興世而淨土不改，亦是悅往生者之心也。"}]},{"p":14006,"q":"華光佛所為","notes":[{"by":"法華義疏","era":"","t":"半行，第三、總結也。"}]},{"p":14043,"q":"爾時四部眾","notes":[{"by":"法華義疏","era":"","t":"第二、明大眾歡喜悟解。"}]},{"p":14095,"q":"見舍利弗","notes":[{"by":"法華義疏","era":"","t":"第二、明歡喜之緣。"}]},{"p":14114,"q":"心大歡喜","notes":[{"by":"法華義疏","era":"","t":"第二、別明諸天供養稱歎。"}]},{"p":14190,"q":"而自迴轉","notes":[{"by":"法華義疏","era":"","t":"亦不停空，表心離空也。"}]},{"p":14219,"q":"而作是言","notes":[{"by":"法華義疏","era":"","t":"第二、明法供養。"}]},{"p":14283,"q":"五眾之生滅","notes":[{"by":"法華義疏","era":"","t":"古經為立陰，釋道安云："}]},{"p":14349,"q":"大智舍利弗","notes":[{"by":"法華義疏","era":"","t":"第二、明預欣得記歡喜。"}]},{"p":14385,"q":"佛道叵思議","notes":[{"by":"法華義疏","era":"","t":"領顯真實義，"}]},{"p":14422,"q":"爾時舍利弗","notes":[{"by":"法華義疏","era":"","t":"第二大段，正明譬說。"}]},{"p":14459,"q":"是諸千二百","notes":[{"by":"法華義疏","era":"","t":"第二、騰眾未悟。"}]},{"p":14519,"q":"而今於世尊前","notes":[{"by":"法華義疏","era":"","t":"就佛受請說中復開為三：第一、緣起。"}]},{"p":14633,"q":"諸有智者以譬喻得解","notes":[{"by":"法華義疏","era":"","t":"舍之所以立為柱之所駐，果法所以存以命根之所持，既以陰身為舍，宜用命根為柱，命根勢稍窮報身將壞，其由柱根腐敗堂舍將倒。"}]},{"p":14755,"q":"三十","notes":[{"by":"法華義疏","era":"","t":"譬菩薩，聲聞德少故數少，菩薩德多故數多。"}]},{"p":15305,"q":"各賜諸子等一大車","notes":[{"by":"曉師","era":"元","t":"四者此經中說一切種智，無□不盡、無德不備，一切眾生同到此果。"}]},{"p":16708,"q":"以佛教門出三界苦","notes":[{"by":"法華義疏","era":"","t":"今將所燒之言簡異前門，故知詺三界以之為門。"}]},{"p":16780,"q":"皆以如來滅度而滅度之","notes":[{"by":"胡吉藏","era":"","t":"又舉佛果眾德以合大車，故云"}]},{"p":16965,"q":"當知諸佛方便力故，於一佛乘分別說","notes":[{"by":"曉師","era":"元","t":"此言正開方便之門，諸餘言語例此可知。"},{"by":"胡吉藏","era":"","t":"三中之二目之為麁，佛乘為勝故稱為妙。"}]},{"p":17295,"q":"嬉戲","notes":[{"by":"法華義疏","era":"","t":"貪著五欲無所剋獲也。"}]},{"p":17820,"q":"是時長者","notes":[{"by":"法華義疏","era":"","t":"第四、父見子免難歡喜譬也。"}]},{"p":18168,"q":"大車","notes":[{"by":"法華義疏","era":"","t":"第二，標大車章門。"}]},{"p":18261,"q":"形體姝好","notes":[{"by":"法華義疏","era":"","t":"無有相貌為形體，寂滅微妙為姝好。"}]},{"p":18322,"q":"舍利弗","notes":[{"by":"法華義疏","era":"","t":"第六、明不虛譬。"}]},{"p":18339,"q":"之父","notes":[{"by":"法華義疏","era":"","t":"合上長者也。"}]},{"p":18392,"q":"如是等","notes":[{"by":"法華義疏","era":"","t":"第四、總結眾苦也。"}]},{"p":18457,"q":"能為救護","notes":[{"by":"法華義疏","era":"","t":"接上言勢仍發下語，故言以是方便也。"}]},{"p":18542,"q":"汝舍利弗","notes":[{"by":"法華義疏","era":"","t":"頌合第五、等賜大車譬。"}]},{"p":18567,"q":"信受是語","notes":[{"by":"法華義疏","era":"","t":"第二、就人門嘆，亦為二：初一句，明佛所稱歎；次三句，明除佛以下九道眾生並應稱歎也。"}]},{"p":18622,"q":"無量億千","notes":[{"by":"法華義疏","era":"","t":"一行，第二、出乘體，亦有二義：初三句，就佛實慧以為乘體；次一句，明佛權智以為乘體也。"}]},{"p":18642,"q":"得如是乘","notes":[{"by":"法華義疏","era":"","t":"第三兩偈，頌得車歡喜。"}]},{"p":18682,"q":"以是因緣","notes":[{"by":"法華義疏","era":"","t":"此文有二義故來，一者、近接"}]},{"p":18703,"q":"告舍利弗","notes":[{"by":"法華義疏","era":"","t":"此是頌長行第三大段，勸弘經也。"}]},{"p":18756,"q":"但盡生死","notes":[{"by":"法華義疏","era":"","t":"第二，有十一偈，引菩薩為證明大小權實。"}]},{"p":18856,"q":"若有眾生","notes":[{"by":"法華義疏","era":"","t":"次合辟支佛乘，略不明內因。"}]},{"p":18881,"q":"方便說道","notes":[{"by":"法華義疏","era":"","t":"此非道諦之道，乃是噵說之道也。"}]},{"p":18926,"q":"離諸苦縛","notes":[{"by":"法華義疏","era":"","t":"第二段，偏就滅諦以明權實。"}]},{"p":18946,"q":"但離虛妄","notes":[{"by":"法華義疏","era":"","t":"四住煩惱是凡夫所起，能感分段虛妄生死，故稱虛妄。"}]},{"p":18996,"q":"我為法王","notes":[{"by":"法華義疏","era":"","t":"第三，舉法王釋疑。"}]},{"p":19016,"q":"汝舍利弗","notes":[{"by":"法華義疏","era":"","t":"以理為印，謂文與理相應則應信受，文乖此理則不應信。"}]},{"p":19041,"q":"勿妄宣傳","notes":[{"by":"法華義疏","era":"","t":"非器若傳則有損無益，故方等如甘露亦名為毒藥。"}]},{"p":19206,"q":"又舍利弗","notes":[{"by":"法華義疏","era":"","t":"第二、廣明誡勸。"}]},{"p":19246,"q":"若人不信","notes":[{"by":"法華義疏","era":"","t":"第二、明五種人過。"}]},{"p":19336,"q":"其人命終","notes":[{"by":"法華義疏","era":"","t":"第二、明五種人得果者，凡有三義：一者，上來皆言莫為說之，亦似若無慈，何名菩薩？"}]},{"p":19366,"q":"從地獄出","notes":[{"by":"法華義疏","era":"","t":"第二，明餘報墮於畜生。"}]},{"p":19527,"q":"其形長大","notes":[{"by":"法華義疏","era":"","t":"瞋大法故受大苦身，不耐聞法故聾，愚癡謗故騃，不受行法故無足，多令眾生不信故為諸小虫所食。"}]},{"p":19577,"q":"若得為人","notes":[{"by":"法華義疏","era":"","t":"第三、明餘報。"}]},{"p":19777,"q":"常處地獄","notes":[{"by":"法華義疏","era":"","t":"第二周，重明三品罪。"}]},{"p":19867,"q":"深著我見","notes":[{"by":"法華義疏","era":"","t":"自上已來明受三品苦報。"}]},{"p":19898,"q":"告舍利弗","notes":[{"by":"法華義疏","era":"","t":"第二、總結。"}]},{"p":19941,"q":"若有利根","notes":[{"by":"法華義疏","era":"","t":"第二、廣釋勸義。"}]},{"p":20362,"q":"從佛所聞","notes":[{"by":"法華義疏","era":"","t":"第二、明所聞之法，即是得解之緣。"}]},{"p":20388,"q":"發希有心","notes":[{"by":"法華義疏","era":"","t":"第三、內心歡喜，正是領解也。"}]},{"p":20406,"q":"偏袒右肩","notes":[{"by":"法華義疏","era":"","t":"未起之時正被袈裟，外國依律不著障𦝨及偏袒衣著者得突吉羅罪。"}]},{"p":20430,"q":"而白佛言","notes":[{"by":"法華義疏","era":"","t":"四因緣故不求無上菩提：一者、居僧之首，但是誨授於他，非自進求之時也。"}]},{"p":20474,"q":"世尊往昔說法既久","notes":[{"by":"法華義疏","era":"","t":"前明住小不求於大，今明非但不求親聞大法，亦不一念好樂。"}]},{"p":20550,"q":"又今我等","notes":[{"by":"法華義疏","era":"","t":"意志衰畢不堪自進業也。"}]},{"p":20584,"q":"我等今於佛前","notes":[{"by":"法華義疏","era":"","t":"第二、明今了悟序得解歡喜。"}]},{"p":20606,"q":"心甚歡喜","notes":[{"by":"法華義疏","era":"","t":"正明歡喜也。"}]},{"p":20630,"q":"深自慶幸","notes":[{"by":"法華義疏","era":"","t":"前明歡喜，今自慶也。"}]},{"p":20651,"q":"世尊！我等今者樂說譬喻以明斯義","notes":[{"by":"法華義疏","era":"","t":"就迹而言，昔菩薩時共為父子，而子背父流浪生死貧窮困苦，而父失子行滿成佛眾德圓具如大富也。"}]},{"p":20781,"q":"多有僮僕","notes":[{"by":"法華義疏","era":"","t":"初成道時但說菩薩大行，未說二乘人本是佛子、曾受大化，今違化久也。"}]},{"p":20919,"q":"是以慇懃","notes":[{"by":"法華義疏","era":"","t":"結念子意，有二因緣：一、佛去世；二、無人紹繼故法寶散失，所以憶子。"}]},{"p":20949,"q":"無復憂慮","notes":[{"by":"法華義疏","era":"","t":"既一期得子即付之以法財，令傳化不絕為無盡法燈則暢佛本心，故無復覓不得之憂，亦無散失大乘法財之慮也。"}]},{"p":21003,"q":"恭敬圍繞","notes":[{"by":"法華義疏","era":"","t":"也，如《華嚴》十世界微塵數菩薩也。"}]},{"p":21084,"q":"窮子見父","notes":[{"by":"法華義疏","era":"","t":"小機稟大，進無入理之福，退有違教之罪，故稱為悔。"}]},{"p":21119,"q":"非我傭力得物之處","notes":[{"by":"法華義疏","era":"","t":"大乘道玄理絕，非修五戒十善得人天小果之物處也。"}]},{"p":21172,"q":"時富長者","notes":[{"by":"法華義疏","era":"","t":"釋歡喜凡有三意：初、明既有可化之理，將可付以法財故歡喜。"}]},{"p":21241,"q":"即遣傍人","notes":[{"by":"法華義疏","era":"","t":"初成道時即顯說大乘，欲令了悟大乘，故稱為急。"}]},{"p":21310,"q":"此必定死","notes":[{"by":"法華義疏","era":"","t":"教大機小乖其本情，心生不信則起誹謗，斷於慧命如必定死。"}]},{"p":21331,"q":"語使言","notes":[{"by":"法華義疏","era":"","t":"大乘理不容小機，為"}]},{"p":21357,"q":"莫復與語","notes":[{"by":"法華義疏","era":"","t":"知其過去曾發大心，故云審知是子。"}]},{"p":21404,"q":"使者語之","notes":[{"by":"法華義疏","era":"","t":"即四諦、十二因緣二教，能詮於理故名人也。"}]},{"p":21499,"q":"窮子若許","notes":[{"by":"法華義疏","era":"","t":"從世間入出世間為將來，正稟於教令如說修行稱為使作。"}]},{"p":21530,"q":"我等二人亦共汝作","notes":[{"by":"法華義疏","era":"","t":"二乘不能離文求理，籍教詮理方能斷結，則教有助智斷結之功，為共作義也。"}]},{"p":21561,"q":"爾時窮子","notes":[{"by":"法華義疏","era":"","t":"第二、受命而說。"}]},{"p":21585,"q":"又以他日","notes":[{"by":"法華義疏","era":"","t":"前是思惟不堪受大教、堪受小教時，今是思惟不堪見本身、堪見迹身，故云他日也。"}]},{"p":21614,"q":"即脫瓔珞","notes":[{"by":"法華義疏","era":"","t":"上二句示凡方便，從兜率天下竟道樹之前事等也。"}]},{"p":21695,"q":"汝常此作","notes":[{"by":"法華義疏","era":"","t":"上雖勸常在此作，誡令勿復餘去，恐不受誡勸，故以加價誘之。"}]},{"p":21769,"q":"汝常作時","notes":[{"by":"法華義疏","era":"","t":"第四、稱嘆也。"}]},{"p":21823,"q":"爾時窮子雖欣此遇","notes":[{"by":"法華義疏","era":"","t":"未識大乘為客作，尚守小分為賤人也。"}]},{"p":21861,"q":"心相體信","notes":[{"by":"法華義疏","era":"","t":"有人言：三乘化功為命，今將說《法華》，三乘化功應斷，斷故稱死。"}]},{"p":21928,"q":"汝悉知之","notes":[{"by":"法華義疏","era":"","t":"令其知上略廣受授之事也。"}]},{"p":21979,"q":"領知眾物","notes":[{"by":"法華義疏","era":"","t":"〈序品〉初身子白佛，〈三假品〉始善吉受命。"}]},{"p":22002,"q":"然其所止故在本處，下劣之心亦未能","notes":[{"by":"法華義疏","era":"","t":"上明不取於大，此辨未捨於小也。"}]},{"p":22039,"q":"自鄙先心","notes":[{"by":"法華義疏","era":"","t":"昔日為說大乘教，生其大乘之解，即以後句釋上是子之言也。"}]},{"p":22153,"q":"今我所有","notes":[{"by":"法華義疏","era":"","t":"第四、正委家業，即領上授身子記之言也。"}]},{"p":22182,"q":"是時窮子","notes":[{"by":"法華義疏","era":"","t":"第三、領解歡喜也。"}]},{"p":22230,"q":"大富長者","notes":[{"by":"法華義疏","era":"","t":"釋上皆似佛子之言；如來常說我等為子，非我自稱也。"}]},{"p":22316,"q":"一日之價","notes":[{"by":"法華義疏","era":"","t":"小乘果卑賤微也，如一年傭作一日詶勞。"}]},{"p":22357,"q":"然世尊","notes":[{"by":"法華義疏","era":"","t":"第二、釋疑。"}]},{"p":22394,"q":"寶藏之分","notes":[{"by":"法華義疏","era":"","t":"如來智慧即是一乘，故於一佛乘分別說三也。"}]},{"p":22441,"q":"我等又因如來智慧","notes":[{"by":"法華義疏","era":"","t":"第四、合付財密化譬。"}]},{"p":22468,"q":"所以者何","notes":[{"by":"法華義疏","era":"","t":"舉三事釋佛無吝：一者、我昔有大機即為說大，由我昔無大機故佛不為說大，故知佛昔無吝也。"}]},{"p":22502,"q":"今我等方知","notes":[{"by":"法華義疏","era":"","t":"第五、合委囑家業譬。"}]},{"p":22557,"q":"於此經中唯說一乘","notes":[{"by":"法華義疏","era":"","t":"第二、以佛今為我說一乘，故知佛無吝也。"}]},{"p":22591,"q":"是故我等","notes":[{"by":"法華義疏","era":"","t":"合第二、領解歡喜譬也。"}]},{"p":22628,"q":"爾時摩訶迦葉","notes":[{"by":"法華義疏","era":"","t":"第二、偈頌。"}]},{"p":22686,"q":"譬如童子","notes":[{"by":"法華義疏","era":"","t":"上明解小，今辨惑多也。"}]},{"p":22716,"q":"其父憂念","notes":[{"by":"法華義疏","era":"","t":"頌上第三、頓止一城以待於子。"}]},{"p":22767,"q":"象馬牛羊","notes":[{"by":"法華義疏","era":"","t":"此歎外富，謂教門也。"}]},{"p":22787,"q":"出入息利","notes":[{"by":"法華義疏","era":"","t":"上明一國之富，今明富遍他國，猶是釋迦所化徒眾義耳。"}]},{"p":22807,"q":"千萬億眾","notes":[{"by":"法華義疏","era":"","t":"第二、嘆父貴義。"}]},{"p":22837,"q":"以諸緣故","notes":[{"by":"法華義疏","era":"","t":"一行，結富貴義。"}]},{"p":22897,"q":"爾時窮子","notes":[{"by":"法華義疏","era":"","t":"二偈，頌上第二至城時也。"}]},{"p":22927,"q":"飢餓羸瘦","notes":[{"by":"法華義疏","era":"","t":"上明善小，今辨惑多，外則受於譏毀，內為眾惑所瘵塵也。"}]},{"p":22964,"q":"門內","notes":[{"by":"法華義疏","era":"","t":"明少多義，如五十二位深淺不同。"}]},{"p":23069,"q":"借問貧里","notes":[{"by":"法華義疏","era":"","t":"于時佛未說人天之教，但有人天之機扣佛說人天之教，如借問貧里也。"}]},{"p":23099,"q":"即勅使者","notes":[{"by":"法華義疏","era":"","t":"頌第五、喚子不得譬。"}]},{"p":23141,"q":"長者知子","notes":[{"by":"法華義疏","era":"","t":"頌第七、誘引還家譬也。"}]},{"p":23203,"q":"窮子聞之","notes":[{"by":"法華義疏","era":"","t":"六根非一如諸房舍，除六根中煩惱如淨也。"}]},{"p":23263,"q":"方便附近","notes":[{"by":"法華義疏","era":"","t":"外國作使之人足多龜坼故以油塗之，譬得六通而足不履地也。"}]},{"p":23313,"q":"若如我子","notes":[{"by":"法華義疏","era":"","t":"得羅漢果後始命說《波若》，如除糞已後方乃付財，則知命說之時猶住二乘位，故稱經二十年也。"}]},{"p":23381,"q":"父知子心","notes":[{"by":"法華義疏","era":"","t":"頌第十、委囑家業譬。"}]},{"p":23411,"q":"於此大眾","notes":[{"by":"法華義疏","era":"","t":"頌第三、結會父子。"}]},{"p":23441,"q":"昔於某城","notes":[{"by":"法華義疏","era":"","t":"頌第三、父得於子。"}]},{"p":23461,"q":"凡我所有","notes":[{"by":"法華義疏","era":"","t":"頌第四、正委付財物。"}]},{"p":23481,"q":"子念昔貧","notes":[{"by":"法華義疏","era":"","t":"頌第三、得家業歡喜。"}]},{"p":23521,"q":"佛亦如是","notes":[{"by":"法華義疏","era":"","t":"第二、頌合譬。"}]},{"p":23563,"q":"佛勅我等","notes":[{"by":"法華義疏","era":"","t":"頌第三、付財密化譬。"}]},{"p":23583,"q":"我承佛教","notes":[{"by":"法華義疏","era":"","t":"第二、頌子受。"}]},{"p":23685,"q":"如彼窮子","notes":[{"by":"法華義疏","era":"","t":"第二，有三行，頌不識父意。"}]},{"p":23725,"q":"我等內滅","notes":[{"by":"法華義疏","era":"","t":"凡有三種義：一、約大小乘明內外，大乘具滅三界內外，小乘但滅三界內，故稱內滅。"}]},{"p":23765,"q":"所以者何","notes":[{"by":"法華義疏","era":"","t":"二偈，釋不欣大也。"}]},{"p":23805,"q":"我等長夜","notes":[{"by":"法華義疏","era":"","t":"第二、聞佛果德不生欣樂。"}]},{"p":23935,"q":"如富長者","notes":[{"by":"法華義疏","era":"","t":"若別取即是第七誘引還家，說二乘譬名為方便。"}]},{"p":23965,"q":"佛亦如是","notes":[{"by":"法華義疏","era":"","t":"一行半偈，雙合二譬也。"}]},{"p":23995,"q":"我等今日","notes":[{"by":"法華義疏","era":"","t":"第二、頌上領解歡喜。"}]},{"p":24025,"q":"世尊我今","notes":[{"by":"法華義疏","era":"","t":"昔得小乘道諦之道、滅諦之果，今得大乘道果，如《大品》云"}]},{"p":24065,"q":"法王法中","notes":[{"by":"法華義疏","era":"","t":"第三，有人言：通取一切戒為梵行，別名斷婬為梵行。"}]},{"p":24085,"q":"我等今者","notes":[{"by":"法華義疏","era":"","t":"前三即是三學之法次第，今明人利益，初偈明智果，謂為他說法生他之慧，次一偈半明斷果，謂受他供養生他之福。"}]},{"p":24135,"q":"世尊大恩","notes":[{"by":"法華義疏","era":"","t":"第二大段，嘆佛恩深難報。"}]},{"p":24165,"q":"手足供給","notes":[{"by":"法華義疏","era":"","t":"釋二章門：前、逐近釋報恩章門；次、釋作恩章門。"}]},{"p":24265,"q":"諸佛希有","notes":[{"by":"法華義疏","era":"","t":"釋作恩章門，又二：初二行，明神通輪恩；次四行半，明說法輪恩。"}]},{"p":24432,"q":"藥草喻品","notes":[{"by":"法華義疏","era":"","t":"藥是草木中治病之通稱，草即形木之別名，而言藥草者，通、別兩舉者也。"}]},{"p":24471,"q":"誠如所言","notes":[{"by":"法華義疏","era":"","t":"兩善哉述其言巧，誠如所言印其事實。"}]},{"p":24510,"q":"是諸法之王","notes":[{"by":"法華義疏","era":"","t":"上十譬十恩但明一方之化即未能自在，今明諸法之王即知化之無方。"}]},{"p":24553,"q":"如來觀知一切諸法之所歸趣","notes":[{"by":"法華義疏","era":"","t":"第五句，明佛知一切法終歸至極。"}]},{"p":24582,"q":"又於諸法究盡明了","notes":[{"by":"法華義疏","era":"","t":"有人言：此譬五乘眾生所住處，下明草木喻能住五乘之眾生也。"}]},{"p":24717,"q":"一雲所雨","notes":[{"by":"法華義疏","era":"","t":"第二、明教稱緣也。"}]},{"p":24779,"q":"以大音聲","notes":[{"by":"法華義疏","era":"","t":"第二、總舉聲合雲，次亦以譬帖之。"}]},{"p":24813,"q":"而唱是言","notes":[{"by":"法華義疏","era":"","t":"第三、舉外號合雲。"}]},{"p":24860,"q":"未度者令度","notes":[{"by":"法華義疏","era":"","t":"第四、舉內德以合雲。"}]},{"p":24897,"q":"我是一切知者","notes":[{"by":"法華義疏","era":"","t":"然二乘人又有一切智，如《大品．三慧品》說，而無五眼，故說一切見也。"}]},{"p":24943,"q":"爾時無數","notes":[{"by":"法華義疏","era":"","t":"第二、合草木譬，即受勸而來也。"}]},{"p":24962,"q":"如來于時","notes":[{"by":"法華義疏","era":"","t":"第三、合澍雨譬。"}]},{"p":24990,"q":"種種無量","notes":[{"by":"法華義疏","era":"","t":"別合增長，有二：前、約世間利合增長。"}]},{"p":25029,"q":"亦得聞法","notes":[{"by":"法華義疏","era":"","t":"明得出世利以合增長，亦有三句：初是聞慧；"}]},{"p":25098,"q":"一相一味","notes":[{"by":"法華義疏","era":"","t":"合上一地所生一雨所潤也。"}]},{"p":25117,"q":"究竟至於一切種智","notes":[{"by":"胡吉藏","era":"","t":"此舉智果究竟，顯二乘人智不究竟也。"},{"by":"法華義疏","era":"","t":"合上而諸草木各有差別譬也。"}]},{"p":25150,"q":"不自覺知","notes":[{"by":"法華義疏","era":"","t":"第三、明三慧之因，方便不同宿習各異也。"}]},{"p":25262,"q":"如來知是一相","notes":[{"by":"法華義疏","era":"","t":"第二，明佛知同、眾生不知同也。"}]},{"p":25390,"q":"破有法王","notes":[{"by":"法華義疏","era":"","t":"有人言：破二十五有名為破有，如《涅槃》明得二十五三昧、破二十五有。"}]},{"p":25410,"q":"如來尊重","notes":[{"by":"法華義疏","era":"","t":"竪不見其底為深，橫不惻其邊名遠，此歎佛內智也。"}]},{"p":25450,"q":"是故迦葉","notes":[{"by":"法華義疏","era":"","t":"遙觀彼雲可言傍攬及以下承，如來府順於物如可承攬，不同眾生故不可捉持，即是不思議也。"}]},{"p":25580,"q":"雨之所潤","notes":[{"by":"法華義疏","era":"","t":"頌第五、受潤譬。"}]},{"p":25620,"q":"一切諸樹","notes":[{"by":"法華義疏","era":"","t":"頌第六、增長譬。"}]},{"p":25660,"q":"如其體相","notes":[{"by":"法華義疏","era":"","t":"合頌第七第八同異譬。"}]},{"p":25680,"q":"佛亦如是","notes":[{"by":"法華義疏","era":"","t":"頌第二、合譬。"}]},{"p":25751,"q":"出于世間","notes":[{"by":"法華義疏","era":"","t":"兩偈，頌第四、舉德合雲。"}]},{"p":25792,"q":"諸天人眾","notes":[{"by":"法華義疏","era":"","t":"兩偈，頌長行第二、勸眾聽受。"}]},{"p":25833,"q":"為大眾說","notes":[{"by":"法華義疏","era":"","t":"第二，八偈，頌合兩譬。"}]},{"p":25873,"q":"我觀一切","notes":[{"by":"法華義疏","era":"","t":"第二，二偈半，借雨平等義以合譬。"}]},{"p":25923,"q":"常演說法","notes":[{"by":"法華義疏","era":"","t":"第三，三行半，借雨無惓義以合譬。"}]},{"p":25953,"q":"貴賤上下","notes":[{"by":"法華義疏","era":"","t":"二偈，舉所化之人顯成能化等說無惓，此即兼合草木義也。"}]},{"p":25993,"q":"一切眾生","notes":[{"by":"法華義疏","era":"","t":"第三，十一行偈，合受潤譬。"}]},{"p":26153,"q":"佛平等說","notes":[{"by":"法華義疏","era":"","t":"一行半，第二、明理一而隨眾生得益有異，即兼合上第七第八同異譬也。"}]},{"p":26183,"q":"佛以此喻","notes":[{"by":"法華義疏","era":"","t":"一行半，第三、歎佛智慧也。"}]},{"p":26208,"q":"如海一渧","notes":[{"by":"法華義疏","era":"","t":"上〈信解品〉十譬十恩稱歎於佛德，時眾謂如來之德盡在四大聲聞言下，故品初明八法八譬顯如來復有無量功德，時眾便謂歎佛德已盡，是故今明雖設此譬於佛智慧如海一渧也。"}]},{"p":26283,"q":"聲聞緣覺","notes":[{"by":"法華義疏","era":"","t":"第二，五行，別合。"}]},{"p":26383,"q":"如是迦葉","notes":[{"by":"法華義疏","era":"","t":"第二，一行半，明理唯是一隨緣得益為異，兼合上同異譬也。"}]},{"p":26413,"q":"迦葉當知","notes":[{"by":"法華義疏","era":"","t":"第三，一行半，稱歎諸佛。"}]},{"p":26443,"q":"今為汝等","notes":[{"by":"法華義疏","era":"","t":"大段第二，結示權實。"}]},{"p":26512,"q":"唱如是言","notes":[{"by":"法華義疏","era":"","t":"第二、正授記。"}]},{"p":26545,"q":"供養","notes":[{"by":"法華義疏","era":"","t":"頌得果：半行頌化主果，三行頌國土果，三行頌眷屬果。"}]},{"p":26653,"q":"國界嚴飾","notes":[{"by":"法華義疏","era":"","t":"重明國土果。"}]},{"p":26754,"q":"爾時世尊","notes":[{"by":"法華義疏","era":"","t":"第二、授三人記。"}]},{"p":26771,"q":"諸比丘","notes":[{"by":"法華義疏","era":"","t":"第三、明過十劫大通智勝成佛。"}]},{"p":27041,"q":"皆悉悚慄","notes":[{"by":"法華義疏","era":"","t":"三大弟子自謂已解大乘，而佛未為授記，三人恐所解非解墮增上慢，故悚慄也。"}]},{"p":29557,"q":"諸母涕泣而隨送之","notes":[{"by":"法華義疏","era":"","t":"愛情未斷是故涕泣，道緣已會故而隨送之。"}]},{"p":29842,"q":"爾時十六王子","notes":[{"by":"法華義疏","era":"","t":"第三、請轉法輪。"}]},{"p":29902,"q":"百福","notes":[{"by":"法華義疏","era":"","t":"一善有五品心，謂下、中、上、上中、上上，十善合五十，始有五十心，終有五十，故名百福也。"}]},{"p":30006,"q":"佛告諸比丘","notes":[{"by":"法華義疏","era":"","t":"第三、明成道已後現於瑞相。"}]},{"p":30094,"q":"又其國界","notes":[{"by":"法華義疏","era":"","t":"第三、明二瑞所至。"}]},{"p":30130,"q":"爾時東方","notes":[{"by":"法華義疏","era":"","t":"第四、明十方梵天雲集請轉法輪。"}]},{"p":30398,"q":"即以天華","notes":[{"by":"法華義疏","era":"","t":"明供養，初以華供養，表欲行因也。"}]},{"p":30597,"q":"爾時諸梵天王","notes":[{"by":"法華義疏","era":"","t":"第五、請轉法輪。"}]},{"p":30677,"q":"爾時大通智勝","notes":[{"by":"法華義疏","era":"","t":"第二、明近緣由。"}]},{"p":33387,"q":"汝等皆當數數親近","notes":[{"by":"法華義疏","era":"","t":"以與沙彌有緣故令親近，如十方佛勸常啼親近法涌。"}]},{"p":33457,"q":"佛告諸比丘","notes":[{"by":"法華義疏","era":"","t":"第二、明結緣已後世世相值。"}]},{"p":33479,"q":"一一菩薩","notes":[{"by":"法華義疏","era":"","t":"明現在所得益緣也。"}]},{"p":33499,"q":"世世所生","notes":[{"by":"法華義疏","era":"","t":"第三句、明後時得益也。"}]},{"p":33534,"q":"于今不盡","notes":[{"by":"法華義疏","era":"","t":"一者、過去善根未盡；二者、值多佛猶自未盡也。"}]},{"p":33901,"q":"我滅度後","notes":[{"by":"法華義疏","era":"","t":"第四段，明未來相值，即出下根人也。"}]},{"p":34010,"q":"如來方便","notes":[{"by":"法華義疏","era":"","t":"為釋疑故來。"}]},{"p":34032,"q":"眾又清淨","notes":[{"by":"法華義疏","era":"","t":"以四教調柔其心故得清淨，用人天及二乘教調伏其心，故無復凡夫煩惱，以付財密化及陶練小心，令二乘煩惱漸得消除，既離凡聖二惑，故言眾又清淨也。"}]},{"p":34087,"q":"比丘當知","notes":[{"by":"法華義疏","era":"","t":"第二、明說小。"}]},{"p":34136,"q":"譬如五百由旬","notes":[{"by":"法華義疏","era":"","t":"初發大心欲出離生死，遠求佛道欲離小行，而大解未成於此中間而退也。"}]},{"p":34234,"q":"今欲退還","notes":[{"by":"法華義疏","era":"","t":"前有引向大之能，今復解趣小巧，故云多也。"}]},{"p":34305,"q":"莫得退還","notes":[{"by":"法華義疏","era":"","t":"結累既盡，心得自在。"}]},{"p":34360,"q":"歎未曾有","notes":[{"by":"法華義疏","era":"","t":"以小乘法調柔其心除麁煩惱，心用稍強堪聞大乘也。"}]},{"p":34457,"q":"諸比丘","notes":[{"by":"法華義疏","era":"","t":"第三、合譬。"}]},{"p":34477,"q":"知諸生死","notes":[{"by":"法華義疏","era":"","t":"合上善知通塞之相兼求度之人也。"}]},{"p":34527,"q":"久受懃苦乃可得成","notes":[{"by":"法華義疏","era":"","t":"合上第二、佛照機也。"}]},{"p":34560,"q":"說二涅槃","notes":[{"by":"法華義疏","era":"","t":"上合度三百由旬竟，今餘有二百，故稱二地。"}]},{"p":34600,"q":"當觀察籌量所得涅槃非真實也","notes":[{"by":"法華義疏","era":"","t":"合上向者大城我所化作。"}]},{"p":34633,"q":"如彼導師","notes":[{"by":"法華義疏","era":"","t":"第四、舉譬怗合也。"}]},{"p":34788,"q":"彼佛十六子","notes":[{"by":"法華義疏","era":"","t":"第二、請轉法輪。"}]},{"p":34818,"q":"而請轉法輪","notes":[{"by":"法華義疏","era":"","t":"三句，頌第三。"}]},{"p":34838,"q":"世尊甚難值","notes":[{"by":"法華義疏","era":"","t":"頌第三現瑞。"}]},{"p":34862,"q":"東方諸世界","notes":[{"by":"法華義疏","era":"","t":"頌第四、十方梵天集。"}]},{"p":34886,"q":"諸梵見此相","notes":[{"by":"法華義疏","era":"","t":"一句，含於謀議，故具頌六也。"}]},{"p":34984,"q":"無量慧世尊","notes":[{"by":"法華義疏","era":"","t":"頌上第二、結緣近緣由。"}]},{"p":35040,"q":"六百萬億姟","notes":[{"by":"法華義疏","era":"","t":"長行明六百萬億那由他，今云姟是此間數，代彼那由他也。"}]},{"p":35058,"q":"第二說法時","notes":[{"by":"法華義疏","era":"","t":"兩行，頌多會說法。"}]},{"p":35106,"q":"時十六王子","notes":[{"by":"法華義疏","era":"","t":"頌第二、請說大法。"}]},{"p":35156,"q":"佛知童子心","notes":[{"by":"法華義疏","era":"","t":"頌第三、受請說大法。"}]},{"p":35216,"q":"彼佛說經已","notes":[{"by":"法華義疏","era":"","t":"頌說經竟入定。"}]},{"p":35240,"q":"是諸沙彌等","notes":[{"by":"法華義疏","era":"","t":"第二、頌正結緣。"}]},{"p":35312,"q":"彼佛滅度後","notes":[{"by":"法華義疏","era":"","t":"頌第二、世世相值。"}]},{"p":35384,"q":"我在十六數","notes":[{"by":"法華義疏","era":"","t":"頌第二大段，現在說法。"}]},{"p":35440,"q":"多毒獸","notes":[{"by":"法華義疏","era":"","t":"有愛見煩惱，能害法身慧命，為毒獸也。"}]},{"p":35480,"q":"時有一導師","notes":[{"by":"法華義疏","era":"","t":"頌第三、將導也。"}]},{"p":35556,"q":"尋時思方便","notes":[{"by":"法華義疏","era":"","t":"舍宅薗林皆在郭內，別譬果地諸餘功德，有漏五陰既名生死舍宅，無漏五陰聖人所栖為舍宅也。"}]},{"p":35630,"q":"諸人既入城","notes":[{"by":"法華義疏","era":"","t":"一行，頌第三、得益。"}]},{"p":35654,"q":"導師知息已","notes":[{"by":"法華義疏","era":"","t":"頌第三、後還說大譬。"}]},{"p":35716,"q":"我亦復如是","notes":[{"by":"法華義疏","era":"","t":"合第二、中途說小譬，上文有三：一、知機；二、說教；三、得益。"}]},{"p":35779,"q":"既知到涅槃","notes":[{"by":"法華義疏","era":"","t":"頌第三、後還說大譬。"}]},{"p":35815,"q":"唯有一佛乘，息處故說二。","notes":[{"by":"胡吉藏","era":"","t":"以此三周文證，故知開一為三但為二乘人，今會三歸一亦為二乘。"}]},{"p":35875,"q":"諸佛之導師","notes":[{"by":"法華義疏","era":"","t":"一行，頌第四、舉譬怗合也。"}]},{"p":35987,"q":"復聞宿世因緣之事","notes":[{"by":"法華義疏","era":"","t":"即大通智勝佛十劫坐道場及現瑞等事也。"}]},{"p":36048,"q":"而作是念","notes":[{"by":"法華義疏","era":"","t":"第三、默念領解。"}]},{"p":36105,"q":"唯佛世尊","notes":[{"by":"法華義疏","era":"","t":"第二、歎於七佛法中上弘下利之德。"}]},{"p":36142,"q":"我常稱其","notes":[{"by":"法華義疏","era":"","t":"第二句，歎其有上弘之功。"}]},{"p":36174,"q":"能於四眾","notes":[{"by":"法華義疏","era":"","t":"第三句，歎其下利之德。"}]},{"p":36201,"q":"自捨如來","notes":[{"by":"法華義疏","era":"","t":"第四句，出滿願之位，即十地人也。"}]},{"p":36262,"q":"又於諸佛所說空法","notes":[{"by":"法華義疏","era":"","t":"第三、合歎空有二慧，以具了空有方能無礙說法，不爾則成有所得也。"}]},{"p":36296,"q":"具足菩薩神通之力","notes":[{"by":"法華義疏","era":"","t":"第三，明以具通慧廣能益物。"}]},{"p":36346,"q":"又化無量","notes":[{"by":"法華義疏","era":"","t":"以下，別益求佛人也。"}]},{"p":36367,"q":"為淨佛土故","notes":[{"by":"法華義疏","era":"","t":"第二、歎淨佛國土。"}]},{"p":36404,"q":"今於我所","notes":[{"by":"法華義疏","era":"","t":"第三、歎於釋迦佛所說法中第一。"}]},{"p":36444,"q":"亦於未來","notes":[{"by":"法華義疏","era":"","t":"第二、多劫佛所修行。"}]},{"p":36498,"q":"漸漸具足","notes":[{"by":"法華義疏","era":"","t":"第三、歎修因圓滿也。"}]},{"p":36574,"q":"其佛以恒河沙","notes":[{"by":"法華義疏","era":"","t":"第二、明國土果。"}]},{"p":36597,"q":"地平如掌","notes":[{"by":"法華義疏","era":"","t":"釋有二：一云佛手掌平，指事為言；二云海底有石方四千里平如鏡面，名為掌石也。"}]},{"p":36620,"q":"諸天宮殿","notes":[{"by":"法華義疏","era":"","t":"第三、明眷屬果。"}]},{"p":36808,"q":"劫名寶明","notes":[{"by":"法華義疏","era":"","t":"上出土體、今辨土名。"}]},{"p":36949,"q":"雖小欲懈怠","notes":[{"by":"法華義疏","era":"","t":"雖現小乘威儀說於小教，似如於菩薩法懈怠，而實非懈怠。"}]},{"p":37033,"q":"今此富樓那","notes":[{"by":"法華義疏","era":"","t":"頌第二、過去行因也。"}]},{"p":37153,"q":"未來亦供養","notes":[{"by":"法華義疏","era":"","t":"頌未來行因。"}]},{"p":37213,"q":"其後得成佛","notes":[{"by":"法華義疏","era":"","t":"頌得果為二：初、別頌得果；次、總結。"}]},{"p":37321,"q":"法喜禪悅食","notes":[{"by":"法華義疏","era":"","t":"則定慧能資養法身，故名食也。"}]},{"p":37345,"q":"富樓那比丘","notes":[{"by":"法華義疏","era":"","t":"第二，一行半，總結淨土也。"}]},{"p":37382,"q":"爾時千二百","notes":[{"by":"法華義疏","era":"","t":"第二、授餘聲聞記。"}]},{"p":37426,"q":"不亦快乎","notes":[{"by":"法華義疏","era":"","t":"千二百羅漢見諸人得別記，謂己不得別記故來請之，若得別記，成佛事定故稱為快。"}]},{"p":37476,"q":"於此眾中","notes":[{"by":"法華義疏","era":"","t":"第二、別授記。"}]},{"p":37575,"q":"迦留陀夷","notes":[{"by":"法華義疏","era":"","t":"迦留此翻時，陀夷名之為起。"}]},{"p":37601,"q":"周陀","notes":[{"by":"法華義疏","era":"","t":"翻為善來，本名惡來，外國亦云沙竭陀亦云沙伽陀。"}]},{"p":37877,"q":"迦葉汝已知","notes":[{"by":"法華義疏","era":"","t":"第三段，命迦葉令宣記。"}]},{"p":37914,"q":"爾時五百","notes":[{"by":"法華義疏","era":"","t":"第二、自敘領解。"}]},{"p":37949,"q":"悔過自責","notes":[{"by":"法華義疏","era":"","t":"背大取小、執小疑大，皆是己之鈍根，故自責也。"}]},{"p":37984,"q":"所以者何","notes":[{"by":"法華義疏","era":"","t":"第四、解釋。"}]},{"p":38011,"q":"譬如有人","notes":[{"by":"法華義疏","era":"","t":"乃謂涅槃可證，所存非本故云他國；即大乘為本國，二乘教為他國也。"}]},{"p":38095,"q":"於後親友會遇見之","notes":[{"by":"法華義疏","era":"","t":"即說小教之後，大機潛發名為會遇，為佛智所照稱為見之也。"}]},{"p":38160,"q":"而汝不知","notes":[{"by":"法華義疏","era":"","t":"忘大取小蓋是無明煩惱，故稱癡也。"}]},{"p":38203,"q":"佛亦如是","notes":[{"by":"法華義疏","era":"","t":"第二、合棄大取小譬，即兼合上醉酒而臥也。"}]},{"p":38267,"q":"今者世尊覺悟我等","notes":[{"by":"法華義疏","era":"","t":"合上咄哉丈夫乃至如是之言也。"}]},{"p":38296,"q":"我久令汝等","notes":[{"by":"法華義疏","era":"","t":"合上我昔欲令汝得安樂至繫珠文也。"}]},{"p":38316,"q":"而汝謂為","notes":[{"by":"法華義疏","era":"","t":"合上而汝不知甚為癡也。"}]},{"p":38467,"q":"具設諸餚饍","notes":[{"by":"法華義疏","era":"","t":"長行舉酒，偈舉餚饍，酒譬說菩提心，設餚饍譬說菩薩行；亦得轉譬，上以酒譬法華教，今以餚饍譬教也。"}]},{"p":38485,"q":"默與而捨去","notes":[{"by":"法華義疏","era":"","t":"解之不朽既顯在後時，則後時之解非是言教所授，故稱默與。"}]},{"p":38545,"q":"與珠之親友","notes":[{"by":"法華義疏","era":"","t":"兩偈，頌上會遇示珠譬。"}]},{"p":38593,"q":"我等亦如是","notes":[{"by":"法華義疏","era":"","t":"三行，頌上合譬。"}]},{"p":38665,"q":"我今從佛聞","notes":[{"by":"法華義疏","era":"","t":"一偈，頌第四結歡喜也。"}]},{"p":38764,"q":"我等於此亦應有分","notes":[{"by":"法華義疏","era":"","t":"第二、舉他推必應得記。"}]},{"p":38825,"q":"若佛見授","notes":[{"by":"法華義疏","era":"","t":"第二、明二結。"}]},{"p":38907,"q":"爾時佛告阿難","notes":[{"by":"法華義疏","era":"","t":"第二、授記。"}]},{"p":39146,"q":"爾時世尊","notes":[{"by":"法華義疏","era":"","t":"第二、授學無學人記。"}]},{"p":39283,"q":"爾時會中","notes":[{"by":"法華義疏","era":"","t":"第二、新學生疑。"}]},{"p":39361,"q":"空王佛","notes":[{"by":"法華義疏","era":"","t":"畢竟空是諸空中之王，故《智度論》云"}]},{"p":39447,"q":"阿難面於佛前","notes":[{"by":"法華義疏","era":"","t":"第四、領解稱歎。"}]},{"p":39860,"q":"寂然清淨","notes":[{"by":"法華義疏","era":"","t":"顯二千人知諸法先來寂滅本性清淨，故堪與無生記也。"}]},{"p":40215,"q":"法師","notes":[{"by":"法華義疏","era":"","t":"法謂妙法，平等正觀可為心軌故稱為法；以人能上弘大法、下為物師，故云法師。"}]},{"p":40414,"q":"若復有人","notes":[{"by":"法華義疏","era":"","t":"第二、歎兩世法師功德。"}]},{"p":40511,"q":"成就大願","notes":[{"by":"法華義疏","era":"","t":"明尋此人既供養多佛應生淨土，但成就大願故來生人間耳。"}]},{"p":40568,"q":"何以故","notes":[{"by":"法華義疏","era":"","t":"舉現因釋當果也。"}]},{"p":40707,"q":"何況盡能受持","notes":[{"by":"法華義疏","era":"","t":"第二、明上品法師。"}]},{"p":40756,"q":"若是善男子","notes":[{"by":"法華義疏","era":"","t":"明佛滅度後二種法師，亦前明下品次辨上品。"}]},{"p":40790,"q":"則如來使","notes":[{"by":"法華義疏","era":"","t":"流通得其旨趣，必可委之以理，為所遣也。"}]},{"p":40892,"q":"以佛莊嚴而自莊嚴","notes":[{"by":"法華義疏","era":"","t":"如來荷擔於法，持經之人既其弘法，佛以恭敬於法，既擔所弘之法亦擔能弘之人也。"}]},{"p":41093,"q":"若有能受持","notes":[{"by":"法華義疏","era":"","t":"第二，十三偈，又開兩別：初七偈，頌兩世法師；次六偈，頌前信毀。"}]},{"p":41537,"q":"況滅度後","notes":[{"by":"法華義疏","era":"","t":"佛在世時眾生煩惱猶薄尚不信受，況滅度後顛倒厚重而能解也。"}]},{"p":41581,"q":"又為他方","notes":[{"by":"法華義疏","era":"","t":"第三、內善成就歎。"}]},{"p":41672,"q":"不須復安舍利","notes":[{"by":"法華義疏","era":"","t":"第四、解釋也。"}]},{"p":41826,"q":"其有眾生","notes":[{"by":"法華義疏","era":"","t":"第二對、明近菩提不近菩提。"}]},{"p":41873,"q":"譬如有人","notes":[{"by":"法華義疏","era":"","t":"讀誦解釋如說修行深求法華，發生三慧故去水近也。"}]},{"p":42019,"q":"開方便門，示真實相。","notes":[{"by":"灌頂","era":"","t":"三、華落譬廢權，蓮成譬立實。"}]},{"p":42161,"q":"如來衣","notes":[{"by":"灌頂","era":"","t":"有二種：柔和即圓嬰兒行，忍辱即圓病行。"}]},{"p":42472,"q":"若聞是深經，決了聲聞法。","notes":[{"by":"法華義疏","era":"","t":"昔未開權顯實則未知聲聞非是究竟，今開權顯實定知聲聞非是至極，乃是入大乘之方便耳。"},{"by":"胡吉藏","era":"","t":"決了聲聞法者，知其是三權，一乘為實也。"}]},{"p":42508,"q":"若人說此經","notes":[{"by":"法華義疏","era":"","t":"第二、四行半，頌弘經方法。"}]},{"p":42556,"q":"諸法","notes":[{"by":"灌頂","era":"","t":"諸法者，是所照境廣也。"}]},{"p":42616,"q":"若我滅度後","notes":[{"by":"法華義疏","era":"","t":"七偈，頌第三、感於靈瑞。"}]},{"p":42713,"q":"爾時","notes":[{"by":"法華義疏","era":"","t":"一、開法身時，二、證說時也。"}]},{"p":42835,"q":"妙法","notes":[{"by":"法華義疏","era":"","t":"凡有二義：一者、據事而言，寶塔從地涌出，大眾覩見，因事立名。"}]},{"p":42876,"q":"住在空中","notes":[{"by":"法華義疏","era":"","t":"第七、明塔莊嚴，表法身眾德所成也。"}]},{"p":42913,"q":"寶鈴萬億","notes":[{"by":"法華義疏","era":"","t":"四辨八音也。"}]},{"p":42971,"q":"高至四天王宮","notes":[{"by":"法華義疏","era":"","t":"第八、明塔至處。"}]},{"p":43064,"q":"爾時寶塔","notes":[{"by":"法華義疏","era":"","t":"第十、明出聲。"}]},{"p":43092,"q":"平等大慧","notes":[{"by":"法華義疏","era":"","t":"如來之慧不一不三絕緣絕觀，離一切高下取捨斷常諸邊，故云平等，此是體平等也。"}]},{"p":43141,"q":"爾時四眾","notes":[{"by":"法華義疏","era":"","t":"第二、明現塔意。"}]},{"p":43256,"q":"佛告","notes":[{"by":"法華義疏","era":"","t":"第二、佛答也。"}]},{"p":43473,"q":"今多寶","notes":[{"by":"法華義疏","era":"","t":"明今日涌現時，正答其二問也。"}]},{"p":43504,"q":"是時大樂說","notes":[{"by":"法華義疏","era":"","t":"第三、次明開塔。"}]},{"p":43651,"q":"大樂說白佛","notes":[{"by":"法華義疏","era":"","t":"第三、重請，前欲見多寶，即欲識法身無生滅、應身有生滅也。"}]},{"p":43681,"q":"爾時佛放白毫一光","notes":[{"by":"法華義疏","era":"","t":"第四、正明召集分身。"}]},{"p":43812,"q":"爾時十方諸佛","notes":[{"by":"法華義疏","era":"","t":"第二、明十方佛欲來之意。"}]},{"p":43858,"q":"時娑婆世界","notes":[{"by":"法華義疏","era":"","t":"第三、明變淨。"}]},{"p":43945,"q":"移諸天人","notes":[{"by":"法華義疏","era":"","t":"無緣眾生不得聞也。"}]},{"p":43976,"q":"各到寶樹下","notes":[{"by":"法華義疏","era":"","t":"欲樹立法身義也。"}]},{"p":44474,"q":"爾時東方","notes":[{"by":"法華義疏","era":"","t":"第四，十方佛集欲同開塔也。"}]},{"p":44847,"q":"爾時四眾","notes":[{"by":"法華義疏","era":"","t":"第四，大眾覩見稱歎供養也。"}]},{"p":44893,"q":"爾時多寶佛","notes":[{"by":"法華義疏","era":"","t":"第四、明二佛共坐。"}]},{"p":45026,"q":"以大音聲","notes":[{"by":"法華義疏","era":"","t":"第五，命覓弘經人。"}]},{"p":45164,"q":"又我分身","notes":[{"by":"法華義疏","era":"","t":"第二、釋分身集亦有三意：初一行，明為聽法故來；次半行，欲開寶塔顯真常應滅故來；"}]},{"p":45194,"q":"各捨妙土","notes":[{"by":"法華義疏","era":"","t":"第三、令法久住故來。"}]},{"p":45334,"q":"告諸大眾","notes":[{"by":"法華義疏","era":"","t":"第二、頌命覓弘經人。"}]},{"p":45400,"q":"當知此意","notes":[{"by":"法華義疏","era":"","t":"有二種意：一、欲顯諸佛流通法故來；二、欲顯真常應滅、本一迹多。"}]},{"p":45505,"q":"諸善男子","notes":[{"by":"法華義疏","era":"","t":"第四一命一釋，初一行半命，次六行歎持經利益釋命也。"}]},{"p":47717,"q":"深達罪福相，遍照於十方","notes":[{"by":"灌頂","era":"","t":"即罪即福而見實相，乃名深達，以實相心離十惱亂等，皆是圓戒。"}]},{"p":49899,"q":"如實相","notes":[{"by":"法華義疏","era":"","t":"顯空觀是真實也。"}]},{"p":50177,"q":"亦復不近五種不男之人","notes":[{"by":"法華義疏","era":"","t":"第八、離譏嫌緣也。"}]},{"p":50213,"q":"若為女人說法","notes":[{"by":"法華義疏","era":"","t":"第九、離能生他愛緣。"}]},{"p":50244,"q":"不樂畜年少弟子","notes":[{"by":"法華義疏","era":"","t":"第十、離自生染愛緣。"}]},{"p":50265,"q":"常好坐禪","notes":[{"by":"法華義疏","era":"","t":"第二、明所應親近。"}]},{"p":50289,"q":"近處","notes":[{"by":"法華義疏","era":"","t":"第二、明空親近處。"}]},{"p":50316,"q":"不動","notes":[{"by":"法華義疏","era":"","t":"畢竟清淨，不如數論外道所計虛空也。"}]},{"p":50356,"q":"實無所有","notes":[{"by":"法華義疏","era":"","t":"實錄無所有。"}]},{"p":50373,"q":"但以因緣有","notes":[{"by":"法華義疏","era":"","t":"第二、明因緣世諦觀。"}]},{"p":50454,"q":"常離國王","notes":[{"by":"法華義疏","era":"","t":"第二、釋二門也。"}]},{"p":50714,"q":"以此二處","notes":[{"by":"法華義疏","era":"","t":"有人言：唯應言以此一處，而言二處者，行處是第一，親近處是第二，故言二處耳。"}]},{"p":50774,"q":"一切諸法","notes":[{"by":"法華義疏","era":"","t":"第二、頌空親近處。"}]},{"p":50804,"q":"顛倒分別","notes":[{"by":"法華義疏","era":"","t":"二行，明空親近處前方便觀也。"}]},{"p":50844,"q":"觀一切法","notes":[{"by":"法華義疏","era":"","t":"二偈，明從方便觀入於正觀。"}]},{"p":50884,"q":"若有比丘","notes":[{"by":"法華義疏","era":"","t":"第二，四行半，頌安樂，即行果也。"}]},{"p":51037,"q":"不樂說人及經典過","notes":[{"by":"法華義疏","era":"","t":"弘小乘者名為餘師，當起愍惻不應輕之。"}]},{"p":51097,"q":"善修如是","notes":[{"by":"法華義疏","era":"","t":"第二、明集德行體。"}]},{"p":51127,"q":"但以大乘而為解說","notes":[{"by":"法華義疏","era":"","t":"設答小乘義者，方便誘引終令入大，故〈藥草品〉云"}]},{"p":51290,"q":"除嬾惰意","notes":[{"by":"法華義疏","era":"","t":"第二、頌上離過。"}]},{"p":51390,"q":"我滅度後","notes":[{"by":"法華義疏","era":"","t":"第三、明安樂果。"}]},{"p":51492,"q":"文殊","notes":[{"by":"法華義疏","era":"","t":"第二、明行果。"}]},{"p":51629,"q":"又亦不應戲論諸法","notes":[{"by":"法華義疏","era":"","t":"誡令不應偏有所執，〈求那跋摩遺文偈〉云"}]},{"p":51705,"q":"不多不少","notes":[{"by":"法華義疏","era":"","t":"多說則起輕厭，少說則文理未足生彼迷心也。"}]},{"p":51767,"q":"得好同學","notes":[{"by":"法華義疏","era":"","t":"次明得善果也。"}]},{"p":51989,"q":"文殊","notes":[{"by":"法華義疏","era":"","t":"歎教妙理深。"}]},{"p":52066,"q":"不聞不知不覺","notes":[{"by":"法華義疏","era":"","t":"非但執小不聞於大，住增上慢亦不訪問學大乘人求其權實，學大乘人設為人說亦不信受，非但不受，小執既深在根又鈍，故不能解悟也。"}]},{"p":52129,"q":"文殊","notes":[{"by":"法華義疏","era":"","t":"第三、雙結。"}]},{"p":52166,"q":"常為比丘","notes":[{"by":"法華義疏","era":"","t":"次明得善果。"}]},{"p":52270,"q":"所以者何","notes":[{"by":"法華義疏","era":"","t":"舉此土自有菩薩以釋止。"}]},{"p":52337,"q":"譬如強力","notes":[{"by":"法華義疏","era":"","t":"第二、雙譬。"}]},{"p":52368,"q":"起種種兵","notes":[{"by":"法華義疏","era":"","t":"明佛見眾生，修行滅惑稱為有功，稱根授法各也。"}]},{"p":52470,"q":"獨王頂上有此一珠","notes":[{"by":"法華義疏","era":"","t":"釋迦以一乘大海，澍二乘牛跡，以未有大機而授大法理所不應，故稱驚怪。"}]},{"p":55482,"q":"阿逸多","notes":[{"by":"法華義疏","era":"","t":"此非答問，但釋上"}]},{"p":55525,"q":"諸佛自在神通之力","notes":[{"by":"法華義疏","era":"","t":"然諸佛法身非長非短而能長短適化，故名自在神通力也。"}]},{"p":55587,"q":"佛智叵思議","notes":[{"by":"法華義疏","era":"","t":"非長非短能示長短，雖示長短未曾長短，故名不思議，若昔短今長何名不思議也？"}]},{"p":55647,"q":"甚深叵分別","notes":[{"by":"法華義疏","era":"","t":"此明法身絕四句、超百非，故下文云"}]},{"p":55728,"q":"我於是","notes":[{"by":"法華義疏","era":"","t":"第二、前答其師資之問。"}]},{"p":55766,"q":"此諸菩薩","notes":[{"by":"法華義疏","era":"","t":"次答第一所從來處問也。"}]},{"p":56004,"q":"志念力堅固","notes":[{"by":"法華義疏","era":"","t":"四偈，重答第一師資問。"}]},{"p":56088,"q":"我從久遠來","notes":[{"by":"法華義疏","era":"","t":"則釋上是過去伽耶也。"}]},{"p":56307,"q":"斯等久遠","notes":[{"by":"法華義疏","era":"","t":"第二、明菩薩修行來久，不應始就佛受學。"}]},{"p":56352,"q":"譬如","notes":[{"by":"法華義疏","era":"","t":"第二、譬說。"}]},{"p":56502,"q":"今日世尊","notes":[{"by":"法華義疏","era":"","t":"合父子老少互相指譬也。"}]},{"p":56554,"q":"我等雖復","notes":[{"by":"法華義疏","era":"","t":"第二、請答。"}]},{"p":56615,"q":"唯然","notes":[{"by":"法華義疏","era":"","t":"正明請說也。"}]},{"p":56650,"q":"爾時彌勒","notes":[{"by":"法華義疏","era":"","t":"第三大段，執動疑生申疑致請。"}]},{"p":57045,"q":"如來誠諦之語","notes":[{"by":"法華義疏","era":"","t":"出所信解也。"}]},{"p":57120,"q":"我等","notes":[{"by":"法華義疏","era":"","t":"明菩薩不知。"}]},{"p":57177,"q":"如來祕密神通之力。","notes":[{"by":"法華義疏","era":"","t":"以下，出所執也。"},{"by":"灌頂","era":"","t":"又中間文云："}]},{"p":57263,"q":"譬如","notes":[{"by":"法華義疏","era":"","t":"第二、明譬說。"}]},{"p":57323,"q":"諸善男子","notes":[{"by":"法華義疏","era":"","t":"第二、開方便門，上顯二種真實：一、明證法身久，辨法身真實；二、明垂應久，明應身真實。"}]},{"p":57350,"q":"彌勒菩薩等俱白佛","notes":[{"by":"法華義疏","era":"","t":"第三、彌勒奉酬。"}]},{"p":57387,"q":"一切聲聞","notes":[{"by":"法華義疏","era":"","t":"明二乘不知；"}]},{"p":57443,"q":"爾時佛告","notes":[{"by":"法華義疏","era":"","t":"第四、合譬，正顯成佛已久。"}]},{"p":57485,"q":"一塵一劫","notes":[{"by":"法華義疏","era":"","t":"梁世有僧造《法華經》，感於神夢令安此說。"}]},{"p":57512,"q":"自從是來","notes":[{"by":"法華義疏","era":"","t":"上辨證法身已久，今明垂應久義，以證法身久謂自德滿，垂應久謂化他德圓也。"}]},{"p":57592,"q":"若有眾生來至我所","notes":[{"by":"法華義疏","era":"","t":"機發扣佛故名為至，即是感也。"}]},{"p":57687,"q":"為是人說","notes":[{"by":"法華義疏","era":"","t":"第二、明說教。"}]},{"p":57710,"q":"然我實成佛已來","notes":[{"by":"法華義疏","era":"","t":"第三、明顯實。"}]},{"p":57802,"q":"所以者何","notes":[{"by":"法華義疏","era":"","t":"凡夫見三界故不見三不三，如來見三界又能見三不三，故《法華論》云"}]},{"p":57871,"q":"以諸眾生有種種性","notes":[{"by":"法華義疏","era":"","t":"第二、上明見法身理實故所言不虛，今明見眾生機實故所言不虛。"}]},{"p":57969,"q":"所成壽命","notes":[{"by":"法華義疏","era":"","t":"上明過去無前有三不可數：一、世界不可數；二、抹世界為塵不可數；三、成佛復過此數故不可數。"}]},{"p":58037,"q":"貧窮下賤","notes":[{"by":"法華義疏","era":"","t":"上敘眾生心行，今明佛不得不滅。"}]},{"p":58087,"q":"是故如來","notes":[{"by":"法華義疏","era":"","t":"第二、明唱滅無損有益。"}]},{"p":58142,"q":"以此事故","notes":[{"by":"法華義疏","era":"","t":"第三、結難值章門也。"}]},{"p":58165,"q":"斯眾生等","notes":[{"by":"法華義疏","era":"","t":"第二、聞唱滅得益也。"}]},{"p":58224,"q":"法皆如是","notes":[{"by":"法華義疏","era":"","t":"有二種義：一者、如《涅槃》答純陀云"}]},{"p":58287,"q":"諸子於後","notes":[{"by":"法華義疏","era":"","t":"昔習觀既弱還起顛倒，以正觀為自、顛倒為他，故《涅槃》云"}]},{"p":58331,"q":"遙見其父","notes":[{"by":"法華義疏","era":"","t":"正感釋迦出世，但見丈六身成道、未見法身，去理尚遠故稱為遙。"}]},{"p":58367,"q":"更賜壽命","notes":[{"by":"法華義疏","era":"","t":"戒譬於色，定喻於香，慧譬於美味，三行圓備故稱具足。"}]},{"p":58430,"q":"汝等可服","notes":[{"by":"法華義疏","era":"","t":"第八、利根前悟譬。"}]},{"p":58475,"q":"餘失心者","notes":[{"by":"法華義疏","era":"","t":"第九、鈍根未了譬。"}]},{"p":58492,"q":"求索治病","notes":[{"by":"法華義疏","era":"","t":"亦有感教之機聞說妙法也。"}]},{"p":58532,"q":"父作是念","notes":[{"by":"法華義疏","era":"","t":"第十、如來示滅譬。"}]},{"p":58585,"q":"即作是言","notes":[{"by":"法華義疏","era":"","t":"第二、正唱滅也。"}]},{"p":58627,"q":"作是教已","notes":[{"by":"法華義疏","era":"","t":"第三、正滅。"}]},{"p":58649,"q":"是時諸子","notes":[{"by":"法華義疏","era":"","t":"第十一、鈍根得解譬。"}]},{"p":58732,"q":"其父聞子","notes":[{"by":"法華義疏","era":"","t":"第十二、如來還歸譬。"}]},{"p":58752,"q":"諸善男子","notes":[{"by":"法華義疏","era":"","t":"第十三、佛無虛妄譬。"}]},{"p":58814,"q":"為眾生","notes":[{"by":"法華義疏","era":"","t":"明方便示滅；"}]},{"p":58907,"q":"為度眾生故","notes":[{"by":"法華義疏","era":"","t":"頌第二、未來無終。"}]},{"p":58955,"q":"眾見我滅度","notes":[{"by":"法華義疏","era":"","t":"第二、六行半，舉得益釋滅不滅意。"}]},{"p":59003,"q":"時我及眾僧，俱出靈鷲山","notes":[{"by":"法華義疏","era":"","t":"第三、辨說法，即是法寶明滅不滅。"},{"by":"胡吉藏","era":"","t":"即緣感故出。"}]},{"p":59113,"q":"神通力如是","notes":[{"by":"法華義疏","era":"","t":"四偈半，文開為四句：初半偈，標常在靈鷲山，明佛之與土二俱不滅。"}]},{"p":59233,"q":"是諸罪眾生","notes":[{"by":"法華義疏","era":"","t":"第三、四偈，明感見不同雙結人土。"}]},{"p":59329,"q":"汝等有智者","notes":[{"by":"法華義疏","era":"","t":"第三、次頌長行不虛。"}]},{"p":59494,"q":"聞佛說壽命劫數長遠如是，無量無邊","notes":[{"by":"灌頂","era":"","t":"即迹中之益。"}]},{"p":59828,"q":"復有八世界微塵","notes":[{"by":"法華義疏","era":"","t":"第二、明地前得發菩提心益也。"}]},{"p":60068,"q":"爾時彌勒","notes":[{"by":"法華義疏","era":"","t":"第四、明彌勒疑除領解說偈稱嘆。"}]},{"p":60095,"q":"佛說希有法，昔所未曾聞，世尊有大","notes":[{"by":"灌頂","era":"","t":"說得法利者，歡喜充遍身，或住不退地，或得陀羅尼。"}]},{"p":60552,"q":"爾時佛告彌勒","notes":[{"by":"法華義疏","era":"","t":"第五、格量稱嘆。"}]},{"p":60602,"q":"若有善男子","notes":[{"by":"法華義疏","era":"","t":"第、二格量。"}]},{"p":60715,"q":"若善男子","notes":[{"by":"法華義疏","era":"","t":"第三、結嘆。"}]},{"p":61194,"q":"如是","notes":[{"by":"法華經義記","era":"","t":"此是通序之第一也。"}]},{"p":61236,"q":"阿逸多","notes":[{"by":"法華義疏","era":"","t":"第三、別明持經人攝得造寺功德。"}]},{"p":61274,"q":"何況廣聞","notes":[{"by":"法華義疏","era":"","t":"第二、明思慧功德；"}]},{"p":61466,"q":"又復如來滅後","notes":[{"by":"法華義疏","era":"","t":"第二、明佛滅後持經人功德。"}]},{"p":61591,"q":"以佛舍利起七寶塔","notes":[{"by":"法華經義記","era":"","t":"是第二，詺為瑞相序也。"}]},{"p":61811,"q":"是故我說","notes":[{"by":"法華義疏","era":"","t":"第四、總結持經人具得塔寺二種功德。"}]},{"p":61867,"q":"況復有人","notes":[{"by":"法華義疏","era":"","t":"第三、明上品修慧人。"}]},{"p":61946,"q":"若人讀誦","notes":[{"by":"法華義疏","era":"","t":"第四、上上品人。"}]},{"p":62493,"q":"不瞋不惡口","notes":[{"by":"法華義疏","era":"","t":"頌修慧上上品人也。"}]},{"p":62802,"q":"阿逸多","notes":[{"by":"法華義疏","era":"","t":"第二、格量第五十人。"}]},{"p":62836,"q":"聞是經隨喜已","notes":[{"by":"法華義疏","era":"","t":"第二、明聞法隨喜；"}]},{"p":62899,"q":"是諸人等","notes":[{"by":"法華義疏","era":"","t":"明第三人自行化他，如是展轉至第五十人。"}]},{"p":62967,"q":"若四百萬億","notes":[{"by":"法華義疏","era":"","t":"第二、正舉財法二施以問彌勒。"}]},{"p":63182,"q":"即集此眾生","notes":[{"by":"法華義疏","era":"","t":"第二、正明法施。"}]},{"p":63261,"q":"彌勒白佛","notes":[{"by":"法華義疏","era":"","t":"第三、彌勒奉答。"}]},{"p":63312,"q":"佛告","notes":[{"by":"法華義疏","era":"","t":"第四、正明格量。"}]},{"p":63645,"q":"利根智慧","notes":[{"by":"法華義疏","era":"","t":"三者、以口業勸人聽微妙法生他正信正解，故得離口醜陋得端正果報。"}]},{"p":63846,"q":"何況一心","notes":[{"by":"法華義疏","era":"","t":"第四人，其福最勝報不可說也。"}]},{"p":63923,"q":"最後人","notes":[{"by":"法華義疏","era":"","t":"六行半，頌第二、舉二施格量；次一行，頌第三、舉後況初也。"}]},{"p":64437,"q":"是善男子","notes":[{"by":"法華義疏","era":"","t":"第二，別開六根清淨。"}]},{"p":64573,"q":"父母所生眼","notes":[{"by":"法華義疏","era":"","t":"此云高山，又云光山。"}]},{"p":64681,"q":"得千二百耳功德","notes":[{"by":"法華義疏","era":"","t":"第三、別歎耳用，則是明功德也。"}]},{"p":64941,"q":"不壞耳根","notes":[{"by":"法華義疏","era":"","t":"欲聞即聞隨意自在，故不壞也。"}]},{"p":65448,"q":"三千大千世界","notes":[{"by":"法華義疏","era":"","t":"第四、知機，即是樂說辨也。"}]},{"p":68888,"q":"即得如上眼根清淨","notes":[{"by":"法華義疏","era":"","t":"第三、明得延壽果。"}]},{"p":68936,"q":"於時增上慢","notes":[{"by":"法華義疏","era":"","t":"第四、惡人信伏果。"}]},{"p":68976,"q":"大神通力","notes":[{"by":"法華義疏","era":"","t":"身示現神通力；"}]},{"p":69024,"q":"命終之後","notes":[{"by":"法華義疏","era":"","t":"第六、捨身值佛果。"}]},{"p":69130,"q":"得大勢","notes":[{"by":"法華義疏","era":"","t":"第八、明當得作佛果也。"}]},{"p":69159,"q":"讚歎","notes":[{"by":"法華經義記","era":"","t":"即口業，在口則譽揚聖德，意地則尊重如來，涉身則恭敬於佛，然此諸句皆是經家語也。"}]},{"p":69177,"q":"於諸佛法中","notes":[{"by":"法華義疏","era":"","t":"第七、得六根常淨無所畏果。"}]},{"p":69352,"q":"畢是罪已","notes":[{"by":"法華義疏","era":"","t":"第二、明得善果。"}]},{"p":69437,"q":"皆於阿耨多羅三藐三菩提不退轉","notes":[{"by":"法華經義記","era":"","t":"此是第三談其階位。"}]},{"p":69490,"q":"是故諸菩薩","notes":[{"by":"法華義疏","era":"","t":"第二、勸修。"}]},{"p":69650,"q":"其罪畢已","notes":[{"by":"法華義疏","era":"","t":"十行，頌得果：初五行，頌善人得果；"}]},{"p":69750,"q":"時四部眾","notes":[{"by":"法華經義記","era":"","t":"一偈，今頌上四眾歡喜也。"},{"by":"法華義疏","era":"","t":"五行，頌惡人得果。"}]},{"p":69852,"q":"億億萬劫","notes":[{"by":"法華義疏","era":"","t":"第二、頌歎教勸修。"}]},{"p":69935,"q":"妙法蓮華","notes":[{"by":"法華經義記","era":"","t":"此一句正明經名字同，昔日如來出定即說《法華》，今日如來出定亦應說《法華》也；第三言"}]},{"p":69979,"q":"瞻仰尊顏","notes":[{"by":"法華經義記","era":"","t":"以下盡七十三行半偈，正領解上火宅乃至〈方便品〉中開三顯一之義。"}]},{"p":70019,"q":"所以者何","notes":[{"by":"法華經義記","era":"","t":"此下，是第二，即釋長者得有此大車之意，正言財寶無窮七珍皆具，明知如來蘊內德在懷如充，又有化他之德盈外如溢也。"},{"by":"法華義疏","era":"","t":"對二乘之偽故稱為真，累無不盡所以稱淨，德無不備，目之為大。"}]},{"p":70054,"q":"爾時世尊","notes":[{"by":"法華義疏","era":"","t":"第二、現神力。"}]},{"p":70096,"q":"優婆夷","notes":[{"by":"法華經義記","era":"","t":"此出學人有疑也。"}]},{"p":70217,"q":"滿百千歲","notes":[{"by":"法華義疏","era":"","t":"神力一時未足希有，滿百千歲方是奇特。"}]},{"p":70260,"q":"其中眾生","notes":[{"by":"法華義疏","era":"","t":"第二，十方眾生覩瑞。"}]},{"p":70350,"q":"坐師子座","notes":[{"by":"法華經義記","era":"","t":"此下有四行一句，頌上第六長者歡喜。"}]},{"p":70400,"q":"即時諸天","notes":[{"by":"法華義疏","era":"","t":"第二、諸天唱告勸隨喜供養。"}]},{"p":70498,"q":"彼諸眾生","notes":[{"by":"法華義疏","era":"","t":"第三、明十方順從。"}]},{"p":70555,"q":"嚴身之具","notes":[{"by":"法華經義記","era":"","t":"此一句是第三，明如來又捨相好也。"}]},{"p":70574,"q":"所散諸物","notes":[{"by":"法華義疏","era":"","t":"第四、佛重現二種神力，一成寶帳表成法身不二，即後分經；"}]},{"p":70610,"q":"通達","notes":[{"by":"法華經義記","era":"","t":"通是無壅義，達是到義，明三乘人根性所宜，行必斷煩惱無壅，是通義也。"}]},{"p":70673,"q":"囑累","notes":[{"by":"法華義疏","era":"","t":"囑謂付囑，累謂憑累。"}]},{"p":70693,"q":"如來一切所有之法","notes":[{"by":"法華義疏","era":"","t":"第二、後分經身權身實、短長適化，謂自在神力也。"}]},{"p":70904,"q":"而說偈言","notes":[{"by":"法華經義記","era":"","t":"此品有兩段即長行與偈為二，自此下有五十四行半偈是第二重頌。"}]},{"p":71006,"q":"囑累是經故","notes":[{"by":"法華義疏","era":"","t":"第二、頌獎勸，又開二別：第一、稱歎；第二、勸持。"}]},{"p":71271,"q":"我滅度後","notes":[{"by":"法華經義記","era":"","t":"以下，此明今日相值而不解者，未來世中會得相值，此則明一日結緣歷劫不朽之義。"}]},{"p":71322,"q":"現大神力","notes":[{"by":"法華義疏","era":"","t":"有人言：即是前品七種神力。"}]},{"p":71340,"q":"而作是言","notes":[{"by":"法華義疏","era":"","t":"前現大神力謂意業付囑，以手摩頂謂身業付囑，今明口業也。"}]},{"p":71403,"q":"諸菩薩","notes":[{"by":"法華義疏","era":"","t":"第二、三過順旨。"}]},{"p":71468,"q":"一切眾生","notes":[{"by":"法華經義記","era":"","t":"半行，頌合種種無量句，即是頌合受潤眾生也。"},{"by":"法華義疏","era":"","t":"第二、釋囑累意，即是示宣通之方。"}]},{"p":71494,"q":"亦無所畏","notes":[{"by":"法華義疏","era":"","t":"第三句，明智慧業。"}]},{"p":71531,"q":"汝等亦應隨學","notes":[{"by":"法華義疏","era":"","t":"慳有五種：一、住處慳；二、家慳；三、施慳；四、稱歎慳；五、法慳。"}]},{"p":71615,"q":"汝等若能","notes":[{"by":"法華義疏","era":"","t":"第三、若能上學佛二德、下知兩機，則通法利人，謂報佛恩也。"}]},{"p":71632,"q":"時諸菩薩","notes":[{"by":"法華義疏","era":"","t":"第二，菩薩受付。"}]},{"p":71679,"q":"世尊","notes":[{"by":"法華經義記","era":"","t":"以下正作問也。"}]},{"p":71741,"q":"爾時釋迦","notes":[{"by":"法華義疏","era":"","t":"第三、明說經事畢。"}]},{"p":71780,"q":"如故","notes":[{"by":"法華義疏","era":"","t":"直令閉塔，未遣還土也。"}]},{"p":72000,"q":"佛告","notes":[{"by":"法華經義記","era":"","t":"以下是品之第二明如來答。"},{"by":"法華義疏","era":"","t":"第四、結會古今。"}]},{"p":72228,"q":"爾時彼佛","notes":[{"by":"法華義疏","era":"","t":"第二、正明藥王本事。"}]},{"p":72258,"q":"是一切眾生","notes":[{"by":"法華義疏","era":"","t":"第二、明悟解。"}]},{"p":72309,"q":"得此三昧","notes":[{"by":"法華義疏","era":"","t":"第三、報恩供養。"}]},{"p":72339,"q":"聞法","notes":[{"by":"法華經義記","era":"","t":"來，則舉上第一夢也。"}]},{"p":72374,"q":"雨曼陀羅","notes":[{"by":"法華經義記","era":"","t":"有七行，明彌勒自述于時事，不頌上長行。"}]},{"p":72439,"q":"從三昧起","notes":[{"by":"法華義疏","era":"","t":"第二、辨內身供養。"}]},{"p":72468,"q":"即服諸香","notes":[{"by":"法華經義記","era":"","t":"明服香；第三從"}]},{"p":72484,"q":"畢力迦","notes":[{"by":"法華義疏","era":"","t":"為𧢻池也)。"}]},{"p":72503,"q":"滿千二百歲","notes":[{"by":"法華經義記","era":"","t":"正明燒身；第四"}]},{"p":72561,"q":"其中諸佛","notes":[{"by":"法華經義記","era":"","t":"以下，諸佛歎；第五"}]},{"p":72696,"q":"其身火燃","notes":[{"by":"法華經義記","era":"","t":"以下，明所經時節。"}]},{"p":72716,"q":"一切眾生憙見","notes":[{"by":"法華經義記","era":"","t":"正明本事苦行流通此經；第四"}]},{"p":72767,"q":"而說偈言","notes":[{"by":"法華經義記","era":"","t":"此下十八行偈是答中第二，頌上長行中五人：初有九行頌第一人，次有五行超頌第四人也，次有兩行追頌第二人也，次有一行頌第三人，次有一行頌上第五人也。"}]},{"p":72824,"q":"說是偈已","notes":[{"by":"法華義疏","era":"","t":"第二、明供養得利益恩。"}]},{"p":72907,"q":"白已","notes":[{"by":"法華經義記","era":"","t":"明昇空而往。"}]},{"p":73009,"q":"爾時日月","notes":[{"by":"法華義疏","era":"","t":"第二、如來滅度。"}]},{"p":73034,"q":"涅槃時到","notes":[{"by":"法華義疏","era":"","t":"安住三德為入涅槃也。"}]},{"p":73061,"q":"又勅","notes":[{"by":"法華經義記","era":"","t":"即明淨明德佛以法付此菩薩也。"}]},{"p":73164,"q":"如是日月淨明","notes":[{"by":"法華經義記","era":"","t":"明淨明德佛下入涅槃也。"}]},{"p":73288,"q":"爾時一切眾生憙見","notes":[{"by":"法華經義記","era":"","t":"此下是第二，正明後身苦行通經。"},{"by":"法華義疏","era":"","t":"第二，明佛滅後供養。"}]},{"p":73399,"q":"令無數求聲聞眾","notes":[{"by":"法華義疏","era":"","t":"第二、時眾得益。"},{"by":"法華經義記","era":"","t":"明時眾得益。"}]},{"p":73501,"q":"于時一切","notes":[{"by":"法華義疏","era":"","t":"第四、明菩薩發誓，身返平復。"}]},{"p":73574,"q":"當爾之時","notes":[{"by":"法華義疏","era":"","t":"第五、感諸瑞相。"},{"by":"法華經義記","era":"","t":"明感動之相也。"}]},{"p":73606,"q":"佛告宿王華","notes":[{"by":"法華義疏","era":"","t":"第四、結會古今，兼勸人燒指供養。"}]},{"p":73730,"q":"若復有人","notes":[{"by":"法華義疏","era":"","t":"第二段，次明歎教。"}]},{"p":73797,"q":"譬如一切川流","notes":[{"by":"法華經義記","era":"","t":"十譬，格量歎；第二"},{"by":"法華義疏","era":"","t":"第二、歎教。"}]},{"p":74202,"q":"此經能救","notes":[{"by":"法華義疏","era":"","t":"第三、約人就滅惡門歎。"}]},{"p":74346,"q":"若人得聞","notes":[{"by":"法華義疏","era":"","t":"第四、生善歎也。"}]},{"p":74478,"q":"若有人聞","notes":[{"by":"法華義疏","era":"","t":"第二、別歎一品。"}]},{"p":74501,"q":"若有女人","notes":[{"by":"法華義疏","era":"","t":"第二、別約生報歎。"}]},{"p":75030,"q":"不老","notes":[{"by":"法華義疏","era":"","t":"不起六十二見名為不老。"}]},{"p":75139,"q":"說是藥王","notes":[{"by":"法華義疏","era":"","t":"第三、明說品利益。"}]},{"p":75168,"q":"多寶如來","notes":[{"by":"法華義疏","era":"","t":"第四、多寶稱歎。"}]},{"p":75208,"q":"釋迦牟尼","notes":[{"by":"法華義疏","era":"","t":"第三、的明光照其身。"}]},{"p":75264,"q":"妙音","notes":[{"by":"法華義疏","era":"","t":"此菩薩過去以十萬種伎樂供養於佛，故得美妙音聲，因以立名，舊經稱"}]},{"p":75318,"q":"過是數已","notes":[{"by":"法華義疏","era":"","t":"第二、別照淨光土也。"}]},{"p":75414,"q":"爾時一切","notes":[{"by":"法華義疏","era":"","t":"第三、的照妙音身也。"}]},{"p":75434,"q":"久已殖眾德本","notes":[{"by":"法華義疏","era":"","t":"第二、歎德。"}]},{"p":75463,"q":"得妙幢相三昧","notes":[{"by":"法華義疏","era":"","t":"如有如意寶珠能淨諸寶，是三昧能淨諸三昧垢，煩惱垢易治、三昧垢難斷。"}]},{"p":75624,"q":"文殊","notes":[{"by":"法華義疏","era":"","t":"第七、文殊重問妙音之德。"}]},{"p":75733,"q":"而汝身","notes":[{"by":"法華義疏","era":"","t":"辨淨土之勝也。"}]},{"p":75770,"q":"是故汝往","notes":[{"by":"法華義疏","era":"","t":"第三、總結。"}]},{"p":75841,"q":"於是妙音","notes":[{"by":"法華義疏","era":"","t":"第四、將欲發來先現瑞。"}]},{"p":75879,"q":"化作八萬四千","notes":[{"by":"法華義疏","era":"","t":"一、欲擬八萬四千菩薩座故；二、表八萬四千法藏皆入一乘《妙法華》故。"}]},{"p":75985,"q":"爾時釋迦","notes":[{"by":"法華義疏","era":"","t":"第八、釋迦推於多寶令見妙音，但詶其後請、未答前三問，下華德菩薩重牒三問佛方解釋。"}]},{"p":76018,"q":"與八萬四千","notes":[{"by":"法華義疏","era":"","t":"第二，明與眷屬俱共發來。"}]},{"p":76068,"q":"世尊","notes":[{"by":"法華義疏","era":"","t":"第八、妙音請見多寶。"}]},{"p":76139,"q":"唯願世尊","notes":[{"by":"法華義疏","era":"","t":"第四請、佛欲見妙音。"}]},{"p":76159,"q":"爾時釋迦","notes":[{"by":"法華義疏","era":"","t":"第九、釋迦語於多寶。"}]},{"p":76192,"q":"時多寶佛","notes":[{"by":"法華義疏","era":"","t":"第九、多寶命令來，即詶文殊請。"}]},{"p":76221,"q":"于時妙音","notes":[{"by":"法華義疏","era":"","t":"第十、正明妙音來。"}]},{"p":76342,"q":"入七寶臺","notes":[{"by":"法華義疏","era":"","t":"第五、敘妙音昇空而至。"}]},{"p":76381,"q":"到已","notes":[{"by":"法華義疏","era":"","t":"第六、明見佛儀則。"}]},{"p":76416,"q":"而白佛言","notes":[{"by":"法華義疏","era":"","t":"第七、奉宣聖旨。"}]},{"p":76464,"q":"眾生易度","notes":[{"by":"法華義疏","era":"","t":"第二、問所度眾生。"}]},{"p":76656,"q":"爾時華德菩薩白佛","notes":[{"by":"法華經義記","era":"","t":"正明妙音普現色身通經之軌；第四"},{"by":"法華義疏","era":"","t":"第三、論妙音弘經。"}]},{"p":76686,"q":"有是神力","notes":[{"by":"法華義疏","era":"","t":"正問神力之果。"}]},{"p":76726,"q":"國名","notes":[{"by":"法華義疏","era":"","t":"種善根之處。"}]},{"p":76774,"q":"以是因緣","notes":[{"by":"法華義疏","era":"","t":"明善根得果，結詶其問。"}]},{"p":76850,"q":"是妙音","notes":[{"by":"法華義疏","era":"","t":"第三、總結稱嘆。"}]},{"p":76888,"q":"華德","notes":[{"by":"法華義疏","era":"","t":"第三、總結。"}]},{"p":76904,"q":"是菩薩","notes":[{"by":"法華義疏","era":"","t":"第二、嘆妙音於十方弘經。"}]},{"p":76925,"q":"或現梵王身","notes":[{"by":"法華義疏","era":"","t":"第二、廣釋。"}]},{"p":77104,"q":"諸有地獄","notes":[{"by":"法華義疏","era":"","t":"第四、歎救八難。"}]},{"p":77235,"q":"十方","notes":[{"by":"法華義疏","era":"","t":"次嘆十方弘經。"}]},{"p":77381,"q":"爾時華德菩薩白佛","notes":[{"by":"法華經義記","era":"","t":"此下是品中第三段，正明妙音普現色身弘經。"},{"by":"法華義疏","era":"","t":"第二、問答論妙音所得三昧，亦前問後答。"}]},{"p":77475,"q":"說是妙音菩薩品時","notes":[{"by":"法華經義記","era":"","t":"此下是品中第四段，明東西二國得益，即得此三昧也。"},{"by":"法華義疏","era":"","t":"品中第四段，明彼此蒙益。"}]},{"p":77528,"q":"爾時妙音","notes":[{"by":"法華義疏","era":"","t":"品第五章，明所作已竟還歸本土。"}]},{"p":77581,"q":"既到本國","notes":[{"by":"法華經義記","era":"","t":"明至彼恭敬彼佛也。"}]},{"p":77696,"q":"說是妙音菩薩來往品時","notes":[{"by":"法華經義記","era":"","t":"品中第六段，明經家敘時眾得利益也。"}]},{"p":77734,"q":"普門","notes":[{"by":"法華義疏","era":"","t":"普以周普為義，門是開通無滯之名。"}]},{"p":78158,"q":"觀世音","notes":[{"by":"法華義疏","era":"","t":"第二、出所疑之人。"}]},{"p":78215,"q":"無盡意","notes":[{"by":"法華義疏","era":"","t":"袒肩用顯形恭、合掌以表心一，如掌本在異處今合而為一，心本他緣今斂而不散，心既冥漠難覩，故假外事以顯內心。"}]},{"p":78267,"q":"善男子","notes":[{"by":"法華義疏","era":"","t":"《華嚴經》稱為佛子，餘經多云善男子，有紹繼義故名為子，綱幹之能故稱為男，所行有利他符理清昇感樂之義目之為善。"}]},{"p":78339,"q":"是菩薩","notes":[{"by":"法華義疏","era":"","t":"第三、釋誡。"}]},{"p":78364,"q":"若有百千","notes":[{"by":"法華義疏","era":"","t":"第三、明風難。"}]},{"p":78405,"q":"假使黑風","notes":[{"by":"法華義疏","era":"","t":"一解云：此風起時前有黑雲，故云黑風。"}]},{"p":78440,"q":"是諸人等","notes":[{"by":"法華義疏","era":"","t":"第二、釋無情難竟，故總結之以詶其問也。"}]},{"p":78496,"q":"若三千","notes":[{"by":"法華義疏","era":"","t":"第三、辨財難。"}]},{"p":78544,"q":"設復有人","notes":[{"by":"法華義疏","era":"","t":"第二、明身難，即繫閉於身故名身難。"}]},{"p":78607,"q":"齎持重寶","notes":[{"by":"法華義疏","era":"","t":"故知是財難。"}]},{"p":78636,"q":"汝等","notes":[{"by":"法華義疏","era":"","t":"第四、釋勸。"}]},{"p":78680,"q":"眾商人聞","notes":[{"by":"法華義疏","era":"","t":"第二、稱嘆名，勸物常念。"}]},{"p":78733,"q":"若有眾生","notes":[{"by":"法華義疏","era":"","t":"第二、釋觀世意。"}]},{"p":78821,"q":"是故眾生","notes":[{"by":"法華義疏","era":"","t":"第二大段釋三名竟，結勸受持也。"}]},{"p":78955,"q":"復盡形","notes":[{"by":"法華義疏","era":"","t":"第二、明時久。"}]},{"p":79006,"q":"佛言","notes":[{"by":"法華義疏","era":"","t":"第三、正格量。"}]},{"p":79034,"q":"是二人福","notes":[{"by":"法華義疏","era":"","t":"第二、正格量。"}]},{"p":79055,"q":"無盡意","notes":[{"by":"法華義疏","era":"","t":"第二、總結。"}]},{"p":79087,"q":"白佛言","notes":[{"by":"法華義疏","era":"","t":"問身業，次問口業，"}]},{"p":79212,"q":"梵王","notes":[{"by":"法華義疏","era":"","t":"第二、示凡方便。"}]},{"p":79338,"q":"小王身","notes":[{"by":"法華義疏","era":"","t":"第二、明人方便。"}]},{"p":79414,"q":"婆羅門","notes":[{"by":"法華義疏","era":"","t":"此云外意，亦名淨行。"}]},{"p":79602,"q":"無盡意","notes":[{"by":"法華義疏","era":"","t":"第三、前既明施主福田竟，今第三總結稱嘆也。"}]},{"p":79634,"q":"是故汝等應當一心供養","notes":[{"by":"法華經義記","era":"","t":"以下，仍勸人供養此菩薩也；第四"},{"by":"法華義疏","era":"","t":"第二、勸供養。"}]},{"p":79745,"q":"法施","notes":[{"by":"法華義疏","era":"","t":"如法布施也；又為法故施也；又達財法不二也。"}]},{"p":80570,"q":"爾時持地菩薩即從座起","notes":[{"by":"法華經義記","era":"","t":"明持地菩薩寄也，第寄此品末，仍歎觀世音之德也；第六臨品末"},{"by":"法華義疏","era":"","t":"第十、明時眾得道。"}]},{"p":80626,"q":"佛說是普門品時","notes":[{"by":"法華經義記","era":"","t":"此下是品中第六段，明經家敘說品得利益也。"}]},{"p":80643,"q":"皆發無等等","notes":[{"by":"法華義疏","era":"","t":"第二、正明得益。"}]},{"p":80743,"q":"佛告","notes":[{"by":"法華義疏","era":"","t":"第二、明佛答。"}]},{"p":80844,"q":"爾時藥王","notes":[{"by":"法華經義記","era":"","t":"又有一番問答，正明五人說神呪擁護弘經人也；第三"},{"by":"法華義疏","era":"","t":"第二、明五人說呪。"}]},{"p":82895,"q":"母告子言","notes":[{"by":"法華經義記","era":"","t":"明其母告子導父王邪見，第三"}]},{"p":82997,"q":"於是","notes":[{"by":"法華經義記","era":"","t":"以下第二，正明二子作十八變化父王也。"}]},{"p":83110,"q":"時父見子神力如是","notes":[{"by":"法華經義記","era":"","t":"此下是第三，明父王受化，就此中凡有十四階：第一先明父王與子問答也；第二"}]},{"p":83493,"q":"彼時妙莊嚴王","notes":[{"by":"法華經義記","era":"","t":"明王眷屬堪受法正化也；第五"}]},{"p":83591,"q":"二子如是","notes":[{"by":"法華經義記","era":"","t":"歎二子化父王之德；第六"}]},{"p":83614,"q":"於是妙莊嚴王","notes":[{"by":"法華經義記","era":"","t":"明王及眷屬往佛所也；第七"}]},{"p":83678,"q":"爾時彼佛為王說法","notes":[{"by":"法華經義記","era":"","t":"明如來述此二王子實是善知識也；第十三"}]},{"p":83795,"q":"時雲雷音","notes":[{"by":"法華經義記","era":"","t":"明佛為授記也；第十"}]},{"p":83899,"q":"其王即時","notes":[{"by":"法華經義記","era":"","t":"明王出家修道也；第十一"}]},{"p":83968,"q":"即昇虛空","notes":[{"by":"法華經義記","era":"","t":"明王既得解之後述報子恩也；第十二"}]},{"p":84229,"q":"妙莊嚴王即從虛空中下","notes":[{"by":"法華經義記","era":"","t":"正明勸發聞經；第三臨品末，是經家敘說品得利益。"}]},{"p":84343,"q":"白佛言","notes":[{"by":"法華經義記","era":"","t":"此下是品之第二段，正明勸發之義。"}]},{"p":84423,"q":"佛告大眾","notes":[{"by":"法華經義記","era":"","t":"此下是品中第五，會通古今也。"}]},{"p":84574,"q":"佛說","notes":[{"by":"法華經義記","era":"","t":"是品之第六段，明經家敘說品時得利益也。"}]},{"p":84623,"q":"爾時普賢","notes":[{"by":"法華經義記","era":"","t":"此下是第三段，普賢正勸人行此四行，就中亦有三者：第一總勸也，第二別勸，第三結勸也。"}]},{"p":84687,"q":"又與","notes":[{"by":"法華經義記","era":"","t":"明普賢眷屬之相也；第四"}]},{"p":84739,"q":"到娑婆","notes":[{"by":"法華經義記","era":"","t":"明至佛所致敬也。"}]},{"p":84812,"q":"唯願","notes":[{"by":"法華經義記","era":"","t":"明請答也；第三從"}]},{"p":84846,"q":"佛告普賢","notes":[{"by":"法華經義記","era":"","t":"此下是第二佛答，明勸發之行也。"}]},{"p":84881,"q":"一者","notes":[{"by":"法華經義記","era":"","t":"別出四法之名也；第三"}]},{"p":85366,"q":"亦復與其","notes":[{"by":"法華經義記","era":"","t":"明神呪護；第三"}]},{"p":85698,"q":"若有受持","notes":[{"by":"法華經義記","era":"","t":"明佛神力護，若能受持此經者諸佛神力護之；第四"}]},{"p":85751,"q":"若但書寫","notes":[{"by":"法華經義記","era":"","t":"舉果報勸，若能通此經者，得好果報也。"}]},{"p":85914,"q":"是故","notes":[{"by":"法華義疏","era":"","t":"第五、結嘆。"}]},{"p":85984,"q":"爾時釋迦","notes":[{"by":"法華經義記","era":"","t":"此下是第四，如來述其獎勸，就中亦有三者：第一先述其靈瑞及神呪兩護勸也；第二"}]},{"p":86054,"q":"而能作是神通之願","notes":[{"by":"法華義疏","era":"","t":"第二、嘆其護法。"}]},{"p":86187,"q":"如是之人","notes":[{"by":"法華義疏","era":"","t":"第二、離諸惡嘆。"}]}]},{"base":"T0475","name":"T0475《維摩詰所說經》","path":"01-大正藏/09經集部類/T0475《維摩詰所說經》.md","loci":[{"p":32,"q":"第一","notes":[{"by":"慧遠","era":"","t":"此經始終四門分別：一就處分別；二就會分別；三就義分別；四就文分別。"}]},{"p":75,"q":"大智本","notes":[{"by":"慧遠","era":"","t":"辨其行德，成前知識。"}]},{"p":104,"q":"能師子吼","notes":[{"by":"慧遠","era":"","t":"明其成，行德寬廣名聞十方。"}]},{"p":168,"q":"總持","notes":[{"by":"慧遠","era":"","t":"是陀羅尼，此即十地大陀羅尼。"}]},{"p":213,"q":"已能隨","notes":[{"by":"慧遠","era":"","t":"已下，勝相嚴身，表德名相，愜情稱好。"}]},{"p":271,"q":"名稱高","notes":[{"by":"慧遠","era":"","t":"明其所成，行德殊勝名稱高遠。"}]},{"p":311,"q":"深入緣起","notes":[{"by":"慧遠","era":"","t":"彰其解；三、"}]},{"p":369,"q":"了達","notes":[{"by":"慧遠","era":"","t":"已下，化德成就。"}]},{"p":391,"q":"近無等","notes":[{"by":"慧遠","era":"","t":"歎其所修勝進功德。"}]},{"p":411,"q":"關閉","notes":[{"by":"慧遠","era":"","t":"已下明其利他。"}]},{"p":439,"q":"應病與藥","notes":[{"by":"慧遠","era":"","t":"量宜授法，貪教不淨、瞋教慈心，如是等也。"}]},{"p":502,"q":"等觀","notes":[{"by":"慧遠","era":"","t":"依定立稱，此前約行。"}]},{"p":791,"q":"如是等","notes":[{"by":"慧遠","era":"","t":"也，如是菩薩。"}]},{"p":842,"q":"并餘大威力","notes":[{"by":"慧遠","era":"","t":"辨前兼後，故說為并。"}]},{"p":872,"q":"摩睺羅伽","notes":[{"by":"慧遠","era":"","t":"是腹行神，世人相傳是魔神也。"}]},{"p":891,"q":"優婆塞","notes":[{"by":"慧遠","era":"","t":"名為善宿男，懷善而居；亦云近善住，亦云清信士。"}]},{"p":953,"q":"爾時","notes":[{"by":"慧遠","era":"","t":"獻蓋時也，當爾佛在菴羅園時。"}]},{"p":1014,"q":"遍覆三千大千世界","notes":[{"by":"慧遠","era":"","t":"如經說一四天下，有一須彌、四大海水、鐵圍圍繞，以為一界。"}]},{"p":1155,"q":"合掌禮","notes":[{"by":"慧遠","era":"","t":"等，身業敬也。"}]},{"p":1196,"q":"心淨已度諸禪定","notes":[{"by":"慧遠","era":"","t":"心畢竟離染，超出餘人；一切正受，名度諸禪。"}]},{"p":1244,"q":"於是一切悉見聞","notes":[{"by":"慧遠","era":"","t":"由佛普現，於是會中一切大眾悉見十方無量佛土，及見彼佛、聞其說也。"}]},{"p":1324,"q":"善惡之業亦不亡","notes":[{"by":"慧遠","era":"","t":"真中雖無，世諦恒有用之牽果，故曰不亡。"}]},{"p":1352,"q":"無受行","notes":[{"by":"慧遠","era":"","t":"出其說處，於大千界百億閻浮同時轉也。"}]},{"p":1396,"q":"以斯妙法濟群生","notes":[{"by":"慧遠","era":"","t":"用法教人，所謂以此大乘妙法濟度群生。"}]},{"p":1436,"q":"於善","notes":[{"by":"慧遠","era":"","t":"已下讚嘆如來於緣平等。"}]},{"p":1452,"q":"孰聞","notes":[{"by":"慧遠","era":"","t":"有四行偈，為第四段，訟歎向前所現之事。"}]},{"p":1508,"q":"眾覩希有皆歎佛","notes":[{"by":"慧遠","era":"","t":"有十五行，為第五段，廣歎難餘德。"}]},{"p":1556,"q":"佛以一音演說法","notes":[{"by":"慧遠","era":"","t":"發言不殊，此亦是其隨法一矣。"}]},{"p":1732,"q":"不著世間如蓮華","notes":[{"by":"慧遠","era":"","t":"於有不染，此明離愛。"}]},{"p":1806,"q":"願聞得佛國土清淨","notes":[{"by":"慧遠","era":"","t":"彰己所求，求聞常果。"}]},{"p":1872,"q":"於是寶積及五百","notes":[{"by":"慧遠","era":"","t":"等，是第三段，奉教聽受。"}]},{"p":1904,"q":"所以","notes":[{"by":"慧遠","era":"","t":"上釋前眾生為佛土義。"}]},{"p":2060,"q":"菩薩成","notes":[{"by":"慧遠","era":"","t":"等，對前願聞國土清淨，此義須知。"}]},{"p":2126,"q":"布施","notes":[{"by":"慧遠","era":"","t":"明所起行；三、"}]},{"p":2180,"q":"忍辱","notes":[{"by":"慧遠","era":"","t":"舉因，下明得果，經文不同。"}]},{"p":2417,"q":"迴向","notes":[{"by":"慧遠","era":"","t":"舉因，迴己善法有所趣向，故名迴向。"}]},{"p":2433,"q":"得一切具足功德國土","notes":[{"by":"慧遠","era":"","t":"理實齊通，語之隱顯。"}]},{"p":2516,"q":"命不中夭","notes":[{"by":"慧遠","era":"","t":"無殺生果；言"}]},{"p":2551,"q":"不嫉","notes":[{"by":"慧遠","era":"","t":"無貪嫉行；言"}]},{"p":2699,"q":"是故","notes":[{"by":"慧遠","era":"","t":"是前心淨，得佛一切功德淨土。"}]},{"p":2729,"q":"爾時","notes":[{"by":"慧遠","era":"","t":"生念時也，謂此說時。"}]},{"p":2790,"q":"於意云何","notes":[{"by":"慧遠","era":"","t":"就心總問，問其意解，於汝意中所解云何。"}]},{"p":2819,"q":"是盲者過","notes":[{"by":"慧遠","era":"","t":"答其初問，免過日月，明其日月無不淨咎。"}]},{"p":2849,"q":"非如來咎","notes":[{"by":"慧遠","era":"","t":"取其後答，免過於佛。"}]},{"p":2895,"q":"所以","notes":[{"by":"慧遠","era":"","t":"螺髻自申己之所見，明土實淨，成彼不應。"}]},{"p":2911,"q":"譬如","notes":[{"by":"慧遠","era":"","t":"已下，類以顯勝。"}]},{"p":3081,"q":"汝且觀","notes":[{"by":"慧遠","era":"","t":"暫見非永，故曰且觀。"}]},{"p":3139,"q":"為欲度","notes":[{"by":"慧遠","era":"","t":"辨應顯真，成土本淨。"}]},{"p":3312,"q":"方便品","notes":[{"by":"慧遠","era":"","t":"從此已下第二會說。"}]},{"p":3542,"q":"雖為白衣","notes":[{"by":"慧遠","era":"","t":"已下，即俗以通道。"}]},{"p":3667,"q":"諧偶","notes":[{"by":"慧遠","era":"","t":"心無貪愛，故"}]},{"p":3913,"q":"以如是等無量方便饒益眾生","notes":[{"by":"慧遠","era":"","t":"又復此中巧化眾生，亦即是其施造方便。"}]},{"p":3977,"q":"其往","notes":[{"by":"慧遠","era":"","t":"因其問疾，廣為說法。"}]},{"p":4006,"q":"無力","notes":[{"by":"慧遠","era":"","t":"死也，性不堅固，易可滅壞。"}]},{"p":4025,"q":"為惱","notes":[{"by":"慧遠","era":"","t":"病集，是身苦也。"}]},{"p":4042,"q":"智者所不怙","notes":[{"by":"慧遠","era":"","t":"諸佛賢聖明智慧人，終不恃怙如此苦身。"}]},{"p":4291,"q":"如毒蛇","notes":[{"by":"慧遠","era":"","t":"是其四大違損苦也。"}]},{"p":4351,"q":"從戒","notes":[{"by":"慧遠","era":"","t":"等，是自利行。"}]},{"p":4378,"q":"布施","notes":[{"by":"慧遠","era":"","t":"等，復明自利，施戒忍進四種可解。"}]},{"p":4415,"q":"從方便生","notes":[{"by":"慧遠","era":"","t":"身通、天眼、天耳、他心、宿命、漏盡，是其六也。"}]},{"p":4574,"q":"弟子品","notes":[{"by":"慧遠","era":"","t":"此品之中命聲聞弟子問疾。"}]},{"p":4607,"q":"佛知","notes":[{"by":"慧遠","era":"","t":"如來告問，顯其所說。"}]},{"p":4640,"q":"我不堪","notes":[{"by":"慧遠","era":"","t":"等，是辭言也。"}]},{"p":4668,"q":"時維摩","notes":[{"by":"慧遠","era":"","t":"彰被呵辭；三、"}]},{"p":4790,"q":"若能如是","notes":[{"by":"慧遠","era":"","t":"所印可，嘆勝令學。"}]},{"p":4938,"q":"當如法說","notes":[{"by":"慧遠","era":"","t":"正明理無，亦真法中無三種壽，準前可知。"}]},{"p":5005,"q":"法無名字","notes":[{"by":"慧遠","era":"","t":"正明理無，謂真法中無彼妄想所立名字。"}]},{"p":5050,"q":"離我所","notes":[{"by":"慧遠","era":"","t":"就十八界明法離相。"}]},{"p":5095,"q":"法隨於如","notes":[{"by":"慧遠","era":"","t":"當相正辨不異如義。"}]},{"p":5116,"q":"法無動","notes":[{"by":"慧遠","era":"","t":"五句之文，明六識空；"}]},{"p":5149,"q":"法離好","notes":[{"by":"慧遠","era":"","t":"七句之文，明六塵空。"}]},{"p":5183,"q":"法無高下","notes":[{"by":"慧遠","era":"","t":"還就塵體以辨其空。"}]},{"p":5258,"q":"當了","notes":[{"by":"慧遠","era":"","t":"教離癡心；三、"}]},{"p":5276,"q":"以大悲","notes":[{"by":"慧遠","era":"","t":"不教捨小心；四、"}]},{"p":5375,"q":"所以","notes":[{"by":"慧遠","era":"","t":"自徵起後，下對辨釋。"}]},{"p":5392,"q":"時維摩","notes":[{"by":"慧遠","era":"","t":"出被呵辭；三、"}]},{"p":5427,"q":"住平等法","notes":[{"by":"慧遠","era":"","t":"教修等心，番前有慈而不能普；"}]},{"p":5470,"q":"以空聚","notes":[{"by":"慧遠","era":"","t":"標杓無心，雖在諸味不生分別。"}]},{"p":5543,"q":"若能不捨八邪","notes":[{"by":"慧遠","era":"","t":"已下，就乞食後教生道法。"}]},{"p":5608,"q":"非住世間","notes":[{"by":"慧遠","era":"","t":"牒前一食施於一切供佛及聖。"}]},{"p":5659,"q":"為不空食人之施","notes":[{"by":"慧遠","era":"","t":"結嘆第三施以一食施於一切供佛及聖。"}]},{"p":5688,"q":"即於","notes":[{"by":"慧遠","era":"","t":"明已聞說，準此類餘，乘於一切菩薩深敬。"}]},{"p":5719,"q":"其誰","notes":[{"by":"慧遠","era":"","t":"明已因是慕大厭小。"}]},{"p":5802,"q":"所以","notes":[{"by":"慧遠","era":"","t":"將其化法類己難辭，明無所畏。"}]},{"p":5885,"q":"亦不與俱","notes":[{"by":"慧遠","era":"","t":"是佛不住有為行也。"}]},{"p":5981,"q":"若須菩提不見佛","notes":[{"by":"慧遠","era":"","t":"約凡設難，若同凡夫乃可取食。"}]},{"p":6073,"q":"若須菩提入諸邪","notes":[{"by":"慧遠","era":"","t":"明同外道無解脫行。"}]},{"p":6145,"q":"為與眾魔共一手","notes":[{"by":"慧遠","era":"","t":"明同眾魔乃可取食。"}]},{"p":6321,"q":"所以","notes":[{"by":"慧遠","era":"","t":"明言如化，不離向前幻化相矣。"}]},{"p":6349,"q":"何以","notes":[{"by":"慧遠","era":"","t":"釋前智者不著所以，先徵、後解。"}]},{"p":6448,"q":"所以","notes":[{"by":"慧遠","era":"","t":"徵前起後，下對辨之。"}]},{"p":6475,"q":"時維摩","notes":[{"by":"慧遠","era":"","t":"出被呵辭；三、"}]},{"p":6505,"q":"無以穢","notes":[{"by":"慧遠","era":"","t":"呵違欲說，約喻呵之。"}]},{"p":6595,"q":"此比丘久發大","notes":[{"by":"慧遠","era":"","t":"重就第二呵違根說。"}]},{"p":6689,"q":"即時","notes":[{"by":"慧遠","era":"","t":"由識宿命還得本心，謂還得本大乘心矣。"}]},{"p":6736,"q":"我念聲聞不觀人","notes":[{"by":"慧遠","era":"","t":"申己卑闕，以小自責。"}]},{"p":6799,"q":"所以","notes":[{"by":"慧遠","era":"","t":"徵前起後，下正辨釋。"}]},{"p":6829,"q":"謂無常","notes":[{"by":"慧遠","era":"","t":"等，隨別列之。"}]},{"p":7168,"q":"我時默","notes":[{"by":"慧遠","era":"","t":"諸梵讚嘆，問真天眼；五、維摩為說；六、諸梵聞之，發心願求，禮敬辭去。"}]},{"p":7437,"q":"彼罪性","notes":[{"by":"慧遠","era":"","t":"學等，明罪體空，成應直滅。"}]},{"p":7502,"q":"不出","notes":[{"by":"慧遠","era":"","t":"自下第三重復約心破遣罪相成前第二。"}]},{"p":7597,"q":"一切法生滅","notes":[{"by":"慧遠","era":"","t":"已下，約法以破。"}]},{"p":7623,"q":"諸法皆","notes":[{"by":"慧遠","era":"","t":"明法心起，心外無相，類罪無相。"}]},{"p":7645,"q":"以妄想","notes":[{"by":"慧遠","era":"","t":"合上來別教。"}]},{"p":7825,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後解。"}]},{"p":7852,"q":"問我言","notes":[{"by":"慧遠","era":"","t":"等，彰請問辭。"}]},{"p":7965,"q":"為無為法","notes":[{"by":"慧遠","era":"","t":"彰其所求，無為涅槃是所求也。"}]},{"p":8006,"q":"處於涅槃","notes":[{"by":"慧遠","era":"","t":"總明所入，謂處法性無為涅槃，猶前為無為法耳。"}]},{"p":8026,"q":"度五道","notes":[{"by":"慧遠","era":"","t":"等，壞魔法也。"}]},{"p":8052,"q":"摧諸","notes":[{"by":"慧遠","era":"","t":"明無愛故不著五塵。"}]},{"p":8098,"q":"若能","notes":[{"by":"慧遠","era":"","t":"以下總以結嘆。"}]},{"p":8194,"q":"即出家","notes":[{"by":"慧遠","era":"","t":"菩提心義，廣如別章，此應具論。"}]},{"p":8258,"q":"世尊","notes":[{"by":"慧遠","era":"","t":"已下，舉被呵事。"}]},{"p":8405,"q":"默往","notes":[{"by":"慧遠","era":"","t":"已下第二呵也。"}]},{"p":8450,"q":"轉輪聖","notes":[{"by":"慧遠","era":"","t":"是其後段，遮其口言。"}]},{"p":8630,"q":"即聞","notes":[{"by":"慧遠","era":"","t":"印維摩語，明佛真身無病是實。"}]},{"p":8744,"q":"菩薩品","notes":[{"by":"慧遠","era":"","t":"前品告命聲聞問疾，彼辭不堪，今告菩薩。"}]},{"p":8815,"q":"時維摩","notes":[{"by":"慧遠","era":"","t":"人中得記，捨此身已上生兜率，後生人間然後成佛。"}]},{"p":9030,"q":"法亦如","notes":[{"by":"慧遠","era":"","t":"通明凡聖二法如也。"}]},{"p":9149,"q":"寂滅","notes":[{"by":"慧遠","era":"","t":"是總，餘句是別。"}]},{"p":9192,"q":"亦無退","notes":[{"by":"慧遠","era":"","t":"是呵辭也，呵令相捨；"}]},{"p":9247,"q":"不觀","notes":[{"by":"慧遠","era":"","t":"列名，緣修諸度，名之為行，於真本無，故曰不行。"}]},{"p":9362,"q":"無為","notes":[{"by":"慧遠","era":"","t":"列名，體常不變故曰無為。"}]},{"p":9386,"q":"不會","notes":[{"by":"慧遠","era":"","t":"已下，廣顯不可身得之義。"}]},{"p":9438,"q":"無取","notes":[{"by":"慧遠","era":"","t":"列名，遠離妄識能緣心斷，故曰無取。"}]},{"p":9454,"q":"善寂","notes":[{"by":"慧遠","era":"","t":"列名，不起染過故曰善寂。"}]},{"p":9476,"q":"無異","notes":[{"by":"慧遠","era":"","t":"釋也，世法參差於理如等，故曰法等，等取故無異。"}]},{"p":9649,"q":"直心","notes":[{"by":"慧遠","era":"","t":"列名，於諸行問，起意修學，名為發行。"}]},{"p":9806,"q":"神通","notes":[{"by":"慧遠","era":"","t":"列名，成就八脫故曰解脫。"}]},{"p":9852,"q":"多聞","notes":[{"by":"慧遠","era":"","t":"彰其行能，能治染過，故捨有為。"}]},{"p":9940,"q":"一切法是","notes":[{"by":"慧遠","era":"","t":"就詮以舉，所謂五陰一切諸法。"}]},{"p":9975,"q":"師子吼","notes":[{"by":"慧遠","era":"","t":"是列其名字，能宣正法摧諸外道名師子吼。"}]},{"p":10004,"q":"三明","notes":[{"by":"慧遠","era":"","t":"列名，命宿、天眼及與漏盡是其三也。"}]},{"p":10162,"q":"時魔","notes":[{"by":"慧遠","era":"","t":"此名極惡，依於佛法而得善利，不念加報及欲毀壞，故曰極惡。"}]},{"p":10216,"q":"而語","notes":[{"by":"慧遠","era":"","t":"已下，口言教勸。"}]},{"p":10245,"q":"以求善本","notes":[{"by":"慧遠","era":"","t":"就德以呼，持世出家受行正法，故曰正士。"}]},{"p":10300,"q":"沙門","notes":[{"by":"慧遠","era":"","t":"諸女既是非法之物，莫用要我沙門釋子。"}]},{"p":10341,"q":"即語魔","notes":[{"by":"慧遠","era":"","t":"彰彼維摩降魔索女以法化益；四、"}]},{"p":10385,"q":"而不能隱","notes":[{"by":"慧遠","era":"","t":"復盡力，維摩制之，"}]},{"p":10571,"q":"樂隨護","notes":[{"by":"慧遠","era":"","t":"守菩提心，守護之相如《涅槃》說。"}]},{"p":10628,"q":"樂降伏","notes":[{"by":"慧遠","era":"","t":"等，明修廣行。"}]},{"p":10658,"q":"樂嚴道場","notes":[{"by":"慧遠","era":"","t":"修起法身，亦如上說。"}]},{"p":10760,"q":"以我等與此居士","notes":[{"by":"慧遠","era":"","t":"翻前我欲與汝俱還。"}]},{"p":10881,"q":"無盡燈者","notes":[{"by":"慧遠","era":"","t":"牒前起後，次辨、後結。"}]},{"p":11013,"q":"爾時","notes":[{"by":"慧遠","era":"","t":"已下，是第七段諸女辭去。"}]},{"p":11041,"q":"有如是自在神力","notes":[{"by":"慧遠","era":"","t":"結嘆向前降魔之力。"}]},{"p":11115,"q":"設大施","notes":[{"by":"慧遠","era":"","t":"等，彰被呵事。"}]},{"p":11416,"q":"以敬事","notes":[{"by":"慧遠","era":"","t":"依前第二自利之行明修成相。"}]},{"p":11527,"q":"解眾生縛","notes":[{"by":"慧遠","era":"","t":"修習四地至七地行，名修行地。"}]},{"p":11552,"q":"知一切眾生心念","notes":[{"by":"慧遠","era":"","t":"是九地中入行成就。"}]},{"p":11606,"q":"起一切善","notes":[{"by":"慧遠","era":"","t":"是佛如來智慧莊嚴。"}]},{"p":11658,"q":"大施主","notes":[{"by":"慧遠","era":"","t":"能消物養生世福善名"}]},{"p":11706,"q":"我時心得清淨","notes":[{"by":"慧遠","era":"","t":"已下，約就財事以明法施。"}]},{"p":11742,"q":"我言","notes":[{"by":"慧遠","era":"","t":"別教修習；第三、"}]},{"p":11768,"q":"分作二","notes":[{"by":"慧遠","era":"","t":"用之轉施，為欲則財教人等施，故轉施之。"}]},{"p":11896,"q":"城中一","notes":[{"by":"慧遠","era":"","t":"是第四段明法施益。"}]},{"p":11937,"q":"如是諸菩薩各各向","notes":[{"by":"慧遠","era":"","t":"告餘菩薩，阿難總舉。"}]},{"p":11997,"q":"文殊師利問疾品","notes":[{"by":"慧遠","era":"","t":"前告諸人皆辭不堪，此告文殊令往問疾，因以標品，名為文殊問疾品矣。"}]},{"p":12048,"q":"深達實相","notes":[{"by":"慧遠","era":"","t":"是方便智亦名教智，能宣法化故云善說，所說要當故名法要。"}]},{"p":12106,"q":"雖然","notes":[{"by":"慧遠","era":"","t":"已下，承力往問。"}]},{"p":12121,"q":"於是眾中","notes":[{"by":"慧遠","era":"","t":"就處總舉，謂於菴羅佛眾之中。"}]},{"p":12169,"q":"即時","notes":[{"by":"慧遠","era":"","t":"明前諸眾樂欲隨從。"}]},{"p":12298,"q":"維摩","notes":[{"by":"慧遠","era":"","t":"正對問人廣宣所說。"}]},{"p":12337,"q":"若來","notes":[{"by":"慧遠","era":"","t":"已下，別述前義。"}]},{"p":12353,"q":"所以","notes":[{"by":"慧遠","era":"","t":"徵問，我有何以說生病滅則我病滅？"}]},{"p":12381,"q":"且置","notes":[{"by":"慧遠","era":"","t":"已下問答辨法。"}]},{"p":12489,"q":"入生死","notes":[{"by":"慧遠","era":"","t":"為物受身名有生死，有生死故諸苦隨逐，名有病矣。"}]},{"p":12619,"q":"維摩","notes":[{"by":"慧遠","era":"","t":"答，初別、後結。"}]},{"p":12649,"q":"以空空","notes":[{"by":"慧遠","era":"","t":"以理空為土空也。"}]},{"p":12669,"q":"無分別","notes":[{"by":"慧遠","era":"","t":"空室顯之令人悟解，名為"}]},{"p":12692,"q":"分別亦空","notes":[{"by":"慧遠","era":"","t":"此言拂詮而顯理也。"}]},{"p":12713,"q":"當於六十二見中求","notes":[{"by":"慧遠","era":"","t":"六十二見，後當具論。"}]},{"p":12806,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後解。"}]},{"p":12867,"q":"我病無形不可見","notes":[{"by":"慧遠","era":"","t":"以病實無，故無形相而可見也。"}]},{"p":12970,"q":"而眾生","notes":[{"by":"慧遠","era":"","t":"舉病應有，成前實無。"}]},{"p":13027,"q":"不說厭","notes":[{"by":"慧遠","era":"","t":"常隨諸有，不厭自身而取滅也。"}]},{"p":13046,"q":"說身無我","notes":[{"by":"慧遠","era":"","t":"修滅罪行，過去所犯名為先罪，追改名悔；"}]},{"p":13315,"q":"又此法者各不相知","notes":[{"by":"慧遠","era":"","t":"別觀五陰體非五陰體非神我。"}]},{"p":13435,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後解。"}]},{"p":13497,"q":"以無所受","notes":[{"by":"慧遠","era":"","t":"而受諸受明受為物，為化眾生具受諸苦，名"}]},{"p":13667,"q":"為斷老","notes":[{"by":"慧遠","era":"","t":"等，嘆上修悲。"}]},{"p":13779,"q":"菩薩斷除客塵煩惱而起大悲","notes":[{"by":"慧遠","era":"","t":"故應除離愛見之悲。"}]},{"p":14050,"q":"謂菩薩住貪欲","notes":[{"by":"慧遠","era":"","t":"等，釋無慧也。"}]},{"p":14270,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後辨，反以顯之。"}]},{"p":14298,"q":"是故","notes":[{"by":"慧遠","era":"","t":"已下，結勸不住。"}]},{"p":14314,"q":"離此二","notes":[{"by":"慧遠","era":"","t":"結成菩薩不住道行。"}]},{"p":14377,"q":"雖過魔","notes":[{"by":"慧遠","era":"","t":"是入寂行，所證淵寂。"}]},{"p":14416,"q":"不入正位","notes":[{"by":"慧遠","era":"","t":"明不證無，所謂不入無相正位。"}]},{"p":14530,"q":"而現受","notes":[{"by":"慧遠","era":"","t":"等，顯不住無。"}]},{"p":14958,"q":"不思議品","notes":[{"by":"慧遠","era":"","t":"此初對中前明所行，此明所成。"}]},{"p":14978,"q":"作是念","notes":[{"by":"慧遠","era":"","t":"等，正明所念。"}]},{"p":15080,"q":"非有色","notes":[{"by":"慧遠","era":"","t":"了知真中無十八界。"}]},{"p":15124,"q":"不著佛","notes":[{"by":"慧遠","era":"","t":"等，教其捨相。"}]},{"p":15164,"q":"所以","notes":[{"by":"慧遠","era":"","t":"明其取相不名求法。"}]},{"p":15211,"q":"若行生","notes":[{"by":"慧遠","era":"","t":"已下，明其取相不名求法。"}]},{"p":15275,"q":"若取捨","notes":[{"by":"慧遠","era":"","t":"明有見心不名求法。"}]},{"p":15295,"q":"若著處","notes":[{"by":"慧遠","era":"","t":"明其取相不名求法。"}]},{"p":15315,"q":"若隨相","notes":[{"by":"慧遠","era":"","t":"明隨識不名求法。"}]},{"p":15335,"q":"若住於","notes":[{"by":"慧遠","era":"","t":"明其取相不名求法。"}]},{"p":15361,"q":"若行見","notes":[{"by":"慧遠","era":"","t":"明有見等不名求法。"}]},{"p":15438,"q":"於諸法中得法眼淨","notes":[{"by":"慧遠","era":"","t":"此法眼淨，初地見道。"}]},{"p":15578,"q":"彼佛遣","notes":[{"by":"慧遠","era":"","t":"神力使來，因之為遣。"}]},{"p":15623,"q":"其室廣","notes":[{"by":"慧遠","era":"","t":"等，正明所見。"}]},{"p":15730,"q":"新發","notes":[{"by":"慧遠","era":"","t":"命小菩薩及聲聞眾，令其悶同坐。"}]},{"p":15929,"q":"不可思","notes":[{"by":"慧遠","era":"","t":"經中亦名不思議也。"}]},{"p":15991,"q":"須彌入芥","notes":[{"by":"慧遠","era":"","t":"二、廣狹自在，"}]},{"p":17845,"q":"當住度脫一切眾生","notes":[{"by":"慧遠","era":"","t":"無上菩提獨善不階，故求佛德須度眾生。"}]},{"p":17981,"q":"身為本","notes":[{"by":"慧遠","era":"","t":"言，對問辨釋。"}]},{"p":18102,"q":"無住本","notes":[{"by":"慧遠","era":"","t":"明前倒想八識真心而為本也。"}]},{"p":18150,"q":"華至","notes":[{"by":"慧遠","era":"","t":"明諸菩薩聲聞心別華至有異。"}]},{"p":18171,"q":"一切弟子神力去","notes":[{"by":"慧遠","era":"","t":"明諸聲聞恥花偏著，神力遣之而不能去。"}]},{"p":18217,"q":"天曰","notes":[{"by":"慧遠","era":"","t":"天女隨答以理教呵。"}]},{"p":18251,"q":"若於佛法出家","notes":[{"by":"慧遠","era":"","t":"已下以理教示。"}]},{"p":18439,"q":"如何耆舊大智而默","notes":[{"by":"慧遠","era":"","t":"道其耆舊彰其學久，云其大智顯其能答。"}]},{"p":18625,"q":"天女","notes":[{"by":"慧遠","era":"","t":"答，明其無轉。"}]},{"p":18871,"q":"但聞菩薩大慈大悲","notes":[{"by":"慧遠","era":"","t":"明己偏求大乘所由。"}]},{"p":18893,"q":"此室常現八未曾","notes":[{"by":"慧遠","era":"","t":"總明自地入此室中求大所以。"}]},{"p":19250,"q":"何以不轉","notes":[{"by":"慧遠","era":"","t":"三、舍利答。"}]},{"p":19283,"q":"譬如","notes":[{"by":"慧遠","era":"","t":"寄喻反問，合其生解。"}]},{"p":19362,"q":"即時天女以神通","notes":[{"by":"慧遠","era":"","t":"即取其所答類顯諸法，彰問不應。"}]},{"p":19482,"q":"是故","notes":[{"by":"慧遠","era":"","t":"已下，引說證成。"}]},{"p":19497,"q":"即時天女還攝神","notes":[{"by":"慧遠","era":"","t":"即約其所答，明佛菩薩得菩提義無得而得。"}]},{"p":19828,"q":"汝得阿羅漢道","notes":[{"by":"慧遠","era":"","t":"已下，解釋諸佛得無得義。"}]},{"p":19894,"q":"已能遊","notes":[{"by":"慧遠","era":"","t":"明其用勝，此八地上淨佛國土自在行也。"}]},{"p":19942,"q":"佛道品","notes":[{"by":"慧遠","era":"","t":"通相論之，一切所修皆菩薩行、悉是佛道。"}]},{"p":20072,"q":"示行貪","notes":[{"by":"慧遠","era":"","t":"等，現起煩惱，三毒可知。"}]},{"p":20110,"q":"示行慳","notes":[{"by":"慧遠","era":"","t":"現起凡夫障道之行。"}]},{"p":20213,"q":"而於眾生猶如橋梁","notes":[{"by":"慧遠","era":"","t":"內實卑濡荷負一切，故於眾生猶如橋梁。"}]},{"p":20250,"q":"示入聲聞","notes":[{"by":"慧遠","era":"","t":"已下，起二乘行；三、"}]},{"p":20281,"q":"示入貧","notes":[{"by":"慧遠","era":"","t":"隨生死行；四、"}]},{"p":20630,"q":"卑濕淤泥乃生此華","notes":[{"by":"慧遠","era":"","t":"喻前所明凡夫能也。"}]},{"p":20673,"q":"又如殖","notes":[{"by":"慧遠","era":"","t":"就見煩惱釋為佛種；三、"}]},{"p":20738,"q":"是故","notes":[{"by":"慧遠","era":"","t":"是塵勞疇為如來種，五無間罪生佛法故。"}]},{"p":20811,"q":"誠如所言，塵勞之疇為如來種","notes":[{"by":"慧遠","era":"","t":"述前凡夫能為佛種。"}]},{"p":20862,"q":"而今我等永不能發","notes":[{"by":"慧遠","era":"","t":"呵毀二乘，成上文中聲聞非種。"}]},{"p":21053,"q":"智度菩薩母","notes":[{"by":"慧遠","era":"","t":"照空實慧名為智度，此能內養故說為母。"}]},{"p":21095,"q":"畢竟空寂舍","notes":[{"by":"慧遠","era":"","t":"因緣諸法性相皆空名畢竟空，此為聖依，其猶舍宅，故名為舍。"}]},{"p":21191,"q":"浴此無垢人","notes":[{"by":"慧遠","era":"","t":"神足、天眼、天耳、他心及與宿命，是其五通。"}]},{"p":21275,"q":"從於淨命生","notes":[{"by":"慧遠","era":"","t":"世人多以習誦外典而增智慧，維摩不爾，博受聖教而增智慧。"}]},{"p":21317,"q":"摧滅","notes":[{"by":"慧遠","era":"","t":"已下有二十八偈，彰其所作。"}]},{"p":21581,"q":"或作日月","notes":[{"by":"慧遠","era":"","t":"現作日月星宿諸天，且言日月。"}]},{"p":21605,"q":"劫中有疾","notes":[{"by":"慧遠","era":"","t":"六偈之文，明其隨苦救濟之行；"}]},{"p":22070,"q":"入不二法門品","notes":[{"by":"慧遠","era":"","t":"〈問疾〉至此明修教行，教行既成便能入證。"}]},{"p":22094,"q":"云何菩薩入不二","notes":[{"by":"慧遠","era":"","t":"等，正宣問辭。"}]},{"p":22305,"q":"不動則無念","notes":[{"by":"慧遠","era":"","t":"於情分齊，依動起念；於真常寂，業動本無。"}]},{"p":22347,"q":"若知一相即是無相","notes":[{"by":"慧遠","era":"","t":"知有即無，亦不取無；知無即有，以即有故不偏取無。"}]},{"p":22443,"q":"入無相","notes":[{"by":"慧遠","era":"","t":"等，明其證實，即解入義。"}]},{"p":22494,"q":"無縛","notes":[{"by":"慧遠","era":"","t":"此推對破，以無縛故，不可對之說涅槃解。"}]},{"p":22633,"q":"於其中","notes":[{"by":"慧遠","era":"","t":"以不出故，常隨世間而不除捨，故曰不散。"}]},{"p":22688,"q":"不然","notes":[{"by":"慧遠","era":"","t":"以無縛故，本來不然。"}]},{"p":22884,"q":"非色滅空","notes":[{"by":"慧遠","era":"","t":"簡異將因分果之空，如陽炎水自性非水，不待塵大分為無水。"}]},{"p":23081,"q":"安住其中","notes":[{"by":"慧遠","era":"","t":"為入不二，牒以結之。"}]},{"p":23266,"q":"佛即是法，法即是眾","notes":[{"by":"慧遠","era":"","t":"歷別相即而顯不二。"}]},{"p":23289,"q":"一切法亦爾","notes":[{"by":"慧遠","era":"","t":"以此三寶同體不二，類一切法悉皆同體，故云亦爾。"}]},{"p":23331,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋之，先問、後解。"}]},{"p":23872,"q":"文殊","notes":[{"by":"慧遠","era":"","t":"復一歎以顯之。"}]},{"p":23897,"q":"如我意者","notes":[{"by":"慧遠","era":"","t":"文殊彰己隨自意語不隨他也。"}]},{"p":23999,"q":"真入不二","notes":[{"by":"慧遠","era":"","t":"上來第一明入不二，下明說益。"}]},{"p":24105,"q":"而語","notes":[{"by":"慧遠","era":"","t":"已下，正出呵辭。"}]},{"p":24121,"q":"豈雜欲","notes":[{"by":"慧遠","era":"","t":"許為取飲，令求淨食。"}]},{"p":24283,"q":"彼佛與","notes":[{"by":"慧遠","era":"","t":"是第四段重明人勝。"}]},{"p":24443,"q":"而告之","notes":[{"by":"慧遠","era":"","t":"教往取食；三、"}]},{"p":24468,"q":"國名眾香","notes":[{"by":"慧遠","era":"","t":"四、所現佛，"}]},{"p":24528,"q":"願得","notes":[{"by":"慧遠","era":"","t":"已下，教從求食。"}]},{"p":24570,"q":"時化","notes":[{"by":"慧遠","era":"","t":"明化菩薩蒙命往取。"}]},{"p":24678,"q":"彼諸大士見化","notes":[{"by":"慧遠","era":"","t":"已下，明眾香國諸菩薩等因化往彼，知此娑婆，而來聽法。"}]},{"p":24732,"q":"下方度","notes":[{"by":"慧遠","era":"","t":"答上問中娑婆世界為在何許。"}]},{"p":24780,"q":"彼有菩薩名維摩","notes":[{"by":"慧遠","era":"","t":"答上問中今此上人從何所來，明此化人維摩遣來。"}]},{"p":24863,"q":"一切十方皆遣化往","notes":[{"by":"慧遠","era":"","t":"歎其化廣，對其後問。"}]},{"p":24909,"q":"俱發聲","notes":[{"by":"慧遠","era":"","t":"等，發言正請。"}]},{"p":24973,"q":"勿使","notes":[{"by":"慧遠","era":"","t":"已下，明教所為。"}]},{"p":25001,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後解。"}]},{"p":25038,"q":"時化菩薩既受鉢","notes":[{"by":"慧遠","era":"","t":"化及彼眾承力至此。"}]},{"p":25329,"q":"勿以聲聞小德小智稱量如來無量福慧","notes":[{"by":"慧遠","era":"","t":"言小德者，聲聞福德莊嚴少也。"}]},{"p":25414,"q":"於是鉢飯悉飽眾","notes":[{"by":"慧遠","era":"","t":"是第三段明諸大眾共食不盡。"}]},{"p":25535,"q":"菩薩各各坐香樹","notes":[{"by":"慧遠","era":"","t":"等，依香具善。"}]},{"p":25628,"q":"是地獄","notes":[{"by":"慧遠","era":"","t":"欝單越、長壽天等難處也。"}]},{"p":25684,"q":"是殺生","notes":[{"by":"慧遠","era":"","t":"等，明其十惡。"}]},{"p":25778,"q":"是慳悋","notes":[{"by":"慧遠","era":"","t":"等，彰其下弊。"}]},{"p":25836,"q":"是持戒","notes":[{"by":"慧遠","era":"","t":"等，明其戒行。"}]},{"p":25853,"q":"是障礙","notes":[{"by":"慧遠","era":"","t":"明前二犯能障道也。"}]},{"p":25934,"q":"譬如","notes":[{"by":"慧遠","era":"","t":"喻下食可知。"}]},{"p":26092,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後解。"}]},{"p":26117,"q":"何等","notes":[{"by":"慧遠","era":"","t":"別，先問、後別，通皆利他。"}]},{"p":26324,"q":"不與聲聞而相違背","notes":[{"by":"慧遠","era":"","t":"是第二句，於他學處去恚礙心。"}]},{"p":26430,"q":"菩薩行品","notes":[{"by":"慧遠","era":"","t":"於此品中，因彼眾香菩薩諸法，廣辨菩薩盡不盡行，因以標品，是故名為菩薩行品。"}]},{"p":26448,"q":"其地忽然廣博嚴","notes":[{"by":"慧遠","era":"","t":"等，正明現相。"}]},{"p":26636,"q":"一面立","notes":[{"by":"慧遠","era":"","t":"次諸菩薩、後餘聲聞釋梵等眾，咸皆避坐，稽首佛足。"}]},{"p":27522,"q":"如是見","notes":[{"by":"慧遠","era":"","t":"略明佛等，此即明佛證智等也。"}]},{"p":27624,"q":"是故名為三藐","notes":[{"by":"慧遠","era":"","t":"已下，結歎顯勝，生眾重心。"}]},{"p":27668,"q":"正使","notes":[{"by":"慧遠","era":"","t":"已下，假舉三千大千眾生皆如阿難，壽命一劫，亦不能受。"}]},{"p":27763,"q":"佛告","notes":[{"by":"慧遠","era":"","t":"已下是第三句如來安慰。"}]},{"p":27894,"q":"爾時眾香世界菩薩來者","notes":[{"by":"慧遠","era":"","t":"已下，以法正教。"}]},{"p":27993,"q":"有盡","notes":[{"by":"慧遠","era":"","t":"世帝可思言。"}]},{"p":28032,"q":"不盡有為","notes":[{"by":"慧遠","era":"","t":"即是《地經》發起勝行常隨有也。"}]},{"p":28123,"q":"求法","notes":[{"by":"慧遠","era":"","t":"已下明勝進行。"}]},{"p":28139,"q":"入生死而無所畏","notes":[{"by":"慧遠","era":"","t":"其義相似，翻譯不同。"}]},{"p":28268,"q":"發行善根","notes":[{"by":"慧遠","era":"","t":"明初地上出世間行。"}]},{"p":28373,"q":"常求無念實相智慧","notes":[{"by":"慧遠","era":"","t":"對上初句，明攝對治，修起向前破煩惱慧。"}]},{"p":28408,"q":"不壞","notes":[{"by":"慧遠","era":"","t":"依前聞佛志而不惓，修攝善行。"}]},{"p":28634,"q":"觀於寂滅","notes":[{"by":"慧遠","era":"","t":"是初地中見道解也，見無常等四法即名為見道。"}]},{"p":28953,"q":"歎未","notes":[{"by":"慧遠","era":"","t":"等，口業歎也。"}]},{"p":29016,"q":"欲見如來，為以何等觀如來乎","notes":[{"by":"慧遠","era":"","t":"維摩向前自從其舍欲往見佛，說之以為欲見如來。"}]},{"p":29068,"q":"不觀色","notes":[{"by":"慧遠","era":"","t":"不觀佛身同色有也。"}]},{"p":29131,"q":"不在三界","notes":[{"by":"慧遠","era":"","t":"貪嗔癡惑名為三垢，佛先斷竟名為已離。"}]},{"p":29206,"q":"不此不彼","notes":[{"by":"慧遠","era":"","t":"解亦有二：一、遣相分別。"}]},{"p":29225,"q":"不可以識識","notes":[{"by":"慧遠","era":"","t":"來，明雖妄總，智知識識是妄想故。"}]},{"p":29307,"q":"不來不去","notes":[{"by":"慧遠","era":"","t":"來去就身，解有兩義：一、遣相分別，來去悉無名不來去。"}]},{"p":29344,"q":"非取非捨","notes":[{"by":"慧遠","era":"","t":"取淨捨染名為取捨。"}]},{"p":29378,"q":"非大非小","notes":[{"by":"慧遠","era":"","t":"解有兩義：一、遣相分別，大小竝絕名非大小。"}]},{"p":29406,"q":"於諸法無分別","notes":[{"by":"慧遠","era":"","t":"體真常住，無有始生亦無終滅。"}]},{"p":29548,"q":"無沒生也","notes":[{"by":"慧遠","era":"","t":"舍利所得空無我理，不同事有故無生沒。"}]},{"p":29665,"q":"沒者","notes":[{"by":"慧遠","era":"","t":"已下，簡聖異凡，明己無生。"}]},{"p":29824,"q":"夫日何故行閻浮提","notes":[{"by":"慧遠","era":"","t":"四、舍利答。"}]},{"p":29929,"q":"告維摩","notes":[{"by":"慧遠","era":"","t":"等，正勸令現。"}]},{"p":30153,"q":"以右手","notes":[{"by":"慧遠","era":"","t":"等，顯樓取相。"}]},{"p":30170,"q":"持華鬘","notes":[{"by":"慧遠","era":"","t":"後正取中，句別有四：一、入三昧取彼置此。"}]},{"p":30601,"q":"若有手得是經典","notes":[{"by":"慧遠","era":"","t":"已下，是第三句，明其讀誦解釋等益。"}]},{"p":30642,"q":"其有供養如是人","notes":[{"by":"慧遠","era":"","t":"是第四句，明其供養維摩之益。"}]},{"p":30678,"q":"若聞是經能隨喜","notes":[{"by":"慧遠","era":"","t":"已下，是第七句，明其為化宣說之益。"}]},{"p":30749,"q":"爾時釋提桓因","notes":[{"by":"慧遠","era":"","t":"舉嘆經人，此乃天帝之別名也。"}]},{"p":30802,"q":"如我解","notes":[{"by":"慧遠","era":"","t":"明學多益，令人修習。"}]},{"p":30838,"q":"何況","notes":[{"by":"慧遠","era":"","t":"明依經義修行之益。"}]},{"p":30882,"q":"安處道場","notes":[{"by":"慧遠","era":"","t":"是八地上所得利益。"}]},{"p":30923,"q":"所在","notes":[{"by":"慧遠","era":"","t":"明有經處往彼守護，未信令信、已信作護。"}]},{"p":30980,"q":"善哉","notes":[{"by":"慧遠","era":"","t":"總嘆，下別述之。"}]},{"p":31067,"q":"正使","notes":[{"by":"慧遠","era":"","t":"明財供養不及修經。"}]},{"p":31105,"q":"或一劫","notes":[{"by":"慧遠","era":"","t":"等，明供時節。"}]},{"p":31185,"q":"若一劫","notes":[{"by":"慧遠","era":"","t":"等，明供久近。"}]},{"p":31288,"q":"所以","notes":[{"by":"慧遠","era":"","t":"約佛真德顯經殊，明持福多。"}]},{"p":31403,"q":"其聲聞僧三十六億那由他","notes":[{"by":"慧遠","era":"","t":"等，明眾多少。"}]},{"p":31946,"q":"若聞如是等經","notes":[{"by":"慧遠","era":"","t":"已下，約對前法以明供養。"}]},{"p":32057,"q":"依了義經不依不了義","notes":[{"by":"慧遠","era":"","t":"顯實分明名了義經，憑之取義故說為依。"}]},{"p":32131,"q":"不復起見","notes":[{"by":"慧遠","era":"","t":"正顯觀益，一切斷常有等見不復起也。"}]},{"p":32153,"q":"王子月蓋從藥王佛聞如是","notes":[{"by":"慧遠","era":"","t":"聞法獲益，修行法供。"}]},{"p":32185,"q":"白佛","notes":[{"by":"慧遠","era":"","t":"已後，修行法供。"}]},{"p":32300,"q":"得陀羅尼","notes":[{"by":"慧遠","era":"","t":"明佛滅後以經化地為法供養。"}]},{"p":32404,"q":"無量眾生得生天上","notes":[{"by":"慧遠","era":"","t":"就引證中，上來第二正引往事明財供養不及法供。"}]},{"p":32686,"q":"如此輩人","notes":[{"by":"慧遠","era":"","t":"牒前未來發心之人。"}]},{"p":32732,"q":"有二","notes":[{"by":"慧遠","era":"","t":"人舉數，次列兩名。"}]},{"p":32852,"q":"何等","notes":[{"by":"慧遠","era":"","t":"別，先問、後辨。"}]},{"p":33073,"q":"奉持","notes":[{"by":"慧遠","era":"","t":"對佛向前舉法付囑，自誓弘通。"}]},{"p":33201,"q":"合掌白","notes":[{"by":"慧遠","era":"","t":"等，舉傳通辭。"}]}]},{"base":"T0366","name":"T0366《佛說阿彌陀經》","path":"01-大正藏/16淨土宗部類/T0366《佛說阿彌陀經》.md","loci":[{"p":17,"q":"如是","notes":[{"by":"慧淨","era":"","t":"信順之辭，信則所言之理順，順則師資之道成，經無豐約非信不傳，故名如是。"},{"by":"釋智圓","era":"","t":"訖列眾為序；二、從"},{"by":"阿彌陀經疏","era":"","t":"次釋舉能聞人也。"}]},{"p":57,"q":"眾所知識","notes":[{"by":"阿彌陀經疏","era":"","t":"《大威德陀羅尼經》云：有四：一者、但言難陀，此云喜；二、修難陀，此云善喜；三、阿難陀，此云歡喜；四、婆難陀，此云賢歡喜。"},{"by":"慧淨","era":"","t":"人天大眾所共知其內德、識外形也。"}]},{"p":104,"q":"阿難陀、羅睺羅","notes":[{"by":"窺基","era":"","t":"贊曰：第五多聞密行對。"}]},{"p":124,"q":"迦留陀夷、摩訶劫賓那","notes":[{"by":"元曉","era":"唐","t":"此云黑上，此是悉達未出家時師也。"},{"by":"窺基","era":"","t":"贊曰：第二悲心廣大眾也。"}]},{"p":169,"q":"阿逸多","notes":[{"by":"元曉","era":"唐","t":"此云無能勝。"}]},{"p":198,"q":"及釋提桓因等無量諸天大眾俱。","notes":[{"by":"蕅益智旭","era":"","t":"及者，亦上文聲聞、菩薩言之。"}]},{"p":212,"q":"爾時，佛告","notes":[{"by":"元曉","era":"唐","t":"已下，第二正說分。"}]},{"p":228,"q":"過十萬億佛土","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第五垂化也，謂以法教眾生。"}]},{"p":259,"q":"舍利弗！彼土何故名為極樂？其國眾","notes":[{"by":"蕅益智旭","era":"","t":"娑婆苦樂相雜，苦是苦苦，逼身心故；樂是壞苦，不久住故；不苦不樂是行苦，性遷流故。"},{"by":"天台智者大師","era":"","t":"解釋前明依果。"}]},{"p":306,"q":"七重羅網","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第二上羅珠網也。"}]},{"p":344,"q":"有七寶池","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第一池瑩七珍也。"}]},{"p":420,"q":"大如車輪","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第二分量也。"}]},{"p":445,"q":"微妙香潔","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第三結成極樂。"}]},{"p":483,"q":"黃金為地","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第四檀金飾地也，即形貌圓淨。"}]},{"p":665,"q":"汝勿謂此鳥實是罪報所生","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋有畜生，由此疑心故佛遮掃，莫謂實是罪報所生。"}]},{"p":756,"q":"出微妙音，譬如百千種樂同時俱作","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第二歌音所演也。"}]},{"p":792,"q":"舍利弗！其佛國土成就如是功德莊嚴","notes":[{"by":"蕅益智旭","era":"","t":"心性寂而常照故為光明，今徹證心性無量之體，故光明無量也。"}]},{"p":810,"q":"舍利弗！於汝意云何？","notes":[{"by":"元曉","era":"唐","t":"此下第二正報清淨，於中示顯四種功德：一者、主功德；二者、伴功德；三者、大眾功德；四者、上首功德。"}]},{"p":867,"q":"其人","notes":[{"by":"元曉","era":"唐","t":"已下，第三受執。"}]},{"p":956,"q":"功德莊嚴。","notes":[{"by":"釋元照","era":"","t":"故《觀經》云："}]},{"p":1038,"q":"所以者何？得與如是諸上善人俱會一","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第一簡少因也。"}]},{"p":1179,"q":"舍利弗！我見是利，故說此言。若有","notes":[{"by":"蕅益智旭","era":"","t":"佛眼所見究盡明了，以信願而執持名號，的確是多善根福德，以此善根福德因緣，的確能感佛及聖眾來迎，的確能生四種極樂世界，是為不可思議功德之利。"},{"by":"阿彌陀經疏","era":"","t":"次釋第五結勸敦勵也。"},{"by":"元曉","era":"唐","t":"已下，第四結勸。"}]},{"p":1216,"q":"如我今者","notes":[{"by":"元曉","era":"唐","t":"已下，是第四文，於中有三：先己讚他，次他讚己，其第三者結歎勸信。"}]},{"p":1305,"q":"稱讚不可思議功德一切諸佛所護念經","notes":[{"by":"釋元照","era":"","t":"總十六字，經字為通題，上十五字為別題。"},{"by":"蕅益智旭","era":"","t":"羅什法師順此方好略之機故，但譯云"}]},{"p":1948,"q":"若有人已發願、今發願、當發願，欲","notes":[{"by":"阿彌陀經疏","era":"","t":"次釋第一發心也。"}]},{"p":1972,"q":"是諸人等，皆得不退轉於阿耨多羅三","notes":[{"by":"窺基","era":"","t":"贊曰：第二彰其勝益。"}]},{"p":1993,"q":"於彼國土若已生、若今生、若當生","notes":[{"by":"阿彌陀經疏","era":"","t":"第三釋遂志也。"}]},{"p":2123,"q":"得阿耨多羅三藐三菩提","notes":[{"by":"窺基","era":"","t":"贊曰：第三流通分文有四段：初、說經事畢；二、聽法緣終；三、聞法歡忻；四、退辭佛去，四段合一唱也。"},{"by":"阿彌陀經疏","era":"","t":"次釋第三釋怪登勝果也。"}]},{"p":2196,"q":"佛說此經已，舍利弗及諸比丘，一切","notes":[{"by":"蕅益智旭","era":"","t":"法門不可思議難信難知，故無一人能發問者；佛智鑒機知機已熟，故無問自說令得四益。"}]}]},{"base":"T0251","name":"T0251《般若波羅蜜多心經》","path":"01-大正藏/03般若部類/T0251《般若波羅蜜多心經》.md","loci":[{"p":24,"q":"照見","notes":[{"by":"般若波羅蜜多心經幽贊","era":"","t":"然此空性，資糧位中聽聞、思惟，多唯信解；在加行位方純修觀，雖皆名照，猶帶相故，而未證真；住十地中起無漏觀，通達真理，方實照空；至如來位照見圓滿，知離言境，假名為空。"}]}]},{"base":"T1484","name":"T1484《梵網經》","path":"01-大正藏/11律部類/T1484《梵網經》.md","loci":[{"p":131,"q":"梵網","notes":[{"by":"太賢","era":"","t":"字下標此名者，為簡餘品釋迦說故。"}]},{"p":152,"q":"菩薩","notes":[{"by":"天台菩薩戒疏","era":"","t":"菩薩律儀遍防三業，心意為主舉一攝諸，譬如大地含攝萬物，故言"},{"by":"法藏","era":"","t":"標因異果，顯能持之人；"},{"by":"義寂","era":"","t":"十事根本犯失戒故制"}]},{"p":180,"q":"心地","notes":[{"by":"灌頂","era":"隋","t":"菩薩律儀遍防三業，心意識體一異名，三業之中意業為主，身口居次，據勝為論，故言"}]},{"p":412,"q":"菩薩心地","notes":[{"by":"灌頂","era":"隋","t":"亦是譬名，品內所明大士要用，如人身之有心，能總萬事，能生勝果，為大士所依，義言如地也。"},{"by":"天台菩薩戒疏","era":"","t":"總而言之，《梵網經盧舍那佛說菩薩心地十重四十八輕戒品第十》。"}]},{"p":476,"q":"菩提","notes":[{"by":"天台菩薩戒疏","era":"","t":"梵音，此翻為"}]},{"p":499,"q":"盧舍那","notes":[{"by":"灌頂","era":"隋","t":"無明塵垢永盡，智慧功德圓備如淨滿月，以名表德也。"},{"by":"太賢","era":"","t":"此云淨滿，無障不淨、無德不圓故。"},{"by":"天台菩薩戒疏","era":"","t":"等者，《寶梁經》翻稱為"},{"by":"法藏","era":"","t":"則遍照果圓，"}]},{"p":526,"q":"爾時","notes":[{"by":"法藏","era":"","t":"是此化身從報佛所受旨迴還至此之時，故云爾時也。"}]},{"p":580,"q":"法門","notes":[{"by":"太賢","era":"","t":"文義類別故名為"}]},{"p":655,"q":"爾時","notes":[{"by":"天台菩薩戒疏","era":"","t":"當爾之時也，謂是迹佛從本佛舍那受旨迴時，故云爾時。"}]},{"p":719,"q":"為何等相","notes":[{"by":"太賢","era":"","t":"述曰：第三、啟問，亦有三文：起定故、集眾故、啟問故。"},{"by":"天台菩薩戒疏","era":"","t":"第二、釋迦迹佛傳授菩薩，菩薩授諸眾生。"}]},{"p":735,"q":"大眾","notes":[{"by":"太賢","era":"","t":"述曰：第四、見問中有二：見故，問故。"},{"by":"灌頂","era":"隋","t":"第三，結勸。"}]},{"p":807,"q":"虛空","notes":[{"by":"太賢","era":"","t":"備上二行眾生也。"}]},{"p":841,"q":"本原","notes":[{"by":"太賢","era":"","t":"述曰：第二、問中有二：問故，答故。"}]},{"p":859,"q":"佛即","notes":[{"by":"天台菩薩戒疏","era":"","t":"第二、放光表瑞。"},{"by":"太賢","era":"","t":"照法性空故。"}]},{"p":884,"q":"大眾","notes":[{"by":"灌頂","era":"隋","t":"第三、總結，有三：一、標數，二、勸持，三、勸誦。"},{"by":"天台菩薩戒疏","era":"","t":"勸信受持，為三：初、明所誦之法，次、"},{"by":"法藏","era":"","t":"釋有總有別。"}]},{"p":919,"q":"捨凡夫","notes":[{"by":"太賢","era":"","t":"如《智論》云：數此三千大千世界如恒河沙為一世界種，數此種復至恒沙為一世界海，數此海復至十萬恒沙為一佛世界。"}]},{"p":1013,"q":"菩提樹","notes":[{"by":"法藏","era":"","t":"在摩伽陀國，於此樹下有金剛座，賢劫千佛皆於此座成等正覺，此樹下得菩提，故名菩提樹。"}]},{"p":1043,"q":"千百億","notes":[{"by":"天台菩薩戒疏","era":"","t":"第二、明人法。"},{"by":"灌頂","era":"隋","t":"第三、總結。"}]},{"p":1114,"q":"心地法品","notes":[{"by":"太賢","era":"","t":"述曰：處眾之中有三：處所故、大眾故、所說故。"}]},{"p":1130,"q":"發趣","notes":[{"by":"天台菩薩戒疏","era":"","t":"次入十行增修善根，名為"}]},{"p":1188,"q":"堅法忍","notes":[{"by":"法藏","era":"","t":"十回向是世間修終，堅固不壞，故云"},{"by":"太賢","era":"","t":"明性種性行德法門，亦名思慧；"},{"by":"天台菩薩戒疏","era":"","t":"十迴向位堅修善根，名為"}]},{"p":1253,"q":"堅修忍","notes":[{"by":"太賢","era":"","t":"明道種性行實法門，亦名修慧；"},{"by":"天台菩薩戒疏","era":"","t":"金剛後心所依轉勝，故名十地。"}]},{"p":1322,"q":"堅聖忍","notes":[{"by":"太賢","era":"","t":"明聖種性親證法門，名出世慧。"}]},{"p":1426,"q":"一切","notes":[{"by":"天台菩薩戒疏","era":"","t":"舉例勸學三。"}]},{"p":1449,"q":"無為","notes":[{"by":"法藏","era":"","t":"有二義：一、起此慈等恒在心中無暫時忘，故云常住；二、制令起此順真理之慈，故云常住。"},{"by":"太賢","era":"","t":"述曰：第二、答因中有二：略故，廣故。"}]},{"p":1615,"q":"千佛諦聽","notes":[{"by":"太賢","era":"","t":"知千佛眾未解了故。"}]},{"p":1640,"q":"一切","notes":[{"by":"法藏","era":"","t":"明受戒利益，上順聖意諸佛歡喜，下協群靈得鬼守護，令其身無災厄職位為長存。"}]},{"p":1694,"q":"無合","notes":[{"by":"太賢","era":"","t":"以蘊、界、處一合空相，無我、我所相故。"}]},{"p":1761,"q":"入空三昧","notes":[{"by":"太賢","era":"","t":"述曰：第二、答中有四，如次廣說四十法門故。"}]},{"p":1793,"q":"乃至","notes":[{"by":"法藏","era":"","t":"顯所盜物，於中二：先約主，謂通五趣唯除地獄，始從人天至非人，故云"},{"by":"天台菩薩戒疏","era":"","t":"戒為伏斷之因，故云"}]},{"p":1829,"q":"一道清淨","notes":[{"by":"太賢","era":"","t":"遍一切處，如俗苦相而忍解故。"}]},{"p":1856,"q":"一切處","notes":[{"by":"法藏","era":"","t":"通舉一切，俱是講說經律之處。"}]},{"p":1879,"q":"一一","notes":[{"by":"法藏","era":"","t":"有二種：一、於前六位一一人所各不如法供等，二、於彼人所設一一供事各不如法等。"}]},{"p":1895,"q":"皆如如","notes":[{"by":"太賢","era":"","t":"等者，空所忍境能打人等，四威儀中染淨性空，故言"}]},{"p":1942,"q":"不可得","notes":[{"by":"太賢","era":"","t":"述曰：第三、忍心。"}]},{"p":1972,"q":"無生山","notes":[{"by":"太賢","era":"","t":"見有無者，有相名有，無相名無。"}]},{"p":1999,"q":"三寶","notes":[{"by":"法藏","era":"","t":"非理塵黷，故名為"},{"by":"太賢","era":"","t":"大乘功德門也。"}]},{"p":2021,"q":"起空入世諦法","notes":[{"by":"太賢","era":"","t":"所有進道皆空為首，故言續前。"}]},{"p":2098,"q":"體性相應","notes":[{"by":"太賢","era":"","t":"於一切行，以定力故諸障滅也。"}]},{"p":2120,"q":"見性","notes":[{"by":"太賢","era":"","t":"不生思惟皆心不寂，而滅空空及以八倒無攀緣也。"}]},{"p":2144,"q":"假靜慧觀","notes":[{"by":"太賢","era":"","t":"學觀有情法假定慧，由此定慧一切假會苦諦伏滅，能受三界罪性集滅。"}]},{"p":2171,"q":"生一切善","notes":[{"by":"太賢","era":"","t":"述曰：第五、定心。"}]},{"p":2315,"q":"為慧用故","notes":[{"by":"太賢","era":"","t":"述曰：第六、慧心中"}]},{"p":2333,"q":"一切求","notes":[{"by":"太賢","era":"","t":"明行相中以求遠果修行因故，願心連也，必由願心連相續故。"}]},{"p":2441,"q":"生見見","notes":[{"by":"太賢","era":"","t":"舉章門也，以護所依及自行故。"}]},{"p":2493,"q":"滅我縛、見縛無生","notes":[{"by":"太賢","era":"","t":"以何行相如此護耶？"}]},{"p":2539,"q":"明光","notes":[{"by":"太賢","era":"","t":"幻化所起俗相性空，空智中似無故言"}]},{"p":2568,"q":"不可護","notes":[{"by":"太賢","era":"","t":"如所觀理，能觀亦爾。"}]},{"p":2602,"q":"照寂","notes":[{"by":"太賢","era":"","t":"等者，多聞果德及因行德，普以無相隨喜之智，連生正念而專照也。"}]},{"p":2666,"q":"樂心緣一切法","notes":[{"by":"太賢","era":"","t":"離嫉妬等喜悅緣故。"}]},{"p":2690,"q":"我輪","notes":[{"by":"太賢","era":"","t":"執我為首輪迴煩惱，利見疑身及以鈍品瞋等煩惱皆滅無故，勝如頂也。"}]},{"p":2726,"q":"如人頂","notes":[{"by":"太賢","era":"","t":"簡二類見，故言"}]},{"p":2855,"q":"入道","notes":[{"by":"太賢","era":"","t":"總句，餘三別句。"}]},{"p":2884,"q":"生生入佛家","notes":[{"by":"太賢","era":"","t":"《十住毘婆沙》云以真如為佛家，相應解成故言入也。"}]},{"p":2986,"q":"化被","notes":[{"by":"太賢","era":"","t":"已下，教他生信，大悲門故。"}]},{"p":3012,"q":"非實","notes":[{"by":"太賢","era":"","t":"述曰：第二、十長養中，牒問可知。"}]},{"p":3065,"q":"不殺生緣","notes":[{"by":"太賢","era":"","t":"故；二、法緣悲，如《經》"}]},{"p":3115,"q":"種性行中生道智心","notes":[{"by":"太賢","era":"","t":"出斯位行也。"}]},{"p":3165,"q":"起大悲","notes":[{"by":"太賢","era":"","t":"此有二種：一者性空，不著我及所故。"}]},{"p":3207,"q":"無集","notes":[{"by":"太賢","era":"","t":"爾時一切萬有入空，即觀行成。"}]},{"p":3253,"q":"法中常起歡喜","notes":[{"by":"太賢","era":"","t":"自入法位，復於他入正中隨喜也。"}]},{"p":3281,"q":"苦故喜","notes":[{"by":"太賢","era":"","t":"述曰：第三、喜心中，"}]},{"p":3306,"q":"如虛空","notes":[{"by":"太賢","era":"","t":"喻於三空無障礙行。"}]},{"p":3374,"q":"常修其捨","notes":[{"by":"太賢","era":"","t":"述曰：第四、捨心中，"}]},{"p":3559,"q":"發起善根","notes":[{"by":"太賢","era":"","t":"述曰：第六、愛語心中，"}]},{"p":3579,"q":"實智體性","notes":[{"by":"太賢","era":"","t":"所緣真如也。"}]},{"p":3628,"q":"一切意","notes":[{"by":"太賢","era":"","t":"作用多故，皆令他人次第行成也。"}]},{"p":3648,"q":"法種","notes":[{"by":"太賢","era":"","t":"證地上際行故。"}]},{"p":3678,"q":"但益人為利","notes":[{"by":"太賢","era":"","t":"述曰：第七、利行心也。"}]},{"p":3723,"q":"常生常住常滅","notes":[{"by":"太賢","era":"","t":"於此流轉，隨入事同。"}]},{"p":3777,"q":"同法三昧","notes":[{"by":"太賢","era":"","t":"述曰：第八、同事心中，"}]},{"p":3805,"q":"於我所法","notes":[{"by":"太賢","era":"","t":"即所遍計十八界也。"}]},{"p":3831,"q":"十禪支","notes":[{"by":"太賢","era":"","t":"一、尋，二、伺，三、喜，四、樂，五、心一境性，六、內等淨，七、捨，八、念，九、正知，十、不苦不樂受。"}]},{"p":3856,"q":"無合","notes":[{"by":"太賢","era":"","t":"述曰：第九、定心中，"}]},{"p":3939,"q":"見虛無受","notes":[{"by":"太賢","era":"","t":"慧行善巧故，能生此位十長養心也。"}]},{"p":3975,"q":"百法明門","notes":[{"by":"太賢","era":"","t":"述曰：第十、慧心中，"}]},{"p":4031,"q":"諸見名著","notes":[{"by":"太賢","era":"","t":"招苦造集故，於此必不受，方入空無為。"}]},{"p":4079,"q":"第一義諦","notes":[{"by":"太賢","era":"","t":"念天也，佛常涅槃果第一義天故。"}]},{"p":4128,"q":"三界假我我","notes":[{"by":"太賢","era":"","t":"實我假我無可得一聚集相故。"}]},{"p":4164,"q":"常施","notes":[{"by":"太賢","era":"","t":"等者，觀所念境空無可縛著，況有解脫耶？"}]},{"p":4279,"q":"亦如是","notes":[{"by":"太賢","era":"","t":"述曰：第二、念心中，"}]},{"p":4490,"q":"空空","notes":[{"by":"太賢","era":"","t":"如處緣空，能照亦空，是名"}]},{"p":4527,"q":"轉一切眾生","notes":[{"by":"太賢","era":"","t":"轉凡向聖也。"}]},{"p":4554,"q":"而不受","notes":[{"by":"太賢","era":"","t":"述曰：第五、直心中，"}]},{"p":4586,"q":"不起習因相似我人","notes":[{"by":"太賢","era":"","t":"漸伏俱生故。"}]},{"p":4637,"q":"如如相續","notes":[{"by":"太賢","era":"","t":"如是如是乘勝心入於不二。"}]},{"p":4661,"q":"一道一照","notes":[{"by":"太賢","era":"","t":"雙依二空，證一真法界故。"}]},{"p":4768,"q":"得度苦海","notes":[{"by":"太賢","era":"","t":"述曰：第七、大乘心中，"}]},{"p":4872,"q":"生生","notes":[{"by":"太賢","era":"","t":"相雖遷流然性不起，熏修力故"}]},{"p":4951,"q":"非有陰界入","notes":[{"by":"太賢","era":"","t":"述曰：第九、慧心中，"}]},{"p":4995,"q":"明菩提心","notes":[{"by":"太賢","era":"","t":"一苦、二空、三無常、四無我、五生、六老、七病、八死，非此八種之所惑亂。"}]},{"p":5111,"q":"心心行空","notes":[{"by":"太賢","era":"","t":"初空中忍順能取空，後空上忍印能取空，更無餘相言無相照。"}]},{"p":5156,"q":"廣說","notes":[{"by":"太賢","era":"","t":"述曰：第十、"}]},{"p":5192,"q":"體性地","notes":[{"by":"太賢","era":"","t":"述曰：第二地中有三：章門故，地行故，指廣故。"}]},{"p":5268,"q":"坐佛性地","notes":[{"by":"太賢","era":"","t":"已入大地故。"}]},{"p":5301,"q":"從一劫入無量劫","notes":[{"by":"太賢","era":"","t":"於一念中，攝三際故，或舒一劫，為多劫故。"}]},{"p":5449,"q":"分分了起","notes":[{"by":"太賢","era":"","t":"趣入領受有色報故，即不生無色也。"}]},{"p":5506,"q":"略出","notes":[{"by":"太賢","era":"","t":"結初地大海，今略出也。"}]},{"p":5536,"q":"善慧","notes":[{"by":"太賢","era":"","t":"離犯戒惡故。"}]},{"p":5559,"q":"一切功德本","notes":[{"by":"太賢","era":"","t":"初觀入於最勝真如大空之慧，從初入心遂起後得巧方便道，智中見諸眾生無非苦諦。"}]},{"p":5623,"q":"色陰","notes":[{"by":"太賢","era":"","t":"三者壞苦，境切生苦如𣃆石火，謂由緣逼𣃆行苦石，出壞等苦燒身心也。"}]},{"p":5658,"q":"苦苦緣","notes":[{"by":"太賢","era":"","t":"重故苦苦者，釋逼迫重，名"}]},{"p":5689,"q":"壞苦緣","notes":[{"by":"太賢","era":"","t":"是以三位識漸生三苦，故為"}]},{"p":5760,"q":"苦識","notes":[{"by":"太賢","era":"","t":"苦體也，於此且說四諦門故。"}]},{"p":5786,"q":"不具","notes":[{"by":"太賢","era":"","t":"具所依緣生了別故，名為"}]},{"p":5802,"q":"觸識","notes":[{"by":"太賢","era":"","t":"此心觸對觸惱之境，領受煩毒為苦苦也。"}]},{"p":5832,"q":"心緣識","notes":[{"by":"太賢","era":"","t":"名之差別，初在根發多分率爾，覺所緣境名行苦覺，思受及觸纔覺境觸，未受毒時捨受現前，名為"}]},{"p":5897,"q":"緣集","notes":[{"by":"太賢","era":"","t":"彼後敗壞名為"}]},{"p":5968,"q":"智道道諦","notes":[{"by":"太賢","era":"","t":"次明滅諦，盡有苦果，盡有集因，離障清淨一味所照體性，以聖妙智擇力寂滅一諦也。"}]},{"p":5995,"q":"慧品具足","notes":[{"by":"太賢","era":"","t":"述曰：第二、化導諸有心者，見是三苦起八苦等之因緣故。"}]},{"p":6127,"q":"捨品具足","notes":[{"by":"太賢","era":"","t":"述曰：逆次第二觀捨善根。"}]},{"p":6187,"q":"無癡無貪無瞋","notes":[{"by":"太賢","era":"","t":"如次結前慧捨慈品善根成也。"}]},{"p":6212,"q":"現化無量法身","notes":[{"by":"太賢","era":"","t":"述曰：第三指廣，餘地準此。"}]},{"p":6245,"q":"三昧解了智","notes":[{"by":"太賢","era":"","t":"以依勝定發三慧故。"}]},{"p":6268,"q":"重誦","notes":[{"by":"太賢","era":"","t":"契經此唯長行，對諷頌"}]},{"p":6371,"q":"連連覺著受無窮","notes":[{"by":"太賢","era":"","t":"愛支也，恒著愛故。"}]},{"p":6401,"q":"是十品","notes":[{"by":"太賢","era":"","t":"述曰：第二、知所詮也。"}]},{"p":6451,"q":"現劫化","notes":[{"by":"太賢","era":"","t":"如《維摩經》一日舒為七大劫等，展轉化故，言"}]},{"p":6518,"q":"國土不同身心別化","notes":[{"by":"太賢","era":"","t":"隨其國欲，三業別化。"}]},{"p":6549,"q":"三昧品說","notes":[{"by":"太賢","era":"","t":"述曰：第三、存略指廣，如彼二品已廣說故。"}]},{"p":6573,"q":"不斷不常","notes":[{"by":"太賢","era":"","t":"如無量劫即是一念，況生住滅一世一時一有。"}]},{"p":6592,"q":"種異異","notes":[{"by":"太賢","era":"","t":"如因緣別，果亦不同，故言"}]},{"p":6627,"q":"名為世諦","notes":[{"by":"太賢","era":"","t":"然勝義智道觀彼無一二，如何等法觀彼真耶？"}]},{"p":6652,"q":"初覺定因","notes":[{"by":"太賢","era":"","t":"初悟空理，定即因也，覺之因故。"}]},{"p":6713,"q":"若起念定","notes":[{"by":"太賢","era":"","t":"定之親因，并舉念也。"}]},{"p":6734,"q":"法樂忍","notes":[{"by":"太賢","era":"","t":"述曰：第四地行相中有二：自分行故，勝進行故。"}]},{"p":6774,"q":"百千起發","notes":[{"by":"太賢","era":"","t":"精進法門也。"}]},{"p":6791,"q":"貪定","notes":[{"by":"太賢","era":"","t":"釋味樂定也。"}]},{"p":6836,"q":"出相","notes":[{"by":"太賢","era":"","t":"佛光覺發出相之故，菩薩"}]},{"p":6957,"q":"已明斯義","notes":[{"by":"太賢","era":"","t":"述曰：第二、勝進行。"}]},{"p":7004,"q":"處力品","notes":[{"by":"太賢","era":"","t":"處非處智力也。"}]},{"p":7026,"q":"果欲","notes":[{"by":"太賢","era":"","t":"四、種種界智力，知種姓故。"}]},{"p":7088,"q":"五眼知一切法","notes":[{"by":"太賢","era":"","t":"類舉總數慧法眼等知一切法，以天眼見諸受生故。"}]},{"p":7152,"q":"因果分別","notes":[{"by":"太賢","era":"","t":"述曰：第五地。"}]},{"p":7271,"q":"下足事","notes":[{"by":"太賢","era":"","t":"述曰：第二、通力，三業變化自在用故。"}]},{"p":7303,"q":"現在前","notes":[{"by":"太賢","era":"","t":"述曰：第二、勝進分行。"}]},{"p":7769,"q":"品中說","notes":[{"by":"太賢","era":"","t":"述曰：第六地。"}]},{"p":7921,"q":"一切法","notes":[{"by":"太賢","era":"","t":"第一義諦也，四重之中且舉初故。"}]},{"p":8088,"q":"國土中","notes":[{"by":"太賢","era":"","t":"述曰：第二化相中，先觀平等慈悲門，次量自力能，後現變化。"}]},{"p":8131,"q":"聽法故","notes":[{"by":"太賢","era":"","t":"述曰：第七地中，舉章云"}]},{"p":8185,"q":"一切佛所行法","notes":[{"by":"太賢","era":"","t":"等者，證果法門及勝進法門中已入解也。"}]},{"p":8293,"q":"華光","notes":[{"by":"太賢","era":"","t":"述曰：第八地中有五種行，此初定行。"}]},{"p":8385,"q":"不可說","notes":[{"by":"太賢","era":"","t":"述曰：第二、慧行。"}]},{"p":8427,"q":"轉法度與一切眾生","notes":[{"by":"太賢","era":"","t":"以己之解授與眾生也。"}]},{"p":8526,"q":"平等門","notes":[{"by":"太賢","era":"","t":"陀羅尼門等所行真如門中而大自在，一念一時而修行也。"}]},{"p":8588,"q":"佛說非佛","notes":[{"by":"太賢","era":"","t":"述曰：第四、說行。"}]},{"p":8648,"q":"不動","notes":[{"by":"太賢","era":"","t":"永不復受分段生死，故言"}]},{"p":8698,"q":"品中已明","notes":[{"by":"太賢","era":"","t":"述曰：第五、照行。"}]},{"p":8733,"q":"出入無時","notes":[{"by":"太賢","era":"","t":"述曰：第九地中，言"}]},{"p":8826,"q":"一切法外","notes":[{"by":"太賢","era":"","t":"等者，非趣生法而行趣生，轉魔界等入佛界等，性平等故說無礙也。"}]},{"p":8845,"q":"無量意","notes":[{"by":"太賢","era":"","t":"述曰：第二、外化。"}]},{"p":9000,"q":"從生死際起","notes":[{"by":"太賢","era":"","t":"從初發心至金剛心，所有願行於一心現，入眾生界而教化也。"}]},{"p":9059,"q":"大慧空","notes":[{"by":"太賢","era":"","t":"復空復空，所取能取既平等空，故言"}]},{"p":9128,"q":"法身","notes":[{"by":"太賢","era":"","t":"如隔輕縠見報身故。"}]},{"p":9151,"q":"聖解脫智","notes":[{"by":"太賢","era":"","t":"四者明行足，因行增明已到滿故。"}]},{"p":9203,"q":"去時善善","notes":[{"by":"太賢","era":"","t":"來現世時亦有所益，言"}]},{"p":9374,"q":"名佛界地","notes":[{"by":"太賢","era":"","t":"述曰：第十地中，舉章云"}]},{"p":9446,"q":"虛空藏","notes":[{"by":"太賢","era":"","t":"周遍容受化導門故。"}]},{"p":9514,"q":"與佛道同","notes":[{"by":"太賢","era":"","t":"述曰：第二、行勝利。"}]},{"p":9887,"q":"恒河","notes":[{"by":"太賢","era":"","t":"香山頂無熱惱池流出四河，此東河水寬四十餘里，梵語應言"}]},{"p":9995,"q":"光光","notes":[{"by":"太賢","era":"","t":"告千葉上淨穢土佛："}]},{"p":10046,"q":"一心而行","notes":[{"by":"太賢","era":"","t":"述曰：第五、付屬也。"}]},{"p":10134,"q":"世界而沒","notes":[{"by":"太賢","era":"","t":"述曰：自下大段第二化。"}]},{"p":10159,"q":"菩提樹","notes":[{"by":"太賢","era":"","t":"畢鉢羅樹在伽耶城西南二十四里。"}]},{"p":10179,"q":"金剛","notes":[{"by":"太賢","era":"","t":"《華嚴》第二云蓮華藏世界海，次東方有世界海名淨勝光莊嚴，中有佛剎名眾寶金剛藏。"}]},{"p":10247,"q":"十禪定","notes":[{"by":"太賢","era":"","t":"此文次第當四善根，一向修慧，故偏說定。"}]},{"p":10270,"q":"十金剛","notes":[{"by":"太賢","era":"","t":"《瑜伽．忍品》云：清淨忍有十。"}]},{"p":10345,"q":"品中說","notes":[{"by":"太賢","era":"","t":"述曰：第二、別化也。"}]},{"p":10406,"q":"七歲出家","notes":[{"by":"太賢","era":"","t":"等者，此經應錯，既說娶嫁方出家故，西域傳云諸部見聞不同也。"}]},{"p":10426,"q":"寂滅道場","notes":[{"by":"太賢","era":"","t":"已下顯時，謂成佛已從第四禪事盧舍那受心地法，還來道場說十世界海，如次前說歷十住處，乃至第十摩醯首羅天王宮中說心地時，諸大梵王供網羅幢因此說法，乃至告言："}]},{"p":10509,"q":"八千返","notes":[{"by":"太賢","era":"","t":"述曰：第二、別釋。"}]},{"p":10600,"q":"一戒光明","notes":[{"by":"太賢","era":"","t":"堅牢能持一切功德，令不漏失破諸惡故。"}]},{"p":10655,"q":"當當常有因故，有當當常住法身。","notes":[{"by":"太賢","era":"","t":"三菩提因重言當當，其當果因法爾有故，有當當報化及常住法身。"}]},{"p":10723,"q":"自性清淨","notes":[{"by":"太賢","era":"","t":"述曰：第二、法王勸策。"}]},{"p":10759,"q":"一國","notes":[{"by":"太賢","era":"","t":"在摩伽陀國，於此樹下有金剛臺，此下證覺名菩提樹。"}]},{"p":10783,"q":"盧舍那本身","notes":[{"by":"太賢","era":"","t":"述曰：第四、舉淨穢土機根頓熟，一時重化攝末歸本。"}]},{"p":10813,"q":"甘露","notes":[{"by":"太賢","era":"","t":"故喻樂中最極涅槃。"}]},{"p":10839,"q":"本師","notes":[{"by":"太賢","era":"","t":"即本身，或可戒法名為本師，佛所師故。"}]},{"p":10867,"q":"由是成正覺","notes":[{"by":"太賢","era":"","t":"述曰：此即第二讚戒威力門也。"}]},{"p":10903,"q":"轉授諸眾生","notes":[{"by":"太賢","era":"","t":"述曰：自下末主顯揚門。"}]},{"p":10945,"q":"常作如是信，戒品已具足","notes":[{"by":"義寂","era":"","t":"心常作如上二信，即能堪任為受器，故云戒品已具足也。"},{"by":"太賢","era":"","t":"述曰：第二門也。"}]},{"p":10975,"q":"即入諸佛位","notes":[{"by":"太賢","era":"","t":"佛位有二：一、發心滿位，二、行果滿位。"}]},{"p":11025,"q":"初結","notes":[{"by":"義寂","era":"","t":"已下略釋所結戒之名義，略以二義釋其戒名。"}]},{"p":11066,"q":"即口放","notes":[{"by":"太賢","era":"","t":"等者，放光招眾，放無量光而招有緣，表無礙門照導長夜。"},{"by":"義寂","era":"","t":"明放光，將說戒法，現表瑞也。"}]},{"p":11098,"q":"國王","notes":[{"by":"太賢","era":"","t":"述曰：自下第三結戒序中有二：初經家序，後世尊序。"},{"by":"義寂","era":"","t":"等者，俗等貴族也。"}]},{"p":11148,"q":"乃至","notes":[{"by":"太賢","era":"","t":"然有主物略有五種：一、三寶物，二、屬人物，三、畜生物，四、鬼神物，五、劫賊物。"},{"by":"義寂","era":"","t":"十解，亦名十住，亦名習種姓。"}]},{"p":11178,"q":"有緣非無因","notes":[{"by":"義寂","era":"","t":"外有時眾感法勝緣，內有如來大悲本因，方得現瑞表所說法故。"},{"by":"太賢","era":"","t":"述曰：自下佛序，如次序成師、法、弟子三輪相也。"}]},{"p":11239,"q":"應受","notes":[{"by":"義寂","era":"","t":"從師初受也。"}]},{"p":11255,"q":"若受","notes":[{"by":"義寂","era":"","t":"已下廣釋受義，餘三存略，以初兼後故。"}]},{"p":11291,"q":"黃門","notes":[{"by":"義寂","era":"","t":"五種半擇迦。"}]},{"p":11309,"q":"畜生乃至變化人","notes":[{"by":"義寂","era":"","t":"畜生中能變化者。"}]},{"p":11328,"q":"皆名第一清淨","notes":[{"by":"太賢","era":"","t":"述曰：此即第三、所被弟子。"}]},{"p":11374,"q":"我亦如是誦","notes":[{"by":"太賢","era":"","t":"述曰：第二、正說分，此有二：初重、後輕。"}]},{"p":11409,"q":"木叉相貌","notes":[{"by":"義寂","era":"","t":"不誦非菩薩，即戒之相也，三世皆學，即戒之貌也。"},{"by":"太賢","era":"","t":"述曰：第二、示相勸持門也。"}]},{"p":11447,"q":"見作隨喜","notes":[{"by":"太賢","era":"","t":"故聲聞戒中唯取殺人，今不簡趣，故言"},{"by":"義寂","era":"","t":"毘陀羅等呪，由誦此呪前人被死。"}]},{"p":11504,"q":"而自恣心","notes":[{"by":"太賢","era":"","t":"述曰：初、制意者，說佛法過，必壞他信，失壞菩薩興法利生，況復能招廣大苦果？"},{"by":"義寂","era":"","t":"於內無迷謬，於外無逼切，以了了心，行殺生也。"}]},{"p":11534,"q":"方便盜","notes":[{"by":"義寂","era":"","t":"如律云受供比丘語施主云受汝供養是阿羅漢等是也。"},{"by":"太賢","era":"","t":"故，讚歎隨喜略而不論，理應有故。"}]},{"p":11550,"q":"呪盜","notes":[{"by":"義寂","era":"","t":"誦呪令物自來也。"}]},{"p":11582,"q":"佛性","notes":[{"by":"太賢","era":"","t":"菩薩由此異二乘故。"}]},{"p":11597,"q":"生樂","notes":[{"by":"太賢","era":"","t":"安樂故，而盜人物生彼煩惱故違利益，奪命緣故亦違安樂。"}]},{"p":11622,"q":"自婬、教人婬","notes":[{"by":"太賢","era":"","t":"據實在家唯制邪行，非但障道招惡趣故。"},{"by":"義寂","era":"","t":"聲聞法中，自婬成重，教人非重。"}]},{"p":11658,"q":"諸天","notes":[{"by":"太賢","era":"","t":"女三男二正是境也，以行餘處不犯重故。"},{"by":"義寂","era":"","t":"聲聞法中，女三處，男二處，行即犯重。"}]},{"p":11686,"q":"淨法與人","notes":[{"by":"太賢","era":"","t":"菩薩應以離欲法門施與眾生度生死苦。"}]},{"p":11736,"q":"妄語","notes":[{"by":"義寂","era":"","t":"事設是實，若違內心，皆名妄語。"},{"by":"太賢","era":"","t":"言方便者，假託餘事，令他異解。"}]},{"p":11777,"q":"身心妄語","notes":[{"by":"義寂","era":"","t":"身妄語，謂由身業表示令人妄解，如由起坐表知是聖等。"},{"by":"太賢","era":"","t":"而反自起妄語之時，眾生隨說故生"}]},{"p":11811,"q":"邪語","notes":[{"by":"太賢","era":"","t":"若為救脫多有情故，覆想正知而說妄語，《瑜伽論》云：無所違犯生多功德，不爾妄語犯他勝處。"}]},{"p":11866,"q":"是酒起罪因緣","notes":[{"by":"太賢","era":"","t":"唯除破僧，餘惡並起。"}]},{"p":11901,"q":"是菩薩波羅夷罪","notes":[{"by":"太賢","era":"","t":"述曰：初制意者，佛法僧寶，出邪之大津，入正之要門。"}]},{"p":11928,"q":"罪過","notes":[{"by":"太賢","era":"","t":"今此戒中，初門兼攝境界事門。"},{"by":"義寂","era":"","t":"向他顯揚故名"}]},{"p":11975,"q":"常生悲心","notes":[{"by":"太賢","era":"","t":"勸他令生無瞋善根，自亦應常生大悲心，謂對惡人便作三念：一、念彼人心性本淨，醉無明酒、著煩惱鬼，不獲己有，此所作耳；二、念本願我為眾生誓證菩提，生死大苦尚不生畏，況此小苦應不忍受；三、念彼恩必由惱害乃成忍行，彼即成滿我菩提因，何乃背恩反生瞋害？"},{"by":"義寂","era":"","t":"佛法中起惡見者。"}]},{"p":12020,"q":"自讚毀","notes":[{"by":"義寂","era":"","t":"此有二：一、教前人讚彼自得，毀他人失；二、教前人讚我自得，毀他人失。"}]},{"p":12109,"q":"教人慳","notes":[{"by":"義寂","era":"","t":"亦應有二：一、教前人慳財法，二、遣前人惜自財法。"}]},{"p":12126,"q":"菩薩見一切貧窮人來乞","notes":[{"by":"太賢","era":"","t":"《菩薩地》云：見有勝利而來乞者，方應施與，欲以財攝易化導故。"}]},{"p":12157,"q":"乃至","notes":[{"by":"太賢","era":"","t":"一句威力能出苦輪，是故法施勝於財施。"},{"by":"義寂","era":"","t":"想者，謂於所瞋眾生稱境而想。"}]},{"p":12185,"q":"而反更罵辱者","notes":[{"by":"義寂","era":"","t":"剩顯違過之甚也。"}]},{"p":12256,"q":"乃至於非眾生","notes":[{"by":"義寂","era":"","t":"若非情名非眾生，是深防語。"}]},{"p":12283,"q":"前人求悔善言懺謝","notes":[{"by":"太賢","era":"","t":"如其次第，語、身、意業雖具三業，今取意罪以所等起，顯瞋重故。"},{"by":"義寂","era":"","t":"被侵損人反求悔謝。"}]},{"p":12338,"q":"外道","notes":[{"by":"義寂","era":"","t":"佛法外行異道者。"}]},{"p":12358,"q":"況口自謗","notes":[{"by":"義寂","era":"","t":"義說有四：一、上邪見，二、中，三、下，四雜邪見。"},{"by":"太賢","era":"","t":"《瑜伽論》云："}]},{"p":12391,"q":"善學","notes":[{"by":"太賢","era":"","t":"簡外道諸不善學及以二乘不究竟學。"}]},{"p":12423,"q":"何況具足犯十戒","notes":[{"by":"義寂","era":"","t":"微過尚不應犯，重罪理在絕言，具足五緣成十根本，故云具足犯十戒也。"}]},{"p":12445,"q":"亦失國王位","notes":[{"by":"太賢","era":"","t":"等，顯因亡故，失果利也。"}]},{"p":12481,"q":"佛性","notes":[{"by":"太賢","era":"","t":"通餘二身，如次自性無間相續常故。"}]},{"p":12503,"q":"不聞父母三寶名","notes":[{"by":"太賢","era":"","t":"顯世間及出世間無能救也。"}]},{"p":12520,"q":"汝等","notes":[{"by":"義寂","era":"","t":"勸持，指廣如文也。"}]},{"p":12553,"q":"當廣明","notes":[{"by":"太賢","era":"","t":"述曰：此即第三結成門也。"}]},{"p":12576,"q":"四十八輕今當說","notes":[{"by":"太賢","era":"","t":"述曰：此下別誦輕戒。"}]},{"p":12638,"q":"既得","notes":[{"by":"義寂","era":"","t":"於彼德行崇而不敢慢也。"}]},{"p":12656,"q":"和上","notes":[{"by":"太賢","era":"","t":"即軌範師，授戒、羯磨、威儀、教受、受業等師也。"}]},{"p":12711,"q":"以自賣身","notes":[{"by":"太賢","era":"","t":"除無五德，或反生過，彼雖不舉，無違犯故。"},{"by":"義寂","era":"","t":"引況重誡，尚應捨身況復不禮敬耶？"}]},{"p":12743,"q":"故飲酒","notes":[{"by":"義寂","era":"","t":"似開誤飲，而律中酒非酒想亦犯。"}]},{"p":12767,"q":"五百世無手","notes":[{"by":"太賢","era":"","t":"以極增上惡心過故，非善心等。"}]},{"p":12794,"q":"況自飲酒","notes":[{"by":"太賢","era":"","t":"先以過器況自飲已，此即第二、以教他飲況自飲也。"}]},{"p":12823,"q":"一切肉不得食","notes":[{"by":"義寂","era":"","t":"如鳥入身子影中尚有戰懼，有習氣者猶如是，況全不斷三毒者也。"},{"by":"太賢","era":"","t":"鷹逐之鴿，於鶖子影未解其惶，況乎在食之位。"}]},{"p":12862,"q":"食肉得無量罪","notes":[{"by":"太賢","era":"","t":"如《一切智光明仙人不食肉因緣經》中，廣顯食之失。"},{"by":"義寂","era":"","t":"由食至殺害故得無量罪。"}]},{"p":12922,"q":"犯輕垢罪","notes":[{"by":"太賢","era":"","t":"《瑜伽論》云：若嫌恚心，是染違犯。"}]},{"p":12938,"q":"八戒、五戒","notes":[{"by":"義寂","era":"","t":"或云是八重，又云三塗等八難。"}]},{"p":13001,"q":"犯輕垢罪","notes":[{"by":"太賢","era":"","t":"若護正法，即無違犯。"}]},{"p":13056,"q":"日日三時供養","notes":[{"by":"義寂","era":"","t":"是就能堪辨者說，或令重法故作是說，如雪山士為一偈故自殞身等，況復外財。"},{"by":"太賢","era":"","t":"晨、旦、齋時、非時藥等。"}]},{"p":13091,"q":"常請法師三時說法","notes":[{"by":"太賢","era":"","t":"若彼法師慧行勝己，日初、中、後應請說法。"}]},{"p":13117,"q":"為法滅身請法","notes":[{"by":"太賢","era":"","t":"如求半偈，魂沈雪山，其事非一。"},{"by":"義寂","era":"","t":"故者，釋不生瞋惱所由也。"}]},{"p":13146,"q":"毘尼","notes":[{"by":"太賢","era":"","t":"此云調伏，能止三業惡熾然故。"}]},{"p":13173,"q":"聽受諮問","notes":[{"by":"太賢","era":"","t":"《瑜伽》三十云：始修業者為證義利，先應四處安住正念，然後請問。"}]},{"p":13248,"q":"邪見","notes":[{"by":"太賢","era":"","t":"不瞻病苦戒第九\n經："}]},{"p":13273,"q":"供養如佛無異","notes":[{"by":"太賢","era":"","t":"有人言：一、造曠野美井，二、水路橋梁，三、平治嶮路，四、孝事父母，五、供養沙門，六、供養病人，七、救濟厄難，八、設無遮會。"},{"by":"義寂","era":"","t":"崇敬義後，救悲心初，故田雖有八，看病為上。"}]},{"p":13314,"q":"皆養令差","notes":[{"by":"義寂","era":"","t":"上雖總舉一切皆救，從親至疎不無先後，故偏舉親眷也。"},{"by":"太賢","era":"","t":"離三根故亦言"}]},{"p":13391,"q":"而菩薩","notes":[{"by":"太賢","era":"","t":"以彼還受自宿業果，因果法爾，不應瞋故。"},{"by":"義寂","era":"","t":"違之成犯，違機倒說故云"}]},{"p":13420,"q":"犯輕垢罪","notes":[{"by":"太賢","era":"","t":"《瑜伽》云：他來求法，嫌心、恚心、嫉妬不施，是染違犯。"},{"by":"義寂","era":"","t":"已下總結勸持。"}]},{"p":13439,"q":"六品中當廣明","notes":[{"by":"太賢","era":"","t":"自下十戒分為二門：初四護自善門，後六護攝他門。"}]},{"p":13456,"q":"為利養惡心故","notes":[{"by":"義寂","era":"","t":"作使通兩國命也。"}]},{"p":13485,"q":"不得入軍中往來","notes":[{"by":"義寂","era":"","t":"戰場嚚雜，非道人所踐，必無重緣，道俗俱禁。"}]},{"p":13514,"q":"故販賣良人","notes":[{"by":"太賢","era":"","t":"《周禮》云：牛、馬、犬、羊、豕、雞為六。"},{"by":"義寂","era":"","t":"知非屬己人，而強詐販賣。"}]},{"p":13539,"q":"況教人作","notes":[{"by":"太賢","era":"","t":"以利他為最，故舉自況他。"}]},{"p":13564,"q":"無事","notes":[{"by":"太賢","era":"","t":"此無根謗不能陷沒，故於利他制為輕罪。"}]},{"p":13582,"q":"犯七逆十重","notes":[{"by":"太賢","era":"","t":"父、母、伯、叔、兄、弟為六。"},{"by":"義寂","era":"","t":"偏舉謗事中重者也。"}]},{"p":13612,"q":"墮不如意處","notes":[{"by":"義寂","era":"","t":"不圖損他命物，輒放令至莚蔓，故云"}]},{"p":13651,"q":"若燒他人家屋宅","notes":[{"by":"義寂","era":"","t":"偏為損物，故一切時制。"}]},{"p":13707,"q":"一切善知識","notes":[{"by":"義寂","era":"","t":"便發心已，教彼令解修行次第先後法用也。"}]},{"p":13773,"q":"橫教","notes":[{"by":"太賢","era":"","t":"如《大集》云：勸學小乘，是魔業也。"}]},{"p":13818,"q":"見後新學菩薩","notes":[{"by":"義寂","era":"","t":"正辨為他無倒說法，於中有二：初說苦事以試其心，後說正法以開其解。"}]},{"p":13872,"q":"乃至","notes":[{"by":"天台菩薩戒疏","era":"","t":"舉輕況重，即小妄語，如云"}]},{"p":13912,"q":"而菩薩","notes":[{"by":"義寂","era":"","t":"隨聲取義成五過等，如《涅槃》說也，若說眾生定有佛性、定無佛性，皆謗佛法僧也。"},{"by":"天台菩薩戒疏","era":"","t":"制令行善中，言外道者，遊心圓理之外，乃至外外三宗並名外道。"}]},{"p":13947,"q":"若佛子","notes":[{"by":"天台菩薩戒疏","era":"","t":"通指之辭，謂發發菩提心，受菩薩戒，從佛法生，通名佛子。"}]},{"p":13974,"q":"恃作形勢","notes":[{"by":"義寂","era":"","t":"顯籍彼令謂之"}]},{"p":14042,"q":"解其義理佛性之性","notes":[{"by":"義寂","era":"","t":"明作師之人應先求自解，晝夜各為六時，恐新學人廢忘教詮，於行有缺，故制也。"}]},{"p":14073,"q":"自欺","notes":[{"by":"義寂","era":"","t":"一一法門中不解也。"}]},{"p":14115,"q":"見持戒比丘","notes":[{"by":"太賢","era":"","t":"此是所鬪賢良之眾。"},{"by":"義寂","era":"","t":"舉所鬪之人也。"}]},{"p":14158,"q":"以慈心故行放生業","notes":[{"by":"義寂","era":"","t":"見臨死之厄，深生慈心放之令生。"}]},{"p":14175,"q":"一切女人","notes":[{"by":"天台菩薩戒疏","era":"","t":"等者，除狂迷也。"}]},{"p":14204,"q":"而殺而食者，即殺我父母","notes":[{"by":"太賢","era":"","t":"此於萬物作同體想，大地無曾不捨身處故，火風存為身散即歸本故。"},{"by":"天台菩薩戒疏","era":"","t":"傷慈之甚，是故先制。"}]},{"p":14222,"q":"一切地水是我先身，一切火風是我本","notes":[{"by":"義寂","era":"","t":"眾生之身攬四大而成體，生時聚集為身，死時離散為物，雖集散從緣而其性不殊，大而觀之無非我體。"}]},{"p":14325,"q":"若不","notes":[{"by":"天台菩薩戒疏","era":"","t":"止作結犯，前後例知。"},{"by":"義寂","era":"","t":"總結勸持，指餘廣文。"}]},{"p":14340,"q":"應當","notes":[{"by":"天台菩薩戒疏","era":"","t":"誡勸二者，初勸學持，次"}]},{"p":14354,"q":"明一一戒相","notes":[{"by":"太賢","era":"","t":"自下十戒成六和敬，謂十如次：三、一、四、二，攝彼業、見、利、戒同故；初三各攝三業同故，成六和敬。"}]},{"p":14380,"q":"若殺父母兄弟六親，不得加報","notes":[{"by":"義寂","era":"","t":"外論一世怨親定異，故云："}]},{"p":14409,"q":"殺生報生不順孝道","notes":[{"by":"太賢","era":"","t":"問：俗禮之中，君父之怨不報非孝，何故今言於害王親報之違孝？"},{"by":"義寂","era":"","t":"怨復是親故，亦有生我之恩，殺彼生命報我生恩不孝順道也。"}]},{"p":14438,"q":"況故作七逆之罪","notes":[{"by":"太賢","era":"","t":"出家有二：一、心出家；二、身出家。"},{"by":"義寂","era":"","t":"知一切是親而行報殺，故名作逆耳。"}]},{"p":14485,"q":"自恃聰明有智","notes":[{"by":"義寂","era":"","t":"恃於世事中聰明有智也。"}]},{"p":14505,"q":"大解大福","notes":[{"by":"義寂","era":"","t":"以上五事生憍慢也。"}]},{"p":14627,"q":"佛前懺悔","notes":[{"by":"太賢","era":"","t":"懺悔時憶念斯義。"}]},{"p":14721,"q":"以是","notes":[{"by":"天台菩薩戒疏","era":"","t":"等者，結勸。"}]},{"p":14756,"q":"若千里內","notes":[{"by":"太賢","era":"","t":"等者，若爾，自受功德劣耶？"}]},{"p":14782,"q":"若法師","notes":[{"by":"義寂","era":"","t":"惡說成犯，與前第十六戒異者，彼制為利倒說，此制慢心惡說，開緣同彼。"}]},{"p":14822,"q":"惡心","notes":[{"by":"天台菩薩戒疏","era":"","t":"妬賢嫉能，非為利益，並名為惡。"}]},{"p":14845,"q":"有佛經律","notes":[{"by":"義寂","era":"","t":"現有佛教，若無佛法時亦許從受外法，時世佛法皆滅盡故。"},{"by":"天台菩薩戒疏","era":"","t":"等；次令敷演訓物，故云"},{"by":"太賢","era":"","t":"異二乘故，言"}]},{"p":14869,"q":"而捨七寶","notes":[{"by":"太賢","era":"","t":"大法可珍，從喻為名，如捨七寶，反取瓦礫也。"},{"by":"義寂","era":"","t":"大乘可珍事同七寶，而捨之不習，或經本云"}]},{"p":14894,"q":"斷佛性","notes":[{"by":"太賢","era":"","t":"如契經云：大乘法流行，名佛種子不斷。"}]},{"p":14908,"q":"若故","notes":[{"by":"法藏","era":"","t":"結示罪名，可知。"},{"by":"天台菩薩戒疏","era":"","t":"結犯，如文。"}]},{"p":14927,"q":"為說法主","notes":[{"by":"義寂","era":"","t":"講說之主也，或可講說檀越為說法主也。"}]},{"p":14968,"q":"如自己有","notes":[{"by":"太賢","era":"","t":"有二義：一、勿如己有，任意用也；二、勿應用處，如己悋惜。"}]},{"p":15016,"q":"舍宅","notes":[{"by":"太賢","era":"","t":"北并洲疏云：昔來經論，或名坐夏，或名坐臘，或名夏臘，皆由不善方言也。"},{"by":"義寂","era":"","t":"明在檀越處。"}]},{"p":15085,"q":"若有檀越","notes":[{"by":"太賢","era":"","t":"信施該十方，佛制僧次故。"},{"by":"義寂","era":"","t":"就檀越辨客主同利。"}]},{"p":15105,"q":"次第","notes":[{"by":"天台菩薩戒疏","era":"","t":"圓乘階位，行解宛然。"}]},{"p":15125,"q":"僧房主得無量罪","notes":[{"by":"義寂","era":"","t":"等者，訶其過重，唯貪現利，不見後過，故畜生無異。"},{"by":"太賢","era":"","t":"以盜十方現前僧物，利縱微小，僧無邊故。"}]},{"p":15162,"q":"一切不得受別請利養入己","notes":[{"by":"義寂","era":"","t":"聲聞法中受頭陀法不受別請，非頭陀者亦許受之。"},{"by":"太賢","era":"","t":"若次第受，理屬十方僧及八福田故。"},{"by":"天台菩薩戒疏","era":"","t":"正制止惡，三、"}]},{"p":15197,"q":"八福田","notes":[{"by":"義寂","era":"","t":"一、佛；二、聖人；三、和尚；四、阿闍梨耶；五、僧；六、父；七、母；八、病人。"},{"by":"天台菩薩戒疏","era":"","t":"僧即父母、十方病僧，通有物分，不出法及橋。"}]},{"p":15230,"q":"有出家菩薩","notes":[{"by":"天台菩薩戒疏","era":"","t":"字，天宮云：據《梵網》大本合有凡發大心稟菩薩戒，並名出家菩薩。"},{"by":"義寂","era":"","t":"兼制餘人，雖無戒可犯而失廣福故。"}]},{"p":15260,"q":"知事","notes":[{"by":"義寂","era":"","t":"田廣博包容十方，一切賢聖莫不入中。"},{"by":"天台菩薩戒疏","era":"","t":"等者，故《優婆塞戒經》云："},{"by":"太賢","era":"","t":"於一味僧，廣心供故。"}]},{"p":15292,"q":"不如僧次一凡夫僧","notes":[{"by":"法藏","era":"","t":"明違制辨失，略顯三失：一、是僧法外，故名外道法；二、七代佛戒總無此法，是則正內所無也；三、違逆佛心，故云"},{"by":"太賢","era":"","t":"問：以廣心故，得福如此。"}]},{"p":15307,"q":"是外道法","notes":[{"by":"天台菩薩戒疏","era":"","t":"佛法之外名外道法，非外外也。"}]},{"p":15324,"q":"若故","notes":[{"by":"法藏","era":"","t":"明故違結犯，可知。"}]},{"p":15341,"q":"以惡心","notes":[{"by":"太賢","era":"","t":"即是惡觸、壞生等罪，反作世間之所嫌也。"},{"by":"法藏","era":"","t":"明造惡因，謂不信有業果等而造諸罪。"},{"by":"天台菩薩戒疏","era":"","t":"不為和解，慶快無明，名惡心也。"}]},{"p":15384,"q":"工巧","notes":[{"by":"天台菩薩戒疏","era":"","t":"次列惡伎，縫合鷹眼令喫氈毛等，使其調順以擬畋獵。"},{"by":"法藏","era":"","t":"等七種，有時或通餘六，必無開法。"}]},{"p":15402,"q":"蛇毒","notes":[{"by":"太賢","era":"","t":"如五月五日毒蛇合毒藥，又以毒藥避蛇等也。"},{"by":"法藏","era":"","t":"結彼惡作為無慈心故也。"},{"by":"天台菩薩戒疏","era":"","t":"於境生惱名無慈心。"}]},{"p":15437,"q":"謗三寶","notes":[{"by":"法藏","era":"","t":"明媒嫁婬穢，謂或為私通或為成妻，為其通傳巧令和合，傳著堅密送諸眾生致此罪處，亦犯初篇第三重戒，以犯教人婬故。"},{"by":"天台菩薩戒疏","era":"","t":"說三寶空，背鱠經屏，皆因於此，謗豈過之？"}]},{"p":15470,"q":"於六齋日","notes":[{"by":"太賢","era":"","t":"《提謂經》云：正月本齋十五日，五月本齋十五日，九月本齋十五日。"},{"by":"天台菩薩戒疏","era":"","t":"初八、十四、十五、二十三、二十九、三十。"},{"by":"義寂","era":"","t":"《提謂經》云："}]},{"p":15499,"q":"如是","notes":[{"by":"義寂","era":"","t":"總結勸持，廣指餘品。"},{"by":"天台菩薩戒疏","era":"","t":"結勸指廣，如文。"}]},{"p":15513,"q":"制戒品中廣解","notes":[{"by":"太賢","era":"","t":"自下九戒開正施故、遮橫取故、避邪緣故、趣正乘故、發願求故、立誓厭故、離難故、無亂故、利樂故，所為應知。"},{"by":"法藏","era":"","t":"次、明作禮人，有三：一、外道，以邪信故；二、惡人，以不信故；三、劫賊，以求物故。"}]},{"p":15528,"q":"佛滅度後","notes":[{"by":"天台菩薩戒疏","era":"","t":"發圓三聚四弘之心，是以言"}]},{"p":15547,"q":"賣佛菩薩父母形像","notes":[{"by":"太賢","era":"","t":"法藏師云：己父母形像為他所賣，或佛即名父母。"},{"by":"義寂","era":"","t":"妨損多故；餘人墮難，理亦應救。"}]},{"p":15592,"q":"而菩薩","notes":[{"by":"法藏","era":"","t":"明制令救贖，謂見已生慈為救因，方便等救緣。"},{"by":"天台菩薩戒疏","era":"","t":"示其過非，三、"}]},{"p":15637,"q":"一切","notes":[{"by":"法藏","era":"","t":"二字，為後有總結，是故五中有有者無者。"},{"by":"天台菩薩戒疏","era":"","t":"制不應入，四、若見違制結犯。"}]},{"p":15716,"q":"觀一切","notes":[{"by":"天台菩薩戒疏","era":"","t":"即賊等軍，若自若教若試若戲，並不得觀，故云"}]},{"p":15733,"q":"亦不得","notes":[{"by":"法藏","era":"","t":"明聽音樂戒，於中略明十種，前九別辨九種音樂聲，後一通結伎樂，並可知。"}]},{"p":15764,"q":"彈碁","notes":[{"by":"法藏","era":"","t":"有二種釋：一云即雙六是也，一云別數六種博戲，前釋為定。"},{"by":"天台菩薩戒疏","era":"","t":"趯(他曆反，跳貌也)毬打毬也，亦云拍毬，其義一也。"},{"by":"太賢","era":"","t":"以指彈碁子得遠為勝。"}]},{"p":15823,"q":"護持","notes":[{"by":"義寂","era":"","t":"愛惜守護不欲漏故，事出《涅槃經》。"},{"by":"天台菩薩戒疏","era":"","t":"等者，護即守護，持謂念持。"}]},{"p":15841,"q":"猶如金剛","notes":[{"by":"法藏","era":"","t":"依《莊嚴論》，有諸比丘為賊所剝，裸形伏地，以草連根縛之，經宿不轉。"},{"by":"太賢","era":"","t":"見微小罪，生大怖畏，微有缺漏，易沈流故。"}]},{"p":15879,"q":"佛是已成","notes":[{"by":"天台菩薩戒疏","era":"","t":"捨也，心心相續不捨剎那，緣一體三寶，發四弘誓願，故云"},{"by":"法藏","era":"","t":"信佛亦曾如我今修成此信果也。"},{"by":"義寂","era":"","t":"期心大果，餘念不間。"}]},{"p":15918,"q":"常應發一切願","notes":[{"by":"義寂","era":"","t":"隨事興願，無一空過，如《華嚴》中〈淨行品〉說。"},{"by":"太賢","era":"","t":"不生自要戒第六\n經："},{"by":"天台菩薩戒疏","era":"","t":"別列十願；三、"}]},{"p":15945,"q":"常教","notes":[{"by":"法藏","era":"","t":"等是別句，謂是菩薩趣佛果之路，即三賢十聖之位，是所行之要，故願聞解。"}]},{"p":15968,"q":"使我開解","notes":[{"by":"義寂","era":"","t":"等者，護持勝戒。"},{"by":"太賢","era":"","t":"如理作意願；"}]},{"p":15993,"q":"若一切","notes":[{"by":"天台菩薩戒疏","era":"","t":"違制結犯，如文。"},{"by":"法藏","era":"","t":"不願結犯，可知。"}]},{"p":16015,"q":"十大願","notes":[{"by":"法藏","era":"","t":"等者，挍量表志立誓言，謂火坑刀山但害一身，女色不爾害多少身。"},{"by":"太賢","era":"","t":"總誓此願，如真法界，無所不至；如眾生界，終無盡期。"},{"by":"義寂","era":"","t":"別有十願，初心菩薩之所先發。"},{"by":"天台菩薩戒疏","era":"","t":"列出別誓，三、"}]},{"p":16492,"q":"一切","notes":[{"by":"天台菩薩戒疏","era":"","t":"略列如上，廣不可盡，凡能損害並名為難，故云一切。"},{"by":"法藏","era":"","t":"別釋中，一、先頭陀及遊方時，制畜十八事物。"}]},{"p":16522,"q":"常應二時頭陀","notes":[{"by":"法藏","era":"","t":"等別釋夏安居，並令一一如法，應於聖教冬夏坐禪，略不釋也。"},{"by":"天台菩薩戒疏","era":"","t":"二時不寒不熱，頭陀遊方，無有妨損，冬寒夏熱，但可坐禪。"},{"by":"義寂","era":"","t":"冬則大寒、夏則大熱，又損傷多妨於遊行，故制靜坐。"},{"by":"太賢","era":"","t":"新音杜多，此云抖擻，抖擻煩惱生死染故。"}]},{"p":16584,"q":"而菩薩","notes":[{"by":"法藏","era":"","t":"制為講法，受與大乘令修大行。"},{"by":"天台菩薩戒疏","era":"","t":"制利生修於智業，三、"}]},{"p":16604,"q":"十八種物","notes":[{"by":"太賢","era":"","t":"義寂師云：除楊枝、澡豆，取三衣等，別開經、律、佛、菩薩故。"},{"by":"天台菩薩戒疏","era":"","t":"三衣為一，經律各為一，佛菩薩像各為一，餘名可見。"}]},{"p":16660,"q":"若布薩","notes":[{"by":"法藏","era":"","t":"別釋布薩，布薩者此翻名淨住，以半月半月誦戒文檢三業，若有犯則令悔，無犯默然，使戒淨同住故名也。"},{"by":"義寂","era":"","t":"制布薩法，法如經初序說。"}]},{"p":16708,"q":"乃至","notes":[{"by":"天台菩薩戒疏","era":"","t":"不言遊方、布薩、坐禪，初舉頭陀，越取夏坐，故云乃至。"}]},{"p":16729,"q":"各各披九條","notes":[{"by":"天台菩薩戒疏","era":"","t":"等(去聲呼)，制令出家菩薩。"},{"by":"法藏","era":"","t":"等制著持受三衣也。"}]},{"p":16743,"q":"結夏安居一一如法","notes":[{"by":"法藏","era":"","t":"舉諸難處，略舉十二難處：一、國難惡王者，彼國王不信三寶，頭陀不得入彼界中；二、地有高下；三、草深林密；四、黑師子噉人；五、虎；六、狠；七、水；八、火；九、風；十、賊；十一、毒蛇所行之路；十二、總結一切難處。"},{"by":"天台菩薩戒疏","era":"","t":"總結五行，故云一一如法，謂住處無細虫、無梵命等難也。"},{"by":"義寂","era":"","t":"結時、依處、受日、出界、自恣、舉懺，皆准律行之。"}]},{"p":16795,"q":"一切","notes":[{"by":"天台菩薩戒疏","era":"","t":"三報者，一切之業並有三報：此身造業即此身報，名為現報；此身造業次生受報，名為生報；此世造業二三生後方受其報，名為後報。"}]},{"p":16825,"q":"若故","notes":[{"by":"法藏","era":"","t":"違結犯可知。"}]},{"p":16840,"q":"應如法次第坐","notes":[{"by":"天台菩薩戒疏","era":"","t":"等者，若先小後大，一切俱開。"},{"by":"義寂","era":"","t":"上下次第不違佛制。"}]},{"p":16863,"q":"不問","notes":[{"by":"法藏","era":"","t":"約人辨定中，有人釋云：令四眾等雜合通坐以明長幼。"},{"by":"太賢","era":"","t":"等者，法藏師云：有釋令四眾雜合通坐，非也。"},{"by":"天台菩薩戒疏","era":"","t":"等者，此等不同。"}]},{"p":16907,"q":"莫如","notes":[{"by":"天台菩薩戒疏","era":"","t":"舉外人為誡，三、"},{"by":"法藏","era":"","t":"簡非顯是，謂"}]},{"p":16923,"q":"坐無次第兵奴之法","notes":[{"by":"義寂","era":"","t":"兵奴強者為先，不以長幼次第，佛法道尊不應如彼。"},{"by":"天台菩薩戒疏","era":"","t":"重示所制之法，四、"},{"by":"法藏","era":"","t":"等顯是令修。"}]},{"p":16966,"q":"應教","notes":[{"by":"天台菩薩戒疏","era":"","t":"制應簡擇業報衣服；三、"}]},{"p":16996,"q":"一切行道處皆應立之","notes":[{"by":"義寂","era":"","t":"別明為有難，報恩之處亦為講說，且列十種：一、病難，謂國土多疾之時；二、國難，謂惡王御世時；三、賊難，謂惡人侵暴時；四、所尊終亡時；五、往來治生時，有經本云"}]},{"p":17022,"q":"若疾病","notes":[{"by":"法藏","era":"","t":"救其所厄，於中有五：一、救苦難中有四：一、若病時，二、若國有厄難時，三、若諸方賊起時，四、先亡追福時，皆應說此經等設齋求福。"},{"by":"天台菩薩戒疏","era":"","t":"別列所講之境，於中為三：初對報障勸講。"}]},{"p":17069,"q":"行來","notes":[{"by":"法藏","era":"","t":"救災厄中有五種：一、治生不利時，二、火災，三、水災，四、風災，五、海羅剎謂怖彼諸災，皆應講此大乘。"},{"by":"太賢","era":"","t":"南人經營產業為治生，治生不利，亦講大乘也。"}]},{"p":17106,"q":"此經律","notes":[{"by":"法藏","era":"","t":"一、現報，二、生報，三、後報，滅此三報之罪也。"},{"by":"天台菩薩戒疏","era":"","t":"也，即用報身而為對治。"}]},{"p":17139,"q":"多疾病","notes":[{"by":"太賢","era":"","t":"性多病等，前天行等，故有差別。"}]},{"p":17158,"q":"若不","notes":[{"by":"天台菩薩戒疏","era":"","t":"第二、結勸指廣中，"},{"by":"法藏","era":"","t":"明結勸指廣，可知。"},{"by":"義寂","era":"","t":"已下，總結指餘。"}]},{"p":17182,"q":"梵壇","notes":[{"by":"太賢","era":"","t":"此翻默擯，不受調伏，故以治也。"}]},{"p":17255,"q":"鬼神","notes":[{"by":"義寂","era":"","t":"小乘五部異見故服各一色，菩薩於五無所偏執故通服五色。"}]},{"p":17288,"q":"一切染衣","notes":[{"by":"太賢","era":"","t":"已下，制餘衣色。"}]},{"p":17311,"q":"若一切國","notes":[{"by":"法藏","era":"","t":"明制與俗異，並可知。"}]},{"p":17335,"q":"若欲","notes":[{"by":"法藏","era":"","t":"制問遮簡器，於中亦三：一、問數簡器。"},{"by":"義寂","era":"","t":"簡除重障以成淨器。"}]},{"p":17362,"q":"不得與七逆人現身受戒","notes":[{"by":"太賢","era":"","t":"有說：未懺七逆猶罪現存，故言現身不得戒。"}]},{"p":17409,"q":"若具七遮","notes":[{"by":"太賢","era":"","t":"以一一罪具緣成故，非謂要具七數方爾。"},{"by":"法藏","era":"","t":"制身不拜俗，謂心敬理無所犯。"},{"by":"天台菩薩戒疏","era":"","t":"七逆障戒，故名為遮。"}]},{"p":17435,"q":"不向國王禮拜","notes":[{"by":"太賢","era":"","t":"等者，謂國王等有戒無戒一切不如出家功德，是即出家若禮在家，在家即得無量罪故。"}]},{"p":17459,"q":"但解","notes":[{"by":"法藏","era":"","t":"明違求犯，謂既非七逆，但解師語之類。"},{"by":"義寂","era":"","t":"輒說成犯，無心受者，皆名惡人。"},{"by":"天台菩薩戒疏","era":"","t":"舉是顯非，違制結犯。"}]},{"p":17474,"q":"而菩薩","notes":[{"by":"法藏","era":"","t":"有二義：一、不與彼一切求戒眾生之戒也；二、此是戒名，謂名菩薩戒為一切眾生戒，以此是一切眾生所應得戒，故云也。"}]},{"p":17504,"q":"教化人起信心時","notes":[{"by":"義寂","era":"","t":"教化人令起欲受菩薩戒信。"}]},{"p":17524,"q":"見欲受","notes":[{"by":"太賢","era":"","t":"和上是得戒之本，阿闍梨耶得戒因緣故。"},{"by":"法藏","era":"","t":"明制教弟子。"}]},{"p":17543,"q":"二師應問","notes":[{"by":"義寂","era":"","t":"若現身有七遮罪者，師不應與受戒。"},{"by":"法藏","era":"","t":"明應問七遮。"}]},{"p":17579,"q":"若有","notes":[{"by":"太賢","era":"","t":"如《涅槃經》云：世間有兩種健人：一欲不作惡，二作已能悔。"},{"by":"天台菩薩戒疏","era":"","t":"等者，教懺悔法。"},{"by":"法藏","era":"","t":"教懺犯十重罪。"}]},{"p":17615,"q":"三世千佛","notes":[{"by":"太賢","era":"","t":"法藏師云：過去莊嚴劫，華光佛等一千佛；現在賢劫，俱留孫等一千佛；未來星宿劫，日光佛等一千佛。"},{"by":"法藏","era":"","t":"過去莊嚴劫中，華光如來為首，下至毘舍浮如來，如是等一千諸佛。"},{"by":"天台菩薩戒疏","era":"","t":"禮過未及現在千佛。"}]},{"p":17655,"q":"種種異相","notes":[{"by":"天台菩薩戒疏","era":"","t":"或聞空中聲言毘尼藏，或得印臂作滅罪字等便得。"}]},{"p":17670,"q":"雖懺無益","notes":[{"by":"法藏","era":"","t":"明顯過呵嘖，於中有八：一、供施無一毫分，二、大地無一足分，三、飲水無一渧分。"},{"by":"太賢","era":"","t":"藏師及寂師云：上纏失戒，若得好相，舊戒還生，更不須受。"}]},{"p":17684,"q":"而得增受","notes":[{"by":"義寂","era":"","t":"十重悔得更受，四十八輕但悔得清，是故不同七遮一向不得現受。"},{"by":"天台菩薩戒疏","era":"","t":"等者，對菩薩僧可滅惡者請為懺主，云："}]},{"p":17705,"q":"不同七遮","notes":[{"by":"太賢","era":"","t":"結顯犯重及輕垢罪，不同七遮永不得受。"}]},{"p":17718,"q":"一一好解","notes":[{"by":"義寂","era":"","t":"不解教法，於律知其輕重、於經知其是非，謂十戒為重、四十八為輕，又染犯為重、不染為輕，又故作為重、誤作為輕，是謂輕重之相。"},{"by":"天台菩薩戒疏","era":"","t":"於前七遮、十重、四十八輕分別解釋，故云"},{"by":"法藏","era":"","t":"明實無所知。"}]},{"p":17765,"q":"其中多少","notes":[{"by":"天台菩薩戒疏","era":"","t":"十禪支者，根本四禪，三乘通修，偏圓無隔，故須善解。"},{"by":"義寂","era":"","t":"上卷經中云十心，第十心云八百三昧。"},{"by":"太賢","era":"","t":"總束十八為十支也。"}]},{"p":17790,"q":"而菩薩","notes":[{"by":"法藏","era":"","t":"違制結犯，可知。"}]},{"p":17803,"q":"惡求","notes":[{"by":"太賢","era":"","t":"等者，非法求利故曰"}]},{"p":17837,"q":"與人","notes":[{"by":"法藏","era":"","t":"明作已結犯，可知。"}]},{"p":17861,"q":"未受菩薩戒","notes":[{"by":"法藏","era":"","t":"此有三種：一、純不信菩薩道故不受，二、雖不謗亦不能受，三、信擬受未受。"}]},{"p":17901,"q":"是惡人","notes":[{"by":"天台菩薩戒疏","era":"","t":"明不肯受戒之過，三、"}]},{"p":17942,"q":"而菩薩","notes":[{"by":"法藏","era":"","t":"立制定位，謂要化眾生令發大心方是菩薩，故云也。"},{"by":"天台菩薩戒疏","era":"","t":"示令總勸，凡是有情咸發道意。"}]},{"p":17967,"q":"信心出家","notes":[{"by":"義寂","era":"","t":"故，謂隨所犯結本罪已，更增毀犯受施之罪。"},{"by":"法藏","era":"","t":"等者，舉其本誓也。"}]},{"p":18004,"q":"不得飲國王水","notes":[{"by":"太賢","era":"","t":"出家避役而非福田，於其國王無恩分故，無所用故。"},{"by":"義寂","era":"","t":"以非分冐受故幽被非人之呵。"},{"by":"天台菩薩戒疏","era":"","t":"明鬼神呵責，三、"}]},{"p":18024,"q":"大賊","notes":[{"by":"太賢","era":"","t":"有罪同畜生，無善同木頭也。"}]},{"p":18045,"q":"一切世人","notes":[{"by":"天台菩薩戒疏","era":"","t":"明舉世嫌罵。"}]},{"p":18112,"q":"剝皮","notes":[{"by":"義寂","era":"","t":"等者，若得堅心無動者，則應行之。"},{"by":"天台菩薩戒疏","era":"","t":"等者，先舉難行而誡心。"}]},{"p":18136,"q":"木皮","notes":[{"by":"法藏","era":"","t":"制令供養書寫等十種法行，此中具說。"},{"by":"天台菩薩戒疏","era":"","t":"勸盛持供養，四、若不違制結犯。"}]},{"p":18171,"q":"若不","notes":[{"by":"法藏","era":"","t":"違制結犯，可知。"}]},{"p":18189,"q":"常起大悲心","notes":[{"by":"義寂","era":"","t":"愍彼長沒苦海，常欲拔之令出。"},{"by":"法藏","era":"","t":"是化眾生因，故教常起也。"}]},{"p":18212,"q":"唱言","notes":[{"by":"天台菩薩戒疏","era":"","t":"佛法僧寶為世良田，若不歸之，無由得脫，故《法句經》如佛在世，時天帝釋知命將終應受驢報，歸依於佛，禮拜之頃其命便終，託彼驢陰，母驢鞚斷，踏破坏器，被陶師打，胎落即還入天帝身，未逾食頃天帝便活。"},{"by":"法藏","era":"","t":"明化畜生類，謂彼無領解，故以此言警覺成自熏修，則與彼遠作勝因。"}]},{"p":18247,"q":"汝是畜生，發菩提心。","notes":[{"by":"義寂","era":"","t":"而菩薩入一切處山川、林野，皆使一切眾生發菩提心。"}]},{"p":18314,"q":"貴人","notes":[{"by":"義寂","era":"","t":"已下，正明說法儀式。"},{"by":"法藏","era":"","t":"多慢，故偏舉之。"}]},{"p":18343,"q":"比丘","notes":[{"by":"義寂","era":"","t":"在家為師，範義小故，大小共制。"}]},{"p":18371,"q":"聽者下坐","notes":[{"by":"天台菩薩戒疏","era":"","t":"示令勸他恭順師所說教。"},{"by":"太賢","era":"","t":"等，生渴仰故。"}]},{"p":18393,"q":"其說法者","notes":[{"by":"法藏","era":"","t":"明違制結犯。"}]},{"p":18421,"q":"若國王","notes":[{"by":"天台菩薩戒疏","era":"","t":"出非法制，制於如法比丘四，拘繫帳籍闕於剃髮出家，已出家者不得習學決疑修福，但為營理俗務，故云"},{"by":"義寂","era":"","t":"變持邪慢滅破佛法，由二因緣滅破佛法：一、立非法制；二、不聽出家行道等事。"}]},{"p":18444,"q":"明作","notes":[{"by":"法藏","era":"","t":"別顯中，一、障其出家修道，二、障造形像造經。"}]},{"p":18475,"q":"破三寶之罪","notes":[{"by":"義寂","era":"","t":"由非制而制，是制便斷也。"},{"by":"法藏","era":"","t":"違教結犯，可知。"}]},{"p":18504,"q":"而為名聞","notes":[{"by":"義寂","era":"","t":"乖本好心反從名利。"}]},{"p":18522,"q":"橫與","notes":[{"by":"天台菩薩戒疏","era":"","t":"等者，於王等前妄說佛戒，曲順王心，云佛聽許枷禁打縛僧尼，故云"}]},{"p":18538,"q":"如師子","notes":[{"by":"義寂","era":"","t":"引喻重嘖破法，由自佛子不由外道天魔也。"},{"by":"天台菩薩戒疏","era":"","t":"等者，如《師子蓮華面經》云："}]},{"p":18558,"q":"若受","notes":[{"by":"法藏","era":"","t":"舉德制修中，制令護戒至誠，如慈母念於一子，如孝子事於父母，皆無時暫忘也。"},{"by":"天台菩薩戒疏","era":"","t":"如母念子，以命從之，如事父母，使無譏謗。"}]},{"p":18614,"q":"寧自","notes":[{"by":"法藏","era":"","t":"通入惡趣，並可知。"}]},{"p":18636,"q":"而況","notes":[{"by":"天台菩薩戒疏","era":"","t":"等者，自作教他，他因破法，以他望自，自因他緣，故云"}]},{"p":18657,"q":"若故","notes":[{"by":"法藏","era":"","t":"明故作結犯，可知。"},{"by":"天台菩薩戒疏","era":"","t":"第二、結勸，如文。"}]},{"p":18683,"q":"諸佛子","notes":[{"by":"法藏","era":"","t":"勸眾令持，謂舉彼諸眾，略勸作五事：一、受持，謂領納名受，不忘名持；二、讀；三、誦；四、解釋；五、書寫。"},{"by":"天台菩薩戒疏","era":"","t":"第三大段流通，為二：初流通一經，次流通一品。"},{"by":"義寂","era":"","t":"大段第三、總結輕垢勸令受持。"}]},{"p":18739,"q":"三世","notes":[{"by":"天台菩薩戒疏","era":"","t":"第三、明所說之法，二者：初別列五藏，次"}]},{"p":18752,"q":"我今","notes":[{"by":"法藏","era":"","t":"結勸流通分。"}]},{"p":18792,"q":"應受持","notes":[{"by":"天台菩薩戒疏","era":"","t":"次明流通之相，"},{"by":"法藏","era":"","t":"明流通不絕，謂"},{"by":"太賢","era":"","t":"清淨法界也。"}]},{"p":18808,"q":"流通","notes":[{"by":"天台菩薩戒疏","era":"","t":"第三利益中三文者，初明值聖，次"}]},{"p":18821,"q":"得見","notes":[{"by":"法藏","era":"","t":"明傳授利益，謂於中有三：一、見佛益，謂得見此賢劫中千佛相授；二、永離惡處益；三、得生善處益，謂生人中等為道器身，攝眾生處也。"}]},{"p":18877,"q":"如無相","notes":[{"by":"天台菩薩戒疏","era":"","t":"應是天王名為相，從天目品也。"},{"by":"法藏","era":"","t":"指彼廣文，四、"}]},{"p":18896,"q":"時坐聽","notes":[{"by":"天台菩薩戒疏","era":"","t":"舉此南洲亦有戒本，無此一段文不周足，前勸奉後受持故。"},{"by":"太賢","era":"","t":"述曰：輕戒三門。"}]},{"p":18915,"q":"爾時","notes":[{"by":"天台菩薩戒疏","era":"","t":"第二、流通一品，四：初結說心地，二、總結十處，三、明所明所說之法，四、大眾奉持。"}]},{"p":18949,"q":"千百億","notes":[{"by":"天台菩薩戒疏","era":"","t":"第四、大眾奉行，二者：初明千百億世界機緣受行，次"},{"by":"太賢","era":"","t":"等者，說十世界海等處，如卷初說。"}]},{"p":19017,"q":"一切佛心藏","notes":[{"by":"天台菩薩戒疏","era":"","t":"戒法即心，心、眾生三無差別，名為佛心。"},{"by":"太賢","era":"","t":"等者，傳說心藏即三賢也。"}]},{"p":19035,"q":"因果","notes":[{"by":"天台菩薩戒疏","era":"","t":"等者，謂因中佛性常住藏也，果上佛性常住藏也。"}]},{"p":19423,"q":"疾得成佛道","notes":[{"by":"太賢","era":"","t":"## 梵網經古迹記卷下(末終)\n十重戒\n  1 快意殺生戒\n  2 劫盜人物戒\n  3 無慈行欲戒\n  4 故心妄語戒\n  5 酤酒生罪戒\n  6 談他過失戒\n  7 自讚毀他戒\n  8 慳生毀辱戒\n  9 瞋不受謝戒\n  10 毀謗三寶戒\n四十八輕戒\n  1 十戒\n    1 不敬師長戒\n    2 飲酒戒\n    3 食肉戒\n    4 食五辛戒\n    5 不舉教懺戒\n    6 住不請法戒\n    7 不能遊學戒\n    8 背正向邪戒\n    9 不瞻病苦戒\n    10 畜殺生具戒\n  2 十戒\n    1 通國使命戒\n    2 惱他販賣戒\n    3 無根謗毀戒\n    4 放火損生戒\n    5 法化違宗戒\n   "}]}]},{"base":"T0245","name":"T0245《佛說仁王般若波羅蜜經》","path":"01-大正藏/03般若部類/T0245《佛說仁王般若波羅蜜經》.md","loci":[{"p":25,"q":"序品第一","notes":[{"by":"吉藏","era":"","t":"發起由藉名之為序，義類相從稱之為品。"}]},{"p":449,"q":"乃至","notes":[{"by":"圓測","era":"","t":"明有能化眾生。"}]},{"p":1529,"q":"大王","notes":[{"by":"圓測","era":"","t":"成十二處等。"}]},{"p":1559,"q":"乃至","notes":[{"by":"圓測","era":"","t":"類釋四蘊及一切法。"}]},{"p":1598,"q":"一切","notes":[{"by":"圓測","era":"","t":"明理性智母。"}]},{"p":1630,"q":"大王","notes":[{"by":"圓測","era":"","t":"境智相對以明一義、後"}]},{"p":1661,"q":"白佛言","notes":[{"by":"圓測","era":"","t":"問答分別說法不二、三"}]},{"p":1747,"q":"是法","notes":[{"by":"圓測","era":"","t":"以生等相釋成空義。"}]},{"p":1809,"q":"以般若波羅蜜空故","notes":[{"by":"圓測","era":"","t":"釋能觀智照空及有。"}]},{"p":1870,"q":"因空","notes":[{"by":"圓測","era":"","t":"辨一切法空之分齊。"}]},{"p":1926,"q":"善男子","notes":[{"by":"圓測","era":"","t":"約無聽說以辨空相。"}]},{"p":2046,"q":"是經","notes":[{"by":"圓測","era":"","t":"明多佛同說，讚經勸持；後"}]},{"p":2078,"q":"無量","notes":[{"by":"圓測","era":"","t":"顯方便智，釋上四攝。"}]},{"p":2569,"q":"大王！五忍是菩薩法：伏忍上中下、","notes":[{"by":"吉藏","era":"","t":"佛言下，第二答前三問，即為三段：初從五忍是菩薩法下，說十四忍具足，答初問自行；從白佛言云何菩薩本業清淨乃至諸鬼神現身修行般若，答前第二外化行問；從佛告大王汝先言下竟品，答第三問，就前自行中有二：初略說五忍，明自行體；善男子下，第二廣分別十四忍，顯自行相。"}]},{"p":2610,"q":"名為諸佛菩薩修般若波羅蜜","notes":[{"by":"晁說之","era":"","t":"故知因修般若證五忍。"}]},{"p":2998,"q":"四攝","notes":[{"by":"晁說之","era":"","t":"次歎攝，布施、愛語、利行、同事等也。"}]},{"p":3517,"q":"十善","notes":[{"by":"晁說之","era":"","t":"等者，三歎德也。"}]},{"p":3887,"q":"爾時","notes":[{"by":"晁說之","era":"","t":"當爾之時也。"}]},{"p":3924,"q":"釋迦牟尼佛","notes":[{"by":"晁說之","era":"","t":"上明通號及德，今明別號也。"}]},{"p":4228,"q":"無相","notes":[{"by":"晁說之","era":"","t":"色空空色皆無相也。"}]},{"p":4261,"q":"不動","notes":[{"by":"晁說之","era":"","t":"即色是空，非析色也。"}]},{"p":4501,"q":"眾生","notes":[{"by":"圓測","era":"","t":"言一地行般若波羅者，此法身萬行俱也，或可通說。"},{"by":"晁說之","era":"","t":"是假名世間，"}]},{"p":4616,"q":"慧光開士三禪王，能於千恒一時現，","notes":[{"by":"吉藏","era":"","t":"慧光開士下，二行偈四句頌上九地。"}]},{"p":4644,"q":"一念","notes":[{"by":"晁說之","era":"","t":"從第十回向，以般若慧一念之中即有初地，是時具足八萬四千度也。"}]},{"p":4781,"q":"果報","notes":[{"by":"晁說之","era":"","t":"是五陰世間，謂三界依正也。"}]},{"p":5203,"q":"虛空","notes":[{"by":"晁說之","era":"","t":"無色現處是也。"}]},{"p":5434,"q":"一切諸如來","notes":[{"by":"晁說之","era":"","t":"二明諸佛無化而化不思議。"}]},{"p":5474,"q":"灌頂","notes":[{"by":"晁說之","era":"","t":"在十二法師之上故名頂。"}]},{"p":5498,"q":"我今略述","notes":[{"by":"晁說之","era":"","t":"第三釋上唯佛能知月光之德無量。"}]},{"p":5532,"q":"三賢十聖","notes":[{"by":"晁說之","era":"","t":"第三八行總結歎五忍。"}]},{"p":5573,"q":"一切諸佛","notes":[{"by":"晁說之","era":"","t":"三依義廣釋。"}]},{"p":5603,"q":"薩婆若","notes":[{"by":"晁說之","era":"","t":"二乘正路當依十四忍修學也。"}]},{"p":5671,"q":"勝慧","notes":[{"by":"晁說之","era":"","t":"次頌中品忍。"}]},{"p":5700,"q":"是人超過","notes":[{"by":"晁說之","era":"","t":"三舉果歎勝有二利益：一離苦、二得樂。"}]},{"p":5729,"q":"時諸眾中","notes":[{"by":"晁說之","era":"","t":"三大眾供養。"}]},{"p":5833,"q":"佛告","notes":[{"by":"晁說之","era":"","t":"大章第二答所化眾生之相。"}]},{"p":5940,"q":"色蓋","notes":[{"by":"晁說之","era":"","t":"即是開心為四蓋，蓋即陰也。"}]},{"p":5964,"q":"身名積聚","notes":[{"by":"晁說之","era":"","t":"三十六物共成此身也。"}]},{"p":6094,"q":"眾生者","notes":[{"by":"晁說之","era":"","t":"第二明受假。"}]},{"p":6130,"q":"乃至六道","notes":[{"by":"晁說之","era":"","t":"三約六道明受假也。"}]},{"p":6192,"q":"幻法幻化","notes":[{"by":"晁說之","era":"","t":"三明無三界六道也。"}]},{"p":6248,"q":"是名無量","notes":[{"by":"晁說之","era":"","t":"二結名非一也。"}]},{"p":6269,"q":"相續假法","notes":[{"by":"晁說之","era":"","t":"第四明相續假。"}]},{"p":6300,"q":"相待假","notes":[{"by":"晁說之","era":"","t":"第五釋相待假。"}]},{"p":6474,"q":"爾時","notes":[{"by":"晁說之","era":"","t":"將欲設難，故作兩徵。"}]},{"p":6566,"q":"諦聽","notes":[{"by":"晁說之","era":"","t":"三誡聽勸修三慧也。"}]},{"p":6589,"q":"無相第一義，無自無他作，因緣本自","notes":[{"by":"吉藏","era":"","t":"無相第一義者，此辨真諦也。"}]},{"p":6613,"q":"法性本無性","notes":[{"by":"晁說之","era":"","t":"二一行明通教二諦，上半明真、下半明俗。"}]},{"p":6631,"q":"三假","notes":[{"by":"晁說之","era":"","t":"三一行明圓教二諦。"}]},{"p":6661,"q":"有無本自二","notes":[{"by":"晁說之","era":"","t":"第二正答難，明不一不二。"}]},{"p":6685,"q":"解心見不二","notes":[{"by":"晁說之","era":"","t":"二一行智理相對以遣執，上半明解心求二不可得，下半明遣著。"}]},{"p":6709,"q":"於解常自一","notes":[{"by":"晁說之","era":"","t":"三一行理智相對讚入真義也。"}]},{"p":6733,"q":"世諦幻化起","notes":[{"by":"晁說之","era":"","t":"三二行半結成上三義。"}]},{"p":6757,"q":"幻化見幻化","notes":[{"by":"晁說之","era":"","t":"二一行明聖見有無也。"}]},{"p":6781,"q":"名為諸佛觀","notes":[{"by":"晁說之","era":"","t":"半行，三結正觀也。"}]},{"p":6851,"q":"以一切法","notes":[{"by":"晁說之","era":"","t":"釋中文二：初正釋一義，可解。"}]},{"p":6896,"q":"五眼成就時","notes":[{"by":"晁說之","era":"","t":"二明無行而行，方離五非。"}]},{"p":6935,"q":"菩薩未成佛","notes":[{"by":"晁說之","era":"","t":"第三染淨相對以明一義。"}]},{"p":6986,"q":"白佛言","notes":[{"by":"晁說之","era":"","t":"第三明法門不二，先問、後答。"}]},{"p":7022,"q":"法本","notes":[{"by":"晁說之","era":"","t":"伊帝目多伽經也，《大經》云戒經。"}]},{"p":7090,"q":"若取文字者","notes":[{"by":"晁說之","era":"","t":"因此如如能生佛智，故云"}]},{"p":7157,"q":"三乘般若","notes":[{"by":"晁說之","era":"","t":"第二逐難重釋。"}]},{"p":7184,"q":"若菩薩無","notes":[{"by":"晁說之","era":"","t":"二行性釋如如智母也。"}]},{"p":7267,"q":"法門為一","notes":[{"by":"晁說之","era":"","t":"三問法門也。"}]},{"p":7299,"q":"一切法亦非有相","notes":[{"by":"晁說之","era":"","t":"二明所觀法。"}]},{"p":7356,"q":"以三諦","notes":[{"by":"晁說之","era":"","t":"二約三諦顯諸法。"}]},{"p":7384,"q":"我人知見","notes":[{"by":"晁說之","era":"","t":"三約三假顯法。"}]},{"p":7446,"q":"汝等大眾","notes":[{"by":"晁說之","era":"","t":"二舉益勸持也。"}]},{"p":7557,"q":"況復於此","notes":[{"by":"晁說之","era":"","t":"第三明勝信。"}]},{"p":7620,"q":"時諸大眾","notes":[{"by":"晁說之","era":"","t":"五明得益也。"}]},{"p":7698,"q":"亦名一切","notes":[{"by":"晁說之","era":"","t":"二明用，可見。"}]},{"p":7841,"q":"當國土欲亂","notes":[{"by":"晁說之","era":"","t":"二廣釋護法。"}]},{"p":7883,"q":"七眾","notes":[{"by":"晁說之","era":"","t":"出家五眾，比丘、比丘尼、沙彌、沙彌尼、式叉摩那。"}]},{"p":7927,"q":"三衣","notes":[{"by":"晁說之","era":"","t":"三衣三，鉢四，坐具五，剃刀六，刀子七，漉水囊八，鉢袋九，針筒十也。"}]},{"p":7957,"q":"汝國土中","notes":[{"by":"晁說之","era":"","t":"第三明能護，即是護體也。"}]},{"p":8070,"q":"一切諸難","notes":[{"by":"晁說之","era":"","t":"三對難明護。"}]},{"p":8178,"q":"四重","notes":[{"by":"晁說之","era":"","t":"一地獄、二畜生、三餓鬼、四長壽天、五邊地、六諸根不具、七邪見、八不見佛。"}]},{"p":8334,"q":"九百九十","notes":[{"by":"晁說之","era":"","t":"次諸王得道。"}]},{"p":8361,"q":"其普明王","notes":[{"by":"晁說之","era":"","t":"二明能護難。"}]},{"p":8396,"q":"時普明","notes":[{"by":"晁說之","era":"","t":"三正明護難。"}]},{"p":8515,"q":"瘡疣","notes":[{"by":"晁說之","era":"","t":"即是自身與心，豈在外也。"}]},{"p":8570,"q":"識神無形","notes":[{"by":"晁說之","era":"","t":"四說無我理。"}]},{"p":8629,"q":"法眼空","notes":[{"by":"晁說之","era":"","t":"即是人空也。"}]},{"p":8699,"q":"時班足王問","notes":[{"by":"晁說之","era":"","t":"三諸王悟道。"}]},{"p":8754,"q":"時班足王極大","notes":[{"by":"晁說之","era":"","t":"二放捨諸王。"}]},{"p":8871,"q":"天上人中","notes":[{"by":"晁說之","era":"","t":"二勸六道也。"}]},{"p":8890,"q":"未來世中","notes":[{"by":"晁說之","era":"","t":"三勸諸小王也。"}]},{"p":8944,"q":"得入初地","notes":[{"by":"晁說之","era":"","t":"即圓教十信初心地。"}]},{"p":8961,"q":"性空","notes":[{"by":"晁說之","era":"","t":"則十住一心三觀，觀無明性空也。"}]},{"p":9012,"q":"十三昧","notes":[{"by":"晁說之","era":"","t":"即真俗中三諦三昧也，亦空無相等也。"}]},{"p":9039,"q":"自性信","notes":[{"by":"吉藏","era":"","t":"爾時釋迦牟尼下，品中大段第四明得益。"},{"by":"晁說之","era":"","t":"通教聲聞也。"}]},{"p":9100,"q":"歡喜無量","notes":[{"by":"晁說之","era":"","t":"二花變為城，城即涅槃也。"}]},{"p":9170,"q":"復散八萬","notes":[{"by":"晁說之","era":"","t":"第二散般若花。"}]},{"p":9193,"q":"臺中光明","notes":[{"by":"晁說之","era":"","t":"三化佛說法。"}]},{"p":9212,"q":"臺中大眾","notes":[{"by":"晁說之","era":"","t":"四化眾散花。"}]},{"p":9248,"q":"城中師子吼","notes":[{"by":"晁說之","era":"","t":"三化佛說法，即圓教中菩薩於別中說法也。"}]},{"p":9269,"q":"時城中菩薩","notes":[{"by":"晁說之","era":"","t":"四化菩薩散花。"}]},{"p":9343,"q":"時諸國王","notes":[{"by":"晁說之","era":"","t":"三諸王發願。"}]},{"p":9406,"q":"佛告大王","notes":[{"by":"晁說之","era":"","t":"二如來述成。"}]},{"p":9583,"q":"佛現神足時","notes":[{"by":"晁說之","era":"","t":"第二明時眾得益。"}]},{"p":9934,"q":"自觀己身","notes":[{"by":"晁說之","era":"","t":"二修不淨行。"}]},{"p":9966,"q":"五受","notes":[{"by":"晁說之","era":"","t":"即苦、樂、憂、喜、捨也。"}]},{"p":10013,"q":"住在佛家","notes":[{"by":"晁說之","era":"","t":"三生佛家，行六和敬也。"}]},{"p":10126,"q":"是定人者","notes":[{"by":"晁說之","era":"","t":"二顯其勝位。"}]},{"p":10147,"q":"六重","notes":[{"by":"晁說之","era":"","t":"亦如《優婆塞經》說：一不供養父母師長、二專飲酒、三不能瞻病苦、四不能多少捨施、五見四眾不起承迎禮拜、六見四眾毀戒心生憍慢、七每月不能受持八戒供養三寶、八四十里中有講不聽、九受招提僧臥具床座、十疑水有蟲故飲、十一險處獨行、十二獨宿尼寺、十三為財命打罵奴婢等、十四以殘食施四眾、十五畜猫狸、十六畜象馬等一切畜生、不作淨施未受戒者、十七儲畜長衣鉢等、十八為身田作、十九市賣斗秤不平、二十非時行欲、二十一不輸王稅、二十二犯國戒、二十三得新菓菜不奉三寶、二十四僧若不聽說法而輒自作、二十五道路上在一切出家人前行、二十六僧中時食遍為師長、二十七養蠶、二十八行逢病人不住瞻視付囑所在而便捨去。"}]},{"p":10174,"q":"能以一阿僧","notes":[{"by":"晁說之","era":"","t":"四念處四、三善根七、三世觀十，如〈教化品〉中說。"}]},{"p":10239,"q":"無定相","notes":[{"by":"晁說之","era":"","t":"我自無體，相上亦無也。"}]},{"p":10269,"q":"以二阿僧","notes":[{"by":"晁說之","era":"","t":"三入位時節。"}]},{"p":10337,"q":"第一義諦","notes":[{"by":"晁說之","era":"","t":"即無生中道空也。"}]},{"p":10369,"q":"復以三阿僧","notes":[{"by":"晁說之","era":"","t":"三入位時節，爾許時修方得初地。"}]},{"p":10412,"q":"住平等忍","notes":[{"by":"晁說之","era":"","t":"即標實智，雙照有無而不染也。"}]},{"p":10450,"q":"法性無為","notes":[{"by":"晁說之","era":"","t":"三非擇滅無為，謂無相等法也。"}]},{"p":10512,"q":"無量方便","notes":[{"by":"晁說之","era":"","t":"第二顯方便智。"}]},{"p":10682,"q":"譬如","notes":[{"by":"晁說之","era":"","t":"二舉喻顯非，明不一不二。"}]},{"p":10718,"q":"而一一行成就","notes":[{"by":"晁說之","era":"","t":"三明行成就。"}]},{"p":10742,"q":"無三界業","notes":[{"by":"晁說之","era":"","t":"次生淨土，即方便有餘及實報等土也。"}]},{"p":10777,"q":"鳩摩羅伽","notes":[{"by":"晁說之","era":"","t":"此云勝怨，以離三界及二乘怨也。"}]},{"p":10803,"q":"以四無量心","notes":[{"by":"晁說之","era":"","t":"二辨觀差別。"}]},{"p":10828,"q":"以五阿僧","notes":[{"by":"晁說之","era":"","t":"三入位時節。"}]},{"p":10849,"q":"闍陀波羅","notes":[{"by":"晁說之","era":"","t":"此云滿足，亦名無畏，尸羅圓滿故。"}]},{"p":10898,"q":"盡三界癡煩惱","notes":[{"by":"晁說之","era":"","t":"三明入位時節。"}]},{"p":10933,"q":"伽羅陀","notes":[{"by":"晁說之","era":"","t":"此云度邊，度度等邊也。"}]},{"p":10959,"q":"修行順法忍","notes":[{"by":"晁說之","era":"","t":"二明地別行。"}]},{"p":11010,"q":"亦以七阿","notes":[{"by":"晁說之","era":"","t":"三入位時節。"}]},{"p":11042,"q":"於順道忍","notes":[{"by":"晁說之","era":"","t":"二明地中別行。"}]},{"p":11082,"q":"滅三界疑等煩惱","notes":[{"by":"晁說之","era":"","t":"三入位分齊，亦是借小說大。"}]},{"p":11187,"q":"集業","notes":[{"by":"晁說之","era":"","t":"此地中並盡也。"}]},{"p":11216,"q":"復於九阿","notes":[{"by":"晁說之","era":"","t":"三入位時節。"}]},{"p":11249,"q":"十阿僧","notes":[{"by":"晁說之","era":"","t":"二入位時分。"}]},{"p":11322,"q":"住第十地","notes":[{"by":"晁說之","era":"","t":"即十三法師中第十法師地，非謂十地菩薩也。"}]},{"p":11361,"q":"住無生","notes":[{"by":"晁說之","era":"","t":"念念空也，即明寂義。"}]},{"p":11385,"q":"而用心","notes":[{"by":"晁說之","era":"","t":"二明用而常寂。"}]},{"p":11404,"q":"在有常修空","notes":[{"by":"晁說之","era":"","t":"釋上寂而常用。"}]},{"p":11442,"q":"摩訶羅伽","notes":[{"by":"晁說之","era":"","t":"此云大得，或云龍象等。"}]},{"p":11495,"q":"滅心心相","notes":[{"by":"晁說之","era":"","t":"一明滅心滅意等名滅心，滅心數名滅相。"}]},{"p":11525,"q":"萬阿僧","notes":[{"by":"晁說之","era":"","t":"三明入位時節。"}]},{"p":11570,"q":"觀佛菩薩","notes":[{"by":"晁說之","era":"","t":"若開妙覺，此是等覺猶名菩薩，來至此地保為究竟，乃是未極更須觀察。"}]},{"p":11614,"q":"金剛臺","notes":[{"by":"晁說之","era":"","t":"即金剛三昧。"}]},{"p":11645,"q":"滅一切煩惱","notes":[{"by":"晁說之","era":"","t":"即大涅槃也。"}]},{"p":11711,"q":"唯佛頓解","notes":[{"by":"晁說之","era":"","t":"三漸頓差別也。"}]},{"p":11752,"q":"入理盡","notes":[{"by":"晁說之","era":"","t":"五等無等異。"}]},{"p":11801,"q":"亦復","notes":[{"by":"晁說之","era":"","t":"在別利物，故云"}]},{"p":11883,"q":"佛告波斯匿王","notes":[{"by":"晁說之","era":"","t":"第二付王受持。"}]},{"p":11916,"q":"一切國土","notes":[{"by":"晁說之","era":"","t":"二明般若之力。"}]},{"p":11937,"q":"是故付囑","notes":[{"by":"晁說之","era":"","t":"三釋付囑所以。"}]},{"p":11977,"q":"汝當受持","notes":[{"by":"晁說之","era":"","t":"四別付月光也。"}]},{"p":12151,"q":"二十八","notes":[{"by":"晁說之","era":"","t":"二星宿失度難也。"}]},{"p":12227,"q":"大火燒國","notes":[{"by":"晁說之","era":"","t":"三災火難也。"}]},{"p":12356,"q":"大風吹殺萬姓","notes":[{"by":"晁說之","era":"","t":"五惡風難也。"}]},{"p":12412,"q":"天地國土","notes":[{"by":"晁說之","era":"","t":"六亢陽難也。"}]},{"p":12458,"q":"四方賊來","notes":[{"by":"晁說之","era":"","t":"七惡賊難也。"}]},{"p":12537,"q":"王之父母","notes":[{"by":"晁說之","era":"","t":"即觀照般若，以能生王慧解心故；下六名即文字般若也。"}]},{"p":12608,"q":"高五丈","notes":[{"by":"晁說之","era":"","t":"二別明行住供養，先明行供養。"}]},{"p":12668,"q":"若王住時","notes":[{"by":"晁說之","era":"","t":"是明住供養也。"}]},{"p":13057,"q":"時諸大眾","notes":[{"by":"晁說之","era":"","t":"第三時眾得益。"}]},{"p":13117,"q":"四大","notes":[{"by":"晁說之","era":"","t":"次明十一切處，地水火風、青黃赤白、空處識處。"}]},{"p":13137,"q":"三十忍","notes":[{"by":"晁說之","era":"","t":"即初地，初地是九地相。"}]},{"p":13186,"q":"十八梵天","notes":[{"by":"晁說之","era":"","t":"三天益，修羅及天皆同益也。"}]},{"p":13415,"q":"佛告波斯匿王","notes":[{"by":"晁說之","era":"","t":"佛去百年內五人住持：一迦葉、二阿難、三末田地，三人見佛在世，相次住持，經六十年法行不滅。"}]},{"p":13460,"q":"此經三寶","notes":[{"by":"晁說之","era":"","t":"二明付人法。"}]},{"p":13506,"q":"後五濁世","notes":[{"by":"晁說之","era":"","t":"第二廣辨七誡。"}]},{"p":13551,"q":"明作制法","notes":[{"by":"晁說之","era":"","t":"二辨滅法過。"}]},{"p":13825,"q":"如師子身","notes":[{"by":"晁說之","era":"","t":"二明喻也，此喻如《蓮華面經》"}]},{"p":13888,"q":"六親","notes":[{"by":"晁說之","era":"","t":"父母兄弟夫妻。"}]},{"p":14372,"q":"聞佛所說","notes":[{"by":"晁說之","era":"","t":"二明聞佛法義。"}]}]},{"base":"T0360","name":"T0360《佛說無量壽經》","path":"01-大正藏/16淨土宗部類/T0360《佛說無量壽經》.md","loci":[{"p":255,"q":"普賢","notes":[{"by":"慧遠","era":"","t":"彌勒姓慈，故曰慈氏，字阿逸多，此云無勝。"}]},{"p":280,"q":"又賢護","notes":[{"by":"慧遠","era":"","t":"等，就其所等，隨別以列。"}]},{"p":398,"q":"入佛法","notes":[{"by":"慧遠","era":"","t":"就其勝進廣歎其德。"}]},{"p":548,"q":"入山學道","notes":[{"by":"慧遠","era":"","t":"是第二句，彰其所習。"}]},{"p":574,"q":"而著法服","notes":[{"by":"慧遠","era":"","t":"翻邪學正道，是其所應修學，順而行之。"}]},{"p":635,"q":"吉祥感徵","notes":[{"by":"慧遠","era":"","t":"即以此人表己所成功果福祚，是故名為"}]},{"p":706,"q":"遊步","notes":[{"by":"慧遠","era":"","t":"已下，口業起化，於中十句。"}]},{"p":792,"q":"摑裂","notes":[{"by":"慧遠","era":"","t":"口業破邪，令離煩惱。"}]},{"p":822,"q":"洗濯","notes":[{"by":"慧遠","era":"","t":"結前第一摧邪之義。"}]},{"p":842,"q":"入國分","notes":[{"by":"慧遠","era":"","t":"身業受供，生人福善。"}]},{"p":859,"q":"欲宣法","notes":[{"by":"慧遠","era":"","t":"口業說法，令修出道。"}]},{"p":876,"q":"顯現","notes":[{"by":"慧遠","era":"","t":"教人發心，顯現菩薩所發道意，使人發矣。"}]},{"p":894,"q":"示現","notes":[{"by":"慧遠","era":"","t":"已下，是其第五童子之相。"}]},{"p":913,"q":"具足功德微妙","notes":[{"by":"慧遠","era":"","t":"已下，雙以結歎。"}]},{"p":960,"q":"本學明","notes":[{"by":"慧遠","era":"","t":"等，喻起化德。"}]},{"p":978,"q":"學一切","notes":[{"by":"慧遠","era":"","t":"合本學也，謂學一切化他之法。"}]},{"p":996,"q":"無數佛土皆悉普現","notes":[{"by":"慧遠","era":"","t":"合前化相，合現眾像為男女等。"}]},{"p":1051,"q":"佛所住","notes":[{"by":"慧遠","era":"","t":"證行同佛，佛所法住，菩薩同住。"}]},{"p":1126,"q":"善學","notes":[{"by":"慧遠","era":"","t":"已下，明修智行。"}]},{"p":1204,"q":"具足成就無量總持","notes":[{"by":"慧遠","era":"","t":"得陀羅尼，行德多也，如他經說。"}]},{"p":1240,"q":"宣揚","notes":[{"by":"慧遠","era":"","t":"攝行寬廣，由見多佛，供養生福，受法生智。"}]},{"p":1267,"q":"無不周遍","notes":[{"by":"釋璟興","era":"","t":"述云：第三、重辨起修。"}]},{"p":1281,"q":"分別顯","notes":[{"by":"慧遠","era":"","t":"起說之得，謂得如來四無礙智，解了諸法。"}]},{"p":1304,"q":"開化一切","notes":[{"by":"釋璟興","era":"","t":"述云：此後、起利他修也。"}]},{"p":1318,"q":"心常諦","notes":[{"by":"釋璟興","era":"","t":"述云：第四、重申所成。"},{"by":"慧遠","era":"","t":"等，所成不動。"}]},{"p":1356,"q":"受持如來甚深法","notes":[{"by":"慧遠","era":"","t":"依前勝進，辨修成德。"}]},{"p":1369,"q":"常使不絕","notes":[{"by":"釋璟興","era":"","t":"述云：第四、重辨勝分修成德。"}]},{"p":1403,"q":"施諸黎庶","notes":[{"by":"釋璟興","era":"","t":"述云：此後、利他修。"}]},{"p":1417,"q":"於諸眾生","notes":[{"by":"慧遠","era":"","t":"明得如來福德莊嚴。"}]},{"p":1448,"q":"不可思議","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、所成之德也。"}]},{"p":1466,"q":"一時","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、傳時也。"}]},{"p":1486,"q":"光顏巍巍","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、說經因起序也。"}]},{"p":1524,"q":"諸根悅","notes":[{"by":"慧遠","era":"","t":"等，明所現相。"}]},{"p":1561,"q":"殊妙如今","notes":[{"by":"釋璟興","era":"","t":"述云：此後、正問顯相意。"},{"by":"慧遠","era":"","t":"彰已所念；三"}]},{"p":1582,"q":"住奇特","notes":[{"by":"慧遠","era":"","t":"佛所得法，超出餘人，在世所無，故云奇特。"}]},{"p":1600,"q":"住導師行","notes":[{"by":"慧遠","era":"","t":"四攝法等是佛導師化人之行，今佛住之。"},{"by":"釋璟興","era":"","t":"述云：此第五念也。"}]},{"p":1618,"q":"行如來德","notes":[{"by":"慧遠","era":"","t":"十力、無畏、十八不共、五眼、六通、四無礙等，是佛功德。"}]},{"p":1636,"q":"念諸佛耶","notes":[{"by":"釋璟興","era":"","t":"述云：此後、徵所為也。"},{"by":"慧遠","era":"","t":"已下，結問所為。"}]},{"p":1681,"q":"問威顏乎","notes":[{"by":"釋璟興","era":"","t":"述云：第二、佛審問所以也。"}]},{"p":1706,"q":"問斯義耳","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、阿難唱問所以也。"}]},{"p":1740,"q":"問斯慧義","notes":[{"by":"釋璟興","era":"","t":"有人釋此，依內無盡法而生故。"}]},{"p":1757,"q":"所以","notes":[{"by":"慧遠","era":"","t":"明佛難值，先法、後喻。"}]},{"p":1791,"q":"時時乃出","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、辨佛難值也。"},{"by":"慧遠","era":"","t":"約對三明問有益。"}]},{"p":1809,"q":"諸天人民","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、正申問益也。"}]},{"p":1834,"q":"慧見無礙","notes":[{"by":"慧遠","era":"","t":"彰智自在，於諸法門知見無礙，此則是前行如來德。"},{"by":"釋璟興","era":"","t":"述云，第二、舉德勅許。"}]},{"p":1868,"q":"諸根悅豫不以毀損","notes":[{"by":"慧遠","era":"","t":"勅聽許說，說己所念，謂念西方無量壽佛。"}]},{"p":1881,"q":"光顏無異","notes":[{"by":"釋璟興","era":"","t":"述云：此後、述阿難所見也。"}]},{"p":1904,"q":"而得自在","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、以因顯勝也。"}]},{"p":2279,"q":"次名處世","notes":[{"by":"釋璟興","era":"","t":"述云：此次、敘佛也。"}]},{"p":2335,"q":"天人師","notes":[{"by":"慧遠","era":"","t":"此之兩號，是他化能。"}]},{"p":2362,"q":"正真道意","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、申勝行也。"}]},{"p":2383,"q":"高才勇","notes":[{"by":"慧遠","era":"","t":"第三段中，初詣佛所，次到已敬。"},{"by":"釋璟興","era":"","t":"述云：此第二、出俗修道也。"}]},{"p":2411,"q":"長跪","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、歎佛起願。"},{"by":"慧遠","era":"","t":"已下，讚歎發願。"}]},{"p":2437,"q":"無與等者","notes":[{"by":"慧遠","era":"","t":"對人顯勝，餘人身光無與齊等。"}]},{"p":2497,"q":"殊勝希有","notes":[{"by":"釋璟興","era":"","t":"述云：第三、歎意業。"}]},{"p":2554,"q":"光明威","notes":[{"by":"釋璟興","era":"","t":"此第四、總歎三業也。"},{"by":"慧遠","era":"","t":"等，結嘆前身。"}]},{"p":2579,"q":"靡不解脫","notes":[{"by":"釋璟興","era":"","t":"述云：第三、自誓。"}]},{"p":2602,"q":"智慧為上","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、求因。"}]},{"p":2622,"q":"為作大安","notes":[{"by":"釋璟興","era":"","t":"述云：此後、願利他因也。"}]},{"p":2643,"q":"如恒沙","notes":[{"by":"慧遠","era":"","t":"對願比校，彰其不及。"}]},{"p":2662,"q":"堅正不却","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、歎願勝也。"}]},{"p":2702,"q":"威神難量","notes":[{"by":"釋璟興","era":"","t":"述云：第二、淨土果。"}]},{"p":2732,"q":"而無等雙","notes":[{"by":"釋璟興","era":"","t":"述云：此次、對求勝土也。"}]},{"p":2757,"q":"已到我","notes":[{"by":"慧遠","era":"","t":"其次一偈，請十方佛作證，可知。"},{"by":"釋璟興","era":"","t":"述云：此第三、求淨土之意也。"}]},{"p":2782,"q":"力精所欲","notes":[{"by":"釋璟興","era":"","t":"述云：第二、請佛作證。"}]},{"p":2822,"q":"忍終不悔","notes":[{"by":"釋璟興","era":"","t":"述云：此後、請十方佛證行不悔也。"}]},{"p":2835,"q":"法藏比丘說此頌","notes":[{"by":"慧遠","era":"","t":"等，申己所修。"}]},{"p":2868,"q":"廣宣經法","notes":[{"by":"慧遠","era":"","t":"是其初門，修行法身淨土之因。"},{"by":"釋璟興","era":"","t":"述云：第二、廣說勝行。"}]},{"p":2904,"q":"勤苦之本","notes":[{"by":"釋璟興","era":"","t":"述云：此後、申請說之意也。"}]},{"p":2922,"q":"佛告","notes":[{"by":"慧遠","era":"","t":"已下，校量顯勝。"}]},{"p":2939,"q":"汝自當知","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、佛不許也。"}]},{"p":2989,"q":"成滿所願","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、法藏重請也。"}]},{"p":3019,"q":"而說經言","notes":[{"by":"釋璟興","era":"","t":"述云：第四、如來為說。"}]},{"p":3066,"q":"何願不得","notes":[{"by":"釋璟興","era":"","t":"述云：此別申所說。"}]},{"p":3110,"q":"悉現與之","notes":[{"by":"釋璟興","era":"","t":"述云：此後、正答所請也。"}]},{"p":3134,"q":"超發","notes":[{"by":"慧遠","era":"","t":"已下，修上所說淨土之因。"},{"by":"釋璟興","era":"","t":"述云：第五、正修勝行。"}]},{"p":3175,"q":"清淨之行","notes":[{"by":"慧遠","era":"","t":"彰彼如來壽命長久，成前法藏於彼佛所五劫修行。"},{"by":"釋璟興","era":"","t":"述云：此第二、依願修行也。"}]},{"p":3237,"q":"詣彼佛","notes":[{"by":"慧遠","era":"","t":"等，啟白方便。"}]},{"p":3295,"q":"發起悅","notes":[{"by":"慧遠","era":"","t":"等，明說所為，為益諸眾，故須宣說。"}]},{"p":3318,"q":"無量大願","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、佛勸說也。"}]},{"p":3341,"q":"當具說之","notes":[{"by":"釋璟興","era":"","t":"述云：第三、自宣發願。"}]},{"p":3365,"q":"不取正覺","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、利益自土願，即聞法自在也。"}]},{"p":6190,"q":"如是功德不可稱說","notes":[{"by":"釋璟興","era":"","t":"述云：後、結歎也。"}]},{"p":6232,"q":"相好殊妙","notes":[{"by":"釋璟興","era":"","t":"述云：第二、歎依正報。"}]},{"p":6274,"q":"於一切法而得自在","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、歎智德果也。"}]},{"p":6334,"q":"去此十萬億剎","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、標土已變也。"}]},{"p":6377,"q":"凡歷十劫","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、成佛久近也。"}]},{"p":6466,"q":"猶如第六天寶","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、盡國嚴麗。"}]},{"p":6550,"q":"常和調適","notes":[{"by":"釋璟興","era":"","t":"述云：此後、嚴土無穢。"}]},{"p":6586,"q":"依何而住","notes":[{"by":"釋璟興","era":"","t":"述云：此後、辨無所以。"}]},{"p":6608,"q":"皆依何住","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、阿難答也。"}]},{"p":6669,"q":"故能爾耳","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、佛述成也。"}]},{"p":6699,"q":"故問斯義","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、申問意也。"}]},{"p":6775,"q":"亦復如是","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、諸聖共歎。"}]},{"p":6879,"q":"超日月光佛","notes":[{"by":"釋璟興","era":"","t":"述云：此後、結歎顯勝也。"}]},{"p":6943,"q":"皆蒙解脫","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、見者獲利也。"}]},{"p":7075,"q":"亦如今也","notes":[{"by":"釋璟興","era":"","t":"述云：第四、聞光獲利。"}]},{"p":7129,"q":"汝寧知乎","notes":[{"by":"釋璟興","era":"","t":"述云：第二、辨所成壽。"}]},{"p":7195,"q":"知其限極","notes":[{"by":"釋璟興","era":"","t":"述云：此後、寄事顯長也。"}]},{"p":7226,"q":"所能知也","notes":[{"by":"釋璟興","era":"","t":"述云：此次、答其多少也。"}]},{"p":7260,"q":"一切世界","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、略歎德勝。"}]},{"p":7286,"q":"菩薩亦然","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、廣顯眾多。"}]},{"p":7327,"q":"多少之數","notes":[{"by":"釋璟興","era":"","t":"述云：此後、別釋。"}]},{"p":7377,"q":"何所為多","notes":[{"by":"釋璟興","era":"","t":"述云：此後、寄事顯多。"}]},{"p":7459,"q":"如大海水","notes":[{"by":"釋璟興","era":"","t":"述云：此後、佛述成也。"}]},{"p":7969,"q":"自然相和","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、音樂也。"}]},{"p":8080,"q":"隨應而現","notes":[{"by":"釋璟興","era":"","t":"述云：第二、辨道場樹。"}]},{"p":8121,"q":"不遭苦患","notes":[{"by":"釋璟興","era":"","t":"述云：此次、出聲利物也。"}]},{"p":8178,"q":"無諸惱患","notes":[{"by":"釋璟興","era":"","t":"述云：此後、見聞獲利。"}]},{"p":8230,"q":"威神力故","notes":[{"by":"釋璟興","era":"","t":"述云：此後、智力得忍。"}]},{"p":8255,"q":"究竟願故","notes":[{"by":"釋璟興","era":"","t":"述云：此後、願力獲利也。"}]},{"p":8325,"q":"千億倍也","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、對之顯勝也。"}]},{"p":8366,"q":"最為第一","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、樂莊嚴也。"}]},{"p":8412,"q":"覆蓋其上","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、宮莊嚴也。"}]},{"p":8452,"q":"各皆一等","notes":[{"by":"釋璟興","era":"","t":"述云：第四、池莊嚴。"}]},{"p":8470,"q":"味如甘露","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、水相也。"}]},{"p":8626,"q":"彌覆水上","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、池莊嚴也。"}]},{"p":8756,"q":"不遲不疾","notes":[{"by":"釋璟興","era":"","t":"述云：第四、資用任意也。"}]},{"p":8864,"q":"歡喜無量","notes":[{"by":"釋璟興","era":"","t":"述云：第二、歎聲。"}]},{"p":8903,"q":"所行之道","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、聞之修善也。"}]},{"p":8962,"q":"神通功德","notes":[{"by":"釋璟興","era":"","t":"述云：第四、顯其所攝。"}]},{"p":9047,"q":"自然","notes":[{"by":"慧遠","era":"","t":"德風吹鼓；五"}]},{"p":9198,"q":"無極之體","notes":[{"by":"釋璟興","era":"","t":"述云：第二、舊住報勝。"}]},{"p":9227,"q":"寧可類乎","notes":[{"by":"慧遠","era":"","t":"無以為喻，百千萬億不可計倍，正明貧人不及帝王。"},{"by":"釋璟興","era":"","t":"述云：此後、寄事顯勝。"}]},{"p":9261,"q":"不可計倍","notes":[{"by":"慧遠","era":"","t":"明彼貧人不及所由，由其先世無善故爾，文顯可知。"},{"by":"釋璟興","era":"","t":"述云，此第五、以魔天對西方眾也。"}]},{"p":9409,"q":"所以世間帝王","notes":[{"by":"慧遠","era":"","t":"已下，釋彼帝王勝過所以，以其宿世修善故爾，文亦可知。"}]},{"p":9592,"q":"萬億倍也","notes":[{"by":"釋璟興","era":"","t":"述云：第三、以輪王對帝釋也。"}]},{"p":9611,"q":"不相類也","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、以帝釋對魔王也。"}]},{"p":9730,"q":"應念即至","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、諸寶任意也。"}]},{"p":9751,"q":"踐之而行","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、寶衣布地也。"}]},{"p":9800,"q":"盡極嚴麗","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、寶網羅覆也。"}]},{"p":9971,"q":"如是六反","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、德風吹鼓也。"}]},{"p":10041,"q":"出三十六百千億光","notes":[{"by":"慧遠","era":"","t":"第二明前一一華中各出多佛，"},{"by":"釋璟興","era":"","t":"述云：此第六、寶化充滿。"}]},{"p":10093,"q":"如是諸佛各各","notes":[{"by":"釋璟興","era":"","t":"述云：此後、華光利物也。"},{"by":"慧遠","era":"","t":"已下，彰說利益。"}]},{"p":10154,"q":"皆悉","notes":[{"by":"釋璟興","era":"","t":"故、亦應有不定聚故。"}]},{"p":10229,"q":"願生彼國","notes":[{"by":"兩卷無量壽經宗要","era":"","t":"此一是願、前四是行，行願和合乃得生故。"},{"by":"釋璟興","era":"","t":"述云：此第二、釋中輩。"}]},{"p":10248,"q":"誹謗正法","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、舉諸佛歎令增物生去心也。"}]},{"p":10288,"q":"捨家棄欲而作沙門","notes":[{"by":"兩卷無量壽經宗要","era":"","t":"此顯發起正因方便。"}]},{"p":10337,"q":"現其人前","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、死有相顯也。"}]},{"p":10372,"q":"神通自在","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、生有獲益也。"}]},{"p":10476,"q":"多少修善","notes":[{"by":"兩卷無量壽經宗要","era":"","t":"此觀及行為助滿業。"}]},{"p":10550,"q":"即隨化佛往生其國","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、中有往趣也。"}]},{"p":10600,"q":"欲生彼國","notes":[{"by":"釋璟興","era":"","t":"述云：第三、釋下輩。"}]},{"p":10657,"q":"乃至一念念於彼佛","notes":[{"by":"兩卷無量壽經宗要","era":"","t":"是助滿業，為顯前人無深信故，必須十念；此人有深信故，未必具足十念。"}]},{"p":10675,"q":"此人臨終夢見彼佛","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、死有相現也。"}]},{"p":10801,"q":"亦復如是","notes":[{"by":"釋璟興","era":"","t":"述云：此後、勝聖共生也。"}]},{"p":10836,"q":"往覲無量覺","notes":[{"by":"釋璟興","era":"","t":"述云：此後、餘方往生也。"}]},{"p":10887,"q":"供養無量覺","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、供敬修福。"}]},{"p":10959,"q":"稽首無上尊","notes":[{"by":"釋璟興","era":"","t":"述云：此次、內業供敬也。"}]},{"p":10983,"q":"願我國亦然","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、見土欣求也。"}]},{"p":11019,"q":"三匝從頂入","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、頌聞法生智。"}]},{"p":11058,"q":"唯然願說意","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、觀音請說也。"}]},{"p":11084,"q":"今說仁諦聽","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、如來酬請。"}]},{"p":11108,"q":"受決當作佛","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、逐智行記成佛也。"}]},{"p":11132,"q":"必成如是剎","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、舉智願記獲土也。"}]},{"p":11206,"q":"疾得清淨處","notes":[{"by":"釋璟興","era":"","t":"述云：第二、頌諸佛歎。"}]},{"p":11230,"q":"受記成等覺","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、得通成覺歎。"}]},{"p":11255,"q":"自致不退轉","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、聞名不退歎。"}]},{"p":11303,"q":"還到安養國","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、逐願供佛歎也。"}]},{"p":11375,"q":"樂聽如是教","notes":[{"by":"釋璟興","era":"","t":"述云：此後、有惡不信聞。"}]},{"p":11423,"q":"唯佛獨明了","notes":[{"by":"釋璟興","era":"","t":"述云：第二、佛智難思。"}]},{"p":11471,"q":"如是致清淨","notes":[{"by":"釋璟興","era":"","t":"述云：此後、對諸聖智歎智深淨也。"}]},{"p":11519,"q":"是故","notes":[{"by":"釋璟興","era":"","t":"述云：此次、正勸發心也。"},{"by":"慧遠","era":"","t":"已下，結歎修習。"}]},{"p":11550,"q":"佛告阿難","notes":[{"by":"慧遠","era":"","t":"已下，重攝下人同生彼國；四"}]},{"p":11594,"q":"一切眾生","notes":[{"by":"釋璟興","era":"","t":"述云：第三、褒貶得失以勸凡小。"}]},{"p":11641,"q":"大千世界","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、光明殊妙。"}]},{"p":11715,"q":"具足","notes":[{"by":"慧遠","era":"","t":"是第四段，彰彼眾生智德殊勝。"},{"by":"釋璟興","era":"","t":"述云：此第三、身相備足也。"}]},{"p":11764,"q":"無生法忍","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、智德勝妙也。"}]},{"p":11804,"q":"如我國也","notes":[{"by":"釋璟興","era":"","t":"述云：此第如是四反，積地四寸也。"},{"by":"慧遠","era":"","t":"第六段，彰彼生者能興廣供。"}]},{"p":11847,"q":"隨心","notes":[{"by":"慧遠","era":"","t":"明諸供具隨心化現。"}]},{"p":11906,"q":"在虛空","notes":[{"by":"慧遠","era":"","t":"明於空中化成華蓋。"}]},{"p":11957,"q":"其諸菩薩","notes":[{"by":"慧遠","era":"","t":"明諸菩薩共奏天樂歌歎佛德。"}]},{"p":12056,"q":"莫不","notes":[{"by":"慧遠","era":"","t":"已下，明說利益，心解得道。"}]},{"p":12196,"q":"無違無失","notes":[{"by":"釋璟興","era":"","t":"述云：此第八、行德圓備。"}]},{"p":12215,"q":"無染著心","notes":[{"by":"釋璟興","era":"","t":"述曰：此第二、自行無失。"}]},{"p":12272,"q":"離蓋清淨","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、修忍行也。"}]},{"p":12290,"q":"定心","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、修定行也。"}]},{"p":12387,"q":"覺了法性","notes":[{"by":"釋璟興","era":"","t":"述云：此後、成化德。"}]},{"p":12423,"q":"煩惱之患","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、行修具足。"}]},{"p":12481,"q":"二餘俱盡","notes":[{"by":"釋璟興","era":"","t":"述云：此後、解行並修也。"}]},{"p":12513,"q":"究竟一乘","notes":[{"by":"慧遠","era":"","t":"成德殊勝；五"}]},{"p":12536,"q":"該羅無外","notes":[{"by":"釋璟興","era":"","t":"述云：此次、理教對也。"}]},{"p":12572,"q":"猶如雪山","notes":[{"by":"釋璟興","era":"","t":"述云：此後、定慧對也。"}]},{"p":12665,"q":"無染污故","notes":[{"by":"釋璟興","era":"","t":"述云：此後、別釋。"}]},{"p":12822,"q":"大慈等故","notes":[{"by":"釋璟興","era":"","t":"述云：第二、化德成。"},{"by":"慧遠","era":"","t":"行修增進；六"}]},{"p":12857,"q":"擊法鼓","notes":[{"by":"慧遠","era":"","t":"等，所說法勝。"}]},{"p":12873,"q":"修六和敬","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、行修增進。"}]},{"p":12939,"q":"滅三垢","notes":[{"by":"釋璟興","era":"","t":"述云：第二、勝進行修。"},{"by":"慧遠","era":"","t":"等，自行成也。"}]},{"p":12977,"q":"多聞之力","notes":[{"by":"慧遠","era":"","t":"為第五門，起行之解。"}]},{"p":13003,"q":"諸通明力","notes":[{"by":"釋璟興","era":"","t":"述云：此第六、諸力備足。"}]},{"p":13023,"q":"具足","notes":[{"by":"慧遠","era":"","t":"明德具足；言"}]},{"p":13050,"q":"無量諸佛","notes":[{"by":"釋璟興","era":"","t":"述云：此第七、諸德殊勝。"}]},{"p":13086,"q":"諸三昧門","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、行超二乘也。"}]},{"p":13135,"q":"不能窮盡","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、結歎也。"}]},{"p":13168,"q":"不可稱說","notes":[{"by":"釋璟興","era":"","t":"述云：此後、結土樂勝也。"},{"by":"慧遠","era":"","t":"牒前文中所辨之土。"}]},{"p":13246,"q":"昇道無窮極","notes":[{"by":"釋璟興","era":"","t":"述云：第二、正勸往生。"},{"by":"慧遠","era":"","t":"如來傷歎；三"}]},{"p":13303,"q":"不急之事","notes":[{"by":"釋璟興","era":"","t":"述云：第二、申娑婆穢惡令人厭捨。"}]},{"p":13370,"q":"為心走","notes":[{"by":"慧遠","era":"","t":"如是等事，別明其苦。"},{"by":"釋璟興","era":"","t":"述云：此後、別釋。"}]},{"p":13422,"q":"憂念愁怖","notes":[{"by":"釋璟興","era":"","t":"述云：此次、守護苦也。"}]},{"p":13477,"q":"適無縱捨","notes":[{"by":"釋璟興","era":"","t":"述云：此後、散失苦。"},{"by":"慧遠","era":"","t":"等，明失身苦。"}]},{"p":13495,"q":"莫誰隨者","notes":[{"by":"釋璟興","era":"","t":"述云：此後、失身苦也。"},{"by":"慧遠","era":"","t":"偏就富貴以明貪過；三"}]},{"p":13530,"q":"貧窮","notes":[{"by":"慧遠","era":"","t":"偏就貧賤以明貪過。"}]},{"p":13581,"q":"適有一","notes":[{"by":"慧遠","era":"","t":"少有事中明不足苦；三"}]},{"p":13598,"q":"適欲具","notes":[{"by":"慧遠","era":"","t":"已得事中明散失苦；四"}]},{"p":13645,"q":"亦結眾","notes":[{"by":"慧遠","era":"","t":"明追求時寒熱等苦。"}]},{"p":13659,"q":"終身夭命","notes":[{"by":"釋璟興","era":"","t":"述云：此後、據貧窮以示貪過。"}]},{"p":13693,"q":"莫能知者","notes":[{"by":"釋璟興","era":"","t":"述云：此後、顯後苦也。"}]},{"p":13824,"q":"更相報復","notes":[{"by":"釋璟興","era":"","t":"述云：第二、顯嗔過。"},{"by":"慧遠","era":"","t":"明有未來惡道之過；三"}]},{"p":13928,"q":"復得相值","notes":[{"by":"釋璟興","era":"","t":"述云：此次、別易會難也。"}]},{"p":13974,"q":"欲何樂乎","notes":[{"by":"釋璟興","era":"","t":"述云：此後、勸令脩捨也。"}]},{"p":14032,"q":"且自見","notes":[{"by":"釋璟興","era":"","t":"述云：第三、顯癡過。"}]},{"p":14047,"q":"轉相承受父餘教令","notes":[{"by":"慧遠","era":"","t":"明子無知受父邪言。"}]},{"p":14110,"q":"無一怪也","notes":[{"by":"釋璟興","era":"","t":"述云：此次、承習無信也。"}]},{"p":14162,"q":"教語","notes":[{"by":"慧遠","era":"","t":"已下，明難開曉，是以生死流轉無已，為之輪轉。"}]},{"p":14212,"q":"愛欲","notes":[{"by":"慧遠","era":"","t":"舉世五欲無常之過，勸人修捨。"}]},{"p":14251,"q":"哀哉","notes":[{"by":"釋璟興","era":"","t":"述云：此後、正申癡過。"},{"by":"慧遠","era":"","t":"如來傷歎，令人厭捨。"}]},{"p":14318,"q":"思想","notes":[{"by":"慧遠","era":"","t":"明由相憶不能修善；三"}]},{"p":14359,"q":"便旋","notes":[{"by":"慧遠","era":"","t":"由不修善不能得道。"}]},{"p":14372,"q":"無可奈何","notes":[{"by":"釋璟興","era":"","t":"述云：此後、對親戚以顯過。"},{"by":"慧遠","era":"","t":"明由癡故造惡受苦。"}]},{"p":14419,"q":"勤苦怱務","notes":[{"by":"釋璟興","era":"","t":"述云：此後、造惡受苦報。"},{"by":"慧遠","era":"","t":"癡故起瞋，共相殘害。"}]},{"p":14441,"q":"不從人心","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、起嗔殺害也。"},{"by":"慧遠","era":"","t":"明由前惡受苦難出。"}]},{"p":14491,"q":"無有出期","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、苦報難出也。"},{"by":"慧遠","era":"","t":"如來傷歎，令人生厭。"}]},{"p":14539,"q":"當熟思計遠離眾惡","notes":[{"by":"慧遠","era":"","t":"勸人捨過，謂離向前三毒眾惡。"}]},{"p":14575,"q":"曼佛在","notes":[{"by":"慧遠","era":"","t":"舉佛現在，勸人懃修。"}]},{"p":14596,"q":"智慧明","notes":[{"by":"慧遠","era":"","t":"已下，舉損誡約。"}]},{"p":14617,"q":"在人後也","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、勸人脩捨。"}]},{"p":14636,"q":"當為說之","notes":[{"by":"釋璟興","era":"","t":"述云：此後、勸令請問也。"}]},{"p":14676,"q":"如佛所言","notes":[{"by":"釋璟興","era":"","t":"述云：第二、領解。"}]},{"p":14723,"q":"解脫憂苦","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、領佛慈利也。"},{"by":"慧遠","era":"","t":"重嘆佛說為深為善。"}]},{"p":14752,"q":"莫不究暢","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、歎說深善也。"}]},{"p":14781,"q":"恩德普","notes":[{"by":"慧遠","era":"","t":"等，彰佛果也。"}]},{"p":14809,"q":"威制消","notes":[{"by":"慧遠","era":"","t":"等，以福化益。"}]},{"p":14845,"q":"皆令得道","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、重領佛恩也。"}]},{"p":14867,"q":"心得開明","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、申自喜慶也。"}]},{"p":14884,"q":"若有慈","notes":[{"by":"慧遠","era":"","t":"彰己化意，為化眾生，令離五惡五痛五燒，令持五善獲五福德。"}]},{"p":14901,"q":"乃復有佛","notes":[{"by":"釋璟興","era":"","t":"述云：此次、嘆領荷恩。"}]},{"p":14924,"q":"斷諸","notes":[{"by":"慧遠","era":"","t":"由佛現化，教諸眾生斷死因。"}]},{"p":14941,"q":"遊步","notes":[{"by":"慧遠","era":"","t":"彰已作佛，以法化世。"}]},{"p":14972,"q":"度未度","notes":[{"by":"慧遠","era":"","t":"佛化世，教諸眾生出生死果。"}]},{"p":15021,"q":"不可稱數","notes":[{"by":"釋璟興","era":"","t":"述云：此後、慶值佛聞法。"}]},{"p":15053,"q":"不可具言","notes":[{"by":"釋璟興","era":"","t":"述云：此次、標眾生本末也。"},{"by":"慧遠","era":"","t":"明今值佛聞無量壽；三"}]},{"p":15096,"q":"汝今亦可自厭","notes":[{"by":"慧遠","era":"","t":"已下，正勸修行；四"}]},{"p":15129,"q":"端身","notes":[{"by":"慧遠","era":"","t":"勸修善法；三"}]},{"p":15164,"q":"轉相拯","notes":[{"by":"慧遠","era":"","t":"積累善本，化人成善。"},{"by":"釋璟興","era":"","t":"述云：第二、勸修行。"}]},{"p":15189,"q":"後生","notes":[{"by":"慧遠","era":"","t":"已下，得益也。"}]},{"p":15215,"q":"無復貪","notes":[{"by":"慧遠","era":"","t":"等，長離煩惱。"}]},{"p":15261,"q":"汝等宜各精進","notes":[{"by":"慧遠","era":"","t":"已下，勸捨疑。"}]},{"p":15296,"q":"受諸厄也","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、勸捨疑惑也。"}]},{"p":15323,"q":"不敢有疑","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、彌勒領解也。"}]},{"p":15365,"q":"所以","notes":[{"by":"慧遠","era":"","t":"釋，先徵、後解。"}]},{"p":15388,"q":"易可開化","notes":[{"by":"釋璟興","era":"","t":"述云：第三、廣舉業苦令人厭捨。"}]},{"p":15402,"q":"處於五惡","notes":[{"by":"慧遠","era":"","t":"等，顯己化處。"}]},{"p":15424,"q":"令捨五","notes":[{"by":"慧遠","era":"","t":"等，明己化意，為化眾生，令有所出、令有所得。"},{"by":"釋璟興","era":"","t":"述云：第二、正申業苦而令厭捨。"}]},{"p":15448,"q":"獲其福","notes":[{"by":"慧遠","era":"","t":"由持五戒，於現在世身安無苦，翻前五痛。"}]},{"p":15477,"q":"何等五燒","notes":[{"by":"釋璟興","era":"","t":"述云：第二、別釋。"}]},{"p":15508,"q":"其一惡者","notes":[{"by":"慧遠","era":"","t":"總以樹舉，次辨、後法，下喻顯過。"}]},{"p":15635,"q":"積德所致","notes":[{"by":"釋璟興","era":"","t":"述云：第二、釋。"}]},{"p":15682,"q":"壽終","notes":[{"by":"慧遠","era":"","t":"已下，就殺明燒。"}]},{"p":15815,"q":"會當歸之","notes":[{"by":"釋璟興","era":"","t":"述云：此後、釋燒也。"}]},{"p":15832,"q":"勤苦如是","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、顯過也。"}]},{"p":15847,"q":"人能於中一心制","notes":[{"by":"慧遠","era":"","t":"等，正明作善，翻對前惡。"}]},{"p":15891,"q":"為一大善也","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、釋所持得也。"}]},{"p":15936,"q":"奢婬憍","notes":[{"by":"慧遠","era":"","t":"等，明其造惡。"}]},{"p":16087,"q":"破家","notes":[{"by":"慧遠","era":"","t":"已下，明造惡過。"}]},{"p":16224,"q":"欲為惡","notes":[{"by":"慧遠","era":"","t":"等，正明造惡。"}]},{"p":16265,"q":"事至乃悔","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、釋盜。"}]},{"p":16283,"q":"受其殃罰","notes":[{"by":"釋璟興","era":"","t":"述云：此次、釋痛也。"},{"by":"慧遠","era":"","t":"已下，第三明燒。"}]},{"p":16354,"q":"痛不可言","notes":[{"by":"釋璟興","era":"","t":"述云：此後、釋燒也。"}]},{"p":16371,"q":"勤苦如是","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、顯過也。"}]},{"p":16430,"q":"為二大善也","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、釋所持得也。"},{"by":"慧遠","era":"","t":"已下，明其化人滅惡離苦。"}]},{"p":16501,"q":"常懷邪","notes":[{"by":"慧遠","era":"","t":"正明造作邪婬之惡。"}]},{"p":16628,"q":"患而苦之","notes":[{"by":"釋璟興","era":"","t":"述：此第三、釋邪婬。"}]},{"p":16642,"q":"如是之惡著於","notes":[{"by":"慧遠","era":"","t":"燒惡中初明造惡之人。"}]},{"p":16690,"q":"痛不可言","notes":[{"by":"釋璟興","era":"","t":"述云：此後、釋燒也。"}]},{"p":16707,"q":"勤苦如是","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、顯過也。"}]},{"p":16766,"q":"為三大善也","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、釋所持得也。"}]},{"p":16786,"q":"不念修","notes":[{"by":"慧遠","era":"","t":"正明造作妄語之惡。"}]},{"p":16925,"q":"常懷憍","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、釋妄語。"}]},{"p":16980,"q":"無所復依","notes":[{"by":"釋璟興","era":"","t":"述云：此次、釋痛也。"}]},{"p":17297,"q":"飲食無度","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、釋飲酒。"}]},{"p":17460,"q":"願令其死","notes":[{"by":"釋璟興","era":"","t":"述云：此後、惡過也。"}]},{"p":17567,"q":"意不開解","notes":[{"by":"釋璟興","era":"","t":"述云：此次、釋痛也。"}]},{"p":17754,"q":"痛不可言","notes":[{"by":"釋璟興","era":"","t":"述云：此後、釋燒也。"}]},{"p":17771,"q":"勤苦如是","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、顯過也。"}]},{"p":17882,"q":"展轉相生","notes":[{"by":"釋璟興","era":"","t":"述云：第三、總釋。"}]},{"p":17928,"q":"示眾見之","notes":[{"by":"釋璟興","era":"","t":"述云：此後、別釋。"}]},{"p":17946,"q":"自相燋然","notes":[{"by":"釋璟興","era":"","t":"述云：此後、從燒生惡痛。"}]},{"p":18031,"q":"隨以磨滅","notes":[{"by":"釋璟興","era":"","t":"述云：此次、從燒生惡也。"}]},{"p":18077,"q":"痛哉可傷","notes":[{"by":"釋璟興","era":"","t":"述云：此後、從惡生痛也。"}]},{"p":18094,"q":"佛皆哀之","notes":[{"by":"釋璟興","era":"","t":"述云：第二、釋所持。"}]},{"p":18234,"q":"苦痛之道","notes":[{"by":"釋璟興","era":"","t":"述云：第四、勸人脩捨。"}]},{"p":18414,"q":"未甞寧息","notes":[{"by":"釋璟興","era":"","t":"述云：此後、對餘佛土歎勝令修也。"}]},{"p":18509,"q":"務修禮讓","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、舉現化益以勸修。"}]},{"p":18576,"q":"無為之安","notes":[{"by":"釋璟興","era":"","t":"述云：此後、滅惡離苦也。"}]},{"p":18622,"q":"略言之耳","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、以滅化損以勸修。"}]},{"p":18651,"q":"無得犯也","notes":[{"by":"釋璟興","era":"","t":"述云：此後、勸人使修也。"}]},{"p":18696,"q":"不敢違失","notes":[{"by":"釋璟興","era":"","t":"述云：此第二、彌勒領解也。"}]},{"p":18732,"q":"如來","notes":[{"by":"慧遠","era":"","t":"復為之具辨。"}]},{"p":18885,"q":"亦復如是","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、尋光備見彼土得失也。"}]},{"p":18904,"q":"唯見佛光","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、彼佛放光應請令見。"}]},{"p":18974,"q":"佛告","notes":[{"by":"慧遠","era":"","t":"已下，如來為辨。"}]},{"p":19110,"q":"彼國人民有胎生者，汝復見不","notes":[{"by":"慧遠","era":"","t":"阿難次答，彰己已見。"}]},{"p":19167,"q":"亦皆自然","notes":[{"by":"釋璟興","era":"","t":"述云：此後、顯彼土失令厭令捨。"}]},{"p":19188,"q":"何因何緣彼國人民胎生化生","notes":[{"by":"慧遠","era":"","t":"正辨胎生，約化顯之，為是通問；下佛答之。"},{"by":"釋璟興","era":"","t":"述云：此第二、對因顯果。"}]},{"p":19236,"q":"不可稱","notes":[{"by":"慧遠","era":"","t":"於諸法門，知之窮盡，名為"}]},{"p":19280,"q":"此諸眾生生彼","notes":[{"by":"慧遠","era":"","t":"已下，明因得果。"}]},{"p":19319,"q":"謂之胎生","notes":[{"by":"釋璟興","era":"","t":"唯總別違理，過同前解。"}]},{"p":19383,"q":"具足成就","notes":[{"by":"釋璟興","era":"","t":"述云：此後、兼答化生因果也。"}]},{"p":19455,"q":"智慧勝故","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、挍量顯劣。"}]},{"p":19527,"q":"疑惑所致","notes":[{"by":"釋璟興","era":"","t":"述云：此次、顯胎生之劣也。"}]},{"p":19623,"q":"樂彼處不","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、寄喻申過。"}]},{"p":19661,"q":"亦復如是","notes":[{"by":"釋璟興","era":"","t":"述云：此後、乘申餘方往生。"}]},{"p":19717,"q":"不樂彼處","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、如來申過也。"}]},{"p":19740,"q":"即得","notes":[{"by":"慧遠","era":"","t":"已下，明修得。"}]},{"p":19769,"q":"修諸功德","notes":[{"by":"釋璟興","era":"","t":"述云：第二、勸令脩捨。"}]},{"p":19802,"q":"無上智慧","notes":[{"by":"釋璟興","era":"","t":"述曰：此後、結勸修學也。"}]},{"p":19832,"q":"彼佛國","notes":[{"by":"釋璟興","era":"","t":"述云：第四、重申大菩薩往生西方增其往生之意。"}]},{"p":19898,"q":"皆當往生","notes":[{"by":"釋璟興","era":"","t":"述云：此次、別敘也。"}]},{"p":20287,"q":"佛語彌勒","notes":[{"by":"慧遠","era":"","t":"總舉餘國，明皆往生，甚多無量，不可具說。"}]},{"p":20365,"q":"略說之耳","notes":[{"by":"釋璟興","era":"","t":"述云：此後、類顯往生者多令增欣求之意也。"},{"by":"吉藏","era":"","t":"經流通文也。"}]},{"p":20414,"q":"是故","notes":[{"by":"慧遠","era":"","t":"是此經法有多益故、於中修學最難得故，我今宣說。"},{"by":"吉藏","era":"","t":"勸重法不辭眾苦。"}]},{"p":20458,"q":"所以者何","notes":[{"by":"吉藏","era":"","t":"次句，舉佛真本，以釋定慧究暢無極，故能隨物情所宜，長短自在而無礙也。"}]},{"p":20476,"q":"若有眾生聞此經","notes":[{"by":"慧遠","era":"","t":"明聞此經得益廣大，勸人受行。"}]},{"p":20502,"q":"持誦說行","notes":[{"by":"釋璟興","era":"","t":"述云：第三、聞說喜行分。"}]},{"p":20542,"q":"無得","notes":[{"by":"慧遠","era":"","t":"彰此經法濟益之要，獨留百歲；四"},{"by":"釋璟興","era":"","t":"述云：此第二、勸物除疑也。"},{"by":"吉藏","era":"","t":"以下，重誡勅勸斷疑惑也。"}]},{"p":20592,"q":"皆可得度","notes":[{"by":"吉藏","era":"","t":"舉眾難，欲彰此法難聞，勸生敬仰，受持不忘；第四從"},{"by":"釋璟興","era":"","t":"述云：此第三、歎經普濟也。"}]},{"p":20622,"q":"菩薩勝","notes":[{"by":"慧遠","era":"","t":"明其行法聞之甚難。"}]},{"p":20649,"q":"若聞斯經信樂受","notes":[{"by":"慧遠","era":"","t":"等，難中之難。"}]},{"p":20662,"q":"無過此難","notes":[{"by":"慧遠","era":"","t":"此經宣說彌陀如來修願修行得身得土，名如是作。"},{"by":"釋璟興","era":"","t":"述云：此第四、歎聞而令敬重也。"},{"by":"吉藏","era":"","t":"明其如聞而傳，無有差謬。"}]},{"p":20689,"q":"如法修行","notes":[{"by":"釋璟興","era":"","t":"述云：此第五、結勸修學也。"}]},{"p":20713,"q":"正覺之心","notes":[{"by":"釋璟興","era":"","t":"述云：第二、彰說利益。"}]},{"p":20747,"q":"比丘","notes":[{"by":"吉藏","era":"","t":"三義，如常聞，數有萬二千人。"},{"by":"釋璟興","era":"","t":"述云：此次、聲聞益也。"}]},{"p":20778,"q":"當成正覺","notes":[{"by":"釋璟興","era":"","t":"述云：此後、菩薩利也。"}]},{"p":20810,"q":"自然","notes":[{"by":"釋璟興","era":"","t":"述云：此第三、示相令信也。"},{"by":"吉藏","era":"","t":"後明奉行方也。"}]},{"p":20861,"q":"靡不歡喜","notes":[{"by":"釋璟興","era":"","t":"述云：此第四、大眾喜行也。"}]}]},{"base":"T0365","name":"T0365《佛說觀無量壽佛經》","path":"01-大正藏/16淨土宗部類/T0365《佛說觀無量壽佛經》.md","loci":[{"p":156,"q":"如是","notes":[{"by":"釋慧遠","era":"","t":"人解多種，今正論之，解有兩義：一、約法解；二、約人解。"}]},{"p":507,"q":"我聞","notes":[{"by":"釋慧遠","era":"","t":"已下，義雖兩兼，對前一向證信序故，自下偏就發起以釋。"},{"by":"胡吉藏","era":"","t":"即第四事，誰邊聞？"}]},{"p":526,"q":"比丘","notes":[{"by":"釋慧遠","era":"","t":"胡語，此方義翻備含五義：一名怖魔。"}]},{"p":556,"q":"爾時王舍大城","notes":[{"by":"釋慧遠","era":"","t":"明禁父緣，事如經說。"}]},{"p":572,"q":"隨順調達惡友之教","notes":[{"by":"胡吉藏","era":"","t":"其與調達為親友，常說世王。"}]},{"p":609,"q":"國大夫人","notes":[{"by":"胡吉藏","era":"","t":"此明王得食得法不死因緣。"}]},{"p":778,"q":"時阿闍世問守門","notes":[{"by":"釋慧遠","era":"","t":"明韋提希為子禁閉，如來自身往彼攝化。"}]},{"p":857,"q":"聞此語","notes":[{"by":"釋慧遠","era":"","t":"聞前耆婆重勸之辭。"}]},{"p":981,"q":"王今","notes":[{"by":"釋慧遠","era":"","t":"已下，明今異昔。"}]},{"p":1043,"q":"告耆婆","notes":[{"by":"釋慧遠","era":"","t":"是第三段耆婆重勸。"}]},{"p":1091,"q":"勅語","notes":[{"by":"釋慧遠","era":"","t":"已下，是第三段，明阿闍世餘瞋禁母。"}]},{"p":1108,"q":"時韋提希被幽閉","notes":[{"by":"釋慧遠","era":"","t":"等，身業禮也，禮即身請。"},{"by":"胡吉藏","era":"","t":"此文猶屬別序。"}]},{"p":1173,"q":"願遣","notes":[{"by":"釋慧遠","era":"","t":"已下，請遣弟子與己相見。"}]},{"p":1204,"q":"未舉頭","notes":[{"by":"釋慧遠","era":"","t":"佛與弟子因請赴就；四、"},{"by":"胡吉藏","era":"","t":"第二、總答。"}]},{"p":1266,"q":"見世尊","notes":[{"by":"釋慧遠","era":"","t":"等，正明所見。"}]},{"p":1316,"q":"時韋提希見佛世尊","notes":[{"by":"胡吉藏","era":"","t":"三段，初章竟。"}]},{"p":1395,"q":"不樂閻浮提","notes":[{"by":"胡吉藏","era":"","t":"明厭穢欣淨，願欲往生也。"},{"by":"釋慧遠","era":"","t":"別明所厭，還明前二。"}]},{"p":1421,"q":"多不善聚","notes":[{"by":"釋慧遠","era":"","t":"顯前不樂濁惡世也。"}]},{"p":1440,"q":"今向世尊五體投地","notes":[{"by":"釋慧遠","era":"","t":"如來眉間有一毫毛，白如珂雪，其長一丈五尺五寸之圍，其間空中，如瑠璃筒宛轉右旋。"},{"by":"胡吉藏","era":"","t":"前明離穢生淨，今辨離穢生淨之因。"}]},{"p":1587,"q":"時韋提希白佛言","notes":[{"by":"胡吉藏","era":"","t":"第六、韋提希重問。"}]},{"p":1674,"q":"爾時大王雖在幽閉","notes":[{"by":"胡吉藏","era":"","t":"第二、父王得益，如文。"}]},{"p":1708,"q":"爾時世尊告韋提希","notes":[{"by":"胡吉藏","era":"","t":"第二、運說法輪利益夫人。"}]},{"p":1732,"q":"汝當繫","notes":[{"by":"釋慧遠","era":"","t":"是後九觀，觀別如是。"}]},{"p":1746,"q":"我今為汝廣說眾譬，亦令未來世一切","notes":[{"by":"善導集","era":"","t":"者，是其一證也。"}]},{"p":1816,"q":"受持三歸","notes":[{"by":"釋慧遠","era":"","t":"在家戒也，此亦即是沙彌十戒。"}]},{"p":1854,"q":"如此三事名為淨業","notes":[{"by":"胡吉藏","era":"","t":"第七、重告韋提希。"}]},{"p":1901,"q":"佛告阿難","notes":[{"by":"胡吉藏","era":"","t":"前明三種善為淨土因有二：第一、緣起；第二、正明三種善為淨土因。"},{"by":"釋慧遠","era":"","t":"教其修習十六正觀，定善往生。"}]},{"p":1922,"q":"如來今","notes":[{"by":"釋慧遠","era":"","t":"佛自彰己所說有益；五、"}]},{"p":1949,"q":"善哉","notes":[{"by":"釋慧遠","era":"","t":"別對韋提嘆前快問；三、"},{"by":"胡吉藏","era":"","t":"第三、歎問。"}]},{"p":1982,"q":"教韋提","notes":[{"by":"釋慧遠","era":"","t":"等，舉所教者。"}]},{"p":2040,"q":"應時","notes":[{"by":"釋慧遠","era":"","t":"由見心喜，得無生忍。"}]},{"p":2067,"q":"未得天眼","notes":[{"by":"釋慧遠","era":"","t":"明目不能遠見彼國。"}]},{"p":2133,"q":"五苦","notes":[{"by":"胡吉藏","era":"","t":"此如《無量壽經》五痛、五燒，如彼文出。"}]},{"p":2178,"q":"云何作想","notes":[{"by":"胡吉藏","era":"","t":"第二、正作無量壽觀。"}]},{"p":2287,"q":"佛告阿難及韋提希","notes":[{"by":"胡吉藏","era":"","t":"第二、觀觀世音菩薩身，如文。"}]},{"p":2353,"q":"此想成","notes":[{"by":"釋慧遠","era":"","t":"顯其成相；四、"}]},{"p":2554,"q":"是為","notes":[{"by":"釋慧遠","era":"","t":"結；四、辨觀邪正。"}]},{"p":2599,"q":"作此觀者","notes":[{"by":"胡吉藏","era":"","t":"第三、明觀之功用。"}]},{"p":2622,"q":"阿難","notes":[{"by":"釋慧遠","era":"","t":"辨明此坐得成所由，謂法藏願力故成；四、"}]},{"p":2705,"q":"若觀","notes":[{"by":"釋慧遠","era":"","t":"明觀利益；五、"}]},{"p":2794,"q":"一一樹","notes":[{"by":"釋慧遠","era":"","t":"明其廣觀，觀諸樹下皆有一佛二菩薩像；四、"}]},{"p":4224,"q":"心想佛時，是心即是三十二相","notes":[{"by":"釋元照","era":"","t":"等，即《彌陀經》云"}]},{"p":4439,"q":"菩薩","notes":[{"by":"釋元照","era":"","t":"梵云摩訶菩提質帝薩埵，此云大道心成眾生。"}]},{"p":4667,"q":"韋提","notes":[{"by":"釋元照","era":"","t":"翹誠請佛；三、"}]},{"p":4715,"q":"佛身高","notes":[{"by":"釋慧遠","era":"","t":"觀其大小、三、"},{"by":"釋元照","era":"","t":"即淨土應身也。"}]},{"p":4877,"q":"念佛眾生攝取不捨","notes":[{"by":"釋慧遠","era":"","t":"已下，總以結勸。"}]},{"p":4900,"q":"但當憶","notes":[{"by":"釋慧遠","era":"","t":"等，是勸辭也。"}]},{"p":4957,"q":"佛心者大慈悲","notes":[{"by":"釋慧遠","era":"","t":"辨佛心相，謂無緣慈普攝眾生。"}]},{"p":4994,"q":"是故智","notes":[{"by":"釋慧遠","era":"","t":"是第三段，結勸觀察。"}]},{"p":5119,"q":"佛告","notes":[{"by":"釋慧遠","era":"","t":"明觀利益；五、"}]},{"p":5150,"q":"此菩薩","notes":[{"by":"釋慧遠","era":"","t":"廣顯觀相；三、"}]},{"p":5339,"q":"現自在滿十方界","notes":[{"by":"釋慧遠","era":"","t":"觀瓔珞及手足等，文皆可知。"}]},{"p":5495,"q":"其餘","notes":[{"by":"釋慧遠","era":"","t":"并舉餘相，指同前佛。"}]},{"p":5579,"q":"除無數","notes":[{"by":"釋慧遠","era":"","t":"明觀利益；五、"}]},{"p":5608,"q":"若有","notes":[{"by":"釋慧遠","era":"","t":"重顯觀儀；六、"}]},{"p":5770,"q":"是故","notes":[{"by":"釋慧遠","era":"","t":"明光利益，明照眾生，令離三塗，得佛上力。"}]},{"p":5902,"q":"行時","notes":[{"by":"釋慧遠","era":"","t":"觀其行相；七、"}]},{"p":6093,"q":"此觀成","notes":[{"by":"釋慧遠","era":"","t":"總結觀音及大勢至二觀成義。"}]},{"p":6142,"q":"見此","notes":[{"by":"釋慧遠","era":"","t":"彰成分齊；四、總結之；五、明觀益，化佛菩薩恒至其所。"}]},{"p":6204,"q":"見佛","notes":[{"by":"釋慧遠","era":"","t":"已下，生已得益。"}]},{"p":6233,"q":"與十二","notes":[{"by":"釋慧遠","era":"","t":"明其觀儀；三、"}]},{"p":6357,"q":"如先","notes":[{"by":"釋慧遠","era":"","t":"辨明須教觀像所以。"}]},{"p":6380,"q":"然彼","notes":[{"by":"釋慧遠","era":"","t":"明諸凡夫觀者必成，生人學意。"}]},{"p":6398,"q":"但想","notes":[{"by":"釋慧遠","era":"","t":"明觀多益，勸人觀察。"}]},{"p":6416,"q":"阿彌陀","notes":[{"by":"釋慧遠","era":"","t":"明其所觀若大若小皆是佛身，拂去眾疑生人重意。"}]},{"p":6434,"q":"或現大身滿虛空中","notes":[{"by":"釋元照","era":"","t":"舉此證前，知無限量。"}]},{"p":6452,"q":"所現","notes":[{"by":"釋慧遠","era":"","t":"明其所現大小雖殊，色身相好與前不異，遮人異觀。"}]},{"p":6494,"q":"但觀","notes":[{"by":"釋慧遠","era":"","t":"已下，教人別之，但觀首相，即知二別。"}]},{"p":6511,"q":"此二菩薩助阿彌陀","notes":[{"by":"釋慧遠","era":"","t":"彰此二菩薩助化多益，令人必觀。"}]},{"p":6604,"q":"何等","notes":[{"by":"釋慧遠","era":"","t":"問也，下對辨之。"}]},{"p":6619,"q":"深心","notes":[{"by":"釋慧遠","era":"","t":"慇至心也，起行慇至名曰深心，求去慇至亦曰深心。"}]},{"p":7013,"q":"行此","notes":[{"by":"釋慧遠","era":"","t":"明目連等聞法歡喜。"}]}]},{"base":"T0353","name":"T0353《勝鬘師子吼一乘大方便方廣經》","path":"01-大正藏/06寶積部類/T0353《勝鬘師子吼一乘大方便方廣經》.md","loci":[{"p":35,"q":"如是我聞","notes":[{"by":"勝鬘寶窟","era":"","t":"已下可具二義：若阿難後之所立，屬傳經序；當佛說時實有化主時處，屬說經序。"}]},{"p":71,"q":"共相謂言","notes":[{"by":"勝鬘寶窟","era":"","t":"上敘其內德，今第三明外值勝緣。"}]},{"p":133,"q":"王及夫人與勝鬘書","notes":[{"by":"勝鬘寶窟","era":"","t":"就理釋者，書中詮明佛德，發以大乘之信，是冥相關，有逾常意趣，是故歡喜。"}]},{"p":198,"q":"向旃提羅","notes":[{"by":"勝鬘寶窟","era":"","t":"一解云：佛必如書中讚歎真實不虛者，則是無上福田，理合供養也。"}]},{"p":293,"q":"咸以清淨心","notes":[{"by":"勝鬘寶窟","era":"","t":"上雖五歎，恐物有盡極，未必能一切處一切時常應，是故今明能應物無盡。"}]},{"p":384,"q":"智慧身自在","notes":[{"by":"勝鬘寶窟","era":"","t":"明我過去已生善、現生善、當生善，攝此三善，一者令莫向三有、二者令莫向二乘、三者令莫取相。"}]},{"p":518,"q":"佛於眾中","notes":[{"by":"勝鬘寶窟","era":"","t":"第四許攝受，即是與護事。"}]},{"p":588,"q":"過二萬","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，第二得遠果。"}]},{"p":612,"q":"彼佛國土","notes":[{"by":"勝鬘寶窟","era":"","t":"前明無人天內苦，今明無人天外違緣不適意苦也。"}]},{"p":659,"q":"勝於他化自在諸天","notes":[{"by":"勝鬘寶窟","era":"","t":"上來明有淨果，今辨有淨因，即翻上亦無不善惡業道等。"}]},{"p":714,"q":"世尊悉記","notes":[{"by":"勝鬘寶窟","era":"","t":"第二明佛如願與記。"}]},{"p":738,"q":"恭敬而立","notes":[{"by":"勝鬘寶窟","era":"","t":"若從來已曾受五戒八戒等，今於佛前自誓於所受戒不起犯心。"}]},{"p":883,"q":"凡有所受","notes":[{"by":"勝鬘寶窟","era":"","t":"第二明為救眾生。"}]},{"p":918,"q":"為一切眾生","notes":[{"by":"勝鬘寶窟","era":"","t":"從今時至後際常行四攝，故無厭足也。"}]},{"p":977,"q":"終不暫捨","notes":[{"by":"勝鬘寶窟","era":"","t":"上來敘苦，今欲拔苦。"}]},{"p":1031,"q":"我得力時","notes":[{"by":"勝鬘寶窟","era":"","t":"第二廣明不捨，即是正斷惡因也。"}]},{"p":1063,"q":"何以故","notes":[{"by":"勝鬘寶窟","era":"","t":"第三釋折伏攝受之意。"}]},{"p":1095,"q":"於如來所轉法輪","notes":[{"by":"勝鬘寶窟","era":"","t":"佛今已解化於前人，前人依佛教修行，亦得見苦斷集證滅修道，故言隨轉也。"}]},{"p":1129,"q":"攝受正法終不忘失","notes":[{"by":"勝鬘寶窟","era":"","t":"有人言：正法者，即六度行也。"}]},{"p":1161,"q":"忘波羅蜜者則不欲大乘","notes":[{"by":"勝鬘寶窟","era":"","t":"上辨明忘正法故退聖，此明忘正法故不得越凡。"}]},{"p":1250,"q":"唯佛世尊","notes":[{"by":"勝鬘寶窟","era":"","t":"疑既在心，或當起謗，則未來受苦，故云不得安樂也。"}]},{"p":1407,"q":"勝鬘","notes":[{"by":"勝鬘寶窟","era":"","t":"明佛記其所願也。"}]},{"p":1438,"q":"爾時勝鬘","notes":[{"by":"勝鬘寶窟","era":"","t":"十五章二章已竟，今第三次明三大願章，可作七門釋之。"}]},{"p":1470,"q":"以此善根於一切生得正法智","notes":[{"by":"勝鬘寶窟","era":"","t":"未來一切受生身也。"}]},{"p":1515,"q":"攝受正法","notes":[{"by":"勝鬘寶窟","era":"","t":"上明捨身命財，求所離欲。"}]},{"p":1575,"q":"此三大願","notes":[{"by":"勝鬘寶窟","era":"","t":"第四如來歎印。"}]},{"p":1598,"q":"勝鬘白佛","notes":[{"by":"勝鬘寶窟","era":"","t":"夫弟子說法，大聖在座，要假佛威神方乃得說；不蒙教輒爾而言，即是慢相，故言當承佛力說也。"}]},{"p":1685,"q":"善哉","notes":[{"by":"勝鬘寶窟","era":"","t":"良由勝鬘所說，一合理、二稱機，故重言善哉也。"}]},{"p":1725,"q":"汝之所說","notes":[{"by":"勝鬘寶窟","era":"","t":"第二明說同諸佛，引己為證。"}]},{"p":1772,"q":"如是我說","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一歎能說合理稱機，此第二歎所說正法功德無邊。"}]},{"p":1802,"q":"何以故","notes":[{"by":"勝鬘寶窟","era":"","t":"第二釋上如來辨慧無邊及功德無邊也。"}]},{"p":1828,"q":"我當承佛神力","notes":[{"by":"勝鬘寶窟","era":"","t":"攝受正法，位窮佛地，唯佛能說。"}]},{"p":1877,"q":"得一切佛法","notes":[{"by":"勝鬘寶窟","era":"","t":"所以舉劫初大雲大雨者，雲雨之大莫過劫初，故借此大雲大雨以喻攝受正法之廣大也。"}]},{"p":1943,"q":"有大水聚","notes":[{"by":"勝鬘寶窟","era":"","t":"劫初成時有持水風令水不散，有消水風令水漸盡以成世界。"}]},{"p":2017,"q":"乃至天人","notes":[{"by":"勝鬘寶窟","era":"","t":"別出四名：一者無價，喻於菩薩；二者上價，喻於緣覺；三中價，喻聲聞；四下價，喻人天。"}]},{"p":2104,"q":"離善知識","notes":[{"by":"勝鬘寶窟","era":"","t":"授與福分善根，令修福捨罪，後生善處，漸得入道，故言"}]},{"p":2153,"q":"是名","notes":[{"by":"勝鬘寶窟","era":"","t":"第三結具戒行名波羅蜜。"}]},{"p":2208,"q":"普為眾生作不請之友","notes":[{"by":"勝鬘寶窟","era":"","t":"前歎菩薩為物之友，今歎菩薩能生四乘善根，名之為母。"}]},{"p":2268,"q":"是名","notes":[{"by":"勝鬘寶窟","era":"","t":"第三結成忍度也。"}]},{"p":2419,"q":"攝受正法者","notes":[{"by":"勝鬘寶窟","era":"","t":"此明攝受即正法，謂智不異境。"}]},{"p":2449,"q":"無異波羅蜜","notes":[{"by":"勝鬘寶窟","era":"","t":"明攝受正法不異波羅蜜。"}]},{"p":2472,"q":"何以故","notes":[{"by":"勝鬘寶窟","era":"","t":"別約六度釋無異；今第三總結無異也。"}]},{"p":2498,"q":"乃至","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一明菩薩持戒，今第二明使他行戒，具以如上說。"}]},{"p":2524,"q":"是名檀波羅蜜","notes":[{"by":"勝鬘寶窟","era":"","t":"菩薩持戒有始有終，守護六根是其始也，淨身口意戒行成就。"}]},{"p":2593,"q":"若彼眾生","notes":[{"by":"勝鬘寶窟","era":"","t":"第二明菩薩行忍亦二：初明行忍、二為成就眾生也。"}]},{"p":2614,"q":"饒益心","notes":[{"by":"勝鬘寶窟","era":"","t":"非但無嗔，菩薩見打罵時，即於前人起饒益心。"}]},{"p":2666,"q":"於彼眾生不起懈心","notes":[{"by":"勝鬘寶窟","era":"","t":"上明離過，今辨習德。"}]},{"p":2742,"q":"第一正念","notes":[{"by":"勝鬘寶窟","era":"","t":"明定心恒憶，久時身口業不忘也。"}]},{"p":2798,"q":"彼諸眾生問一切義","notes":[{"by":"勝鬘寶窟","era":"","t":"世辨論、隨世論、圍陀論、毘伽羅論、衛世師論。"}]},{"p":2907,"q":"更說大義","notes":[{"by":"勝鬘寶窟","era":"","t":"上明理大行大，今更說果大。"}]},{"p":2944,"q":"無異攝受正法者","notes":[{"by":"勝鬘寶窟","era":"","t":"上明攝受，今第二明正法，正法即是常身命財。"}]},{"p":2997,"q":"何等為三","notes":[{"by":"勝鬘寶窟","era":"","t":"第二列出三名。"}]},{"p":3020,"q":"生死後際等","notes":[{"by":"勝鬘寶窟","era":"","t":"北土人有二釋：一云生死是前際、涅槃為後際，而言等者，生死涅槃於事不齊、於理則等。"}]},{"p":3080,"q":"通達","notes":[{"by":"勝鬘寶窟","era":"","t":"第三顯所得體，即以功德為財也。"}]},{"p":3156,"q":"常為","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，正明稱歎。"}]},{"p":3191,"q":"法欲滅","notes":[{"by":"勝鬘寶窟","era":"","t":"此翻為善宿男。"}]},{"p":3276,"q":"佛為實眼","notes":[{"by":"勝鬘寶窟","era":"","t":"如此護法之人，化功淵曠，下地不測，唯佛照之分明，故言佛為實眼。"}]},{"p":3347,"q":"如大力士","notes":[{"by":"勝鬘寶窟","era":"","t":"第二稱歎勸修。"}]},{"p":3377,"q":"我不見","notes":[{"by":"勝鬘寶窟","era":"","t":"第三對餘善歎。"}]},{"p":3396,"q":"又如牛王","notes":[{"by":"勝鬘寶窟","era":"","t":"第二舉牛王對二乘歎，明述成意。"}]},{"p":3460,"q":"以攝取心攝受正法","notes":[{"by":"勝鬘寶窟","era":"","t":"合前譬中端嚴殊特。"}]},{"p":3508,"q":"開示","notes":[{"by":"勝鬘寶窟","era":"","t":"即上理正法出生四乘名為大利。"}]},{"p":3598,"q":"佛告勝鬘","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一略釋歸怖，今第二廣釋歸怖。"}]},{"p":3656,"q":"何以故","notes":[{"by":"勝鬘寶窟","era":"","t":"第二釋章門，為二：初略釋、次廣釋。"}]},{"p":3773,"q":"住於大乘","notes":[{"by":"勝鬘寶窟","era":"","t":"大外無別小，小乘即是大乘麁近之法，故云即是住於二乘攝受二乘。"}]},{"p":3805,"q":"如世尊說六處","notes":[{"by":"勝鬘寶窟","era":"","t":"自上已來名為略說，從此已去第二廣說。"}]},{"p":3843,"q":"為大乘故說此六處","notes":[{"by":"勝鬘寶窟","era":"","t":"上來明四智不圓、涅槃未滿，此下第二解釋二乘不得所以。"}]},{"p":3936,"q":"是故說大乘威儀","notes":[{"by":"勝鬘寶窟","era":"","t":"第四總結也。"}]},{"p":3957,"q":"是故阿羅漢","notes":[{"by":"勝鬘寶窟","era":"","t":"第二句，顯二乘不得涅槃所以也。"}]},{"p":3986,"q":"阿羅漢歸依於佛","notes":[{"by":"勝鬘寶窟","era":"","t":"羅漢有三界內治道之智，名之為行，斷三界煩惱盡，無有三界內分段生死，於三界內無有怖畏，是故昔日說羅漢無怖畏。"}]},{"p":4111,"q":"有餘","notes":[{"by":"勝鬘寶窟","era":"","t":"明義不盡，對盡理之說。"}]},{"p":4154,"q":"以不斷故","notes":[{"by":"勝鬘寶窟","era":"","t":"第四對，且有三句：一明佛得、次明二乘不得、第三會教。"}]},{"p":4192,"q":"阿羅漢","notes":[{"by":"勝鬘寶窟","era":"","t":"此第四明不受後有智以為方便。"}]},{"p":4208,"q":"言得涅槃者","notes":[{"by":"勝鬘寶窟","era":"","t":"第三會昔教也。"}]},{"p":4228,"q":"成就無量功德","notes":[{"by":"勝鬘寶窟","era":"","t":"釋成佛得所以。"}]},{"p":4377,"q":"瞻仰","notes":[{"by":"勝鬘寶窟","era":"","t":"降金剛已還是眾生位，如來居宗體極，道出三乘十地行外，為三乘十地眾生之所瞻仰也。"}]},{"p":4418,"q":"觀察解脫四智究竟","notes":[{"by":"勝鬘寶窟","era":"","t":"第二得涅槃究竟，離分段死，故名為蘇。"}]},{"p":4506,"q":"意生身","notes":[{"by":"勝鬘寶窟","era":"","t":"是初地已上一切菩薩，彼人受生無礙自在，如心如意，名意受生。"}]},{"p":4616,"q":"非盡","notes":[{"by":"勝鬘寶窟","era":"","t":"是第一門，謂不斷集體，集體即是煩惱體。"}]},{"p":4659,"q":"煩惱有二種","notes":[{"by":"勝鬘寶窟","era":"","t":"廣明非盡一切煩惱。"}]},{"p":4694,"q":"見一處住地","notes":[{"by":"勝鬘寶窟","era":"","t":"能生名地，令所生成立名住，心迷不解名惑，八忍七智推求諦理名見。"}]},{"p":4728,"q":"起者剎那心剎那相應","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，別彰無明；三"}]},{"p":4788,"q":"如是無明住地","notes":[{"by":"勝鬘寶窟","era":"","t":"對劣顯勝，初法、次喻、後合。"}]},{"p":4896,"q":"唯如來","notes":[{"by":"勝鬘寶窟","era":"","t":"明佛能斷；三結無明其力最大。"}]},{"p":4925,"q":"又如取","notes":[{"by":"勝鬘寶窟","era":"","t":"廣明非盡一切受生。"}]},{"p":4971,"q":"此三地","notes":[{"by":"勝鬘寶窟","era":"","t":"此世間中三乘地，謂阿羅漢、辟支佛、大力菩薩，是三乘地。"}]},{"p":5051,"q":"佛地所斷","notes":[{"by":"勝鬘寶窟","era":"","t":"第二舉佛能盡，顯其異相。"}]},{"p":5081,"q":"無漏不盡","notes":[{"by":"勝鬘寶窟","era":"","t":"顯不得無礙道正斷自在力也。"}]},{"p":5148,"q":"以不知見故","notes":[{"by":"勝鬘寶窟","era":"","t":"顯不能證見，故不能除障。"}]},{"p":5211,"q":"以成就","notes":[{"by":"勝鬘寶窟","era":"","t":"知諦有餘；四"}]},{"p":5251,"q":"名得少分","notes":[{"by":"勝鬘寶窟","era":"","t":"得涅槃有餘。"}]},{"p":5271,"q":"若知一切苦","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一明小乘不得四智，此下明佛得四智。"}]},{"p":5292,"q":"於無常壞世間","notes":[{"by":"勝鬘寶窟","era":"","t":"明涅槃無餘；三"}]},{"p":5312,"q":"無覆護世間","notes":[{"by":"勝鬘寶窟","era":"","t":"分段世間也，離佛更無餘人覆護。"}]},{"p":5413,"q":"無明住地不斷","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，用後釋前。"}]},{"p":5468,"q":"是故無明住地","notes":[{"by":"勝鬘寶窟","era":"","t":"顯無明生一切煩惱、障一切佛法。"}]},{"p":5560,"q":"如來","notes":[{"by":"勝鬘寶窟","era":"","t":"正明佛得四智。"}]},{"p":5779,"q":"一切知見","notes":[{"by":"勝鬘寶窟","era":"","t":"第二明得三事。"}]},{"p":5796,"q":"法王","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，得解脫也。"}]},{"p":5872,"q":"不受後有智有二","notes":[{"by":"勝鬘寶窟","era":"","t":"總牒大小二種四智。"}]},{"p":6003,"q":"作是念","notes":[{"by":"勝鬘寶窟","era":"","t":"是四智相出觀有中，緣己所得生究竟想，故言作是念。"}]},{"p":6092,"q":"何以故","notes":[{"by":"勝鬘寶窟","era":"","t":"第二問答辨釋。"}]},{"p":6115,"q":"是故","notes":[{"by":"勝鬘寶窟","era":"","t":"第四明一乘並攝眾德，顯所入者是究竟。"}]},{"p":6166,"q":"得究竟法身","notes":[{"by":"勝鬘寶窟","era":"","t":"第三還復宗結法身即一乘也。"}]},{"p":6221,"q":"如來無有限齊時住","notes":[{"by":"勝鬘寶窟","era":"","t":"明時有二種：一有限時，日月歲等；二無限時，猶如虛空。"}]},{"p":6243,"q":"如來無限齊大悲","notes":[{"by":"勝鬘寶窟","era":"","t":"顯於自德義善同前，故言是名善說。"}]},{"p":6325,"q":"與後際","notes":[{"by":"勝鬘寶窟","era":"","t":"盡未來際為物作歸依也。"}]},{"p":6354,"q":"法者即是說一乘道","notes":[{"by":"勝鬘寶窟","era":"","t":"略明不真，非是真歸，故非究竟；但是權歸，故名少分。"}]},{"p":6402,"q":"於上更無說一乘法","notes":[{"by":"勝鬘寶窟","era":"","t":"於究竟法身上也。"}]},{"p":6455,"q":"若有眾生","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一當相顯二歸依非究竟，今第二約能歸顯所歸非究竟。"}]},{"p":6484,"q":"是二歸依","notes":[{"by":"勝鬘寶窟","era":"","t":"牒所歸彰未即佛果，故顯非究竟二歸也。"}]},{"p":6501,"q":"歸依第一義者是歸依如來","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一明不究竟歸依，今第二明究竟歸依。"}]},{"p":6572,"q":"若如來","notes":[{"by":"勝鬘寶窟","era":"","t":"是攝末歸本法輪也。"}]},{"p":6627,"q":"初觀聖諦","notes":[{"by":"勝鬘寶窟","era":"","t":"明二乘人，單用初一有作諦智斷四住地，不用無作斷無明地，故名一智。"}]},{"p":6726,"q":"初聖諦智","notes":[{"by":"勝鬘寶窟","era":"","t":"二乘但得一有作智，斷四住地；不得第二無作智，故不滅無明。"}]},{"p":6789,"q":"若壞一切煩惱藏","notes":[{"by":"勝鬘寶窟","era":"","t":"一對，顯究竟不究竟。"}]},{"p":6832,"q":"聖義","notes":[{"by":"勝鬘寶窟","era":"","t":"總以標舉窮極大聖義也，即是明佛有聖義也。"}]},{"p":6852,"q":"有量功德","notes":[{"by":"勝鬘寶窟","era":"","t":"有三界內治道斷四住煩惱盡所得無為，名有量功德。"}]},{"p":6875,"q":"聖諦者","notes":[{"by":"勝鬘寶窟","era":"","t":"自上來明聖義竟，此第二次論於諦。"}]},{"p":6900,"q":"此諦","notes":[{"by":"勝鬘寶窟","era":"","t":"無作四諦也。"}]},{"p":6929,"q":"是故","notes":[{"by":"勝鬘寶窟","era":"","t":"是無量諦，佛聖所知，故名聖諦。"}]},{"p":6947,"q":"甚深","notes":[{"by":"勝鬘寶窟","era":"","t":"非報趣生識智境界，以是真證智境界，故言"}]},{"p":7022,"q":"如來藏處甚深故","notes":[{"by":"勝鬘寶窟","era":"","t":"第二以藏甚深類顯諦亦深，顯就藏說諦之意也。"}]},{"p":7117,"q":"及方便說","notes":[{"by":"勝鬘寶窟","era":"","t":"於彼藏身權之與實信不疑也。"}]},{"p":7295,"q":"如是八聖諦","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，第四明開權顯實。"}]},{"p":7381,"q":"以一切如來","notes":[{"by":"勝鬘寶窟","era":"","t":"上但言滅意生身，恐畏疑滅苦不盡，故云一切苦滅作證。"}]},{"p":7451,"q":"無始","notes":[{"by":"勝鬘寶窟","era":"","t":"理滅本有也，非生因造，故云無作。"}]},{"p":7466,"q":"自性清淨","notes":[{"by":"勝鬘寶窟","era":"","t":"未現之時名為性淨，顯現之時為方便淨，故云自性清淨。"}]},{"p":7494,"q":"不思議","notes":[{"by":"勝鬘寶窟","era":"","t":"第二對妄情顯深。"}]},{"p":7541,"q":"如來藏智是如來空智","notes":[{"by":"勝鬘寶窟","era":"","t":"略明二乘及大力菩薩無二智；三"}]},{"p":7588,"q":"有二種","notes":[{"by":"勝鬘寶窟","era":"","t":"廣釋如來有二智；四從"}]},{"p":7650,"q":"此二空智","notes":[{"by":"勝鬘寶窟","era":"","t":"廣釋二乘、大力菩薩無二智。"}]},{"p":7717,"q":"壞一切煩惱藏","notes":[{"by":"勝鬘寶窟","era":"","t":"上來明佛三諦究竟，今第四釋佛知道諦究竟。"}]},{"p":7745,"q":"三是無常","notes":[{"by":"勝鬘寶窟","era":"","t":"苦集及道為三相所為，故曰有為。"}]},{"p":7857,"q":"是諦","notes":[{"by":"勝鬘寶窟","era":"","t":"對前非虛妄是真諦。"}]},{"p":7904,"q":"一切阿羅漢","notes":[{"by":"勝鬘寶窟","era":"","t":"上來明凡夫二見及顛倒，從此下釋二乘上智。"}]},{"p":7936,"q":"苦滅諦者","notes":[{"by":"勝鬘寶窟","era":"","t":"上來第一理出情外，自下第二情不及理。"}]},{"p":7991,"q":"邊見者","notes":[{"by":"勝鬘寶窟","era":"","t":"此明從我見生邊見，計即陰我，陰滅我滅，而生斷見；離陰計我，陰滅我存，而生常見。"}]},{"p":8028,"q":"見諸行無常","notes":[{"by":"勝鬘寶窟","era":"","t":"第二計行斷，就法明斷常。"}]},{"p":8053,"q":"妄想見故","notes":[{"by":"勝鬘寶窟","era":"","t":"此就色心起邊見亦二：初明邊見、次明過失。"}]},{"p":8094,"q":"於心相續","notes":[{"by":"勝鬘寶窟","era":"","t":"明依心計常。"}]},{"p":8124,"q":"此妄想見","notes":[{"by":"勝鬘寶窟","era":"","t":"牒上所辨斷常二見。"}]},{"p":8149,"q":"顛倒眾生","notes":[{"by":"勝鬘寶窟","era":"","t":"第二次明顛倒。"}]},{"p":8188,"q":"淨智","notes":[{"by":"勝鬘寶窟","era":"","t":"又前是能生依，以境能生智故；後明依持名依，非佛性能生生死。"}]},{"p":8243,"q":"何以故","notes":[{"by":"勝鬘寶窟","era":"","t":"良以如來到常住彼岸，故稱波羅蜜。"}]},{"p":8272,"q":"於佛法身","notes":[{"by":"勝鬘寶窟","era":"","t":"上來舉境顯心，此明心稱境。"}]},{"p":8293,"q":"真子","notes":[{"by":"勝鬘寶窟","era":"","t":"應是信心，從佛口教生信故。"}]},{"p":8333,"q":"智波羅蜜","notes":[{"by":"勝鬘寶窟","era":"","t":"即二乘滿足無漏智，即四智究竟為智波羅蜜。"}]},{"p":8410,"q":"一依","notes":[{"by":"勝鬘寶窟","era":"","t":"三由有倒見，不得聖法，具此三義，名之為世。"}]},{"p":8501,"q":"不受根起","notes":[{"by":"勝鬘寶窟","era":"","t":"雖有根相，不能生識領納前塵，故云不受根。"}]},{"p":8518,"q":"此二法","notes":[{"by":"勝鬘寶窟","era":"","t":"明生死即是如來藏也。"}]},{"p":8543,"q":"生者新諸根起","notes":[{"by":"勝鬘寶窟","era":"","t":"由業煩惱力，未來還生，為起。"}]},{"p":8607,"q":"不思議","notes":[{"by":"勝鬘寶窟","era":"","t":"性淨而染，明下情不及也。"}]},{"p":8659,"q":"於此六識及心法智","notes":[{"by":"勝鬘寶窟","era":"","t":"有人言：六識者，六是事識。"}]},{"p":8699,"q":"無前際","notes":[{"by":"勝鬘寶窟","era":"","t":"辨能起染淨所以。"}]},{"p":8781,"q":"法界藏","notes":[{"by":"勝鬘寶窟","era":"","t":"凡言而者，返前述後之辭也。"}]},{"p":8909,"q":"唯佛世尊","notes":[{"by":"勝鬘寶窟","era":"","t":"佛有實眼，見此自性清淨心為煩惱所染，了了分明，故如眼見。"}]},{"p":8929,"q":"為正法依","notes":[{"by":"勝鬘寶窟","era":"","t":"佛能抦持此法，法由人弘，故為正法依。"}]},{"p":8955,"q":"佛即隨喜","notes":[{"by":"勝鬘寶窟","era":"","t":"第二明如來隨喜述成。"}]},{"p":9012,"q":"如此二法","notes":[{"by":"勝鬘寶窟","era":"","t":"偏就惡人以明化益。"}]},{"p":9050,"q":"若我弟子","notes":[{"by":"勝鬘寶窟","era":"","t":"上來明二種信，此下明二種解，此是解行地所成益也。"}]},{"p":9102,"q":"觀察心自在樂","notes":[{"by":"勝鬘寶窟","era":"","t":"上觀羅漢眠，是淨果；此之二句，觀淨法因也。"}]},{"p":9139,"q":"於我滅","notes":[{"by":"勝鬘寶窟","era":"","t":"歎行功德；三"}]},{"p":9181,"q":"是究竟者入大乘道因","notes":[{"by":"勝鬘寶窟","era":"","t":"既信佛所說，離闡提障，故不謗深義。"}]},{"p":9280,"q":"何等","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，別列善人。"}]},{"p":9323,"q":"於諸深法不自了","notes":[{"by":"勝鬘寶窟","era":"","t":"是解行前隨信信增。"}]},{"p":9379,"q":"諸餘眾生","notes":[{"by":"勝鬘寶窟","era":"","t":"明三善人外總舉惡人。"}]},{"p":9400,"q":"習諸外道","notes":[{"by":"勝鬘寶窟","era":"","t":"然惡人有二：一於佛法中起過、二於外道法中起過。"}]},{"p":9442,"q":"佛言","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，列名勸持。"}]},{"p":9463,"q":"降伏","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，歎其摧邪。"}]},{"p":9487,"q":"爾時世尊","notes":[{"by":"勝鬘寶窟","era":"","t":"初應從空而來，今說經竟還乘空而去。"}]},{"p":9530,"q":"合掌","notes":[{"by":"勝鬘寶窟","era":"","t":"已下，明三業虔仰。"}]},{"p":9567,"q":"還入城","notes":[{"by":"勝鬘寶窟","era":"","t":"勝鬘以法傳化流通；四"}]},{"p":9665,"q":"向天帝","notes":[{"by":"勝鬘寶窟","era":"","t":"佛為說經，以法付屬；次"}]},{"p":9697,"q":"憍尸迦","notes":[{"by":"勝鬘寶窟","era":"","t":"顯此法深，名不能盡。"}]},{"p":9753,"q":"是故","notes":[{"by":"勝鬘寶窟","era":"","t":"《浮荼不多羅經》云"}]},{"p":9815,"q":"云何奉持","notes":[{"by":"勝鬘寶窟","era":"","t":"歎經勝德，誡聽許說。"}]},{"p":9941,"q":"不思議大受","notes":[{"by":"勝鬘寶窟","era":"","t":"是勝鬘復於佛前發三願等。"}]},{"p":9984,"q":"說入一乘","notes":[{"by":"勝鬘寶窟","era":"","t":"是上佛告汝今更說諸佛所說攝受正法。"}]},{"p":10074,"q":"顛倒真實","notes":[{"by":"勝鬘寶窟","era":"","t":"是前文中生死依如來藏等。"}]},{"p":10116,"q":"勝鬘夫人師子吼","notes":[{"by":"勝鬘寶窟","era":"","t":"是前文中更有餘益復說斯等。"}]}]},{"base":"T1667","name":"T1667《大乘起信論》","path":"01-大正藏/15論集部類/T1667《大乘起信論》.md","loci":[{"p":1610,"q":"此心生滅因緣相能顯示大乘體相用故","notes":[{"by":"智旭","era":"","t":"今釋此心生滅因緣相既畢，故須顯示此心大乘體相用也。"}]}]},{"base":"T0452","name":"T0452《佛說觀彌勒菩薩上生兜率天經》","path":"01-大正藏/09經集部類/T0452《佛說觀彌勒菩薩上生兜率天經》.md","loci":[{"p":2224,"q":"若他觀者名為邪觀","notes":[{"by":"觀彌勒上生兜率天經贊","era":"","t":"是發請廣說爾。"}]},{"p":2306,"q":"劫波利村波婆利大婆羅門家","notes":[{"by":"觀彌勒上生兜率天經贊","era":"","t":"初生便有三十二相八十隨好，身紫金色姿容挺特。"}]},{"p":2417,"q":"時兜率陀天七寶臺內","notes":[{"by":"觀彌勒上生兜率天經贊","era":"","t":"答生彼天；第三"}]},{"p":2693,"q":"閻浮提歲數","notes":[{"by":"觀彌勒上生兜率天經贊","era":"","t":"乘言便故說下生時節，明住彼天之壽量也；第四"}]}]},{"base":"T1630","name":"T1630《因明入正理論》","path":"01-大正藏/15論集部類/T1630《因明入正理論》.md","loci":[{"p":50,"q":"總攝諸論要義","notes":[{"by":"因明入正理論疏","era":"","t":"論　此中宗等多言名為能立。"}]},{"p":104,"q":"差別","notes":[{"by":"因明入正理論疏","era":"","t":"因及二喻成此宗故，而為能立。"},{"by":"苾芻慧沼","era":"","t":"豈以昧識為誠言、靈哲為謾語？"}]},{"p":208,"q":"謂於是處無其所立","notes":[{"by":"因明入正理論疏","era":"","t":"又若是常，見非所作，如虛空等。"}]},{"p":498,"q":"雖樂成立，由與現量等相違故，名似","notes":[{"by":"慧沼","era":"","t":"故知樂為非簡彼五。"}]},{"p":1726,"q":"如遮實等，俱決定故。","notes":[{"by":"因明入正理論疏","era":"","t":"勝論此因既成有性，遮非實等，而作有緣性；此因亦遮有性非作有性有緣性。"}]},{"p":2034,"q":"諸所作者皆是無常","notes":[{"by":"因明入正理論疏","era":"","t":"即應以無常成所作性，非以所作成宗無常。"}]},{"p":2333,"q":"相有三","notes":[{"by":"因明入正理論疏","era":"","t":"釋前眾相，離重言失，故指如前。"}]}]},{"base":"T1666","name":"T1666《大乘起信論》","path":"01-大正藏/15論集部類/T1666《大乘起信論》.md","loci":[{"p":576,"q":"馬鳴菩薩造","notes":[{"by":"慧遠","era":"","t":"是法佛也，萬德積聚名之為身，法無藉他故名為體，亦可應用所依在之為體，故曰身體。"}]},{"p":594,"q":"盡十方","notes":[{"by":"大乘起信論內義略探記","era":"","t":"二意：一、非直歸一方三寶，亦乃盡十方齊敬；二、十方內非歸一二剎，亦乃一一方所各無盡剎一切三寶。"}]},{"p":634,"q":"如實修行","notes":[{"by":"大乘起信論內義略探記","era":"","t":"此二成行者，既於真不疑、於邪不執，未知於何乘起行？"}]},{"p":695,"q":"因緣分","notes":[{"by":"大乘起信論內義略探記","era":"","t":"又有釋云：造論大意不出二種，上半明為下化眾生、下半顯為上弘佛道。"}]},{"p":741,"q":"有何因緣","notes":[{"by":"慧遠","era":"","t":"以下，別表其意。"}]},{"p":762,"q":"云何為八","notes":[{"by":"慧遠","era":"","t":"以下別釋；三者"}]},{"p":785,"q":"得究竟樂","notes":[{"by":"慧遠","era":"","t":"所以眾生不得樂者，不知善行是應行故。"}]},{"p":836,"q":"摩訶衍","notes":[{"by":"慧遠","era":"","t":"以下，正釋。"}]},{"p":852,"q":"善根微少眾生","notes":[{"by":"慧遠","era":"","t":"是十信人也，以玄信故。"}]},{"p":899,"q":"對治凡夫二乘心過故","notes":[{"by":"慧遠","era":"","t":"凡夫有著有之過，二乘有著無之過。"}]},{"p":989,"q":"眾生根行不等","notes":[{"by":"慧遠","era":"","t":"色者是其三十二相，是身業也；心者是其大悲大慈，是意業也；言業勝者以因題果，以業勝故，所感果勝。"}]},{"p":1071,"q":"或有眾生無自心力","notes":[{"by":"慧遠","era":"","t":"以下，明無力人。"}]},{"p":1121,"q":"為欲總攝如來廣大深法無邊義故，應","notes":[{"by":"釋元曉","era":"","t":"此論之意既其如是，開則無量無邊之義為宗、合則二門一心之法為要，二門之內容萬義而不亂、無邊之義同一心而混融，是以開合自在、立破無礙，開而不繁、合而不狹，立而無得、破而無失，是為馬鳴之妙術、《起信》之宗體也。"}]},{"p":1165,"q":"云何為二","notes":[{"by":"慧遠","era":"","t":"以下第二列二章門。"}]},{"p":1186,"q":"眾生心","notes":[{"by":"慧遠","era":"","t":"以法受生，名為眾生。"}]},{"p":1205,"q":"依於此心","notes":[{"by":"慧遠","era":"","t":"是第八識，隨緣成妄，攝體從用，攝在心生滅中。"}]},{"p":1222,"q":"真如","notes":[{"by":"釋元曉","era":"","t":"無遣曰真、無立曰如。"}]},{"p":1263,"q":"云何","notes":[{"by":"慧遠","era":"","t":"真如中恒沙法是也。"},{"by":"釋元曉","era":"","t":"以下，列其章名："}]},{"p":1278,"q":"真如","notes":[{"by":"釋元曉","era":"","t":"以下別釋文也。"}]},{"p":1309,"q":"用大","notes":[{"by":"慧遠","era":"","t":"用有二種：一染、二淨，此二用中，各有二種。"}]},{"p":1338,"q":"菩薩皆乘此法到如來地","notes":[{"by":"慧遠","era":"","t":"此識為正因。"}]},{"p":1352,"q":"立義分","notes":[{"by":"釋元曉","era":"","t":"因緣既陳，宜立正義，若不略立，不知宗要故。"}]},{"p":1377,"q":"顯示正義","notes":[{"by":"慧遠","era":"","t":"以下，正明初段，此中有二：一明題章門、二"}]},{"p":1406,"q":"依一心法","notes":[{"by":"慧遠","era":"","t":"簡異色、無作二聚，但一心聚，故言一心：就此明義，故名為依。"}]},{"p":1474,"q":"大總相","notes":[{"by":"慧遠","era":"","t":"以妄故有所緣之境，生死境界但隨妄生，相應不捨，對上離心緣相也。"}]},{"p":1604,"q":"此真如體無有可遣，以一切法悉皆真","notes":[{"by":"釋元曉","era":"","t":"當知一切法不可說、不可念，故名為真如。"}]},{"p":1655,"q":"問曰","notes":[{"by":"慧遠","era":"","t":"若上所言絕言離心，今者此領前也。"},{"by":"釋元曉","era":"","t":"通舉前四種人。"}]},{"p":1701,"q":"亦無能念可念","notes":[{"by":"慧遠","era":"","t":"修行之人名為能念；所行之法名為可念。"}]},{"p":1731,"q":"依言說分別","notes":[{"by":"慧遠","era":"","t":"就真之中，不得分言空有兩義；而依名相言說故，得言空有，故依言說也。"}]},{"p":1753,"q":"以能究竟顯實故","notes":[{"by":"慧遠","era":"","t":"雖夫空義，是皆真空，是諸法之體，更無復染，故究竟實也。"}]},{"p":1783,"q":"所言空者","notes":[{"by":"慧遠","era":"","t":"以下，第三別釋。"}]},{"p":1819,"q":"當知真如","notes":[{"by":"慧遠","era":"","t":"能無一性而無不性，常義為言終日是常，非是樂義。"}]},{"p":1897,"q":"故說為空","notes":[{"by":"慧遠","era":"","t":"是顯首也，此中有三：一者釋不空義；二者"}]},{"p":1957,"q":"唯證","notes":[{"by":"慧遠","era":"","t":"其體常住，隨緣成妄，而體非無常，如上說也。"}]},{"p":2002,"q":"此識有二","notes":[{"by":"慧遠","era":"","t":"以下廣說其義。"}]},{"p":2034,"q":"不覺","notes":[{"by":"慧遠","era":"","t":"非但眾生身中之理，諸佛以此為體原故，故言即是也。"}]},{"p":2086,"q":"何以故","notes":[{"by":"釋元曉","era":"","t":"依門別立，此一文內含其二義：望上釋總義、望下立別門。"}]},{"p":2101,"q":"以始覺者即同本覺。","notes":[{"by":"大乘起信論內義略探記","era":"","t":"如《金光明．三身品》云"}]},{"p":2115,"q":"依本覺故而有不覺","notes":[{"by":"慧遠","era":"","t":"無明之心覆隱真實，而依不覺起緣照解，對治眾惑然後方顯，故名始覺。"}]},{"p":2215,"q":"捨麁分別執著相","notes":[{"by":"大乘起信論內義略探記","era":"","t":"也，猶眠住相夢中又未至證位。"}]},{"p":2247,"q":"離分別麁念相","notes":[{"by":"慧遠","era":"","t":"分別事識解也。"}]},{"p":2277,"q":"初起心無初相","notes":[{"by":"慧遠","era":"","t":"於四相中初生相時，悟一切法從本以來本無有生。"},{"by":"大乘起信論內義略探記","era":"","t":"即生相盡也。"}]},{"p":2293,"q":"心性","notes":[{"by":"釋元曉","era":"","t":"約真如門論其心性。"}]},{"p":2306,"q":"是故修多羅","notes":[{"by":"慧遠","era":"","t":"七識緣智名為念也。"}]},{"p":2356,"q":"是故一切眾生","notes":[{"by":"慧遠","era":"","t":"以下，總結真妄。"}]},{"p":2387,"q":"若得無念","notes":[{"by":"慧遠","era":"","t":"以下，結前三位非究竟覺。"}]},{"p":2438,"q":"復次","notes":[{"by":"釋元曉","era":"","t":"以下，第二明真如相。"}]},{"p":2470,"q":"智淨相","notes":[{"by":"慧遠","era":"","t":"是法佛性也。"}]},{"p":2506,"q":"破和合","notes":[{"by":"慧遠","era":"","t":"顯所治障；三者"}]},{"p":2545,"q":"無明之相不離覺","notes":[{"by":"慧遠","era":"","t":"以下，開譬；三者"}]},{"p":2581,"q":"水非動性","notes":[{"by":"慧遠","era":"","t":"合上水相風相不相離也。"}]},{"p":2672,"q":"所謂","notes":[{"by":"釋元曉","era":"","t":"以下，第二辯相。"}]},{"p":2685,"q":"隨眾生根","notes":[{"by":"慧遠","era":"","t":"明應佛性也。"}]},{"p":2718,"q":"與虛空等","notes":[{"by":"慧遠","era":"","t":"喻淨無染也，亦喻相入無障礙。"}]},{"p":2755,"q":"非覺照義故","notes":[{"by":"慧遠","era":"","t":"雖是一體，心法不同，擿心而言，法不生知，是真諦理，故非覺照上法性空，即是謂也。"}]},{"p":2772,"q":"不空","notes":[{"by":"釋元曉","era":"","t":"亦有三句：初牒空門，謂言"}]},{"p":2786,"q":"不出","notes":[{"by":"慧遠","era":"","t":"一云，就真法說，絕言離相，超外眾物而不離有無，故言不出。"}]},{"p":2826,"q":"具足無漏熏眾生","notes":[{"by":"慧遠","era":"","t":"具淨法故，冥資眾生，令修善行也。"}]},{"p":2869,"q":"緣熏習鏡","notes":[{"by":"慧遠","era":"","t":"猶上不思議業相也。"}]},{"p":2936,"q":"如迷人","notes":[{"by":"慧遠","era":"","t":"諸群盲類諸眾生等，迷二諦理不知超出生死之津，似是迷人。"},{"by":"釋元曉","era":"","t":"以下，是反結也。"}]},{"p":3018,"q":"與彼不覺相應不離","notes":[{"by":"慧遠","era":"","t":"共為第七識體也。"}]},{"p":3113,"q":"以有境界","notes":[{"by":"慧遠","era":"","t":"以下，明相應也。"}]},{"p":3134,"q":"智相","notes":[{"by":"慧遠","era":"","t":"前所說境分別染淨、違順差別，非明解智也。"}]},{"p":3154,"q":"相續相","notes":[{"by":"慧遠","era":"","t":"依前智識心相轉麁，境界牽心，心隨境界分別不斷，如海波浪，又復三世因果令不斷絕，故名相續。"}]},{"p":3180,"q":"執取相","notes":[{"by":"慧遠","era":"","t":"十使根本取性無明。"}]},{"p":3206,"q":"計名字相","notes":[{"by":"慧遠","era":"","t":"所謂五見麁起煩惱，若復通論十使皆是，此二合為煩惱分也。"}]},{"p":3227,"q":"起業相","notes":[{"by":"慧遠","era":"","t":"依煩惱，造種種業也。"}]},{"p":3250,"q":"業繫苦相","notes":[{"by":"慧遠","era":"","t":"眾惑根本故也。"}]},{"p":3300,"q":"云何為二","notes":[{"by":"釋元曉","era":"","t":"問數發起；次言"},{"by":"慧遠","era":"","t":"以下，釋章門。"}]},{"p":3327,"q":"皆同微塵性相","notes":[{"by":"慧遠","era":"","t":"以下，合喻；三者"}]},{"p":3351,"q":"是故","notes":[{"by":"慧遠","era":"","t":"以下，引經證成。"}]},{"p":3393,"q":"畢竟無得","notes":[{"by":"慧遠","era":"","t":"唯隨染業幻所作也，非是真智，理色不空性也。"}]},{"p":3480,"q":"所謂眾生依心","notes":[{"by":"大乘起信論內義略探記","era":"","t":"此即明心體是所依，意、意識即是能依也。"},{"by":"慧遠","era":"","t":"生死根源故，理與無明俱一時有。"}]},{"p":3501,"q":"阿梨耶識","notes":[{"by":"釋元曉","era":"","t":"不生滅與生滅和合，非一非異，故總名為阿梨耶識。"}]},{"p":3553,"q":"業識","notes":[{"by":"慧遠","era":"","t":"依前無明，便有妄念不覺心起，說之為業。"}]},{"p":3571,"q":"轉識","notes":[{"by":"慧遠","era":"","t":"依前業識，心慮漸麁而取外相，故名為轉識。"}]},{"p":3588,"q":"現識","notes":[{"by":"慧遠","era":"","t":"依前轉識所起境界，還顯自心，名為現識。"}]},{"p":3646,"q":"智識","notes":[{"by":"慧遠","era":"","t":"於前現識所顯法中，分別染淨違順差別，故名智識。"}]},{"p":3663,"q":"續識","notes":[{"by":"慧遠","era":"","t":"依前智識心相轉麁，境界事心心隨境界，分別不斷，故名續識。"}]},{"p":3730,"q":"是故三界","notes":[{"by":"慧遠","era":"","t":"唯隨於心，以從心故，心生法生，心滅法滅，故言唯心也。"}]},{"p":3756,"q":"一切法","notes":[{"by":"慧遠","era":"","t":"就真論真，無有分別，無能所故、無相可得故，名不見心也。"}]},{"p":3809,"q":"是故一切法","notes":[{"by":"慧遠","era":"","t":"以下，結無體依心。"}]},{"p":3874,"q":"種種妄執隨事攀緣","notes":[{"by":"慧遠","era":"","t":"計名字相也。"}]},{"p":3898,"q":"又復說","notes":[{"by":"慧遠","era":"","t":"見是五見，愛是五鈍。"}]},{"p":3984,"q":"何以故","notes":[{"by":"釋元曉","era":"","t":"第二釋義，是對始覺釋本覺義。"},{"by":"慧遠","era":"","t":"釋難知由；三者"}]},{"p":4011,"q":"染心","notes":[{"by":"慧遠","era":"","t":"除無明識，其餘皆是為染心也。"}]},{"p":4024,"q":"是故","notes":[{"by":"釋元曉","era":"","t":"以下，舉非顯是，如前所說無念是覺，是故有念不得名覺；是即金剛心以還，一切眾生未離無始無明之念，依是義故，不得名覺。"}]},{"p":4054,"q":"不相應","notes":[{"by":"慧遠","era":"","t":"即心不覺常無別異，即指心體以為無明，非是心外緣有迷用。"}]},{"p":4070,"q":"有六種","notes":[{"by":"慧遠","era":"","t":"是執取相也，信相應地者，是種性也。"}]},{"p":4097,"q":"遠離","notes":[{"by":"釋元曉","era":"","t":"以下，明覺分齊。"}]},{"p":4143,"q":"依具戒地漸離，乃至無相方便地究竟","notes":[{"by":"大乘起信論內義略探記","era":"","t":"一地三聚戒具，故云具戒。"}]},{"p":4173,"q":"色自在地","notes":[{"by":"慧遠","era":"","t":"是第八地，能淨佛土，名色自在。"}]},{"p":4192,"q":"依心自在地能離故。","notes":[{"by":"大乘起信論內義略探記","era":"","t":"第九地中善知眾生心行十種稠林，此於他得自在。"}]},{"p":4213,"q":"菩薩盡地","notes":[{"by":"釋元曉","era":"","t":"無垢地，此是總舉，下之二句，別明二道。"}]},{"p":4264,"q":"言相應","notes":[{"by":"慧遠","era":"","t":"心體是知，染用亦知，詑境迷故，言同知緣也。"}]},{"p":4299,"q":"不覺","notes":[{"by":"慧遠","era":"","t":"是恒沙惑亂勞義強，能障真如寂滅智也。"},{"by":"釋元曉","era":"","t":"如《仁王經》言"}]},{"p":4355,"q":"此義云何","notes":[{"by":"釋元曉","era":"","t":"以下，重顯前說滅不滅義。"}]},{"p":4375,"q":"違平等性","notes":[{"by":"慧遠","era":"","t":"以染心者是分別心，真心寂靜故正相返。"}]},{"p":4397,"q":"與法違故","notes":[{"by":"慧遠","era":"","t":"無明闇惑，種智真明，故相返也。"}]},{"p":4418,"q":"復次","notes":[{"by":"釋元曉","era":"","t":"以下，次明性淨本覺之相，於中有二：一者總標、二者別解。"}]},{"p":4442,"q":"與心相應","notes":[{"by":"慧遠","era":"","t":"以下，據人以辨；三者、"}]},{"p":4481,"q":"菩薩境界","notes":[{"by":"慧遠","era":"","t":"種性以上乃至金剛心也。"}]},{"p":4539,"q":"若因滅","notes":[{"by":"慧遠","era":"","t":"明亡本故末竭，是業轉現識也。"}]},{"p":4643,"q":"唯風滅故動相隨滅，非是水滅","notes":[{"by":"慧遠","era":"","t":"是故明知是設喻也。"}]},{"p":4715,"q":"熏習義","notes":[{"by":"慧遠","era":"","t":"以下，略釋熏義；三者、"}]},{"p":4751,"q":"染因","notes":[{"by":"慧遠","era":"","t":"第七識中，始從業識乃至相續通名業識。"}]},{"p":4788,"q":"世間衣服","notes":[{"by":"慧遠","era":"","t":"喻染淨法體也。"}]},{"p":4810,"q":"此亦如是","notes":[{"by":"慧遠","era":"","t":"以下，合喻也。"}]},{"p":4859,"q":"云何熏習起染","notes":[{"by":"慧遠","era":"","t":"以下，廣顯熏相。"}]},{"p":4882,"q":"以有","notes":[{"by":"釋元曉","era":"","t":"已下，次明麁相。"}]},{"p":4965,"q":"此妄境界","notes":[{"by":"慧遠","era":"","t":"以下，明其熏習所起不同。"}]},{"p":5000,"q":"妄心熏習","notes":[{"by":"慧遠","era":"","t":"以下，列章門，謂體用也。"}]},{"p":5046,"q":"增長分別事識","notes":[{"by":"慧遠","era":"","t":"凡夫二乘厭生死苦，取向涅槃，此六識中方便修行熏發真也。"}]},{"p":5064,"q":"無明","notes":[{"by":"釋元曉","era":"","t":"本末不覺也。"}]},{"p":5116,"q":"云何熏習起淨法","notes":[{"by":"慧遠","era":"","t":"以下，明其熏習起淨，就初中有二：一者、就前四明其熏習相生次第；二者、"},{"by":"釋元曉","era":"","t":"以下，第二廣顯因緣差別。"}]},{"p":5143,"q":"因緣","notes":[{"by":"釋元曉","era":"","t":"阿梨耶心體變作諸法，是生滅因；根本無明熏動心體，是生滅緣。"}]},{"p":5157,"q":"樂求涅槃","notes":[{"by":"慧遠","era":"","t":"以還，攝上真如熏習也。"}]},{"p":5256,"q":"因緣俱滅","notes":[{"by":"慧遠","era":"","t":"因是心也，緣是境也。"}]},{"p":5330,"q":"意熏習","notes":[{"by":"慧遠","era":"","t":"諸菩薩見虛妄法，無所貪取，知真如法寂靜安隱，發心勇猛趣大涅槃。"}]},{"p":5348,"q":"真如熏習義","notes":[{"by":"慧遠","era":"","t":"以下，明其唯真熏習起淨。"}]},{"p":5392,"q":"無漏法","notes":[{"by":"慧遠","era":"","t":"法身本體，法佛之性。"},{"by":"釋元曉","era":"","t":"本覺始覺也；"}]},{"p":5425,"q":"眾生","notes":[{"by":"釋元曉","era":"","t":"而無別體，唯依心體，故言"}]},{"p":5475,"q":"云何","notes":[{"by":"慧遠","era":"","t":"以下，列二章門；三者、釋二章門。"}]},{"p":5515,"q":"真如本一","notes":[{"by":"慧遠","era":"","t":"諸眾生中，真如理一本來無二，故成佛時以理成故，但是一佛無有二也。"}]},{"p":5557,"q":"我見愛","notes":[{"by":"慧遠","era":"","t":"是四住所起也。"}]},{"p":5602,"q":"有因有緣","notes":[{"by":"慧遠","era":"","t":"因者內心，緣謂外緣。"}]},{"p":5785,"q":"示教利喜","notes":[{"by":"慧遠","era":"","t":"四諦三轉法輪也。"}]},{"p":5848,"q":"差別緣者","notes":[{"by":"慧遠","era":"","t":"此應身化也。"}]},{"p":5950,"q":"此緣有二","notes":[{"by":"慧遠","era":"","t":"以下，就時以辨，謂時遠近也；三者、"}]},{"p":6017,"q":"平等緣者","notes":[{"by":"慧遠","era":"","t":"以下，釋第二章門。"}]},{"p":6047,"q":"以同體智力","notes":[{"by":"慧遠","era":"","t":"此觀照彼苦也。"}]},{"p":6102,"q":"未相應","notes":[{"by":"慧遠","era":"","t":"是凡、二乘、地前菩薩也。"}]},{"p":6149,"q":"未得自在業修行","notes":[{"by":"慧遠","era":"","t":"初地以上，出世法身菩薩令捨妄心，除滅無明契證真如，與佛如來法身相應，無有分別，唯依法身自然修行，趣佛智海也。"}]},{"p":6222,"q":"乃至","notes":[{"by":"慧遠","era":"","t":"以下，結名，包含蘊積名之為藏，眾法積聚名為法身；若別言，隱時名藏，顯為法身。"}]},{"p":6245,"q":"此義云何","notes":[{"by":"慧遠","era":"","t":"以下，無分別故也。"}]},{"p":6306,"q":"無有增減","notes":[{"by":"慧遠","era":"","t":"是理體也，若論行義，凡聖殊異因果差別，而理體者等同一味。"}]},{"p":6340,"q":"所謂","notes":[{"by":"慧遠","era":"","t":"故，此之二句，是心與法同一體性，互相緣集。"}]},{"p":6414,"q":"乃至","notes":[{"by":"慧遠","era":"","t":"以下，釋上結德，此中有二：初釋結德。"}]},{"p":6438,"q":"問曰","notes":[{"by":"慧遠","era":"","t":"以下，釋簡前後；三者、"}]},{"p":6490,"q":"等同一味","notes":[{"by":"慧遠","era":"","t":"自下釋所以，中有三：一者、正釋；二、傳釋；三者、結。"}]},{"p":6519,"q":"復以何義","notes":[{"by":"慧遠","era":"","t":"自下第三別釋，此中有二：一者、略別本由；二者、"}]},{"p":6543,"q":"以一切法","notes":[{"by":"慧遠","era":"","t":"是無明也，以有此故便起末條。"}]},{"p":6591,"q":"若心起見","notes":[{"by":"慧遠","era":"","t":"即知而無知相，不緣而照，即是遍照法界義也。"}]},{"p":6667,"q":"此義","notes":[{"by":"釋元曉","era":"","t":"以下，釋其所以。"}]},{"p":6741,"q":"復次","notes":[{"by":"釋元曉","era":"","t":"以下，第三廣上立義分中生滅之相，於中有二：先明生滅麁細之相、後顯麁細生滅之義。"},{"by":"慧遠","era":"","t":"以下，明菩薩所見。"}]},{"p":6819,"q":"此以何義","notes":[{"by":"慧遠","era":"","t":"是緣智也，契真之智名如實知。"}]},{"p":6873,"q":"種種之用","notes":[{"by":"慧遠","era":"","t":"以下，明真諦觀；四者、"}]},{"p":6916,"q":"第一義諦","notes":[{"by":"慧遠","era":"","t":"以下，明其見聞得益不同。"}]},{"p":6945,"q":"此用","notes":[{"by":"釋元曉","era":"","t":"凡夫二乘未知唯識，計有外塵，即是分別事識之義；今見佛身，亦計心外，順意識義，故說依分別事識見；此人不知依自轉識能現色相，故言"}]},{"p":6981,"q":"不知轉識現故見從外來","notes":[{"by":"釋元曉","era":"","t":"然其所見有分齊色，即無有邊離分齊相；彼人唯取有分齊義，未解分齊則無有邊，故言"},{"by":"慧遠","era":"","t":"諸可見色依轉識起，此起根源，不知自心現故、為從外來？"}]},{"p":7005,"q":"依於業識","notes":[{"by":"釋元曉","era":"","t":"十解以上菩薩，能解唯心，無外塵義，順業識義以見佛身，故言依於業識見也。"},{"by":"慧遠","era":"","t":"是地前菩薩也。"}]},{"p":7055,"q":"所住依果","notes":[{"by":"慧遠","era":"","t":"即蓮華藏世界也。"}]},{"p":7090,"q":"常能住持不毀不失","notes":[{"by":"慧遠","era":"","t":"是報淨土也。"}]},{"p":7141,"q":"凡夫所見","notes":[{"by":"釋元曉","era":"","t":"以下，第二重牒分別，先明應身，文相可知。"}]},{"p":7165,"q":"非受樂相","notes":[{"by":"慧遠","era":"","t":"小乘教中明佛無常，但以修行故增智慧耳，故具苦無常，故非受樂也。"},{"by":"釋元曉","era":"","t":"以下，顯報身相，於中有二：先明地前所見、後顯地上所見。"}]},{"p":7248,"q":"若得淨心","notes":[{"by":"釋元曉","era":"","t":"以下，顯地上所見。"}]},{"p":7273,"q":"若離業識則無見相","notes":[{"by":"釋元曉","era":"","t":"要依業識，乃有轉相及與現相，故離業識，即無見相也。"}]},{"p":7298,"q":"問曰","notes":[{"by":"釋元曉","era":"","t":"以下，往復除疑，問意可知。"}]},{"p":7313,"q":"云何","notes":[{"by":"慧遠","era":"","t":"有人釋言：法身無色，應中但有。"}]},{"p":7339,"q":"所謂","notes":[{"by":"釋元曉","era":"","t":"以下，釋平等義，依於三昧平等見者，十解以上諸菩薩等，見佛報身無量相好，皆無有邊，離分齊相，故言"}]},{"p":7427,"q":"此非心識","notes":[{"by":"慧遠","era":"","t":"以下，總結殊勝。"}]},{"p":7463,"q":"推求五陰色之與心","notes":[{"by":"釋元曉","era":"","t":"色陰名色，餘四名心也。"}]},{"p":7496,"q":"如人","notes":[{"by":"釋元曉","era":"","t":"以下，次觀心法，先喻、後合。"},{"by":"慧遠","era":"","t":"以下，開譬；三者、"}]},{"p":7524,"q":"心實不動","notes":[{"by":"釋元曉","era":"","t":"推求動念已滅未生，中無所住，無所住故即無有起，故知心性實不動也。"}]},{"p":7548,"q":"對治邪執","notes":[{"by":"釋元曉","era":"","t":"文亦有四：一者總標舉數、二者依數列名、三者依名辨相、四者總顯究竟離執。"}]},{"p":7572,"q":"是我見有二","notes":[{"by":"慧遠","era":"","t":"以下，舉數列章門；三者、"}]},{"p":7587,"q":"人我見","notes":[{"by":"釋元曉","era":"","t":"計有總相宰主之者，名人我執；"}]},{"p":7646,"q":"即謂虛空是如來性","notes":[{"by":"釋元曉","era":"","t":"計如來性同虛空相也。"}]},{"p":7788,"q":"乃至涅槃真如之法亦畢竟空","notes":[{"by":"釋元曉","era":"","t":"如《大品經》云"}]},{"p":7904,"q":"云何","notes":[{"by":"釋元曉","era":"","t":"以下，顯其對治，文相可知。"}]},{"p":7951,"q":"而有","notes":[{"by":"慧遠","era":"","t":"以下，撥權顯實。"}]},{"p":8009,"q":"不離、不斷","notes":[{"by":"釋元曉","era":"","t":"等者，如《不增不減疏》中廣說也。"}]},{"p":8165,"q":"若說三界外更有眾生始起","notes":[{"by":"釋元曉","era":"","t":"即是外道經說者，如《仁王經》之所說故。"}]},{"p":8210,"q":"法我見","notes":[{"by":"釋元曉","era":"","t":"亦有三句：初明起見之由；"}]},{"p":8237,"q":"見有","notes":[{"by":"釋元曉","era":"","t":"以下，次顯執相；"}]},{"p":8280,"q":"復次","notes":[{"by":"釋元曉","era":"","t":"以下，第四究竟離執之義，於中有二：先明諸法離言道理，後顯假說言教之意，文相可見。"},{"by":"慧遠","era":"","t":"以下，遣情；三者、"}]},{"p":8309,"q":"是故","notes":[{"by":"慧遠","era":"","t":"是染淨一切法也，本來無相不可說也。"}]},{"p":8341,"q":"而有言說","notes":[{"by":"慧遠","era":"","t":"第二明其廢權，此中有三：一者、明撥權；二者、"}]},{"p":8365,"q":"其旨","notes":[{"by":"慧遠","era":"","t":"以下，明其顯實；三者、"}]},{"p":8402,"q":"一切諸佛所證之道","notes":[{"by":"釋元曉","era":"","t":"以下，別開分別，於中有三：一者舉數開章、二者依數列名、三者依名辨相。"},{"by":"慧遠","era":"","t":"以下，明其發心。"}]},{"p":8424,"q":"略說","notes":[{"by":"慧遠","era":"","t":"以下，列章門；三者、釋章門。"}]},{"p":8440,"q":"信成就發心","notes":[{"by":"釋元曉","era":"","t":"在十迴向，兼取十行；十行位中，能解法空，隨順法界，修六度行，六度行純熟，發迴向心，入向位故，言"},{"by":"慧遠","era":"","t":"自下第三釋章門，釋三章門，故即分為三。"}]},{"p":8478,"q":"得信成就堪能發心","notes":[{"by":"慧遠","era":"","t":"明其起行；三者、"}]},{"p":8541,"q":"一萬劫信心成就","notes":[{"by":"釋元曉","era":"","t":"等者，發心之緣，乃有眾多，今略出其二種勝緣也。"},{"by":"慧遠","era":"","t":"第二明其發心。"}]},{"p":8588,"q":"如是信心","notes":[{"by":"慧遠","era":"","t":"種性以上決定不退，故名正定聚。"},{"by":"釋元曉","era":"","t":"未入十信，不信因果，名邪定聚。"}]},{"p":8620,"q":"若有眾生","notes":[{"by":"慧遠","era":"","t":"以下，明退之人。"}]},{"p":8777,"q":"略說","notes":[{"by":"釋元曉","era":"","t":"是窮原義，若一善不備，無由歸原，歸原之成，必具萬行，故言"}]},{"p":8872,"q":"大摩尼寶體性明淨","notes":[{"by":"慧遠","era":"","t":"是心為煩惱所染也。"}]},{"p":8990,"q":"略說方便","notes":[{"by":"慧遠","era":"","t":"第二明行，此中有二：一者、立名，謂行根方便；二者、即釋，此有三：一者、明不住生死行；二者、"}]},{"p":9013,"q":"觀一切法","notes":[{"by":"慧遠","era":"","t":"以下，明不住涅槃行；三者、"}]},{"p":9081,"q":"謂慚愧","notes":[{"by":"慧遠","era":"","t":"即釋；三者、"}]},{"p":9205,"q":"所謂","notes":[{"by":"慧遠","era":"","t":"以下，明八相益；三者、"}]},{"p":9271,"q":"菩薩發是心","notes":[{"by":"釋元曉","era":"","t":"以下，第三顯其發心功德，於中有四：初顯勝德、次明微過、三通權教、四歎實行。"},{"by":"慧遠","era":"","t":"以下，二明果分行，此中有三：一者、明真證行；二者、"}]},{"p":9293,"q":"隨其願力","notes":[{"by":"釋元曉","era":"","t":"如《華嚴經》歎十住初發心住云"}]},{"p":9338,"q":"然是菩薩","notes":[{"by":"慧遠","era":"","t":"以下，明未盡有漏之業。"},{"by":"釋元曉","era":"","t":"以下，顯其微過。"}]},{"p":9388,"q":"如修多羅","notes":[{"by":"釋元曉","era":"","t":"以下，第三會通權教，如《本業經》云"}]},{"p":9414,"q":"未入正位","notes":[{"by":"慧遠","era":"","t":"是不定聚也。"}]},{"p":9431,"q":"又是菩薩","notes":[{"by":"釋元曉","era":"","t":"以下，第四歎其實行，永無怯弱，即成彼經是權非實也。"}]},{"p":9454,"q":"若聞","notes":[{"by":"慧遠","era":"","t":"以下，明其不畏苦難行也；三者、"}]},{"p":9493,"q":"解行發心","notes":[{"by":"慧遠","era":"","t":"以下，釋第二章門，此中有二：一者、明其總勝，當知轉勝解行俱明也；二者、"}]},{"p":9674,"q":"證發心","notes":[{"by":"釋元曉","era":"","t":"在文有二：一者通約諸地明證發心、二者別就十地顯成滿德。"},{"by":"慧遠","era":"","t":"以下，明釋證發心。"}]},{"p":9691,"q":"證何境界","notes":[{"by":"釋元曉","era":"","t":"轉識之相，是能見用，對此能見說為境界，以此諸地所起證智，要依轉識而證真如，故對所依假說境界，直就證智即無能所，故言"},{"by":"慧遠","era":"","t":"以熏修緣故所證境異，若廢行緣則無境界之異。"}]},{"p":9746,"q":"諸佛","notes":[{"by":"慧遠","era":"","t":"以下，明佛種智。"}]},{"p":9810,"q":"如是","notes":[{"by":"慧遠","era":"","t":"第二雙，此中有二：一者、明能化；二者、"}]},{"p":9847,"q":"以一切菩薩","notes":[{"by":"慧遠","era":"","t":"以下，明所化。"}]},{"p":9879,"q":"故示所行亦有差別","notes":[{"by":"慧遠","era":"","t":"第三明第十地能證之行，就此中有二：一者、明因滿果成；二者、以問答重明。"}]},{"p":9892,"q":"發心相","notes":[{"by":"釋元曉","era":"","t":"以下，第四顯相。"}]},{"p":9943,"q":"業識心","notes":[{"by":"釋元曉","era":"","t":"以下，第二別顯成滿功德，於中有二：一者直顯勝德、二者往復除疑。"},{"by":"慧遠","era":"","t":"以下，明第十地能證之行。"}]},{"p":9977,"q":"謂以一念","notes":[{"by":"慧遠","era":"","t":"是緣智終一念解也。"}]},{"p":10015,"q":"問曰","notes":[{"by":"釋元曉","era":"","t":"以下，第二遣疑，二番問答，即遣二疑。"}]},{"p":10092,"q":"一切境界，本來一心離於想念","notes":[{"by":"釋元曉","era":"","t":"是立道理，謂一切境界，雖非有邊，而非無邊，不出一心故；以非無邊故，可得盡了；而非有邊故，非思量境，以之故言離想念也。"}]},{"p":10106,"q":"以眾生","notes":[{"by":"慧遠","era":"","t":"明凡夫無種智；三者、"}]},{"p":10134,"q":"諸佛如來","notes":[{"by":"慧遠","era":"","t":"第三明佛種智，此中有二：一者、明佛有智體；二者、"},{"by":"釋元曉","era":"","t":"佛心離想，體一心原，離妄想故，名心真實。"}]},{"p":10168,"q":"有大智","notes":[{"by":"慧遠","era":"","t":"明佛有智用。"}]},{"p":10233,"q":"若見","notes":[{"by":"慧遠","era":"","t":"以下，正釋。"}]},{"p":10307,"q":"鏡若有垢，色像不現。如是眾生心若","notes":[{"by":"釋元曉","era":"","t":"法身如本質，化身似影像，今據能現之本質，故言法身不現。"}]},{"p":10347,"q":"是中依未入正定眾生","notes":[{"by":"釋元曉","era":"","t":"上說發趣道相中，言依不定聚眾生，今此中言未入正定，當知亦是不定聚人；然不定聚內，有劣有勝，勝者乘進，劣者可退，為彼勝人故說發趣，所謂信成就發心，乃至證發心等，為令勝人次第進趣故也；為其劣者故說修信，所謂四種信心、五門行等，為彼劣人信不退故也。"},{"by":"慧遠","era":"","t":"以下，正釋信行；四者、"}]},{"p":10390,"q":"信根本","notes":[{"by":"釋元曉","era":"","t":"真如之法，諸佛所歸，眾行之原，故曰根本也。"}]},{"p":10487,"q":"有五門","notes":[{"by":"釋元曉","era":"","t":"有信無行，即信不熟，不熟之信，遇緣便退，故修五行以成四信也。"},{"by":"慧遠","era":"","t":"以下，明行。"}]},{"p":10528,"q":"止觀門","notes":[{"by":"釋元曉","era":"","t":"六度之中，定慧合修，故合此二為止觀門也。"}]},{"p":10567,"q":"若見厄","notes":[{"by":"慧遠","era":"","t":"明無畏施；三者、"}]},{"p":10618,"q":"迴向菩提","notes":[{"by":"慧遠","era":"","t":"以下，明勸修迴向。"}]},{"p":10675,"q":"若出家","notes":[{"by":"慧遠","era":"","t":"以下，明威儀戒。"}]},{"p":10734,"q":"當護","notes":[{"by":"慧遠","era":"","t":"以下，明威儀戒。"}]},{"p":10820,"q":"當念","notes":[{"by":"慧遠","era":"","t":"以下，據昔以勸；三者、"}]},{"p":10842,"q":"是故","notes":[{"by":"慧遠","era":"","t":"以下，結勸。"}]},{"p":10860,"q":"復次，若人","notes":[{"by":"釋元曉","era":"","t":"以下，第二明修止勝能，是明依前真如三昧，能生一行等諸三昧。"}]},{"p":10924,"q":"應當","notes":[{"by":"釋元曉","era":"","t":"此總明除諸障方便，如人負債，依付於王，則於債主無如之何；如是行人禮拜諸佛，諸佛所護，能脫諸障也。"},{"by":"慧遠","era":"","t":"以下，明勸修因行；三者、"}]},{"p":10962,"q":"免諸障、善根增長","notes":[{"by":"釋元曉","era":"","t":"是義廣說，如《金鼓經》也。"}]},{"p":10985,"q":"謂止一切境界相","notes":[{"by":"釋元曉","era":"","t":"先由分別作諸外塵，今以覺慧破外塵相，塵相既止，無所分別，故名為止也。"}]},{"p":11016,"q":"隨順毘鉢舍那觀義","notes":[{"by":"釋元曉","era":"","t":"彼云奢摩他，此翻云止；毘鉢舍那，此翻云觀；但今譯此論者，為別方便及與正觀，故於正觀仍存彼語。"},{"by":"慧遠","era":"","t":"以下，雙釋。"}]},{"p":11050,"q":"若修止","notes":[{"by":"慧遠","era":"","t":"別廣止觀；三者、"}]},{"p":11088,"q":"不依見聞覺知","notes":[{"by":"釋元曉","era":"","t":"是舉散心所取六塵，於此諸塵推求破壞，知唯自心，不復託緣，故言不依；不依外塵，即是內住也。"}]},{"p":11173,"q":"即復此心亦無自相，念念不可得","notes":[{"by":"釋元曉","era":"","t":"是明失念還存內心，而由修力尋即反吐也；能於內外不受反吐，是故名為最極寂靜。"}]},{"p":11214,"q":"久習淳熟其心得住","notes":[{"by":"釋元曉","era":"","t":"略顯真如三昧力用，由此進趣得入種性不退位故。"}]},{"p":11322,"q":"一行三昧","notes":[{"by":"慧遠","era":"","t":"第二定難中有三：一者、明身業亂；二者、"},{"by":"釋元曉","era":"","t":"如《文殊般若經》言"}]},{"p":11351,"q":"或有","notes":[{"by":"釋元曉","era":"","t":"以下，次明對治，若能思惟如前諸塵，唯是自心分別所作，自心之外無別塵相。"}]},{"p":11391,"q":"當念","notes":[{"by":"慧遠","era":"","t":"以下，明對治解。"}]},{"p":11406,"q":"或現天像","notes":[{"by":"慧遠","era":"","t":"以下，明口業亂；三者、"}]},{"p":11425,"q":"若說陀羅尼","notes":[{"by":"慧遠","era":"","t":"明所說法；三者、"}]},{"p":11483,"q":"或令人知","notes":[{"by":"慧遠","era":"","t":"以下，明神通亂；四者、"}]},{"p":11602,"q":"皆是","notes":[{"by":"慧遠","era":"","t":"以下，明其當知非真之相。"}]},{"p":11677,"q":"以是義故","notes":[{"by":"釋元曉","era":"","t":"以下，第三簡其真偽，於中有二：初舉內外以別邪正，先邪後正，文相可知；"},{"by":"慧遠","era":"","t":"以下，明應觀察。"}]},{"p":11718,"q":"應知外道","notes":[{"by":"慧遠","era":"","t":"以下，辨邪正相。"}]},{"p":11747,"q":"真如三昧者","notes":[{"by":"慧遠","era":"","t":"以下，明真正定；三者、"}]},{"p":11781,"q":"若諸凡夫","notes":[{"by":"釋元曉","era":"","t":"以下，次顯事定之偽，謂不淨觀、安那槃念等，皆名世間諸三昧也。"},{"by":"慧遠","era":"","t":"以下，勸人修定。"}]},{"p":11869,"q":"云何","notes":[{"by":"慧遠","era":"","t":"以下，別釋。"}]},{"p":12115,"q":"一切心行","notes":[{"by":"慧遠","era":"","t":"以下，明變易無常。"}]},{"p":12172,"q":"應觀世間","notes":[{"by":"慧遠","era":"","t":"以下，明不淨觀。"}]},{"p":12194,"q":"如是當念","notes":[{"by":"慧遠","era":"","t":"以下，念所化境；二者、"},{"by":"釋元曉","era":"","t":"以下，第二明大悲觀。"}]},{"p":12270,"q":"作此思惟","notes":[{"by":"慧遠","era":"","t":"以下，正明發願；三者、"}]},{"p":12336,"q":"以起如是","notes":[{"by":"釋元曉","era":"","t":"以下，第四明精進觀。"},{"by":"慧遠","era":"","t":"以下，明化度行。"}]},{"p":12371,"q":"唯除坐時","notes":[{"by":"慧遠","era":"","t":"以下，就二諦門以辨觀慧。"},{"by":"釋元曉","era":"","t":"以下，第三總結勸修。"}]},{"p":12395,"q":"若行","notes":[{"by":"釋元曉","era":"","t":"以下，第二合修，於中有三：一總標俱行、第二別明行相、三者總結。"}]},{"p":12412,"q":"所謂","notes":[{"by":"釋元曉","era":"","t":"依非有門以修止行也。"},{"by":"慧遠","era":"","t":"以下，別釋。"}]},{"p":12445,"q":"雖念因緣","notes":[{"by":"慧遠","era":"","t":"以下，明真諦觀。"}]},{"p":12463,"q":"若修","notes":[{"by":"釋元曉","era":"","t":"以下，對障分別。"}]},{"p":12513,"q":"以此義故","notes":[{"by":"慧遠","era":"","t":"以下，明相助成；三者、"}]},{"p":12534,"q":"若止觀","notes":[{"by":"慧遠","era":"","t":"明不具有損。"}]},{"p":12549,"q":"復次，眾生","notes":[{"by":"釋元曉","era":"","t":"以下，第三示修行者不退方便，於中有二：先明初學者畏退墮，後示不退轉之方便。"}]},{"p":12605,"q":"當知","notes":[{"by":"釋元曉","era":"","t":"以下，引證、六者"}]},{"p":12695,"q":"若觀","notes":[{"by":"釋元曉","era":"","t":"欲明十解以上菩薩，得少分見真如法身，是故能得畢竟往生。"}]},{"p":12749,"q":"若有眾生","notes":[{"by":"釋元曉","era":"","t":"以下，舉益勸修、三者"},{"by":"慧遠","era":"","t":"以下，明其勸持。"}]},{"p":12794,"q":"若人聞是","notes":[{"by":"慧遠","era":"","t":"以下，明約終果，勸持此論。"}]},{"p":12823,"q":"假使有人","notes":[{"by":"釋元曉","era":"","t":"以下，信受福勝、四者"},{"by":"慧遠","era":"","t":"以下，舉勝勸學。"}]},{"p":12957,"q":"其有眾生","notes":[{"by":"慧遠","era":"","t":"以下，舉非返釋；四者、"},{"by":"釋元曉","era":"","t":"以下，毀謗罪重、五者"}]},{"p":12985,"q":"是故","notes":[{"by":"慧遠","era":"","t":"以下，勸生仰信；三者、"},{"by":"釋元曉","era":"","t":"以下，第三釋罪重意；"}]},{"p":13017,"q":"以一切如來","notes":[{"by":"釋元曉","era":"","t":"以下，第四轉釋斷三寶種之意，餘之文可見。"},{"by":"慧遠","era":"","t":"以下，取人以證；五者、"}]},{"p":13094,"q":"諸佛甚深廣大義","notes":[{"by":"慧遠","era":"","t":"此之所顯不能廣辨，故名"}]}]},{"base":"T0672","name":"T0672《大乘入楞伽經》","path":"01-大正藏/09經集部類/T0672《大乘入楞伽經》.md","loci":[{"p":311,"q":"元嘉建號，跋陀之譯未弘；延昌紀年","notes":[{"by":"(寶臣)","era":"","t":"今此注者，正釋唐本，仍將流支所譯餘八品題，如次間入注文，經中亦成一十八品，庶知文有始終，理無二致，讀者易曉。"}]},{"p":874,"q":"開示此法。","notes":[{"by":"(寶臣)","era":"","t":"從此至品終，別明發起序也。"}]},{"p":2238,"q":"為如煙焰旋火輪耶？","notes":[{"by":"(寶臣)","era":"","t":"諸法既隱，楞伽王唯見自身住本宮中，此明不離當處也。"}]},{"p":3153,"q":"如是等事悉無有別。","notes":[{"by":"(寶臣)","era":"","t":"言夜叉王復念，願得重見如來。"}]},{"p":3541,"q":"及諸外道皆不能測。","notes":[{"by":"(寶臣)","era":"","t":"言大慧知菩薩眾會之心，及觀未來一切眾生迷惑執取，為斷彼疑，而問於佛。"}]},{"p":3792,"q":"梵釋天等所未曾見。","notes":[{"by":"(寶臣)","era":"","t":"明是時如來知楞伽王欲請問，告其速問，欲解釋滿其願。"}]},{"p":5419,"q":"法身如幻夢，云何可稱讚？知無性無","notes":[{"by":"(寶臣)","era":"","t":"《大般若》云"}]},{"p":5605,"q":"云何起計度？云何淨計度？云何起迷","notes":[{"by":"(寶臣)","era":"","t":"上二句問：妄計度性，起滅染淨。"}]},{"p":5653,"q":"解脫至何所？誰縛誰能解？","notes":[{"by":"(寶臣)","era":"","t":"問：心外無物，云何知見五法、三自性等，悟入諸地，具諸佛法至如來位？"}]},{"p":5785,"q":"三昧心何相？願佛為我說。","notes":[{"by":"(寶臣)","era":"","t":"問：既有三乘、五姓之異，云何復說唯是心量？"}]},{"p":5893,"q":"云何為性空？云何剎那滅？","notes":[{"by":"(寶臣)","era":"","t":"上句問：依如來藏而有生死？"}]},{"p":5941,"q":"云何菩提分？覺分從何起？","notes":[{"by":"(寶臣)","era":"","t":"如下，善觀二無我，及淨自心現流中，別答此二問。"}]},{"p":6073,"q":"明處與伎術，誰之所顯示？","notes":[{"by":"(寶臣)","era":"","t":"問：五明法及世間伎能，誰之所作？"}]},{"p":6157,"q":"解脫有幾種？修行師復幾？","notes":[{"by":"(寶臣)","era":"","t":"問：解脫是無學人，修行即是有學人。"}]},{"p":6193,"q":"眾魔及異學，如是各有幾？","notes":[{"by":"(寶臣)","era":"","t":"問：云何諸法是妄想假施設量？"}]},{"p":6301,"q":"云何修行進？云何修行退？","notes":[{"by":"(寶臣)","era":"","t":"問：學者修行，云何而有進退之異？"}]},{"p":6349,"q":"云何釋迦種？云何甘蔗種？","notes":[{"by":"(寶臣)","era":"","t":"問：仙人修苦行，謂得長生。"}]},{"p":6397,"q":"何因不食肉？何因令斷肉？食肉諸眾","notes":[{"by":"(寶臣)","era":"","t":"問：食肉，制斷食肉因緣。"}]},{"p":6493,"q":"云何變化佛？云何為報佛？真如智慧","notes":[{"by":"(寶臣)","era":"","t":"問：佛名義也，隨機赴感應化佛；酬其往因名報佛；體性無二真如佛；本覺顯照智慧佛。"}]},{"p":6553,"q":"世尊住久如，正法幾時住？","notes":[{"by":"(寶臣)","era":"","t":"問：如來住世久近，及正法住時分長短？"}]},{"p":6613,"q":"云何得世通？云何得出世？","notes":[{"by":"(寶臣)","era":"","t":"問：世間五通及出世六通，云何而得？"}]},{"p":7284,"q":"云何得財富？云何轉輪王？云何王守","notes":[{"by":"(寶臣)","era":"","t":"從此以下凡二十偈，復領大慧所問。"}]},{"p":8619,"q":"諸識有幾種生住滅？","notes":[{"by":"(寶臣)","era":"","t":"真如妙性，本自無生，一念隨緣，事分起盡，即是真心不守自性，隨無明緣成於諸識，生住異滅，此非凡小及因位菩薩智慮所知。"}]},{"p":8716,"q":"大慧！如明鏡中現諸色像，現識亦爾","notes":[{"by":"(寶臣)","era":"","t":"言賴耶現識及分別事識無異相，皆由最初一念為緣，令真如心不守自性，隨緣成有。"}]},{"p":64351,"q":"色識雖轉滅，而業不失壞；令於諸有","notes":[{"by":"(寶臣)","era":"","t":"若色識轉滅諸業失壞者，是則無生死，亦無常無常，即斷常二見亦俱離也。"}]},{"p":71235,"q":"三世及非世，第五不可說","notes":[{"by":"(寶臣)","era":"","t":"天竺犢子部，以我法俱有而為宗趣，立五法藏，謂三世為三，無為為四(即是非世)，第五不可說藏，我在其中，以不可說為有為及無為也。"}]},{"p":71973,"q":"當依此教理，勿更餘分別。","notes":[{"by":"(寶臣)","era":"","t":"## 注大乘入楞伽經卷第十(終)\n　　　丐緣鏤板沙門　(逈瑋)　重校勘\n1 羅婆那王勸請品(一)\n2 問答品(一-二)\n  1\n  2\n3 集一切法品(二-五)\n  1\n  2\n  3\n  4\n4 佛心品(五-七)\n  1\n  2\n  3\n5 盧迦耶陀品(七)\n6 涅槃品(七)\n7 法身品(七)\n8 無常品(八)\n9 現證品(八)\n10 如來常無常品(八)\n11 如來藏性品(八)\n12 五法門品(八)\n13 恒河沙品(八)\n14 剎那品(八-九)\n  1\n  2\n15 變化品(九)\n16 斷食肉品(九)\n17 陀羅尼品(九)\n18 偈頌品(九-一〇)\n  1\n  2"}]}]},{"base":"T0685","name":"T0685《佛說盂蘭盆經》","path":"01-大正藏/09經集部類/T0685《佛說盂蘭盆經》.md","loci":[{"p":266,"q":"當為七世父母及現在父母厄難中者，","notes":[{"by":"宗密","era":"","t":"當為者，能救之心。"}]},{"p":459,"q":"福樂百年","notes":[{"by":"宗密","era":"","t":"是也，不應重舉。"}]}]},{"base":"T0701","name":"T0701《佛說溫室洗浴眾僧經》","path":"01-大正藏/09經集部類/T0701《佛說溫室洗浴眾僧經》.md","loci":[{"p":147,"q":"明至佛所，當問我疑。","notes":[{"by":"釋慧遠","era":"","t":"晨且勅家大小眷屬，嚴至佛所。"}]}]},{"base":"T1585","name":"T1585《成唯識論》","path":"01-大正藏/14瑜伽部類/T1585《成唯識論》.md","loci":[{"p":240,"q":"云何世間及諸聖教","notes":[{"by":"成唯識論述記","era":"","t":"正釋本文，名"}]},{"p":95734,"q":"因緣","notes":[{"by":"成唯識論掌中樞要","era":"","t":"又有聞《釋迦論》一千五百頌；又有《溫那地論》二千五百頌。"},{"by":"成唯識論述記","era":"","t":"言，正表此法與漏俱故。"}]},{"p":95826,"q":"識變","notes":[{"by":"成唯識論述記","era":"","t":"簡薩婆多等；"}]},{"p":95842,"q":"唯識","notes":[{"by":"成唯識論述記","era":"","t":"現行成就者，《對法》等說：諸蘊處界，若善、不善、無記現行，名現行成就；種若斷損，現行亦"}]},{"p":95861,"q":"見等","notes":[{"by":"成唯識論掌中樞要","era":"","t":"顯上所明俱有依攝。"},{"by":"成唯識論述記","era":"","t":"亦名不共，今言"}]},{"p":95890,"q":"真如","notes":[{"by":"成唯識論述記","era":"","t":"若爾，此與化地部計實有善等真如，有何差別？"}]},{"p":95947,"q":"煩惱","notes":[{"by":"成唯識論述記","era":"","t":"字，故名煩惱。"}]},{"p":95981,"q":"解脫","notes":[{"by":"成唯識論掌中樞要","era":"","t":"一體之上，義有三故，名"},{"by":"成唯識論述記","era":"","t":"體即圓寂，西域梵音云"}]},{"p":96005,"q":"由熏","notes":[{"by":"成唯識論述記","era":"","t":"論：若本全無至永不得生。"}]},{"p":96034,"q":"此中","notes":[{"by":"成唯識論述記","era":"","t":"是簡持義，此解第八識行相故。"},{"by":"成唯識論掌中樞要","era":"","t":"無所簡別，餘如疏說。"}]},{"p":96050,"q":"相應","notes":[{"by":"成唯識論述記","era":"","t":"之言等故，若心所即心，不可言相應，相應者必與他性，非自性故。"}]},{"p":96129,"q":"分別","notes":[{"by":"成唯識論述記","era":"","t":"有漏三界心、心所法，以妄分別為自體故，隱其無漏有為不論，但染依他對心外法故，下文自例淨法亦爾。"},{"by":"成唯識論掌中樞要","era":"","t":"是滿、分淨者，簡於因位，不名法身故。"}]},{"p":96268,"q":"於有","notes":[{"by":"成唯識論述記","era":"","t":"後有，即唯異熟三有果也。"}]},{"p":96399,"q":"大乘","notes":[{"by":"成唯識論述記","era":"","t":"簡彼定性及無種姓，此是未種解脫分善，名"}]}]},{"base":"T1626","name":"T1626《大乘法界無差別論》","path":"01-大正藏/14瑜伽部類/T1626《大乘法界無差別論》.md","loci":[{"p":74,"q":"所謂","notes":[{"by":"法藏","era":"","t":"此顯凡位雖與如是功德相應，然為無明覆故，不能起自他饒益。"}]},{"p":151,"q":"然後安立","notes":[{"by":"法藏","era":"","t":"等者，既具彼因，次宜顯彼所發心性，望心性為出也、望心相為生也。"}]},{"p":227,"q":"何者","notes":[{"by":"法藏","era":"","t":"依章解釋中，釋十二分即為十二段。"}]},{"p":244,"q":"此唯諸佛","notes":[{"by":"法藏","era":"","t":"明能證至極，亦是結法屬人。"}]},{"p":278,"q":"於中","notes":[{"by":"法藏","era":"","t":"明此等功德皆無衰耗改變，故云無老也。"}]},{"p":326,"q":"無病","notes":[{"by":"法藏","era":"","t":"標也，謂二障及習所病盡故。"}]},{"p":393,"q":"不退失因","notes":[{"by":"法藏","era":"","t":"非直當成佛果為最上之因，亦與中間所修諸行作不退失因，以離菩提心令餘行退失故。"}]},{"p":434,"q":"不思議法身","notes":[{"by":"法藏","era":"","t":"此中有轉依義，如別說。"}]},{"p":511,"q":"如海","notes":[{"by":"法藏","era":"","t":"明菩提心亦能生長二乘聖法。"}]},{"p":526,"q":"如種子","notes":[{"by":"法藏","era":"","t":"明菩提心能親生佛果。"}]},{"p":604,"q":"深信","notes":[{"by":"法藏","era":"","t":"《唯識》中信別有三：一、信實有，謂於諸法實事理中深信忍故；二、信有德，謂於三寶真淨德中深信樂故；三、信有能，謂於一切世出世善，深信有力，能得能成，起希望故。"}]},{"p":777,"q":"雖其自性","notes":[{"by":"法藏","era":"","t":"喻離垢淨，可知。"}]},{"p":801,"q":"如是一切","notes":[{"by":"法藏","era":"","t":"合中亦初合性淨、二"}]},{"p":862,"q":"以一切","notes":[{"by":"法藏","era":"","t":"釋也，謂以一切法同一無我味故，是故能證所證為一味相，以非不彼起無以證彼故也。"}]},{"p":878,"q":"眾寶所依","notes":[{"by":"法藏","era":"","t":"喻修生德；二、"}]},{"p":943,"q":"不思議法","notes":[{"by":"法藏","era":"","t":"恒沙性德深廣難測故也。"}]},{"p":973,"q":"得四種","notes":[{"by":"法藏","era":"","t":"釋轉至佛果，則釋頌中初三句。"}]},{"p":1043,"q":"又如","notes":[{"by":"法藏","era":"","t":"釋第二頌中，引《不增不減經》釋因位異名，亦是就法顯異名。"}]},{"p":1098,"q":"無作","notes":[{"by":"法藏","era":"","t":"標也，謂性非緣作故。"}]},{"p":1134,"q":"復次","notes":[{"by":"法藏","era":"","t":"明染淨位中法身即菩提。"}]},{"p":1158,"q":"所謂","notes":[{"by":"法藏","era":"","t":"釋別顯中，十句內各有標釋。"}]},{"p":1191,"q":"清淨","notes":[{"by":"法藏","era":"","t":"標也，謂知性空之智能了此性。"}]},{"p":1242,"q":"染淨諸法所依止故","notes":[{"by":"法藏","era":"","t":"此心性是諸法依處。"}]},{"p":1287,"q":"眾生界","notes":[{"by":"法藏","era":"","t":"若別唯結初門，通言具前三門，以佛菩薩是眾生數故。"}]},{"p":1321,"q":"不淨位","notes":[{"by":"法藏","era":"","t":"正顯其相；三、"}]},{"p":1343,"q":"說名如來","notes":[{"by":"法藏","era":"","t":"等者，正顯法身隨彼染緣作眾生義。"}]},{"p":1401,"q":"厭離","notes":[{"by":"法藏","era":"","t":"等，明成行中，先起別行，謂十地中各修一度行故；二、通行，謂八萬等遍通之行，為對治八萬四千諸煩惱故。"}]},{"p":1465,"q":"遠離","notes":[{"by":"法藏","era":"","t":"等者，明隨眠惑及習垢悉亦永盡。"}]},{"p":1515,"q":"昇無二","notes":[{"by":"法藏","era":"","t":"三、於所證法自在，故云"}]},{"p":1547,"q":"是故","notes":[{"by":"法藏","era":"","t":"引《勝鬘經》釋第二頌中二：先簡妄非真、後顯真非妄。"}]},{"p":1585,"q":"此但名異","notes":[{"by":"法藏","era":"","t":"等者，簡名定義門。"}]},{"p":1735,"q":"復次","notes":[{"by":"法藏","era":"","t":"引《勝鬘經》釋第二頌，二：先標二藏空智者，境智合標也。"}]},{"p":1767,"q":"法界亦爾","notes":[{"by":"法藏","era":"","t":"舉法合可知。"}]},{"p":1806,"q":"非如來藏","notes":[{"by":"法藏","era":"","t":"顯真非妄中亦二句：初、明體無妄法。"}]},{"p":1825,"q":"過有為相","notes":[{"by":"法藏","era":"","t":"總顯是無為故。"}]},{"p":1864,"q":"諸佛法","notes":[{"by":"法藏","era":"","t":"等者，總舉諸佛功德法與法身不離不脫。"}]},{"p":2003,"q":"所謂","notes":[{"by":"法藏","era":"","t":"別顯恒沙淨德大智慧光明義等，以對恒沙染法況恒沙功德也。"}]},{"p":2029,"q":"何等","notes":[{"by":"法藏","era":"","t":"釋中，先釋空藏，有三義：一謂如來藏與妄染俱，不為所染，故云名為空，以真妄不相到故。"}]},{"p":2144,"q":"應知","notes":[{"by":"法藏","era":"","t":"明具智斷勝德。"}]},{"p":2406,"q":"了知","notes":[{"by":"法藏","era":"","t":"明具德故益生中亦二：先兩頌明具德、後半頌明益生。"}]},{"p":2430,"q":"佛心","notes":[{"by":"法藏","era":"","t":"二句，明心雲遍空德。"}]},{"p":2484,"q":"遠離","notes":[{"by":"法藏","era":"","t":"等，明智德圓滿，德無不熟故，釋後具德。"}]},{"p":2515,"q":"於常","notes":[{"by":"法藏","era":"","t":"領納如此究竟之樂，盡未來際永無斷絕，故云恒受等也。"}]},{"p":2581,"q":"猶如冷即水","notes":[{"by":"法藏","era":"","t":"此有三義：一通喻前後三門皆同一性，如冷即水。"}]},{"p":2624,"q":"眾生界","notes":[{"by":"法藏","era":"","t":"與功德法為依止，具性德故也。"}]},{"p":2709,"q":"復次應知","notes":[{"by":"法藏","era":"","t":"明此出纏法身，不異在纏苦法性滅平等真理，謂以心性無二故。"}]},{"p":2773,"q":"遠離一切煩惱藏","notes":[{"by":"法藏","era":"","t":"等，明顯淨，即不空如來藏也。"}]},{"p":2867,"q":"唯佛世尊","notes":[{"by":"法藏","era":"","t":"明唯佛妙智所能證合。"}]},{"p":2919,"q":"唯有一乘道","notes":[{"by":"法藏","era":"","t":"總標因果一道解脫。"}]},{"p":2939,"q":"同一法界","notes":[{"by":"法藏","era":"","t":"歸順釋，謂同一如來藏法界也。"}]},{"p":2956,"q":"亦不可","notes":[{"by":"法藏","era":"","t":"明果一因無異，破小乘因。"}]},{"p":3007,"q":"平等諸法","notes":[{"by":"法藏","era":"","t":"明所得理平等，離所見相也。"}]}]}];

